	\title{Circular Holographic MIMO Beamforming for Integrated Data and Energy Multicast Systems
		\author{Qingxiao Huang,~\IEEEmembership{Graduate Student Member,~IEEE}, Yizhe Zhao,~\IEEEmembership{Member,~IEEE}, Jie Hu,~\IEEEmembership{Senior Member,~IEEE},   Kun~Yang,~\IEEEmembership{Fellow,~IEEE} and Yuguang Fang,~\IEEEmembership{Fellow,~IEEE}}
		\thanks{Qingxiao Huang, Yizhe Zhao and Jie Hu are with the School of Information and Communication Engineering, University of Electronic Science and Technology of China, Chengdu, 611731, China, email: qxhuang@std.uestc.edu.cn, yzzhao@uestc.edu.cn and hujie@uestc.edu.cn. }
		\thanks{Kun Yang is with the School of Computer Science and Electronic Engineering, University of Essex, U.K., email: kyang@ieee.org.}
