	\centering
	\begin{align}\label{eq:resolution derivation}
		&\Delta(r_1,\theta_1,\phi_1,r_2,\theta_2,\phi_2) \nonumber\\  \approx& \left|\frac{1}{2\pi}\sum_{n=1}^{N}e^{j\frac{2\pi}{\lambda}R\left(\sin\theta_2\cos(\phi_2-\psi_n) -\sin\theta_1\cos(\phi_1-\psi_n)+\frac{R}{2r_1}\left( 1-\cos^2(\phi_1-\psi_n)\sin^2\theta_1\right)- \frac{R}{2r_2}\left( 1-\cos^2(\phi_2-\psi_n)\sin^2\theta_2\right)\right) }  \right|\nonumber\\
		\approx& \left|\frac{1}{2\pi}\int_{0}^{2\pi}e^{j\frac{2\pi}{\lambda}R\left(\sin\theta_2\cos(\phi_2-x) -\sin\theta_1\cos(\phi_1-x)+\frac{R}{2r_1}\left( 1-\cos^2(\phi_1-x)\sin^2\theta_1\right)- \frac{R}{2r_2}\left( 1-\cos^2(\phi_2-x)\sin^2\theta_2\right)\right) } \mathrm{d}x \right| \nonumber\\
		=&\Bigg|\frac{1}{2\pi}\int_{0}^{2\pi}e^{j\frac{2\pi}{\lambda}R \left(\left( \sin\theta_2\cos\phi_2-\sin\theta_1\cos\phi_1\right) \cos x -\left( \sin\theta_2\sin\phi_2-\sin\theta_1\sin\phi_1\right) \sin x \right)} \nonumber \\  
		&\times e^{j\frac{2\pi}{\lambda}R^2 \left(\left( \frac{\sin^2\theta_2}{4r_2}\cos(2\phi_2)-\frac{\sin^2\theta_1}{4r_1}\cos(2\phi_1)\right)\cos(2x)+\left( \frac{\sin^2\theta_2}{4r_2}\sin(2\phi_2)-\frac{\sin^2\theta_1}{4r_1}\sin(2\phi_1)\right)\sin(2x)+\frac{\sin^2\theta_2}{4r_2}-\frac{\sin^2\theta_1}{4r_1}+\frac{1}{2r_1}-\frac{1}{2r_2} \right) }\mathrm{d}x \Bigg|\nonumber \\  
		=&\Bigg|\frac{\xi_5}{2\pi}\int_{0}^{2\pi}e^{j\left( \sqrt{\eta_1^2+\eta_2^2}\sin(x+\arctan\frac{\eta_1}{\eta_2} )+\sqrt{\eta_3^2+\eta_4^2}\sin(2x+\arctan\frac{\eta_3}{\eta_4} )\right) }\mathrm{d}x \Bigg|
	\end{align}
