Then, we have
\begin{align}
	&\Delta(r_1,\theta_1,\phi_1,r_2,\theta_2,\phi_2) 
	=\Bigg|\frac{\xi_5}{2\pi}\int_{0}^{2\pi}e^{j\left( \xi_1\sin(x+\xi_2 )+\xi_3\sin(2x+\xi_4 )\right) }\mathrm{d}x \Bigg| \nonumber \\
	\overset{\text{(a)}}=&\left| \xi_5 I_0(j\xi_1)I_0(j\xi_3)+2\xi_5\sum_{n=1}^{\infty}I_n(j\xi_3)I_{2n}(j\xi_1)e^{jn(2\xi_2-\xi_4-\pi/2)} \right| \nonumber \\
	=& \left| \xi_5 J_0(\xi_1)J_0(\xi_3)+2\xi_5\sum_{n=1}^{\infty}j^{-n}J_n(-\xi_3)j^{-2n}J_{2n}(-\xi_1)e^{jn(2\xi_2-\xi_4-\pi/2)}\right| \nonumber \\
	=&\left| \xi_5\sum_{n=-\infty}^{\infty}j^n J_n(\xi_3)J_{2n}(\xi_1)e^{jn(2\xi_2-\xi_4-\pi/2)}\right| 
\end{align}
where (a) is realized by utilizing $ \frac{1}{2\pi}\int_{0}^{2\pi}e^{ z\cos(m\theta)+y\cos\theta }\mathrm{d}\theta=I_0(z)I_0(y)+2\sum_{n=1}^{\infty}I_n(z)I_{mn}(y) $.
\end{IEEEproof}

With the closed-form expression of the resolution function obtained, it can be shown, as stated in {\it Lemma 2}, that the channel response vectors exhibit spatial asymptotic orthogonality as the number of antennas increases.

\begin{Lemma}
	\textbf{(Near-field asymptotic spatial orthogonality for channel response vectors of circular antenna array):} 
	\begin{equation}
			\lim_{{N \rightarrow \infty}} \mathbf{a}_t^H(r_1,\theta_1,\phi_1)\mathbf{a}_t(r_2,\theta_2,\phi_2)=0.
	\end{equation}
\end{Lemma}

\begin{IEEEproof}
	\begin{align}\label{eq：resolution upper boound}
	&\mathbf{a}_t^H(r_1,\theta_1,\phi_1)\mathbf{a}_t(r_2,\theta_2,\phi_2)\nonumber \\
	&\leq \Delta(r_1,\theta_1,\phi_1,r_2,\theta_2,\phi_2) \nonumber \\
	& =\left| \xi_5\sum_{n=-\infty}^{\infty}j^n J_n(\xi_3)J_{2n}(\xi_1)e^{jn(2\xi_2-\xi_4-\pi/2)}\right| \nonumber \\
	&\overset{\text{(a)}}\approx \left| \xi_5\sqrt{\frac{2}{\pi\xi_1}}\sum_{n=-\infty}^{\infty}j^n J_n(\xi_3)\cos(\xi_1-n\pi-\pi/4)e^{jn(2\xi_2-\xi_4-\pi/2)}\right| \nonumber \\
	&= \left| \xi_5\cos(\xi_1-\pi/4)\sqrt{\frac{2}{\pi\xi_1}}\sum_{n=-\infty}^{\infty}(-je^{j(2\xi_2-\xi_4-\pi/2)})^n J_n(\xi_3)\right| \nonumber \\
	&\overset{\text{(b)}}=\left| \xi_5\cos(\xi_1-\pi/4)\sqrt{\frac{2}{\pi\xi_1}} e^{-j\xi_3\sin(2\xi_2-\xi_4)}\right|
	\nonumber \\
	&\leq\sqrt{\frac{2}{\pi\xi_1}}
	\end{align}
where (a) is realized by utilizing the asymptotic property of $ J_n(\cdot) $ in Eq.(9.2.1) of \cite{mabramowitz64:handbook}. (b) is realized by utilizing Eq.(9.1.41) in \cite{mabramowitz64:handbook}. Then, supposing that $ \theta_1 \neq \theta_2 $ or $ \phi_1 \neq \phi_2 $, we have
\begin{align}
	&\lim_{\substack{N \rightarrow \infty}} \mathbf{a}_t^H(r_1,\theta_1,\phi_1)\mathbf{a}_t(r_2,\theta_2,\phi_2)\leq\lim_{\substack{N \rightarrow \infty}}\sqrt{\frac{2}{\pi\xi_1}}\nonumber \\
	&\approx \lim_{\substack{N \rightarrow \infty}}\sqrt{\frac{4}{\pi N\sqrt{ \sin^2\theta_1+\sin^2\theta_2-2\sin\theta_1\sin\theta_2\cos(\phi_1-\phi_2) } }}
	\nonumber \\
	&=0.
\end{align}
When $ \theta_1 =\theta_2 $, $ \phi_1 = \phi_2 $ and $ r_1 \neq r_2 $, we have
\begin{align}
	&\lim_{\substack{N \rightarrow \infty}}\mathbf{a}_t^H(r_1,\theta,\phi)\mathbf{a}_t(r_2,\theta,\phi)\nonumber \\
	&\leq \lim_{\substack{N \rightarrow \infty}} \Delta(r_1,r_2,\theta,\phi) \nonumber \\
	& =\lim_{\substack{N \rightarrow \infty}}\left| \xi_5 \int_{0}^{2\pi}e^{j\left(\frac{\pi R^2 \sin^2\theta}{2\lambda}(\frac{1}{r_2}-\frac{1}{r_1})\cos(2x-2\phi )\right) }\mathrm{d}x \right| \nonumber \\
	& \approx\lim_{\substack{N \rightarrow \infty}}\left| \xi_5 J_0(\frac{ \lambda N^2 \sin^2\theta(r_1-r_2)}{32 \pi r_1 r_2}) \right|  =0
\end{align}
Therefore, when $ \theta_1 \neq\theta_2 $, $ \phi_1 \neq \phi_2 $ or $ r_1 \neq r_2 $, we have $ \lim_{\substack{N \rightarrow \infty}} \mathbf{a}_t^H(r_1,\theta_1,\phi_1)\mathbf{a}_t(r_2,\theta_2,\phi_2)=0 $.
\end{IEEEproof}

After demonstrating the orthogonality of the channel response vectors, the asymptotic spatial orthogonality of the near-field channel for circular antenna array can be subsequently established in Theorem 1.
\begin{Theorem}
	\textbf{(Asymptotic spatial orthogonality of near-field channel for circular antenna array):} 
	\begin{equation}
		\lim_{\substack{N \rightarrow \infty}}\frac{1}{N}\mathbf{h_1}^H\mathbf{h_2}=0.
	\end{equation}
\end{Theorem}
\begin{IEEEproof}
		\begin{align}
		&\lim_{\substack{N \rightarrow \infty}}\frac{1}{N}\mathbf{h_1}^H\mathbf{h_2}\nonumber \\=&	\lim_{\substack{N \rightarrow \infty}}\frac{1}{N}\left( 	\sqrt{N}\alpha_1^{[0]} \mathbf{a}_t(r_1^{[0]},\theta_1^{[0]},\phi_1^{[0]})+\sqrt{\frac{N}{I}}\sum_{i=1}^{I}\alpha^{[i]} \mathbf{a}_t(r_1^{[i]},\theta_1^{[i]},\phi_1^{[i]})\right)^H \nonumber \\ &\times \left( 	\sqrt{N}\alpha_2^{[0]} \mathbf{a}_t(r_2^{[0]},\theta_2^{[0]},\phi_2^{[0]})+\sqrt{\frac{N}{I}}\sum_{i=1}^{I}\alpha_2^{[i]} \mathbf{a}_t(r_2^{[i]},\theta_2^{[i]},\phi_2^{[i]})\right)\nonumber \\ =&\lim_{\substack{N \rightarrow \infty}}(\alpha_1^{[0]})^H\alpha_2^{[0]}\mathbf{a}_t^H(r_1^{[0]},\theta_1^{[0]},\phi_1^{[0]}) \mathbf{a}_t(r_2^{[0]},\theta_2^{[0]},\phi_2^{[0]})\nonumber \\&+\sqrt{\frac{1}{I}}\sum_{i=1}^{I}(\alpha_1^{[0]})^H\alpha_2^{[i]}\mathbf{a}_t^H(r_1^{[0]},\theta_1^{[0]},\phi_1^{[0]}) \mathbf{a}_t(r_2^{[i]},\theta_2^{[i]},\phi_2^{[i]})\nonumber \\&+\sqrt{\frac{1}{I}}\sum_{i=1}^{I}(\alpha_1^{[i]})^H\alpha_2^{[0]}\mathbf{a}_t^H(r_1^{[i]},\theta_1^{[i]},\phi_1^{[i]}) \mathbf{a}_t(r_2^{[0]},\theta_2^{[0]},\phi_2^{[0]})\nonumber \\&+\frac{1}{I}\sum_{i=1}^{I}\sum_{j=1}^{I}(\alpha_1^{[i]})^H\alpha_2^{[j]}\mathbf{a}_t^H(r_1^{[i]},\theta_1^{[i]},\phi_1^{[i]}) \mathbf{a}_t(r_2^{[j]},\theta_2^{[j]},\phi_2^{[j]})\nonumber \\&=0. 
	\end{align}
\end{IEEEproof}
So far, we have shown that asymptotic spatial orthogonality can be maintained in near-field channels and under the configuration of circular arrays. In strong LoS path scenarios, such as radar sensing and ultra-high-frequency communications, channel orthogonality can be approximated using the closed-form expression of the resolution function derived earlier. In the next section, we capitalize on this spatial orthogonality to develop low-complexity and efficient beamforming schemes for IDET systems.


\section{Circular Beamforming Design based on Asymptotic Spatial Orthogonality}
\subsection{Asymptotically optimal transmitter design.}
Before solving (P1), we first consider the beamforming design for the asymptotically optimal fully-digital transmitter \( \mathbf{f} \) with a circular antenna array. For the fully-digital transmitter, the actual hardware constraints of H-MIMO can be ignored, and we have \( \mathbf{f} = \mathbf{Q} \mathbf{P} \mathbf{b} \). Thus, the problem can be formulated as:
\begin{align}
	\text{ (P2):}  & \max_{ \substack{ \mathbf{f}} } \ { \min \limits_{1\leq k \leq K}} R_k=\log_2(1+\frac{P_t}{\sigma^2}||\mathbf{h}^H_k\mathbf{f}||^2), \label{eq:object2} \\
	\text{s.t.} \  &
	||\mathbf{f}||^2= 1,  \tag{\ref{eq:object2}a} \label{eq:object2-a} \\
	& {E}_l\geq E_0, l \in \mathcal{E}  \tag{\ref{eq:object2}b} \label{eq:object2-b}
\end{align}
\begin{Proposition}
	The asymptotically optimal beamformer of the  full-digital transmitter can be expressed as 
	\begin{equation}\label{eq:21}
		\mathbf{f} = \sum_{k=1}^{K}\omega_k \mathbf{h}_k + \sum_{l=K+1}^{K+L}\omega_l \mathbf{h}_l, k \in \mathcal{D}, l \in \mathcal{E}.
	\end{equation} 
	where 
	\begin{align}
		\omega_k &= \sqrt{\frac{1-\sum_{l=K+1}^{K+L}\omega_l^2 \mathbf{h}_l^H\mathbf{h}_l}{(\mathbf{h}^H_k\mathbf{h}_k)^2\sum_{k=1}^{K}\frac{1}{\mathbf{h}^H_k\mathbf{h}_k}}},\label{eq:22} \\
		\omega_l &= \sqrt{\frac{E_0}{P_t(\mathbf{h}^H_{l}\mathbf{h}_{l})^2}}.\label{eq:23}
	\end{align}
\end{Proposition}
\begin{IEEEproof}
	According to {\it Theorem} 1, $ \{\mathbf{h}_k| k \in \mathcal{D}\} $ and $ \{\mathbf{h}_l| l \in \mathcal{E}\} $ are asymptotically orthogonal to one another. Then the optimal solution for (P9) can be expressed as 
\begin{equation}
	\mathbf{f}=\sum_{k=1}^{K}\omega_k \mathbf{h}_k + \sum_{l=K+1}^{K+L}\omega_l \mathbf{h}_l+\sum_{i}\tau_i\mathbf{g}_i ,
\end{equation}
where $ \mathbf{g}_i $ are vectors orthogonal to {both} $ \{\mathbf{h}_k| k \in \mathcal{D}\} $ and $ \{\mathbf{h}_l| l \in \mathcal{E}\} $.
Then, the asymptotically received signal of the $ k $-th DU and the energy harvesting power of the $ l $-th EU can be expressed as 
\begin{align}\label{eq:25}
	\lim_{ N  \rightarrow \infty }y_k&=\lim_{ N  \rightarrow \infty }\sqrt{P_t}\mathbf{h}^H_k\mathbf{f}s+n_k\nonumber \\ 
	& =\lim_{ N  \rightarrow \infty }\sqrt{P_t}\mathbf{h}^H_k\left( {\sum_{j=1}^{K}\omega_j \mathbf{h}_j} + \sum_{l=K+1}^{K+L}\omega_l \mathbf{h}_l+\sum_{i}\tau_i\mathbf{g}_i\right) s+n_k \nonumber \\ 
	& \overset{\text{(a)}}=\underbrace{\sqrt{P_t}\omega_k \mathbf{h}^H_k \mathbf{h}_k s}_{\varrho}+o(\varrho)+n_k, 
\end{align}
\begin{align}\label{eq:26}
	\lim_{ N  \rightarrow \infty }E_l&=\lim_{ N  \rightarrow \infty }||y_l||^2=\lim_{ N  \rightarrow \infty }P_t||\mathbf{h}^H_l\mathbf{f}||^2 \nonumber \\
	& = \lim_{ N  \rightarrow \infty }P_t\left\| \mathbf{h}^H_l\left( \sum_{k=1}^{K}\omega_k \mathbf{h}_k + {\sum_{j=K+1}^{K+L}\omega_j} \mathbf{h}_j+\sum_{i}\tau_i\mathbf{g}_i\right)\right\| ^2 \nonumber \\ 
	&\overset{\text{(a)}} =\underbrace{P_t\left\| \omega_l \mathbf{h}^H_l \mathbf{h}_l \right\| ^2}_{\varrho}+o(\varrho),
\end{align}
where $ f(y)\sim o(y) $ indicates that $ \lim_{y \rightarrow \infty }(f(y)/y)=0 $ and $\text{(a)} $ is realized by using $\mathbf{a}_t^H(r_1,\theta_1,\phi_1)\mathbf{a}_t(r_1,\theta_1,\phi_1)=1 $. Since the third term of $ \mathbf{f} $ have no contribution to both DUs and EUs from Eq. (\ref{eq:25}) and Eq. (\ref{eq:26}), we obtain $ \tau_i=0 $. Moreover, the asymptotically optimal $ 	\mathbf{f} $ is obtained when all DUs have the same achievable rate \cite{10559446}. By considering the constraint of (\ref{eq:object2}a), we have the following equation
\begin{equation}
	\begin{cases}
		\left\| \sum_{k=1}^{K}\omega_k \mathbf{h}_k + \sum_{l=K+1}^{K+L}\omega_l \mathbf{h}_l\right\|^2 = 1, \\
		R_i=R_j, \forall i,j \in \mathcal{D}.
	\end{cases}
\end{equation}
Then, $ \mathbf{f}$ can be obtained by solving the equation, which is experssed as $ 			\mathbf{f} = \sum_{k=1}^{K}\omega_k \mathbf{h}_k + \sum_{l=K+1}^{K+L}\omega_l \mathbf{h}_l$, where $ \omega_k = \sqrt{\frac{1-\sum_{l=K+1}^{K+L}\omega_l^2 \mathbf{h}_l^H\mathbf{h}_l}{(\mathbf{h}^H_k\mathbf{h}_k)^2\sum_{k=1}^{K}\frac{1}{\mathbf{h}^H_k\mathbf{h}_k}}} $ and $ \omega_l = \sqrt{\frac{E_0}{P_t(\mathbf{h}^H_l\mathbf{h}_l)^2}} $.
\end{IEEEproof}
\subsection{Circular H-MIMO beamforming design}
Although fully-digital transmitters offer the highest degree of control and a straightforward solution, their use in high-frequency and near-field scenarios with large antenna arrays is impractical due to the prohibitively high hardware costs. Fortunately, H-MIMO with a hybrid analog-digital architecture can enable the cost-effective implementation of massive antenna arrays to support near-field transmission. When a fully-digital beamformer $ \mathbf{f} $ is given, the H-MIMO counterpart can be designed by minimizing the Euclidean distance, which can be expressed as
\begin{align}
	\text{ (P3):}  & O_{e} \triangleq \min_{ \substack{\mathbf{Q}, \mathbf{b}} } \  \left\| \mathbf{f}-\mathbf{Q}\mathbf{P}\mathbf{b} \right\| , \label{eq:object3} \\
	\text{s.t.} \  & (\ref{eq:object1}a), (\ref{eq:object1}b).  \nonumber
\end{align}

The alternating optimization is conceived to solve problem (P3), where the digital and analog  beamfomer of H-MIMO are separated and optimized iteratively by varying one while fixing the other as the constant.
\subsubsection{Digital beamformer desigen}
By fixing the analog beamformer of H-MIMO $ \mathbf{Q} $, the optimal solution to the digital beamformer $ \mathbf{b} $ can be obtained by 
\begin{equation}\label{eq:29}
	\mathbf{b}=\arg\min_{ \substack{ \mathbf{b}} } \ \left\| \mathbf{f}-\mathbf{Q}\mathbf{P}\mathbf{b} \right\|=(\mathbf{Q}\mathbf{P})^{-1}\mathbf{f},
\end{equation}
which is the least-square solution.
\subsubsection{Analog beamformer desigen}
By fixing the digital beamformer of H-MIMO $ \mathbf{b} $, the subproblem of optimizing the analog beamformer $ \mathbf{Q} $ can be reformulated as
\begin{align}
	\text{ (P4):}  & \min_{ \substack{\mathbf{q}} }\sum_{i=1}^{N} \ \left\| \mathbf{f}(i)- \mathbf{P}(i,:)\mathbf{b}\mathbf{q}(i) \right\| , \label{eq:object4} \\
	\text{s.t.} \  & \mathbf{q}(i)\in \mathcal{Q}, \forall n, \tag{\ref{eq:object4}b}  \nonumber
\end{align}
For the simplicity, let $ \mathbf{x}(i)=\frac{\mathbf{f}(i)}{\mathbf{P}(i,:)\mathbf{b}} $, the corresponding beamforming schemes for three different control modes of H-MIMO analog beamformer can be experessed as follows: 
\begin{itemize}
	\item Amplitude only:
	\begin{align}
		\mathbf{q}(i)=\left\{
		\begin{array}{rcl}
			1,       &      & {\Re(\mathbf{x}(i))      >      1,}\\
			\Re(\mathbf{x}(i)),    &      & {0 < \Re(\mathbf{x}(i)) \leq 1,}\\
			0,     &      & {\Re(\mathbf{x}(i)) \leq 0 .}
		\end{array} \right.
	\end{align}
	\item Binary amplitude:
\begin{align}
	\mathbf{q}(i)=\left\{
	\begin{array}{rcl}
		1,       &      & {\Re(\mathbf{x}(i))      >      1/2,}\\
		0,     &      & {\Re(\mathbf{x}(i)) \leq 1/2. }
	\end{array} \right.
\end{align}
	\item Lorentzian-constrained phase:
	\begin{equation}
		\mathbf{q}(i)=\frac{j+e^{j\phi(i)}}{2}, 
	\end{equation}
\end{itemize}
where $ \phi(i)=\arg(\mathbf{x}(i)-\frac{1}{2}j) $. Then, the power constraint (\ref{eq:object1}a) can be satisfied by the normalization operation $ \mathbf{b}= \frac{1}{\left\| \mathbf{Q}\mathbf{P}\mathbf{b} \right\| }\mathbf{b}$. However, the performance of the Euclidean distance approximation is limited by the strong constraints of the analog beamformer, for which we propose the following relaxated constraint scheme.
\begin{Proposition}
	The hardware constraints for H-MIMO in the analog domain can be equivalently scaled as 
	 \begin{itemize}
		\item Amplitude only, \textit{i.e.}, $ 0<q<a $;
		\item Binary amplitude, \textit{i.e.}, $ q = 0 $ or $ a $;
		\item Lorentzian-constrained phase, \textit{i.e.}, $ q = \frac{a(j+e^{j\phi})}{2}, \phi\in[0,2\pi] $. 
	\end{itemize}
where $ a \in \mathbb {R}^{+} $ is the scaling parameter.
\end{Proposition}
\begin{Proof}
	Since the transmit power constraint is $ 	\left\| \mathbf{Q}\mathbf{P}\mathbf{b}\right\| ^2= 1  $, when the analog beamformer is scaled as $ \mathbf{Q}^{'} = a\mathbf{Q} $, the digital beamformer can be scaled as $ \mathbf{b}^{'}=\frac{1}{a}\mathbf{b} $ to satisfy the power constraint. Furthermore, the scaling of the digital beamformer can be achieved automatically by the normalization operation $ \mathbf{b}= \frac{1}{\left\| \mathbf{Q}\mathbf{P}\mathbf{b} \right\| }\mathbf{b}$. After obtaining the converged relaxed solution $ \mathbf{Q}' $, $ \mathbf{b}^{'} $ and the scaling parameter \(a\) through iteration, appropriate scaling can be applied in both the analog and digital domains to satisfy the original analog domain constraints, \textit{i.e.}, $ \mathbf{Q} = \mathbf{Q}^{'}/a, \mathbf{b}=a\mathbf{b}^{'} $.
\end{Proof} 



Then, the corresponding analog beamforming schemes for Amplitude only and Lorentzian-constrained phase can be rewritten as
\begin{itemize}
	\item Amplitude only:
	\begin{align}\label{34}
		\mathbf{q}(i)=\left\{
		\begin{array}{rcl}
			\Re(\mathbf{x}(i)),    &      & {\Re(\mathbf{x}(i))      >      0,}\\
			0,     &      & {\Re(\mathbf{x}(i)) \leq 0 ,}
		\end{array} \right. 
	\end{align}

	where the scaling parameter $ a  = \Re(\mathbf{x}(i)) $.

	\item Binary amplitude:

	The optimal analog beamformer with binary amplitude can be obtained by solving the following problem

	\begin{align}
		\text{ (P5):}  & \min_{ \substack{\mathbf{q}},a }\sum_{i=1}^{N} \ \left\| \mathbf{x}(i)- \mathbf{q}(i) \right\| , \label{eq:object5} \\
		\text{s. t.} \  & \mathbf{q}(i)=0 \ \mathrm{or} \ a, \forall i, \tag{\ref{eq:object5}b}  \nonumber
	\end{align}
	The optimal $ \mathbf{q}(i) $ can be obtained as 
	\begin{align}\label{36}
		\mathbf{q}(i)=\left\{
		\begin{array}{rcl}
			a,       &      & {\Re(\mathbf{x}(i))      >      a/2,}\\
			0,     &      & {\Re(\mathbf{x}(i)) \leq a/2. }
		\end{array} \right.
	\end{align}
Substituting (36) into (P5), we have 
\begin{align}\label{eq:37}
	a=&\arg \min_{a} \sum_{\Re(\mathbf{x}(i))\leq a/2}\left|\mathbf{x}(i) \right| +  \sum_{\Re(\mathbf{x}(i))>a/2}\left|\mathbf{x}(i)-a \right| \nonumber\\
	=&\arg \min_{a}\sum_{\Re(\mathbf{x}(i))      >      a/2}\left|\Re(\mathbf{x}(i))-a \right|. 
\end{align}
Then, the scaling parameter $ a  $ can be obtained from the median of $ \left\{  \Re(\mathbf{x}(i)) \mid \Re(\mathbf{x}(i)) > a/2 \right\}  $.
Note that the summation term in Eq. (\ref{eq:37}) satisfies the condition $ \Re(\mathbf{x}(i))> a/2 >0 $, thus the scaling parameter $ a  $ is only affected by $ \mathcal{A}= \left\{  \Re(\mathbf{x}(i)) \mid \Re(\mathbf{x}(i)) > 0 \right\} $ and the initial value of $ a $ can be obtianed from $ \mathcal{A} $. Assuming that $ \mathbf{x}(j) \in \mathcal{B}=\left\{  \mathbf{x}(i) \mid \Re(\mathbf{x}(i)) < a/2 \right\} $, then the optimal scaling parameter $ a  $ can be obtained in \textbf{Algorithm I}: 
%		\\ \rule{\textwidth}{0.4pt}
%	 Let $ \mathcal{A}= \left\{  \mathbf{q}(i) \mid \Re(\mathbf{q}(i)) > 0 \right\}  $, do\\
%		1. $ a=\mathrm{Median(\mathcal{A})} $;\\
%		2. Remove $ \mathcal{B}=\left\{  \mathbf{q}(i) \mid \Re(\mathbf{q}(i)) < a/2 \right\} $ from $ \mathcal{A} $;\\
%		Until $ \mathcal{B} = \emptyset $.\\ \rule{\textwidth}{0.4pt}
		\begin{algorithm}[!]
			\linespread{1}
			\caption{Obtaining the scaling parameter $ a $ for Binary amplitude circular H-MIMO}
			\small
			\begin{algorithmic}[1]
				\STATE Initialise $ \mathcal{A}= \left\{  \mathbf{x}(i) \mid \Re(\mathbf{x}(i)) > 0 \right\}, m=\left| \mathcal{A} \right|  $;
				\REPEAT
				\STATE $ a=\frac{1}{m} \sum_{i} \mathbf{x}(i) $;
				\STATE Remove $ \mathcal{B}=\left\{  \mathbf{x}(i) \mid \Re(\mathbf{x}(i)) < a/2 \right\} $ from $ \mathcal{A} $;		
				\UNTIL $ \mathcal{B} = \emptyset $
				\STATE Return $ a$. 
			\end{algorithmic}
		\end{algorithm}




	\item Lorentzian-constrained phase: 

	The optimal analog beamformer with Lorentzian-constrained phase can be obtained from
	\begin{equation}\label{eq:38}
		(a,\phi(i))=\arg \min_{a>0,  \phi(i)} \sum_{i=1}^{N}\left| \frac{a(j+e^{j\phi(i)})}{2}-\mathbf{x}(i) \right| .
	\end{equation}
    Then, the optimal $ \phi(i) $ can be obtained as
    \begin{equation}\label{eq:39}
    	\phi(i)=\arg(2\mathbf{x}(i)-aj).
    \end{equation} 
    Substituting (\ref{eq:39}) into (\ref{eq:38}), we have 
    \begin{equation}\label{eq:40}
    	a=\arg \min_{a>0} \sum_{i=1}^{N}\left|\sqrt{\mathbf{x}(i)^2-a\Im(\mathbf{x}(i))+\frac{a^2}{4}} -\frac{a}{2}\right| ,
    \end{equation}
    which is a single variable non-convex problem. Let $ 	\widetilde{\mathbf{p}} = \arg \max_{i,\Im(\mathbf{x}(i))>0} \left| \mathbf{x}(i)\right| $. For simplicity, the suboptimal scaling parameter $ a $ can be obtained from 
	\begin{equation}
	\frac{a(j+e^{j\phi})}{2}=\widetilde{\mathbf{p}},
	\end{equation}
Then, we have
\begin{align}\label{42}
	\left\{	
	\begin{array}{lr}
		a=\frac{\widetilde{\mathbf{p}}^2}{2\Im(\widetilde{\mathbf{p}})},          \\
		\phi=-2\arctan \frac{\Re(\widetilde{\mathbf{p}})-\Im(\widetilde{\mathbf{p}})}{\Re(\widetilde{\mathbf{p}})+\Im(\widetilde{\mathbf{p}})},            
	\end{array} \right.
\end{align}
Finally, the analog beamformer with Lorentzian-constrained phase can be expressed as
	\begin{equation}\label{43}
		\mathbf{q}(i)=\frac{a(j+e^{j\phi(i)})}{2}, 
	\end{equation}
where $ a=\frac{\widetilde{\mathbf{p}}^2}{2\Im(\widetilde{\mathbf{p}})} $ and $ \phi(i)=\arg(2\mathbf{x}(i)-aj) $. In general, genetic algorithms work well for multi-modal non-convex problems with one variable. Therefore, the genetic algorithms for Eq. (\ref{eq:40}) is used as a benchmark to demonstrate the effectiveness of the low-complexity suboptimal $ a $ in Eq. (\ref{42}).

After obtaining the analog beamformer $ \mathbf{Q}=\mathrm{diag}(\mathbf{q}) $ of H-MIMO and the scaling parameter $ a $, the digital beamformer $ \mathbf{b}$ can be normalized as
\begin{equation}\label{44}
	\mathbf{b}= \frac{1}{\left\| \mathbf{Q}\mathbf{P}\mathbf{b} \right\| }\mathbf{b},
\end{equation}
which keeps the power constraint satisfied. Furthermore, after convergence, the solution satisfying the analog domain hardware constraints can be obtained by
\begin{equation}\label{eq:45}
 \mathbf{Q}^{*} = \mathbf{Q}/a ,\,\,\,\,\, \mathbf{b}^{*} = a\mathbf{b} .
\end{equation}


For clarity, the details of our algorithm for obtaining the optimal digital beamfomer $ \mathbf{b}$ and analog beamfomer $ \mathbf{Q} $ of H-MIMO are summarized in \textbf{Algorithm II}.
\begin{algorithm}[!t]
	\linespread{1}
	\caption{Circular H-MIMO Beamforming for Integrated Data and Energy Multicast System}
	\small
	\begin{algorithmic}[1]
		\REQUIRE ~~\
		The channels of users $\{ \mathbf{h}_k\mid  k \in \mathcal{U} \}$;
		\ENSURE ~~\
		The minimum achievable rate $ R_{\mathrm{min}} $ of DUs, the digital beamformer $ \mathbf{b}\in \mathbb {C}^{N_{RF}\times1} $ and analog beamformer $ \mathbf{Q}\in \mathbb {C}^{N\times N} $ of H-MIMO;
		\STATE Obtain the optimal digital beamforming  $ \mathbf{f}$ by (\ref{eq:21}), (\ref{eq:22}) and (\ref{eq:23});
		\STATE Initialize $ \mathbf{Q} $ and $ a $;
		\REPEAT
		\STATE Update $ \mathbf{b}$ by (\ref{eq:29});

			\STATE \textbf{Case 1: Amplitude Only}
		\IF {$ q\in [0,1] $}
		\STATE Update $ \mathbf{Q} $ and $ a $ by (\ref{34});
		\ENDIF

		\STATE \textbf{Case 2: Binary Amplitude}
		\IF {$ q = 0 $ or $ 1 $}
		\STATE Update $ \mathbf{Q} $ and $ a $ by (\ref{36}) and \textbf{Algorithm I}, respectively;
		\ENDIF

		\STATE \textbf{Case 3: Lorentzian-constrained Phase}
		\IF {$ q = \frac{j+e^{j\phi}}{2}, \phi\in[0,2\pi] $}
		\STATE Update $ \mathbf{Q} $ and $ a $ by (\ref{43}) and (\ref{42}), respectively;
		\ENDIF

		\STATE Normalize $ \mathbf{b}$ by (\ref{44});
		\STATE Caculate $ R_{\mathrm{min}} $ by (\ref{eq:object1});
		\UNTIL $ R_{\mathrm{min}} $ converges
		\STATE Caculate $\mathbf{b} $ and $ \mathbf{Q} $ by (\ref{eq:45});
		\STATE Return $ R_{\mathrm{min}} $, $\mathbf{b} $ and $ \mathbf{Q} $. 
	\end{algorithmic}
\end{algorithm}


\end{itemize}



\subsection{Convergence and Complexity Analysis}
\subsubsection{Convergence}
We briefly explain the convergence of the proposed algorithm. As shown in \textbf{Algorithm II}, the fully digital relaxed solution obtained is in closed form, so it is only necessary to ensure the convergence of the subsequent norm approximation iterations. Specifically, we introduce the superscript \(t\) as the iteration index, and the convergence of the iterations can be summarized as follows:
\begin{align}
	O_{e}(\mathbf{Q},^{(t)},\mathbf{b}^{(t)})&\overset{(a)}\geq O_{e}(\mathbf{Q},^{(t)},\mathbf{b}^{(t+1)}) \overset{(b)}\geq O_{e}(\mathbf{Q},^{(t+1)},\mathbf{b}^{(t+1)}).
\end{align}
where (a) and (b) follow since the updates of digital beamformer $ \mathbf{b} $ in (\ref{eq:29}) and analog beamformer $ \mathbf{Q} $ in (\ref{34}), (\ref{36}), \textbf{Algorithm I} and (\ref{43}) are monotonous.
\subsubsection{Complexity}
The computational complexity of the proposed beamforming design scheme is mainly introduced by the updates of variables $ \mathbf{b} $ and $ \mathbf{Q} $, as shown in (\ref{eq:29}), (\ref{34}), (\ref{36}), \textbf{Algorithm I}, and (\ref{43}), respectively. Let \( N_{RF} \) and \( N_t \) denote the number of RF chains and transmit antennas, respectively. The computational complexity of obtaining the fully-digital beamformer \( \mathbf{f} \) is \( \mathcal{O}((K+L)N_t)\) according to {\it Proposition 1}. Furthermore, the computational complexity of updating \( \mathbf{b} \) is \( \mathcal{O}(N_{RF}N_t + N_{RF}^3) \), primarily attributed to the matrix inversion and the unique properties of the diagonal matrix \( \mathbf{Q} \) in (\ref{eq:29}). Additionally, the three different control methods exhibit similar complexity in the analog domain. Specifically, for the amplitude only and Lorentzian-constrained phase control, the complexity of updating $ \mathbf{Q} $ in (\ref{34}) and in (\ref{43}) is both \( \mathcal{O}(N_{RF}N_t) \). Let $I_b$ denote the number of iterations in \textbf{Algorithm I}, the complexity of updating $ \mathbf{Q} $ in (\ref{36}) and \textbf{Algorithm I} for the Binary amplitude control is \( \mathcal{O}((N_{RF}+I_b)N_t) \). Let $ I_0 $ denote the number of iterations required by the convergence of sum-rate $ R_{\mathrm{min}} $ in \textbf{Algorithm II}. The overall complexity of \textbf{Algorithm II} is approximated as $ \mathcal{O}((K+L)N_t+I_0(N_{RF}N_t+N_{RF}^3)) $ for amplitude only and Lorentzian-constrained control and $ \mathcal{O}((K+L)N_t+I_0((N_{RF}+I_b)N_t+N_{RF}^3)) $ for binary amplitude control.




\section{Numerical results}
In this section, we conduct numerical results to validate the theoretical analysis of spatial orthogonality. The beam patterns of circular antenna array are also presented, and the performance of the proposed beamforming scheme in the circular H-MIMO-assisted IDET system is evaluated. As shown in Figure 1, the center of the circular antenna array is located at the origin, with the antenna plane parallel to the $ xoy $-plane. The number of transmit antennas is set to 800, and the operating frequency is set to 30 GHz \cite{10243590}.
