\title{Quantum-mechanical treatment of two particles in a potential box}
\author{Gottfried Mann\thanks{Leibniz-Institut f\"{u}r Astrophysik Potsdam (AIP), An der Sternwarte 16, D-14482 Potsdam, Germany, e-mail: gmann@aip.de}}
