%\bar{d} & = & \frac{1}{L^{2}} \times \nonumber \\
%        &   & \left [ \int_{0}^{L} \text{d}x_{1} \int_{0}^{x_{1}} \text{d}x_{2} (x_{1}-x_{2}) + %\int_{0}^{L} \text{d}x_{2} \int_{0}^{x_{2}} \text{d}x_{1} (x_{2}-x_{1}) \right ]  \nonumber \\
%        & = & \frac{L}{3}
%\end{eqnarray}
%
Such a value is expected, since both particles have the same distance to the walls of the potential box and to each other in the mean sense. In order to obtain the mean square $\overline{(\Delta d)^{2}}$ of the fluctuations of the distance $d$ between both particles around its mean value $\bar{d}$, the quantity
%
\begin{equation}
\label{eqn:55}
\overline{d^{2}} = \int \text{d}x_{1} \text{d}x_{2} \cdot \|x_{1}-x_{2}\|^{2} \cdot w_{2}(x_{1},x_{2}) = \frac{L^{2}}{6}
\end{equation}
