\section{Application to the power iteration with momentum}\label{sec:power}
In this section, we describe a direct application of Theorem
\ref{newpolyboundedgrow} to accelerating the power iteration. 
The intuition for the algorithms introduced in this section results from  scaling and dilating  the polynomial $P_n$ as follows:
$$
\tilde{P}_n(x) = \left(\frac{2\lambda}{3} \right)^n P_n(x/\lambda), \quad \text{for} \quad n \ge 0,
$$
such that $\tilde{P}_{0}(z) = 1$, $\tilde{P}_1(z) = \frac{2}{3} z$, and $\tilde{P}_2(z) = \frac{4}{9} z^2$, and
\begin{equation} \label{scaledilatepn}
\tilde{P}_{n+1}(z) = z \tilde{P}_n(z) - \tfrac{4 \lambda^3}{27}\tilde{P}_{n-2}(z),
\quad \text{for}  \quad n \ge 2.
\end{equation}
In particular, take note of the constant $4\lambda^3/27$, which will make an appearance below.

\subsection{Notation} \label{algnotation}
The following notation and assumptions are used throughout this section. Let $\vect{A} \in \mathbb{C}^{n \times n}$ be a diagonalizable matrix 
(this assumption could be generalized) 
with eigenvalues $\lambda_1,\ldots,\lambda_n$. Assume $\vec{A}$ has a unique eigenvalue of largest magnitude and its other eigenvalues are sorted in descending order by magnitude
$$
|\lambda_1| > |\lambda_2| \ge \cdots \ge |\lambda_n|.
$$
Let $\vec{\phi}_1,\ldots,\vec{\phi}_n$ be the corresonding normalized eigenvectors.
Given $\vect{x},\vect{y} \in \mathbb{C}^n$, let $\langle \vec{x}, \vec{y} \rangle = \sum_{i=1}^n \vec{x}_i \overline{\vec{y}}_i$ and $\|\vect{x}\|_2 = \sqrt{\langle \vect{x}, \vec{x} \rangle}$.

\subsection{Algorithms} \label{secalgorithms}
First, in Algorithm \ref{alg1}, we precisely state the power method, which we use for comparison and to initialize the proposed methods.
%
\begin{algorithm}[h!] 
\caption{Power method}
\label{alg1}
\begin{algorithmic}[1]
\REQUIRE Matrix $\vect{A} \in \mathbb{R}^{n \times n}$, vector $\vect{v}_0 \in \mathbb{R}^n$,  $N \in \mathbb{N}$
\STATE Set $h_0 = \|\vect{v}_0\|_2$ and $\vect{x}_0 = h_{0}^{-1}\vect{v}_{0}$
\FOR{$k = 0,\dots,N-1$}
    \STATE Set $\vect{v}_{k+1} = \vect{A} \vect{x}_k$
    \STATE Set $h_{k+1} = \|\vect{v}_{k+1}\|_2$ and $\vect{x}_{k+1} = h_{k+1}^{-1}\vect{v}_{k+1}$
    \STATE Set $\nu_{k} = \langle \vect{v}_{k+1}, \vec{x}_k \rangle$ and $d_{k} = \| \vect{v}_{k+1} - \nu_{k}\vect{x}_k\|_2$ \hfill $\triangleright$ \emph{defined for later use}
\ENDFOR
\RETURN $\vec{x}_N$
\end{algorithmic}
\end{algorithm}
%
Next, in Algorithm \ref{algnew}, we present the Deltoid Momentum Power Method, a modification of the power method inspired by Theorem \ref{newpolyboundedgrow}.
%
In \cite{xu2018accelerated}, a momentum accelerated power iteration for problems with real eigenvalues is developed based on the recursion for Chebyshev polynomials. As shown in \cite{austin2024dynamically,xu2018accelerated}, this iteration given by $\vect{u}_{k+1} = \vec{A}\vect{x}_k - \beta/h_k \vect{x}_{k-1}$ with normalization $\vect{x}_k = \vect{u}_k/h_k$, $h_k =\|\vect{u}_k\|_2$, can be written in terms of a power iteration applied to an augmented matrix. 
In \cite{xu2018accelerated} it is shown that the optimal parameter is $\beta = \lambda_2^2/4$. The main contribution of \cite{austin2024dynamically} was showing the optimal (static) method could be efficiently approximated by a dynamically set parameter based on a posteriori information, 
without a priori knowledge of $\lambda_2$.


Similarly, Algorithm \ref{algnew}, which is based on a Faber polynomial recursion, can be expressed in terms of a power iteration applied to an augmented matrix.
Observe that writing $\vect{x}_n = \tilde P_n(\vec{A})\vect{x}_0$, the rescaled polynomial iteration \eqref{scaledilatepn} with $z$ replaced by $\vec{A}$,  defines, up to normalization, a power-like iteration $\vect{x}_{n+1} = \vec{A} \vect{x}_n - \beta \vect{x}_{n-2}$, 
where, as in \eqref{scaledilatepn}, the optimal choice for parameter $\beta$ is
$\beta = 4 \lambda_2^3/27$.
An appropriate normalization follows naturally from formulating the accelerated iteration as a power iteration applied to an augmented matrix $\vec{A}_\beta$ given by
\[ \vect{A}_\beta = \begin{pmatrix}
\vect{A} & \vect{0} & -\beta \vect{I}\\
\vect{I} & \vect{0} & \vect{0} \\
\vect{0} & \vect{I} & \vect{0} \end{pmatrix}.
\]
The accelerated iteration 
$\vect{u}_{k+1} = \vect{A} \vect{x}_{k} - (\beta/(h_k h_{k-1})) \vect{x}_{k-2}$ 
in line 3 of Algorithm \ref{algnew} 
results from applying the power iteration to the augmented matrix $\vect{A}_\beta$ by
$\tilde{\vect{u}}_{k+1} = \vect{A}_\beta \tilde{\vect{x}}_{k}$,  for $\tilde{\vect{x}}_k = \tilde{\vect{u}}_k/h_k$ 
and $h_k = \|\vect{u}_k\|_2$ where $\vect{u}_k$
 is the $n$-dimensional vector consisting of the first $n$ entries of $\tilde{\vec{u}}_k$. 
 The details can be found by following the arguments in \cite{austin2024dynamically}.
 Algorithm \ref{algnew} as it is presented is efficient but not practical, as $\lambda_2$ is in general a priori unknown.  A dynamic method to approximate Algorithm \ref{algnew}, analogous to the approach of \cite{austin2024dynamically}, is presented in Subsection \ref{subsec:dynamic}.

\begin{algorithm}[h!] 
\caption{Deltoid Momentum Power Method}
\label{algnew}
\begin{algorithmic}[1]
\REQUIRE 
Matrix $\vect{A} \in \mathbb{R}^{n \times n}$,
vector $\vect{v}_0 \in \mathbb{R}^n$,  parameter $\beta  \in \mathbb{C}$, $N \in \mathbb{N}$
\STATE Do two iterations of Algorithm \ref{alg1} with inputs $\frac{2}{3} \vect{A}$ and $\vec{v}_0$
\FOR{$k = 2, \dots, N - 1$} 
\STATE Set $\vect{v}_{k+1} = \vect{A} \vect{x}_k$
\STATE{Set $\vect{u}_{k+1} = \vect{v}_{k+1} - (\beta /(h_{k} h_{k-1})) \vect{x}_{k-2}$}
\STATE{Set $h_{k+1} = \|\vect{u}_{k+1}\|_2$ and $\vect{x}_{k+1} = h_{k+1}^{-1} \vect{u}_{k+1}$}
%\STATE Set $\vect{v}_{k+2} = \vect{A} \vect{x}_{k+1}$
\ENDFOR
\RETURN  $\vec{x}_N$ 
\end{algorithmic}
\end{algorithm}

\subsection{Theoretical guarantees} \label{secguarantee}

\begin{theorem} \label{algoworks} 
In addition to the assumptions of Section \ref{algnotation}, assume that $\lambda_* \in \mathbb{C}$ is given such that
$|\lambda_*| < |\lambda_1|$ and
\begin{equation} \label{eqdeltoidcondition}
\lambda_2,\ldots,\lambda_n \in \lambda_* \Gamma  = \{ \lambda_* z \in \mathbb{C} : z \in \Gamma\}.
\end{equation}
Let $\vec{v}_0 \in \mathbb{R}^n$ be an initial vector with eigenbasis expansion $\vec{v}_0 = \sum_{j=1}^n a_j \vect{\phi}_j$. 
Run Algorithm \ref{algnew} with inputs $\vect{A}$, $\vect{v}_0$, $\beta = 4\lambda_*^3/27$, and $N$. Then, the output $\vect{x}_N$ satisfies
$$
\min_{\theta \in [0,2\pi)} \| \vec{x}_N  - e^{i \theta}\vec{\phi}_1\|_2 = \mathcal{O} \left( \left(1+\sqrt{\left|\frac{\lambda_1}{\lambda_*}\right| - 1}\right)^{-N} \right),
$$
as $N \to \infty$, where the implied constant in the big-$\mathcal{O}$ only depends on $\|\vect{v}_0\|_2/|a_1|$.
\end{theorem}

The proof of Theorem \ref{algoworks} is given in Section \ref{proofalgoworks}. 

\begin{remark}[Optimizing the error bound]  \label{rmkconv}
Under the assumption that \eqref{eqdeltoidcondition} holds with $\lambda_*=\lambda_2$, the error bound is optimized when $\lambda_* = \lambda_2$. Indeed, if $|\lambda_*| < |\lambda_2|$, then the condition $\lambda_2,\ldots,\lambda_n \in \lambda_* \Gamma$ cannot hold since $\Gamma$ is contained in the unit disk. Assume $\lambda_* = \lambda_2$ and 
set $\varepsilon = |\lambda_1/\lambda_2| - 1$. Then, for small $\varepsilon$,
in terms of the convergence rate, Theorem \ref{algoworks} says that the error for the estimate of $\vec{\phi}_1$ decays like 
$$
(1+\sqrt{\varepsilon})^{-N} \approx e^{-N \sqrt{\varepsilon}},
\quad \text{compared to} \quad
\left|\frac{\lambda_2}{\lambda_1} \right|^N = (1+\varepsilon)^{-N} \approx e^{-N \varepsilon},
$$
for the power method. Note that $\varepsilon$ can be interpreted as the size of the spectral gap $|\lambda_1| - |\lambda_2|$ relative to $|\lambda_2|$. Thus, in the critical case when the gap is small, 
we achieve a square root gain over the power method with respect to the relative spectral gap.
\end{remark}


\subsection{Dynamic parameter assignment}\label{subsec:dynamic}
In this section, we assume that \eqref{eqdeltoidcondition} holds with $\lambda_*=\lambda_2$ such that $\lambda_* = \lambda_2$ optimizes the error bound, see Remark \ref{rmkconv}.
we will consider an efficient and practical approximation of Algorithm \ref{algnew} in which the optimal parameter $\beta = 4\lambda_2^3/27$ is approximated by a sequence $\beta_k$ that does not rely on a priori knowledge of $\lambda_2$. The main idea follows that in \cite{austin2024dynamically}.  For the remainder of this section, in addition to the assumptions of Section \ref{algnotation}, we assume
$\lambda_1, \lambda_2 \in \mathbb{R}$, $\lambda_1 > \lambda_2 > 0$.

In light of Remark \ref{rmkconv}, the convergence rate, given by
the ratio of consecutive normed errors for Algorithm \ref{algnew} is asymptotically governed by
$e^{-(N+1)\sqrt{\varepsilon}}/e^{-N\sqrt{\varepsilon}} = e^{-\sqrt{\varepsilon}}$. Writing $\varepsilon$ in terms of $r = |\lambda_2/\lambda_1|$ we have $\varepsilon = 1/r -1$, yielding a convergence rate
$\rho(r) = e^{-\sqrt{1/r -1}}$,
a bijective map $(0,1) \rightarrow (0,1)$. Solving for $r$ in terms of $\rho$ in that interval yields
\begin{align}\label{eqn:rofrho}
r(\rho) = \frac{1}{(\log \rho)^2 + 1}.
\end{align}
In the dynamic Algorithm \ref{alg:dymo2}, we monitor the convergence rate $\rho_k$ given by the ratio of normed residual vectors (denoted $d_k$), and use \eqref{eqn:rofrho} to approximate $r$ by $r_{k+1}$, which is used together with the Rayleigh quotient (denoted $\nu_k$) to produce $\beta_{k}$.
The additional assumption that the first two eigenvalues are real and positive comes from the use of the ratio of normed residuals to approximate $\rho$, which produce a real and positive approximation to $r$ via $\eqref{eqn:rofrho}$, by which the approximation to $\lambda_2$ necessarily agrees with the sign of the Rayleigh quotient. 

%% -- --------------------------------------------------------------------
\begin{algorithm}
\caption{Dynamic Deltoid Momentum Power Method}
\label{alg:dymo2}
\begin{algorithmic}[1]
\REQUIRE  Matrix $\vect{A} \in \mathbb{R}^{n \times n}$, vector $\vect{v}_0  \in \mathbb{R}^n$, $N \in \mathbb{N}$.
\STATE Do two iterations of Algorithm \ref{alg1} with inputs $\frac{2}{3} \vect{A}$ and $\vec{v}_0$
\FOR{$k =2,\ldots,N-1$} 
\STATE{Set $\vect{v}_{k+1} = \vect{A} \vect{x}_{k}$, $\nu_{k} = \langle \vect{v}_{k+1}, \vect{x}_{k}\rangle$ and $d_{k} = \|\vect{v}_{k+1} - \nu_{k} \vect{x}_{k}\|_2$}
\STATE{Set $\rho_{k-1} = \min\{d_{k}/d_{k-1},1\}$  and $r_k = 1/((\log \rho_{k-1})^2 + 1)$}
\STATE{Set $\beta_k = 4(\nu_{k} r_{k})^3/27$}
\STATE{Set $\vect{u}_{k+1} = \vect{v}_{k+1} - (\beta_k/(h_k h_{k-1})) \vect{x}_{k-2}$}
\STATE{Set $h_{k+1} = \|\vect{u}_{k+1}\|_2$ and $\vect{x}_{k+1} = h_{k+1}^{-1} \vect{u}_{k+1}$}
\ENDFOR
\RETURN $\vec{x}_N$
\end{algorithmic}
\end{algorithm}
