\section{Formulas for roots and coefficients}
\label{appendixA}

This appendix contains formulas for the roots of a cubic polynomial \eqref{cas1trig} and formulas for the solution to a three-by-three linear system of equations involving the roots \eqref{cas2trig}. The correctness of these equations can be verified by direct substitution. As the calculations, although elementary, are somewhat lengthy, we omit them for brevity. Additionally, a Mathematica notebook verifying these equations by direct substitution is included in the GitHub repository associated with this paper:
\begin{center}\url{https://github.com/petercowal/higher-order-momentum-power-methods}.
\end{center}

\begin{lemma}
Let $z = (1+\delta)^{1/3}$ for $\delta > 0$. Then, the roots of the polynomial 
\begin{equation}  \label{pzappendix}
p_z(r) = r^3 - \frac{3z}{2}r^2 + \frac{1}{2}
\end{equation}
are
\begin{equation} \label{cas1trig}
\begin{split}
r_1 &= \frac{1}{2} (\delta+1)^{1/3} \left(1 + 2 \cos \left( \frac{2}{3} \arccot \left( \sqrt{\delta} \right) \right) \right)\\
r_2 &= \frac{1}{2} (\delta+1)^{1/3} \left(1 + 2 \cos \left( \frac{2}{3} \arccot \left( \sqrt{\delta} \right) + \frac{2 \pi}{3} 
\right) \right)\\
r_3 &= \frac{1}{2} (\delta+1)^{1/3} \left(1 + 2 \cos \left( \frac{2}{3} \arccot \left( \sqrt{\delta} \right) - \frac{2 \pi}{3}
\right) \right).\\
\end{split}
\end{equation}
\end{lemma}

\begin{lemma}
Let $z = (1+\delta)^{1/3}$ for $\delta > 0$, and
 $r_1,r_2,r_3$ be as defined in
\eqref{cas1trig}. Then, the linear system of equations
\begin{equation} \label{coeffeqappedix}
\begin{split}
c_1 + c_2 + c_3 =& 1 \\
c_1 r_1 + c_2 r_2 + c_3 r_3 =& z \\
c_1 r_1^2 + c_2 r_2^2 + c_3 r_3^2 =& z^2
\end{split}
\end{equation}
has solution
\begin{equation} \label{cas2trig}
\begin{split}
c_1 =& \frac{1}{3} \left(1 + (\delta+1)^{1/2} \sin \left(\frac{1}{3} \arccot\left(\sqrt{\delta}\right)\right)\right) \\[5pt]
c_2 =& \frac{1}{3} \left(1 + (\delta+1)^{1/2} \sin \left( \frac{1}{3} \arccot\left(\sqrt{\delta}\right)
- \frac{2\pi}{3} \right)\right) \\[5pt]
c_3 =& \frac{1}{3} \left(1 + (\delta+1)^{1/2} \sin \left(\frac{1}{3} \arccot\left(\sqrt{\delta}\right)
+ \frac{2\pi}{3}  \right)\right).\\[5pt]
\end{split}
\end{equation}
\end{lemma}


\section{Estimates on roots and coefficients} \label{appendixB}

In this section, we derive estimates on the roots $r_1,r_2,r_3$ of the polynomial $p_z(r)$ defined in \eqref{pzappendix}, and coefficients $c_1,c_2,c_3$ defined by  \eqref{coeffeqappedix}. The key estimate is Lemma \ref{lemtrig} that establishes a lower bound on $r_1$ for $z=1+\varepsilon$, for small $\varepsilon > 0$. We establish both an upper and lower bound to show that our analysis is sharp up to lower-order terms.

\begin{lemma}  \label{lemtrig}
Let $z = 1+\varepsilon$. Then,
$1+ \sqrt{\varepsilon} \le r_1 \le 1 + \sqrt{\varepsilon} + 2\varepsilon$, for
$0 \le \varepsilon \le 1/4$.
\end{lemma} 


\begin{proof}[Proof of Lemma \ref{lemtrig}]
Let $z = 1+\varepsilon = (1+\delta)^{1/3}$ for $\delta > 0$. 
We establish upper and lower bounds on $r_1$ by using the formula \eqref{cas1trig}. 
Note that the assumption $0 \le \varepsilon \le 1/4$ implies that $0 \le \delta \le (1+1/4)^3 - 1 < 1$. Recall that alternating series whose terms decrease in magnitude can be bounded above and below by truncating the series at a positive and negative term, respectively; by applying this alternating series bound to Taylor series, we can deduce that
\begin{eqnarray}
&1 + \frac{\delta}{3} - \frac{\delta^2}{9} \le (1+\delta)^{1/3} \le 1 + \frac{\delta}{3},
\label{est1} \\
&\frac{\pi}{3} - \frac{2}{3} \sqrt{\delta} \le \frac{2}{3} \arccot(\sqrt{\delta}) \le \frac{\pi}{3} - \frac{2}{3}\sqrt{\delta} + \frac{2 \delta^{3/2}}{9},
 \label{est2} \\
&\frac{1}{2} + \frac{\sqrt{3}}{2} x - \frac{x^2}{4} -\frac{x^3}{4 \sqrt{3}} \le \cos(\pi/3-x) \le  \frac{1}{2} + \frac{\sqrt{3}}{2} x,
\label{est3} 
\end{eqnarray}
where the final series alternates every two terms. 
Using \eqref{est1}, \eqref{est2}, and \eqref{est3}, 
to upper and lower bound the formula for $r_1$ in \eqref{cas2trig} gives
\begin{equation} \label{combine1}
\frac{2 \delta^{7/2}}{243 \sqrt{3}}-\frac{11 \delta^{5/2}}{81 \sqrt{3}}+\frac{7 \delta^{3/2}}{27 \sqrt{3}}+\frac{\delta^3}{81}-\frac{4 \delta^2}{27}+\frac{2 \delta}{9}+\frac{\sqrt{\delta}}{\sqrt{3}}+1  \le r_1  \le  
1 + \frac{\sqrt{\delta}}{\sqrt{3}} + \frac{\delta}{3} -\frac{\delta^{5/2}}{9 \sqrt{3}}.
\end{equation}
Since we may assume $0 \le \delta < 1$, we can deduce the simplified bound
\begin{equation} \label{combine1cor}
1 + \frac{\sqrt{\delta}}{\sqrt{3}} \le r_1 \le 1 + \frac{\sqrt{\delta}}{\sqrt{3}} + \frac{\delta}{3}.
\end{equation}
Next, we set $1+\varepsilon = (1+\delta)^{1/3}$, which implies
\begin{equation} \label{eps}
3\varepsilon + 3 \varepsilon^2 + \varepsilon^3 = \delta.
\end{equation}
Combining \eqref{combine1cor} and \eqref{eps} gives
\begin{equation} \label{deltaeps}
1 + \frac{\sqrt{3\varepsilon + 3 \varepsilon^2 + \varepsilon^3}}{\sqrt{3}} \le r_1 \le 1 + \frac{\sqrt{3\varepsilon + 3 \varepsilon^2 + \varepsilon^3}}{\sqrt{3}} + \frac{3\varepsilon + 3 \varepsilon^2 + \varepsilon^3}{3}.
\end{equation}
We note that on both sides of \eqref{deltaeps}, we can factor out 
$\sqrt{3 \varepsilon}$
to write
\begin{equation} \label{factoreps3}
\frac{\sqrt{3\varepsilon + 3 \varepsilon^2 + \varepsilon^3}}{\sqrt{3}} = \sqrt{\varepsilon} \sqrt{1 + \varepsilon + \varepsilon^2/3}.
\end{equation}
Using the inequality $1 \le \sqrt{1+x} \le 1 + x/2,$ can bound \eqref{factoreps3} above and below by
\begin{equation} \label{epsbound}
\sqrt{\varepsilon} \leq \sqrt{\varepsilon} \sqrt{1 + \varepsilon + \varepsilon^2/3} \le \sqrt{\varepsilon} + \frac{1}{2}\varepsilon^{3/2} + \frac{1}{6}\varepsilon^{5/2} \leq \sqrt{\varepsilon} + \frac{1}{4}\varepsilon + \frac{1}{48}\varepsilon,
\end{equation}
where we also use our assumption that $0 \le \varepsilon \le 1/4$.
From \eqref{deltaeps}, \eqref{epsbound}, the fact that $0 \le \varepsilon \le 1/4$, 
we can deduce from the simplified bound $1+ \sqrt{\varepsilon} \le r_1 \le 1 + \sqrt{\varepsilon} + 2\varepsilon$.
\end{proof}

\begin{lemma} \label{extendingbound}
Let $z = 1 + \varepsilon$. Then
$r_1 \ge 1 + \sqrt{\varepsilon},$ for $1 \ge \varepsilon \ge 1/4.$
\end{lemma}
\begin{proof}[Proof of Lemma \ref{extendingbound}]
From  \eqref{cas1trig} it is clear that $r_1$ is an increasing function of $\delta$, which is an increasing function of $\varepsilon$. Hence $r_1 = r_1(\varepsilon)$ is an increasing function of $\varepsilon$.
For $1/4+k/8 \le \varepsilon \le (k+1)/8$ the function $r_1(\varepsilon)$ is bounded below by $r_1(1/4+k/8)$ while $1+\sqrt{\varepsilon}$ is bounded above by $1+\sqrt{1/4+(k+1)/8}$. 
One can verify that 
$$
 r_1(1/4+k/8) - 1+\sqrt{1/4 + (k+1)/8} > 0,
%(0.090124,0.22088,0.35034,0.48068,0.6125,0.7462,0.88158).
\quad \text{for} \quad  k \in \{1,\ldots,7\},
$$
which implies $r_1(\varepsilon) \ge 1+\sqrt{\varepsilon}$ on $[1/4,1]$.
\end{proof}

\begin{lemma} \label{extendingbound2}
Let $z = 1 + \varepsilon$. Then
$r_1 \ge 1 + \sqrt{\varepsilon}$, for $\varepsilon \ge 1$.
\end{lemma}
\begin{proof}
From  \eqref{cas1trig}, $r_1$ is a product of $(\delta+1)^{1/3}$ and $(1+2\cos \left( \frac{2}{3} \arccot \left( \sqrt{\delta} \right) \right))/2$, which are both increasing functions of $\delta$. Note $\delta= 7$, that corresponds to $\varepsilon =1$. Using the fact that
$\left(1+2\cos \left( \frac{2}{3} \arccot \left( \sqrt{7} \right)\right) \right) \approx
1.47112$ gives
$$
r_1 \ge (1+\delta)^{1/3} \frac{1}{2}\left(1+2\cos \left( \frac{2}{3} \arccot \left( \sqrt{7} \right)\right) \right) \ge (1+\delta)^{1/3} \cdot 1.47.
$$
Using the fact that $\delta = 3\varepsilon + 3 \varepsilon^2 + \varepsilon^3$ gives
$$
r_1 \ge (1+3\varepsilon + 3 \varepsilon^2 + \varepsilon^3)^{1/3}\cdot 1.47 \ge 1 + \sqrt{\varepsilon},
\quad \text{for} \quad \varepsilon \ge 1.
$$
\end{proof}

\begin{lemma} \label{lowerboundc1}
Let $z = 1+\varepsilon$. We have
$c_1 \ge 1/3$, for $\varepsilon \ge 0.$
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lowerboundc1}]
This result is a consequence of the formula for $c_1$ in \eqref{cas2trig}: note that $\arccot(\sqrt{\delta})/3 \in [0,\pi/6]$, which implies that the sine of this quantity is nonnegative. We conclude that
$c_1 \ge 1/3$.
\end{proof}


\begin{lemma}\label{estr2r3c2c3}
Let $z = 1+\varepsilon$. Then,
$r_3 > -r_2 > 0$ and  $c_3 > -c_2 > 0$ for $\varepsilon > 0.$
\end{lemma}

\begin{proof}[Proof of Lemma \ref{estr2r3c2c3}]
This result is a consequence of the formulas for $r_2,r_3$ and $c_2,c_3$ in \eqref{cas1trig} and \eqref{cas2trig}, respectively. Indeed, in order to observe that $r_3 > -r_2 > 0$, we can ignoring the leading factor of $(1/2) (1+\delta)^{1/3}$, which is the same for both $r_2$ and $r_3$ and perform the substitution $x = (2/3) \arccot(\sqrt{\delta})$. With this substitution the inequality $r_3 > -r_2 > 0$ is equivalent to the inequality 
$$
1 + 2 \cos\left(x - \frac{2\pi}{3} \right) > - \left(1+ 2\cos\left(x + \frac{2 \pi}{3} \right) \right) > 0, \quad \text{for} \quad x \in [0,\pi/3], 
$$
which is straightforward to verify.  
The inequality $c_3 > -c_2 > 0$ can similarly be established.
\end{proof}





