for all messages $s\in S^{0}(\mu)$ and thus
\[
V((\pi,S)\vert\mu+\varepsilon d)=\sum_{j}\sum_{s\in S^{1}(\mu+\varepsilon d)}\pi_{j}(s)(\mu_{j}+\varepsilon d_{j})\leq\sum_{j}\sum_{s\in S^{1}(\mu)}\pi_{j}(s)(\mu_{j}+\varepsilon d_{j}).
\]
Because our choice of $z$ implies
\begin{align*}
\sum_{j}\sum_{s\in S^{1}(\mu)}\pi_{j}(s)(\mu_{j}+\varepsilon d_{j}) & =\alpha+\varepsilon(zd_{i}+\sum_{j>i}d_{j})<\alpha,
\end{align*}
we have $V((\pi,S)\vert\mu+\varepsilon d)<\alpha$. If instead $\mu-\varepsilon d\in\mathcal{P}(\alpha)$,
then we have $S^{0}(\mu)\subset S^{0}(\mu-\varepsilon d)$ by the
same argument as above and thus
\[
V((\pi,S)\vert\mu-\varepsilon d)=\sum_{j}\sum_{s\in S^{1}(\mu-\varepsilon d)}\pi_{j}(s)(\mu_{j}-\varepsilon d_{j})\leq\sum_{j}\sum_{s\in S^{1}(\mu)}\pi_{j}(s)(\mu_{j}-\varepsilon d_{j}).
\]
Because our choice of $z$ implies
\begin{align*}
\sum_{j}\sum_{s\in S^{1}(\mu)}\Delta_{j}\pi_{j}(s)(\mu_{j}-\varepsilon d_{j}) & =-\varepsilon(z\Delta_{i}d_{i}+\sum_{j>i}\Delta_{j}d_{j})<0,
\end{align*}
there exists a message $s^{*}\in S^{0}(\mu-\varepsilon d)\cap S^{1}(\mu)$
with $\sum_{j}\pi_{j}(s^{*})(\mu_{j}-\varepsilon d_{j})>0$. Together,
we obtain
\[
V((\pi,S)\vert\mu-\varepsilon d)\leq\sum_{j}\sum_{s\in S^{1}(\mu)\setminus\{s^{*}\}}\pi_{j}(s)(\mu_{j}-\varepsilon d_{j})<\sum_{j}\sum_{s\in S^{1}(\mu)}\pi_{j}(s)(\mu_{j}-\varepsilon d_{j})\approx\alpha.
\]
This establishes the argument for case $i\in L$ in subcase (\ref{one direction}).
Subcase (\ref{the other direction}) is symmetric. 

Second, suppose instead $i=\max L+1$ and consider subcase (\ref{one direction}).
Choose $z\in(0,1)$ to satisfy $zd_{i-1}+\sum_{j\geq i}d_{j}<0<zd_{i-1}\Delta_{i-1}+\sum_{j\geq i}d_{j}\Delta_{j}$
and recall again that Lemma \ref{Lemma: rationalizing P} provides
a cutoff signal $(i-1,z)$ and prior with full support $\mu$ such
that $(i(\mu),z(\mu))=(i-1,z)$. At this point, The argument is the
same as in the $i\in L$ case, with subcase (\ref{the other direction})
again symmetric to its counterpart.
\end{proof}
%

\subsection{Section \ref{Section: Simple experiments}}
\begin{proof}[Proof of Proposition \ref{Proposition: simple character}]
We write $d^{ij}$ for the vector in $\mathbb{R}^{n}$ satisfying
$d_{i}^{ij}\equiv1$ and $d_{j}^{ij}\equiv-1$ with $0$ in all other
entries. Suppose $A$ is simple. Let $\{\Sigma_{1},...,\Sigma_{k}\}$
be the associated partition of $\Omega$, let $\tau\equiv(\tau_{1},...,\tau_{k})$
be an arbitrary selection from the correspondence $t\rightrightarrows\Sigma_{t}$,
define experiment $B\equiv(B_{1},...,B_{k})$ by $B_{t}\equiv A_{\tau_{t}}$,
and let $\mu$ be any prior with full support. First, we claim $A_{i}=B_{t}$
for all $i\in\Sigma_{t}$. To see why, let $i,j\in\Sigma_{t}$ be
distinct and define $\nu\equiv\mu+\varepsilon d^{ij}$. Because $A$
is simple and $\nu(\Sigma_{t})=\mu(\Sigma_{t})$ for all $t$, we
have $\nu\in\mathcal{Q}(A\mu)$ and hence $(\nu-\mu)\in\mathcal{D}$.
Accordingly, $Ad^{ij}=A_{i}-A_{j}=0$, as claimed. Second, we claim
$B$ has full rank. To see why, suppose to the contrary that $Bx=0$
for some $(x_{1},...,x_{k})\neq(0,...,0)$ and let $(y_{1},...,y_{n})$
be any vector satisfying $\sum_{i\in\Sigma_{j}}y_{i}=x_{j}$ for all
indices $j$. Because $Ay=Bx=0$, we have $\nu\equiv(\mu+\varepsilon y)\in\mathcal{Q}(A\mu)$.
Further, because there exists index $t$ with $\sum_{i\in\Sigma_{t}}y_{i}=x_{t}\neq0$,
we have $\nu(\Sigma_{t})\neq\mu(\Sigma_{t})$. This contradicts our
hypothesis that $A$ is simple, and we conclude that $B$ indeed has
full rank.

Conversely, suppose there exists a partition $\{\Sigma_{1},...,\Sigma_{k}\}$
of $\Omega$ and an experiment $B\equiv(B_{1},...,B_{k})$ such that
(i) $A_{i}=B_{t}$ for all $i\in\Sigma_{t}$ and (ii) $B$ has full
rank. Let $\mu,\nu\in\Delta(\Omega)$, define $(x_{1},...,x_{k})\equiv(\mu(\Sigma_{1})-\nu(\Sigma_{1}),...,\mu(\Sigma_{k})-\nu(\Sigma_{k}))$,
and note that $\nu\in\mathcal{Q}(A\mu)\iff A(\mu-\nu)=Bx=0\iff x=0$.
Accordingly, $A$ is simple. 
\end{proof}
%
\begin{proof}[Proof of Theorem \ref{Theorem: which simple experiments are ordered}]
We again write $d^{ij}$ for the vector in $\mathbb{R}^{n}$ satisfying
$d_{i}^{ij}\equiv1$ and $d_{j}^{ij}\equiv-1$ with $0$ in all other
entries. Our approach is to show that $A$ is ordered if and only
if it satisfies one of the two criteria in the statement of the result.
Theorem \ref{Theorem: reliable iff ordered} then implies the result.

Suppose $A$ separates every low state and choose $d\in\mathcal{D}$.
Because $\sum_{i\in L}d_{i}=\sum_{i\in L}0=0$ by hypothesis and $\sum_{i}d_{i}=0$
by definition, we have $\sum_{i\in H}d_{i}=0$. By normalization,
then, we also have $\sum_{i\in H}\Delta_{i}d_{i}\geq0$. It follows
quickly from $d_{i}=0$ for all $i\in L$ that $\sum_{j\geq i}d_{i},\sum_{j\geq i}\Delta_{i}d_{i}\geq0$
for all $j=1,...,\max L+1$, and we conclude that $A$ is ordered.

Alternatively, suppose that $A$ pools exactly one pair of states
$(i,j)\in H\times L$ and separates all other states. It is immediate
that (i) $\mathcal{D}=\{\kappa d^{ij}\vert\kappa\geq0\}$ and (ii)
$\kappa d^{ij}$ satisfies both the frequency and the incentive compatibility
criteria for all $\kappa\geq0$. Accordingly, $A$ is ordered.

Conversely, suppose $A$ satisfies neither property. There are four
subcases. First, if there exist states $j<i\leq\max L$ with $i,j\in\Sigma_{t}$,
then $d^{ij}\in\mathcal{D}$. Because $\sum_{i'\geq i}\Delta_{i'}d_{i'}<0$,
$A$ is not ordered. Second, if there exist distinct states $i\leq\max L<j<k$
then $\mathcal{D}$ contains the direction $d\equiv d^{jk}+\varepsilon d^{ji}$.
Because $\sum_{\tau\geq j}\Delta_{\tau}d_{\tau}=(1+\varepsilon)\Delta_{j}-\Delta_{k}<0$,
$A$ is not ordered. Third, if there exist states $i<j\leq\max L<k<l$
and indices $t,t'$ such that $\Sigma_{t}=\{i,k\},\Sigma_{t'}=\{j,l\}$,
then $\mathcal{D}$ contains the direction $d\equiv d^{jl}+(1+\varepsilon)d^{ki}$.
Because $\sum_{\tau\in H}\Delta_{\tau}d_{\tau}=(1+\varepsilon)\Delta_{k}-\Delta_{l}<0$,
$A$ is not ordered. Fourth, and finally, if there exist states $i,j,k,l$
with $i\leq\max L<j,$ $\max L<k<l$ and indices $t,t'$ with $\Sigma_{t}=\{i,j\}$
and $k,l\in\Sigma_{t'}$ then $\mathcal{D}$ contains the direction
$d\equiv d^{sk}+\varepsilon d^{ji}$. Because $\sum_{\tau\in H}\Delta_{\tau}d_{\tau}=\varepsilon\Delta_{j}+(\Delta_{k}-\Delta_{l})<0$,
$A$ is not ordered.
\end{proof}
%

\subsection{Section \ref{Section: sequential experiments}}
\begin{proof}[Proof of Lemma \ref{Lemma: full support (i,z) sequential}]
Write $i^{0}$ for the state $i$ with $\Delta_{i^{0}}=0$ and recall
that Lemma \ref{Lemma: rationalizing P} provides a fully supported
prior $\mu$ with $(i(\mu),z(\mu))=(i,z)$, $\Delta_{i}\mu_{i}z+\sum_{j>i}\Delta_{j}\mu_{j}=0$.
Because $\mu$ has full support and $z>0$, we also have $\Pi(\mu)>0$.
If $\Pi(\mu)\leq\alpha$, define 
\[
\nu\equiv\frac{1-\alpha}{1-\Pi(\mu)}\mu+\frac{\alpha-\Pi(\mu)}{1-\Pi(\mu)}\delta(\omega_{i^{0}}).
\]
Alternatively, if $\Pi(\mu)>\alpha$ define 
\[
\nu\equiv\frac{\alpha}{\Pi(\mu)}\delta(\omega_{1})+\frac{\Pi(\mu)-\alpha}{\Pi(\mu)}\mu.
\]
In both cases, we have $\nu_{i}z+\sum_{j>i}\nu=\alpha$ and $\Delta_{i}\nu_{i}z+\sum_{j>i}\Delta_{j}\nu_{j}=0.$
Because $\nu$ inherits full support from $\mu$, it meets all the
criteria of the claim.
\end{proof}
%
\begin{proof}[Proof of Theorem \ref{Theorem: sequential esxperimentation}]
Fix action distribution $\alpha$. First, if $A$ is ordered then
Theorem \ref{Theorem: reliable iff ordered} implies $A$ is reliable.
Because reliability implies sequential reliability, $A$ is sequentially
reliable. Conversely, if $A$ is not ordered then the non-reliability
of $A$ follows from Lemma \ref{Lemma: opposite signs}, Lemma \ref{lemma: Rationalizing Q},
and Lemma \ref{Lemma: full support (i,z) sequential} from the same
argument given in the proof of Proposition \ref{Proposition: Negative result},
with Lemma \ref{Lemma: full support (i,z) sequential} as a surrogate
for Lemma \ref{Lemma: rationalizing P}.
\end{proof}

