e^x \ln(1 - x) = -\sum_{n\geq 1} \frac{M^{(0)}(n)}{n!}\,x^n
.
\end{equation}
%%
One can express $M^{(0)}(n)$ via contour integrals, 
%%
\begin{equation}
\label{Mn-int}
M^{(0)}(n) = - e n! \,\frac{1}{2\pi \text{i}}  \oint\limits_C \frac{dx}{x^{n+1}} \, e^{-(1-x)} \ln(1 - x) 
,
