,
\nonumber
\\[3pt]
&&
\hspace{-72pt}
Q^{(1)}(2) = [\hspace{1.5pt}[0,2],[1,3]\hspace{1.5pt}]
,
\nonumber
\\[3pt]
&&
\hspace{-72pt}
Q^{(0)}(3) = [\hspace{1.5pt}[1,5],[2,5],[3,3],[6,1],[8,2]\hspace{1.5pt}]
,
\nonumber
\\[3pt]
&&
\hspace{-72pt}
Q^{(1)}(3) = [\hspace{1.5pt}[0,5],[1,12],[2,3],[3,3]\hspace{1.5pt}]
,
\nonumber
\\[3pt]
&&
\hspace{-72pt}
Q^{(2)}(3) = [\hspace{1.5pt}[0,5],[1,4]\hspace{1.5pt}]
,
\label{390}
\eea
%%
We used Mathematica to determine the arrays $Q^{(d)}(n)$ with $4\leq n \leq 8$, see Appendix~\ref{sa1}. 

The number $D^{(0)}(1,n)$ of vertices of degree $1$ is 
%%
\begin{equation}
D^{(0)}(1,n) = D^{(1)}(0,n) = N_0(n-1)
%%.
\label{392}
\end{equation}
and the number $D^{(0)}(2,n)$ of vertices of degree $2$ is 
%%
\begin{equation}
D^{(0)}(2,n) = N_1(n-1)
.
\label{394}
\end{equation}
These results are valid for $n \geq 2$. The sum rules
%%
\bea
&&
\sum_{j=1}^{M^{(0)}(n)} D^{(0)}(j,n)=N_0(n)
, 
\label{D-sums}
\\[3pt]
&&
\sum_{j=1}^{M^{(0)}(n)} j D^{(0)}(j,n)=2N_1(n) 
,
\label{3945}
\eea 
lead to 
\begin{equation}
\sum_{j=2}^{M^{(0)}(n)} (j-1) D^{(0)}(j,n)=2N_1(n)-N_0(n)
,
\label{395}
\end{equation}
%%
which in conjunction with $D^{(0)}_{M^{(0)}(n)}(n)=2$ (see figure~\ref{fig:2}) and the asymptotic behaviors \eq{N0-asymp} and \eq{N1-asymp} leads to the bound $M^{(0)}(n) < e\, n!\,\ln n$ asserting that the maximal degree is smaller than the total number of edges $N_1(n)$. This upper bond is not tight as is evident from the asymptotics of $M^{(0)}(n)$, equation~\eq{Mn-asymp}. 

In general, for $n \geq 2$ and $1 \leq d \leq n-1$, the number $D^{(d)}(0,n)$ of $d$-simplices of $d$-degree $0$ is 
%%
\be
D^{(d)}(0,n) = N_{d-1}(n-1) 
.
\label{396}
\ee
%%
For $n \geq 2$, the numbers $D^{(n-1)}(0,n)$ and $D^{(n-1)}(1,n)$  of $(d=n-1)$-simplices of $d$-degrees $0$ and $1$ are  
%%
\begin{equation}
\label{Dn1n}
\begin{split}
D^{(n-1)}(0,n) &= \frac{(n - 1)(n + 2)}{2}\,, \\
D^{(n-1)}(1,n) &= n + 1.
\end{split}
\end{equation}
For $n \geq 3$, the numbers $D^{(n-2)}(0,n)$,  $D^{(n-2)}(1,n)$,  $D^{(n-2)}(2,n)$, and $D^{(n-2)}(3,n)$  of $(d=n-2)$-simplices of $d$-degrees $0$, $1$, $2$, and $3$, respectively, are  
%%
\bea
D^{(n-2)}(0,n) &=& \frac{(n - 2)(n - 1)n(3n + 11)}{24}\,, 
\nonumber
\\[3pt]
D^{(n-2)}(1,n) &=& \frac{n(n^2 + n - 4)}{2}\,, 
\nonumber
\\[3pt]
D^{(n-2)}(2,n) &=& \frac{(n - 1)n}{2}\,, 
\nonumber
\\[3pt]
D^{(n-2)}(3,n) &=& n.
\label{Dn2n}
\eea
%%
Furthermore, 
\begin{equation}
D^{(d)}\!\left(M^{(d)}(n), n\right) = d + 2
\end{equation}
for $n\geq 1$ and
\begin{equation}
\label{399}
D^{(d)}\!\left(\widetilde{M}^{(d)}(n)
,n\right) = \frac{(d+1)(d+2)}{2}
\end{equation}
for $n\geq d+2$. 
We guessed \eq{Dn1n}--\eq{399} from $Q^{(d)}(n)$ with $n \leq 8$ obtained with the help of Mathematica, see \eqref{Qn1}--\eq{a20}; we conjecture that \eq{Dn1n}--\eq{399} hold for all $n$. 

The fraction of $d$-simplices with a given $d$-degree is 
%%
\begin{equation}
p^{(d)}(k^{(d)},n) = \frac{D^{(d)}(k^{(d)},n)}{N_d(n)}
.
\label{400}
\end{equation}
%%
We shortly refer to $p^{(d)}(k^{(d)})$ as the upper-degree distribution, or simply the $d$-degree distribution. Specifically, $p^{(0)}(k^{(0)})$ is the degree distribution of the $1$-skeleton of a simplicial complex. In particular, using \eq{392}, we compute the fraction of vertices of the smallest degree 
%%
\begin{equation}
p^{(0)}(1,n)=\frac{N_0(n-1)}{N_0(n)}
.
\label{401}
\end{equation} 
%%
Hence $p^{(0)}(1,n) \simeq n^{-1}$ as $n\gg 1$, i.e., it asymptotically vanishes. 

The fraction $p^{(d)}(k^{(d)})$ cannot be directly compared to the degree distributions of random simplicial complexes, as deterministic complexes often exhibit non-uniform gaps between degree values. In our simplicial complex, these gaps become significantly wider as the degrees increase. To relate the exponent of this discrete upper-degree distribution to the standard $\gamma$ exponent of a continuous degree distribution for random scale-free networks, we use the cumulative distribution  
%%
\begin{equation}
p^{(d)}_{\text{cum}}(k^{(d)},n) \equiv \sum_{q \geq k} p^{(d)}(q^{(d)},n)
, 
\label{402}
\end{equation}
%%
for which exponent $\gamma$ is defined as $p_{\text{cum}}(k) \sim k^{-\gamma + 1}$. 

