% \end{equation*}

% where $P$ represents the total number of out-of-sample forecasts, $d_{t+h,i,j}$ is the loss difference at time $t+h$, and $\hat{V}_h$ is the heteroskedasticity and autocorrelation consistent (HAC) estimator of the asymptotic variance of $P^{-1} \sum_t d_{t+h}$. 


