% The MCS procedure evaluates the difference in loss functions between competing models $l$ and $j$ over time, denoted as $d_{l,j,t}$. Assuming stationarity in the loss differentials, the null hypothesis of equal predictive accuracy is formulated as follows:

% \begin{equation*}
% H_0: \mathbb{E}[d_{l,j,t}] = 0, \quad \forall l, j \in M.
% \end{equation*}
