\section{Replica computation of the free energy}
\label{sec:Replica_computation}

The equilibrium free energy is evaluated using the replica trick
\begin{equation}
    f(\alpha, \beta)=-\lim_{N\rightarrow\infty}\frac{1}{N\beta}\overline{\log \mathcal{Z}(\alpha,\beta)}=-\lim_{N\rightarrow\infty}\frac{1}{N\beta}\lim_{n\rightarrow 0}\frac{\overline{\mathcal{Z}^n}-1}{n}
\end{equation}
which allows one to exchange the disorder average of the log with that of the $n$-th moments of $\mathcal{Z}$. If one assumes $n$ to be an integer, we can introduce $n$ fictitious replica of the original system and perform the average over the disorder on this system. We have  

\begin{equation}
\label{eq:Zn_1}
\begin{gathered}
   \overline{\mathcal{Z}^n} = \int D\conf{S}_1\cdots\int d\conf{S}_n\;\overline{e^{\frac{N\beta}{2 }\sum_{\mu=1}^s\left(\frac{1}{N}\sum_{j=1}^N \bm{S}_j^a\cdot \bm{\xi}_j^\mu\right)^2
   +\frac{\beta}{2}\sum_{\mu=s+1}^P\left(\frac{1}{\sqrt{N}}\sum_{j=1}^N\bm{S}_j^a\cdot \bm{\xi}_j^\mu\right)^2
   -\frac{\beta}{2 N}\sum_{\mu=1}^P\sum_{j=1}^N(\bm{S}_j^a\cdot\bm{\xi}_j^\mu)^2
   }} \\
   \;\\
   \propto\,e^{-\frac{\beta P n \sigma^2}{2\;d}}\int D\conf{m}D\conf{\hat{m}}
   \exp\Bigl(-iN\sum_{\mu\le s}\sum_{a}m_{\mu}^a \hat{m}_{\mu}^a
   +\frac{\beta N \sigma^2}{2}\sum_{\mu\le s}\sum_a\;(m_{\mu}^a)^2-i\sum_{\mu>s}\sum_{a}m_{\mu}^a \hat{m}_{\mu}^a
   +\frac{\beta}{2}\sum_{\mu>s}\sum_a\;(m_{\mu}^a)^2\Bigr) \\
     \\
   \times\int\prod_a D\conf{S}_a\;\int \prod_{\mu}\prod_{k=1}^N\left[d\bm{\xi}_k^\mu P(\bm{\xi}_k^\mu)\right] 
   \exp\left(\frac{i}{\sigma }\sum_{\mu\le s}\sum_a\;\;\hat{m}_{\mu}^a\sum_k\bm{\xi}_{k}^a\cdot \bm{S}_{k}^a
   +\frac{i}{\sqrt{N}}\sum_{\mu>s}\sum_a\;\;\hat{m}_{\mu}^a\sum_k\bm{\xi}_{k}^a \cdot\bm{S}_{k}^a\right)
\end{gathered}
\end{equation}
In the last equation we do not show prefactors that are not relevant for the final saddle point evaluation.
We introduced magnetizations order parameters through delta functions:
\begin{equation*}
    m_{\mu, a}=\begin{cases}
        \frac{1}{N\sigma}\sum_{k=1}^N \xi_{k}^{\mu}S_{k}^a\qquad \mu\leq s \\
        \; \\
        \frac{1}{\sqrt{N}}\sum_{k=1}^N \xi_{k}^{\mu}S_{k}^a\qquad \mu>s.
    \end{cases}
\end{equation*}
The disorder average over noncondensated magnetizations reads

\begin{equation}
\label{eq:disorder_avg_noncond}
    \int \prod_{\mu>s}\prod_{k=1}^N\left[d\bm{\xi}_k^\mu P(\bm{\xi}_k^\mu)\right]\exp\left(\frac{i}{\sqrt{N}}\sum_{\mu>s}\sum_a\;\;\hat{m}_{\mu}^a\sum_k\bm{\xi}_{k}^a \cdot \bm{S}_{k}^a\right)\,\simeq\,\exp\left(-\frac{1}{2 d N}\sum_{\mu>s}\sum_{ab}\hat{m}_{\mu, a}\hat{m}_{\mu, b}\sum_{k}\bm{S}_{k}^a\cdot \bm{S}_{k}^{b}\right)
\end{equation}
Next, we introduce the spin glass overlap matrix
\begin{equation}
    Q_{ab}=\frac{1}{N\sigma^2}\sum_{k=1}^N \bm{S}_k^a \cdot \bm{S}_k^b
\end{equation}
through delta functions. After the last passages, the replicated partition function reads
\begin{equation}
\label{eq:Zn_2}
\begin{gathered}
    \overline{\mathcal{Z}^n}\propto\,e^{-\frac{\beta P n \sigma^2}{2\;d}}
    \int D\conf{m}_{\mu\leq s}D\conf{\hat{m}}_{\mu\leq s}D\mathbb{Q}D\widehat{\mathbb{Q}}\exp\left(-iN\sum_{\mu\le s}\sum_{a}m_{\mu}^a \hat{m}_{\mu}^a
   +\frac{\beta N \sigma^2}{2}\sum_{\mu\le s}\sum_a\;(m_{\mu}^a)^2+iN\sum_{ab}\widehat{Q}_{ab}Q_{ab}\right) \\
   \; \\
    \int\prod_a D\conf{S}_a\;\int \prod_{\mu\leq s}\prod_{k=1}^N\left[d\bm{\xi}_k^\mu P(\bm{\xi}_k^\mu)\right] 
   \exp\left(\frac{i}{\sigma }\sum_{\mu\le s}\sum_a\;\;\hat{m}_{\mu}^a\sum_k\bm{\xi}_{k}^a\cdot \bm{S}_{k}^a-\frac{i}{\sigma^2}\sum_{ab}\widehat{Q}_{ab}\sum_{k=1}^N \bm{S}_k^a\cdot \bm{S}_k^b\right)   \\ 
   \; \\
   \times \int D\conf{m}_{\mu > s}\frac{D\conf{\hat{m}}_{\mu > s}}{(2\pi)^{P-s}}\exp\left(-\frac{\sigma^2}{2d}\sum_{\mu>s}\sum_{ab}Q_{ab} \hat{m}_{\mu}^a \hat{m}_{\mu}^b-i\sum_{\mu>l}\sum_{a} m_{\mu}^a \hat{m}_{\mu}^a+\frac{\beta}{2}\sum_{\mu>s}\sum_a\;(m_{\mu}^a)^2\right)
\end{gathered}
\end{equation}
The integrals over noncondensated magnetizations $\{m_{\mu, a}\}_{\mu>s}$ and their conjugated fields $\{\widehat{m}_{\mu, a}\}_{\mu>s}$, after the integration over disorder in \eqref{eq:disorder_avg_noncond}, are gaussian integrals and thus can be performed straightforwardly
\begin{equation}
\begin{gathered}
        \int D\conf{m}_{\mu > s} \exp\left(\frac{\beta}{2}\sum_{\mu>s}\sum_a\;(m_{\mu}^a)^2
        \right)\int \frac{D\conf{\hat{m}}_{\mu > s}}{(2\pi)^{P-s}} \exp\left(
        -\frac{\sigma^2}{2d}\sum_{\mu>s}\sum_{ab}Q_{ab} \hat{m}_{\mu}^a \hat{m}_{\mu}^b
        -i\sum_{\mu>s}\sum_{a} m_{\mu}^a \hat{m}_{\mu}^a\right) \\
        \; \\
        \,=\, \left(\det \frac{\sigma^2}{d}\mathbb{Q}\right)^{-\frac{(P-s)}{2}}
        \int \frac{D\conf{m}_{\mu > s}}{(2\pi)^{\frac{P-s}{2}}}
        \exp\left(-\frac{1}{2}\sum_{\mu>s}\sum_{ab}\left(\frac{d(Q^{-1})_{ab}}{\sigma^2}-\beta\delta_{ab}\right)m_{\mu}^a m_{\mu}^b\right)=\left[\det\left(\mathbb{I}_n-\frac{\beta \sigma^2}{d}\mathbb{Q}\right)\right]^{-\frac{(P-s)}{2}}
\end{gathered}
\end{equation}
We can easily eliminate $\{\widehat{m}_{\mu, a}\}_{\mu\le s}$, $Q_{aa}$ and $\widehat{\mathbb{Q}}$ through saddle point evaluations
\begin{equation*}
    Q_{aa} = 1\qquad i\widehat{m}_{\mu}^a=\beta\sigma^2 m_{\mu}^a\qquad i\widehat{Q}_{ab}=\frac{\alpha}{2}\frac{\partial}{\partial Q_{ab}}\log\det\left(\mathbb{I}_n-\frac{\beta \sigma^2}{d}\mathbb{Q}\right)= -\frac{\alpha \beta \sigma^2}{2 d}\left(\mm{I}_{n}-\frac{\beta \sigma^2}{d}\mm{Q}\right)^{-1}_{ab}\equiv -\frac{\alpha\beta^2\sigma^2}{2} R_{ab}
\end{equation*}
The replicated partition function can be finally written as a saddle point integral
\begin{equation}
    \label{eq:Zn_3}
\begin{gathered}
    \overline{\mathcal{Z}^n}\propto\int D\conf{m}_{\mu\le s}D\mathbb{Q}\exp(N A_n(\conf{m}_{\mu\le s}, \mathbb{Q})) \\
    \; \\
    A_n(\conf{m}_{\mu\le s}, \mathbb{Q})) = -\frac{\alpha\beta\sigma^2 n}{2d} -\frac{\beta \sigma^2}{2}\sum_{\mu\le s}\sum_a (m_{\mu}^a)^2-\frac{\alpha\beta^2\sigma^2}{2}\sum_{a b} R_{ab}Q_{ab}-\frac{\alpha}{2}\log\det\left(\mathbb{I}_n-\frac{\beta \sigma^2}{d}\mathbb{Q}\right)+\log W(\conf{m}_{\mu\le s}, \mathbb{R}) \\
    \; \\
    W(\conf{m}_{\mu\le s, a}, \mathbb{R})=\int \prod_{a=1}^n\left(dS_a\delta(S_a-\sigma)\right)\int \prod_{\mu\le s}\left(\frac{d\xi^\mu\delta(\xi^\mu-1)}{\mathcal{S}_{d-1}(1)}\right)e^{\beta\sigma\sum_a \sum_{\mu\le s} m_\mu^a\;\bm{\xi}_\mu\cdot \bm{S}_a+\frac{\alpha\beta^2}{2}\sum_{ab}R_{ab}\;\bm{S}_a\cdot \bm{S}_b}
\end{gathered}
\end{equation}
The original problem has been reduced to a problem of $n$ interacting spins $\{\bm{S}_a\}_{a=1}^n$: once the saddle point integral is evaluated, the free energy can be finally evaluated after continuing analytically to continuous $n$ and performing the $n\rightarrow 0$ limit. The saddle point equations related to \eqref{eq:Zn_3} read
\begin{equation}
    \label{eq:sp_eq_m_Zn3}
    m_{\mu}^a = \frac{1}{\sigma}\langle \bm{\xi}_{\mu}\cdot\bm{S}_a \rangle_{\text{eff}}
\end{equation}
\begin{equation}
    \label{eq:sp_eq_Q_Zn3}
    Q_{ab} = \frac{1}{\sigma^2}\langle \bm{S}_a\cdot\bm{S}_b \rangle_{\text{eff}}
\end{equation}
\begin{equation}
    \langle\cdot\rangle_{\text{eff}}=\frac{1}{W}\int \prod_{a=1}^n\left(dS_a\delta(S_a-\sigma)\right)\int \prod_{\mu\le s}\left(\frac{d\xi^\mu\delta(\xi^\mu-1)}{\mathcal{S}_{d-1}(1)}\right)e^{\beta\sigma\sum_a \sum_{\mu\le s} m_\mu^a\;\bm{\xi}_\mu\cdot \bm{S}_a+\frac{\alpha\beta^2}{2}\sum_{ab}R_{ab}\;\bm{S}_a\cdot \bm{S}_b}(\cdot)
\end{equation}
Unfortunately, saddle point equations \eqref{eq:sp_eq_m_Zn3}, \eqref{eq:sp_eq_Q_Zn3} cannot be solved for generic $\conf{m}_{\mu\le s}, \mm{Q}$, but an ansatz is needed. The natural choice is a Replica Symmetric ansatz, as the original problem is invariant under permutation of replica indices:
\begin{equation}
\label{eq:RS_ansatz}
    m_{\mu}^a=m_{\mu}\qquad Q_{ab}=\delta_{ab}+(1-\delta_{ab})q
\end{equation}
With this ansatz the action in \eqref{eq:Zn_3} can be further simplified, allowing us to finally evaluate the free energy of the system. First, the noise parameter $\mm{R}$ becomes
\begin{equation}
    R_{ab}\equiv \begin{cases}
        \frac{1}{\beta\sigma^2}\frac{1}{\frac{d}{\sigma^2}-\beta (1-q)}+\frac{q}{\sigma^2\left[\frac{d}{\sigma^2}-\beta (1-q)\right]^2}+O(n)\equiv r_d\qquad a=b \\
        \; \\
        \frac{q}{\sigma^2\left[\frac{d}{\sigma^2}-\beta (1-q)\right]^2}+O(n)\equiv r\qquad a\neq b
    \end{cases}
\end{equation}
The action becomes
\begin{equation}
\label{eq:RS_Action}
\begin{gathered}
A_{n}=-\frac{\alpha\beta\sigma^2 n}{2d} -\frac{\beta \sigma^2 n}{2}\sum_{\mu\le s}m_{\mu}^2-\frac{\alpha\beta^2\sigma^2n(n-1)}{2} rq-\frac{\alpha\beta^2\sigma^2 n}{2}r-\frac{\alpha}{2}\Bigl[\log\left(1-\frac{\beta\sigma^2}{d}(1+(n-1)q)\right) \\
\; \\
+(n-1)\log\left(1-\frac{\beta\sigma^2}{d}(1-q)\right)\Bigr]+\log \overline{\int_{(\mm{S}_{d-1}(1))^n}\prod_a (ds_a)\sigma^{n-1} e^{\beta\sigma^2\sum_{\mu\le s} m_\mu\;\bm{\xi}_\mu\cdot \sum_a\bm{s}_a+\frac{\alpha\beta^2\sigma^2 r}{2}\left(\sum_{a}\;\bm{s}_a\right)^2}}^{(\{\bm{\xi}_{\mu}\}_{\mu\le s})}    
\end{gathered}
\end{equation}
The first term with the log can be easily simplified
\begin{equation*}
\begin{gathered}
    \frac{\alpha}{2}\Bigl[\log\left(1-\frac{\beta\sigma^2}{d}(1+(n-1)q)\right)+(n-1)\log\left(1-\frac{\beta\sigma^2}{d}(1-q)\right)\Bigr] \\
    \; \\
    =\frac{\alpha n}{2}\log\left(1-\frac{\beta\sigma^2}{d}(1-q)\right)+\frac{\alpha\beta\sigma^2}{2 d}\frac{nq}{1-\frac{\beta\sigma^2}{d}(1-q)}+O(n^2)
\end{gathered}
\end{equation*}
The integral in the last entropic term can be further simplified through an Hubbard-Stratonovich transform
\begin{equation*}
    e^{\frac{\alpha\beta^2\sigma^2 r}{2}\left(\sum_a \bm{s}_a\right)^2}=\int\frac{d\bm{h}}{(2\pi \alpha r)^{d/2}}e^{-\frac{h^2}{2\alpha r}+\beta\sigma \bm{h}\cdot\sum_a \bm{s}_a}
\end{equation*}
With this last passage, we have 
\begin{equation*}
\begin{gathered}
\log \overline{\int_{(\mm{S}_{d-1}(1))^n}\prod_a (ds_a)\sigma^{n-1} e^{\beta\sigma^2 \sum_{\mu\le s} m_\mu\;\bm{\xi}_\mu\cdot \sum_a\bm{s}_a+\frac{\alpha\beta^2\sigma^2 r}{2}\left(\sum_{a}\;\bm{s}_a\right)^2}}^{(\{\bm{\xi}_{\mu}\}_{\mu\le s})} \\
\; \\
= n\int\frac{d\bm{h}}{(2\pi \alpha r)^{d/2}}e^{-\frac{h^2}{2\alpha r}}\,\overline{\log \K{d}\left(\beta\sigma\left|\bm{h}+\sigma \sum_{\mu\le s}m_{\mu}\bm{\xi}_{\mu}\right|\right)}^{(\{\bm{\xi}_{\mu}\}_{\mu\le s})}
\end{gathered}
\end{equation*}
where we used $\K{d}(x)=\int_{\mm{S}_{d-1}(1)}d\bm{s}e^{\bm{s}\cdot \bm{x}}$ defined in \eqref{eq:Kd_gd}.
Combining all these passages, using \eqref{eq:free_energy_density_from_replica} one can straightforwardly obtain \eqref{eq:free_energy_density_RS} and related saddle point equations \eqref{eq:sp_eqs_T} by extremizing \eqref{eq:free_energy_density_RS}.

\section{The instability of mixtures}
\label{sec:Instability_mixtures}

In this appendix, we show that mixture solutions ($s>1$) of eq. \eqref{eq:sp_defm_a0} are unstable. 
Although we have numerical evidence for such instability for $\alpha>0$ and generic mixtures, we focus on the sublinear case $\alpha=0$ and on symmetric mixtures.
We study the spectrum of the Hessian of the $\alpha=0$ free energy in eq. \eqref{eq:eq_free_en_dens_a0}, which reads
\begin{equation}
\label{eq:hessian_mixtures_alphazero_general}
    \frac{1}{\sigma^2}\frac{\partial^2 f}{\partial m_{\mu}\partial m_{\nu}}\,=\,\delta_{\mu\nu}-\beta\sigma^2\overline{\bm{\xi}_{\mu}^T\left[g_d'(\beta \sigma^2 |\bm{z}| )\mm{P}_{\parallel}\left(\frac{\bm{z}}{|\bm{z}|}\right)
    + \frac{g_d(\beta \sigma^2 |\bm{z}| )}{\beta \sigma^2 |\bm{z}|}\mm{P}_{\perp}\left(\frac{\bm{z}}{|\bm{z}|}\right)
    \right]\bm{\xi}_{\nu}}
\end{equation}
where $\g{d}(\cdot)$ is defined in eq. \eqref{eq:Kd_gd}.

Let us consider symmetric mixtures of $s$ examples
$\conf{m}\,=\,(m,\dots,m,0,\dots,0)$.
The saddle point eq. for Matthis magnetization $m$, eq. \eqref{eq:sp_defm_a0}, and the elements of the hessian in eq. \eqref{eq:hessian_mixtures_alphazero_general} can be rewritten as
\begin{equation}
\label{eq:m_a0_sym_mix}
    m\,=\,\int_0^{s-1}\;dw P_w^{(s)}(w)\int_{-1}^1\;du P_u(u)\;\g{d}\left(\beta \sigma^2 m\sqrt{1+w^2+2 w u} \right)\frac{1+u w}{\sqrt{1+w^2+2w u}}
\end{equation}
\begin{itemize}
    \item For $\mu=\nu\leq s$
    \begin{equation}
    \label{eq:hessian_a0_sym_mix_a}
    \begin{gathered}
        \frac{1}{\rho_1^2 \rho_2^2}\frac{\partial^2 f}{\partial m_{\mu}\partial m_{\mu}}\,=\,1-\beta\sigma^2 I_1\equiv a \\
        \; \\
        I_1 = \int_0^{s-1}\;dw P_w^{(s)}(w)\int_{-1}^1\;du P_u(u)\;
        \Bigl[\frac{(1+u w)^2}{1+w^2+2 w u}\g{d}'\left(\beta \sigma^2 m\sqrt{1+w^2+2 w u}\right) \\
        \;\\
        +\left(1-\frac{(1+u w)^2}{1+w^2+2 w u}\right)\frac{\g{d}\left(\beta \sigma^2 m\sqrt{1+w^2+2 w u}\right)}{\beta \sigma^2 m\sqrt{1+w^2+2 w u}}\Bigr]
    \end{gathered}
    \end{equation}
    \item For $\mu=\nu>s$
    \begin{equation}
    \label{eq:hessian_a0_sym_mix_c}
    \begin{gathered}
        \frac{1}{\sigma^2}\frac{\partial^2 f}{\partial m_{\mu}\partial m_{\mu}}\,=\,1-\beta\sigma^2 I_2\equiv c \\
        \; \\
        I_2=\frac{1}{d}\int_0^{s}\;dw P_w^{(s+1)}(w)\left[\g{d}'(\beta \sigma^2 m w)+(d-1)\frac{\g{d}(\beta \sigma^2 m w)}{\beta \sigma^2 m w}\right]
    \end{gathered}
    \end{equation}
    \item For $\mu\neq \nu\leq s$ by computing $\sum_{\mu\nu}^{1,s}\frac{\partial^2 f}{\partial m_{\mu}\partial m_{\nu}}$ using \eqref{eq:hessian_mixtures_alphazero_general} and knowing that $\frac{\partial^2 f}{\partial m_{\mu}\partial m_{\nu}}$ are expected to be all equal, one can show that
    \begin{equation}
    \label{eq:hessian_a0_sym_mix_b}
    \begin{gathered}
    \frac{1}{\sigma^2}\frac{\partial^2 f}{\partial m_{\mu}\partial m_{\nu}}\,=\,\frac{\beta\sigma^2}{s-1} \left(I_1-\frac{I_3}{s}\right)\equiv b \\
    \; \\
    I_3=\int_0^{s}\;dw P_w^{(s+1)}(w) \g{d}'(\beta \sigma^2 m w)w^2]
    \end{gathered}
    \end{equation}
    \item For $\mu\neq\nu>s$, the Hessian entries are zero.
\end{itemize}
We decomposed the mixture vector $\bm{z}=\sum_{\mu\le s}\bm{\xi}_{\mu}=\sum_{\mu\le s-1}\bm{\xi}_{\mu}+\bm{\xi}_s=\bm{w}+\bm{\xi}_s$, so that $|\bm{z}|^2=|\bm{w}|^2+1+2|\bm{w}|u$ with $u=\frac{\bm{w}}{|\bm{w}|}\cdot \bm{\xi}_s$. The pdfs of $u$ and $w=|\bm{w}|$ and are respectively
\begin{equation}
    P_u(u)\,=\,\frac{(1-u^2)^{\frac{d-3}{2}}}{\int_0^{\pi}(\sin\vartheta)^{d-2}d\vartheta}\qquad\qquad -1\leq u \leq 1
\end{equation}
\begin{equation}
    P_w^{(s)}(w)=\mathcal{S}_{d-1}(1)w^{d-1}\rho_{s-1}(w)
\end{equation}
where $\rho_{s}(z)\equiv P_{\bm{z}}(\bm{z})$, the pdf of the mixture vector $\bm{z}$, satisfies the recursive equation
\begin{equation}
\label{eq:iterative_formula_pdf_of_mixtures}
\begin{gathered}
\rho_1(z)\,=\,\frac{\delta(z-1)}{\mathcal{S}_{d-1}(1)} \\
\; \\
\rho_s(z)\,=\,\frac{\int_{0}^{\pi}\;d\vartheta\sin^{d-2}(\vartheta)\;\rho_{s-1}(\sqrt{z^2+1-2 z \cos\vartheta})}{\int_{0}^{\pi}\;d\vartheta\sin^{d-2}(\vartheta)}\qquad s>1
\end{gathered}
\end{equation}
Note that $\rho_s(z)$ is the distribution of the position vector of a discrete-time random walk in $d$ dimensions at time $s$, where at each time step the walker makes a unit-length move in a random direction.

For simplicity, we consider only the cases $s=2, 3$: for these values, the distributions $\rho_2(z)$ and $\rho_3(z)$ read
\begin{equation}
    \rho_2(z)\,=\,\frac{1}{\mathcal{S}_{d-1}(1)}\frac{\left(4-z^2\right)^{\frac{d-3}{2}}\vartheta(z)\vartheta(2-z)}{2^{d-3}z\int_{0}^{\pi}\;d\vartheta\sin^{d-2}(\vartheta)}
\end{equation}
\begin{equation}
    \rho_3(z)\,=\,\frac{\int_0^{\Theta(z)}\;\frac{d\theta\;\sin^{d-2}(\theta)\;\left[4-(z^2+1-2z\cos\theta)\right]^{\frac{d-3}{2}}}{2^{d-3}\sqrt{z^2+1-2z\cos\theta}}}{\mathcal{S}_{d-1}(1)\left[\int_{0}^{\pi}\;d\vartheta\sin^{d-2}(\theta)\right]^2},\qquad \Theta(z)\,=\,\pi\vartheta(1-z)+\arcos\left(\frac{z}{2}-\frac{3}{2 z}\right)\vartheta(z-1)\vartheta(3-z).
\end{equation}

We now proceed to evaluate the Hessian spectrum. When evaluated on a symmetric mixture, the Hessian \eqref{eq:hessian_mixtures_alphazero_general} has a simple block structure (compare with eqs \eqref{eq:hessian_a0_sym_mix_a}, \eqref{eq:hessian_a0_sym_mix_b}, \eqref{eq:hessian_a0_sym_mix_c})

\[
\begin{pNiceArray}{cc|cc}
  \mathbf{a} & \mathbf{b} & \Block{2-2}<\Large>{\mathbf{0}} \\
  \mathbf{b} & \mathbf{a} \\
  \hline
  \Block{2-2}<\Large>{\mathbf{0}} && \mathbf{c} & 0 \\
  && 0 & \mathbf{c}
\end{pNiceArray}
\]
Due to this simple structure, the Hessian has three distinct eigenvalues
\begin{itemize}
    \item The nondegenerate eigenvalue \begin{equation}     \label{eq:lambda1}         \lambda_1\,=\, a+(s-1)b \,=\,1-\frac{\beta\sigma^2}{s}I_3 \end{equation}
    This eigenvalue is related to longitudinal fluctuations of the symmetric mixture, i.e. fluctuations that preserve the degree and symmetry of the mixture.
    \item The eigenvalue
    \begin{equation}
    \label{eq:lambda2}
        \lambda_2\,=\,c\,=\,1-\beta\sigma^2 I_2
    \end{equation}
    with degeneracy $M-s$. This eigenvalue is related to fluctuations that increase the degree of the mixture, without breaking its symmetry.
    \item The eigenvalue
    \begin{equation}
    \label{eq:lambda3}
        \lambda_3\,=\,a-b\,=\,1-\frac{s}{s-1}\beta\sigma^2 I_1+\frac{\beta\sigma^2}{s(s-1)}I_3
    \end{equation}
     with degeneracy $s-1$. This eigenvalue represents fluctuations that break the symmetry of the mixtures.
\end{itemize}
\begin{figure}
    \centering
    \includegraphics[width=0.4\linewidth]{figures/stability_of_mixtures_alpha=0_s=2_d=3_l1l2l3.pdf}
    \includegraphics[width=0.4\linewidth]{figures/stability_of_mixtures_alpha=0_s=3_d=3_l1l2l3.pdf}
    \caption{The three distinct eigenvalues of the $\alpha=0$ free energy Hessian in \eqref{eq:hessian_mixtures_alphazero_general} evaluated on symmetric mixtures, as functions of inverse temperature $\beta$. The left panel is for $s=2$ mixtures, the right one for $s=3$ ones. Mixtures of patterns are never stable states: the instability is due to the eigenvalue $\lambda_3$, related to fluctuations that break the symmetry of the mixture.}
    \label{fig:instability_sym_mixtures_a0}
\end{figure}
In figure \ref{fig:instability_sym_mixtures_a0} we show for the $d=3$ VHM that symmetric mixtures with $s=2, 3$ are unstable for any $T\geq 0$: the instability is due to the eigenvalue $\lambda_3$, therefore, to fluctuations that break the symmetry of the mixture. In the SHM ($d=1$) one has instead that for a given symmetric mixture of order $s>2$ the eigenvalue $\lambda_3$ becomes positive for sufficiently low temperatures \cite{amit1985spin}.

\subsection{Large $s$ and large $d$ limits}

We now consider the instability of mixtures in the limits $s\rightarrow\infty,\,d=\Oo(1)$ and $d\rightarrow\infty,\,s=\Oo(1)$ respectively.
For both these limits, we find that solutions of symmetric mixtures become marginally stable. Let us consider the two cases in the following:
\begin{itemize}
    \item Large $s$, fixed $d$:
    Here we find that the the distribution of $|\bm{z}|$ is
    \begin{equation}
        P_z^{(s)}(z)=\frac{\mathcal{S}_{d-1}(1)z^{d-1}e^{-\frac{d z^2}{2 s}}}{(2\pi \frac{s}{d})^{d/2}}
    \end{equation}
    where finite $s$ corrections are present close to the upper edge $z_{max}=s$.
    Let us focus on the $T=0$ case: we have
    \begin{equation}
        m\simeq \frac{1}{\sqrt{s}}(1-1/d)\sqrt{\frac{d}{2}}\frac{\Gamma(\frac{d-1}{2})}{\Gamma(\frac{d}{2})}\equiv \frac{k_d}{\sqrt{s}}
    \end{equation}
    \begin{eqnarray}
        &\beta I_1=1+O(1/s) \\
        &\beta I_2=1-O(1/\sqrt{s}) \\
        &\beta I_3=\frac{\beta I_1}{s-1}=\frac{1}{s}+O(1/s^2)
    \end{eqnarray}
    The eigenvalues \eqref{eq:lambda1},\eqref{eq:lambda2}, \eqref{eq:lambda3} are
    \begin{equation}
    \begin{gathered}
        \lambda_1=1-\frac{c_1}{s} \\
        \; \\
        \lambda_2=\frac{c_2}{\sqrt{s}} \\
        \; \\
        \lambda_3=-\frac{c_3}{s}
    \end{gathered}
    \end{equation}
    for some constants $c_1, c_2, c_3>0$.
    For any $d$, in the large $s$ limit, mixtures become marginally stable.
    \item Large $d$, fixed $s$:
    in this limit, the distribution of $|\bm{z}|$ is trivial, $P_z^{(s)}(z)\simeq \delta(z-\sqrt{s})$. The distribution of the scalar products is $P_u(u)\simeq \delta(u)$. Thus, we find for $d\rightarrow\infty$ (compare with eq. \eqref{eq:m_a0_sym_mix})
    \begin{equation}
        m=\frac{1}{\sqrt{s}}\sqrt{1-\frac{1}{\beta}}
    \end{equation}
    \begin{equation}
    \begin{gathered}
        \beta I_1=\frac{1}{s(2\beta-1)}+1-\frac{1}{s} \\
        \; \\
        \beta I_2=1 \\
        \; \\
        \beta I_3=\begin{cases}
            0\qquad s=1 \\
            \; \\
            \frac{\beta I_1}{s-1}-\frac{1}{(s-1)(2\beta-1)}\qquad s>1
        \end{cases}
    \end{gathered}
    \end{equation}
    Thus we find for the three eigenvalues \eqref{eq:lambda1},\eqref{eq:lambda2}, \eqref{eq:lambda3}
    \begin{equation}
    \begin{gathered}
        \lambda_1=1-\frac{1}{2\beta-1}-\frac{c_1}{d} \\
        \; \\
        \lambda_2=\frac{c_2}{d} \\
        \; \\
        \lambda_3=\begin{cases}
            \lambda_1\qquad s=1 \\
            \; \\
            -\frac{c_3}{d}\qquad s>1
        \end{cases}
    \end{gathered}
    \end{equation}
    for some constants $c_1, c_2, c_3>0$.
    In the large $d$ limit, symmetric mixtures of $s$ examples become marginally stable.
\end{itemize}

\section{Scaling limits}
\label{sec:scaling_limits_computations}

We consider the RS solution \eqref{eq:free_energy_density_RS}, \eqref{eq:energy_density_RS} and the related saddle point equations \eqref{eq:sp_eqs_T}, \eqref{eq:sp_eqs_T0} in the limit $d\rightarrow\infty$. We consider this limit as simultaneous with $N\rightarrow\infty$ and $P\rightarrow\infty$, identifying two scaling regimes:
\begin{itemize}
    \item Superlinear Scaling (SupLS): $N, P, d\rightarrow\infty$ with $\alpha'=\frac{P}{N d}=\Oo(1)$.
    \item Sublinear Scaling (SubLS): $N, P, d\rightarrow\infty$ with $\alpha''=\frac{P d}{N}=\Oo(1)$.
\end{itemize}
The SupLS regime corresponds to storing $P'=\Oo(N d)\gg \Oo(N)$ examples, while in the SubLs one instead has $P''=\Oo(N/d)\ll N$. Note that in this latter case one can store an infinite number of examples, provided that $N/d\rightarrow \infty$.

When $d\rightarrow\infty$, the correct scaling for the spins norm such that the free energy in eq. \eqref{eq:free_energy_density_RS} is well defined is $\sigma=\Oo(\sqrt{d})$: in particular, $\sigma=\sqrt{d}$ fixes the $\alpha=0$ critical temperature to unit for any $d$, so we choose this value for spin norms in our large $d$ limit computations. 

Let us first consider the SupLS case: expressing the free energy in \eqref{eq:free_energy_density_RS} it in terms of $\alpha'$ and fixing $\sigma=\sqrt{d}$, it reads
\begin{equation}
\label{eq:fe_larged_intermediate_passage}
\begin{gathered}
    \frac{f}{d}\,=\,\frac{1}{2}m^2 -\frac{1}{\beta d}\int_0^{\infty}dh\; P_h\left(h\right)|_{\alpha=\alpha'd}\log   \left[d^{\frac{d-1}{2}}\K{d}\left(\beta \sigma h\right)\right]   \\
    \\
    +\frac{\alpha'}{2}\left\{
    1
    +\frac{1}{\beta}\log\left[1-\left(1-q\right)\right]\right.
    + \left. \frac{\beta (1-q)q}{\left[1-\beta\left(1-q\right)\right]^2}
    -\frac{q}{1-\beta\left(1-q\right)}
    \right\}
\end{gathered}
\end{equation}
The distribution of cavity field in this last equation is
\begin{equation}
    P_h(h)|_{\alpha=\alpha'd}=\frac{h^{d-1}e^{-\frac{h^2}{2 \alpha' r'}}}{(2\pi \alpha' r')^{d/2}}e^{-\frac{m^2d}{2\alpha' r'}}\K{d}\left(\frac{m \sqrt{d}}{\alpha' r'}h\right)
\end{equation}
where we set $r'=r d$.
To perform the limit $d\rightarrow\infty$, we shall evaluate the integral in \eqref{eq:fe_larged_intermediate_passage}. The function $\K{d}(\cdot)$ defined in \eqref{eq:Kd_gd} has the following asymptotic behavior for large $d$ \cite{abramowitz1965handbook}
\begin{equation}
\label{eq:Kd_asymp_larged}
    d^{\frac{d-1}{2}}\K{d}(d\,x)=\int_{\sph{d}(\sqrt{d)}}d\bm{r}e^{\bm{r\cdot\bm{x}d}}\sim \left(\frac{1}{\sqrt{1+4 x^2}+1}\right)^{\frac{d-2}{2}}\frac{2^{d-1}e^{\frac{d}{2}}\pi^{\frac{d-1}{2}}e^{d\frac{2 x^2}{1+\sqrt{1+4 x^2}}}}{(1+4 x^2)^{1/4}}
\end{equation}
After rescaling $h\rightarrow\sqrt{d}\,h$, by using the expression in eq. \eqref{eq:Kd_asymp_larged} we can evaluate the integral in \eqref{eq:fe_larged_intermediate_passage} as a saddle point integral for large $d$, obtaining
\begin{equation}
\begin{gathered}
    \lim_{d\rightarrow\infty}\frac{1}{d}\int_0^{\infty}dh\; P_h\left(h\right)|_{\alpha=\alpha'd}\log   \left[d^{\frac{d-1}{2}}\K{d}\left(\beta \sigma h\right)\right] \\
    \, \\
    =\frac{1}{2}
        \left[\sqrt{1+4 \beta^2 \left(\alpha' r'+m^2\right)}-\log\left(\sqrt{1+4\beta^2  \left(\alpha' r'+m^2\right)}+1\right)+\log 4\pi\right]
\end{gathered}
\end{equation}
Finally, we obtain the free energy density
\begin{equation}
\label{eq:large_d_free_energy_alpha1}
\begin{gathered}
    \lim_{d\rightarrow \infty}\frac{f}{d}\Bigl|_{\alpha=\alpha'd}\,=\,\frac{1}{2}m^2-\frac{1}{2\beta}
        \left[\sqrt{1+4 \beta^2 \left(\alpha' r'+m^2\right)}-\log\left(\sqrt{1+4\beta^2  \left(\alpha' r'+m^2\right)}+1\right)+\log 4\pi\right] \\
    \\
    +\frac{\alpha'}{2}\left\{1+\frac{1}{\beta}\ln[1-\beta (1-q)]+\frac{q\beta (1-q)}{[1-\beta (1-q)]^2}-\frac{q}{1-\beta (1-q)}\right\}
\end{gathered}
\end{equation}
The saddle point equations in eqs \eqref{eq:sp_eqs_T} converge to the following equations
\begin{equation}
\label{eq:sp_eq_r'_infty_d_alpha1}
    r' = \frac{q}{1-\beta (1-q)}
\end{equation}
\begin{equation}
\label{eq:sp_eq_m_infty_d_alpha1}
    m=\frac{2 \beta m}{1+\sqrt{1+4 \beta^2\left(\alpha' r'+m^2\right)}}
\end{equation}
\begin{equation}
\label{eq:sp_eq_q_infty_d_alpha1}
    q = \frac{4 \beta^2 (\alpha' r'+m^2)}{[1+\sqrt{1+4 \beta^2 (\alpha' r'+m^2)}]^2}
\end{equation}
where we proceeded as before for the integral using the asymptotic expansion of $\g{d}(\cdot)$:
\begin{equation}
    \label{eq:gd_asymp_larged}
    \g{d}(d\, x)= \frac{2 x}{1+\sqrt{1+4 x^2}}+\Oo\left(\frac{1}{d}\right).
\end{equation}

The only physical solution of eqs \eqref{eq:sp_eq_r'_infty_d_alpha1}, \eqref{eq:sp_eq_m_infty_d_alpha1}, \eqref{eq:sp_eq_q_infty_d_alpha1} for $\alpha'>0$ is the no retrieval solution, with $m=0$ and $q=1-\beta_c(\alpha')/\beta$ for $\beta>\beta_c(\alpha')=1/(1+\sqrt{\alpha'})$, $q=0$ otherwise. This solution, when casted into eq. \eqref{eq:large_d_free_energy_alpha1}, returns the equilibrium free energy of the spherical Hopfield model with pairwise interactions \cite{bolle2003spherical}.

As to the SubLS regime, by proceeding analogously to the previous case, one gets the limiting free energy
\begin{equation}
\label{eq:large_d_free_energy_alpha2}
\begin{gathered}
    \lim_{d\rightarrow \infty}\frac{f}{d}\Bigl|_{\alpha=\frac{\alpha''}{d}}\,=\,\frac{1}{2}(m^2+\alpha'' r'')-\frac{1}{2\beta}
        \left[\sqrt{1+4 \beta^2 \left(\alpha'' r''+m^2\right)}-\log\left(\sqrt{1+4\beta^2 \left(\alpha'' r''+m^2\right)}+1\right)+\log 4\pi\right].
\end{gathered}
\end{equation}
where we set $r''=r/d$.
The saddle point equations read
\begin{equation}
\label{eq:sp_eq_r_infty_d_alpha2}
    r'' = \lim_{d\rightarrow\infty}\frac{1-1/\beta}{[1-\beta(1-\langle\g{d}^2(\beta \sqrt{d} h)\rangle_{h, \alpha=\alpha''/d})]^2d^2}
\end{equation}
\begin{equation}
\label{eq:sp_eq_m_infty_d_alpha2}
    m=\frac{2 \beta m}{1+\sqrt{1+4 \beta^2\left(\alpha'' r''+m^2\right)}}
\end{equation}
\begin{equation}
\label{eq:sp_eq_q_infty_d_alpha2}
    q=1-\frac{1}{\beta} = \frac{4 \beta^2 (\alpha'' r''+m^2)}{[1+\sqrt{1+4 \beta^2 (\alpha'' r''+m^2)}]^2}
\end{equation}
Equations \eqref{eq:sp_eq_m_infty_d_alpha2}, \eqref{eq:sp_eq_q_infty_d_alpha2} admit the retrieval solution
\begin{equation}
    \label{eq:solution_sp_eqs_alpha2}
    m(\alpha'', \beta)=\sqrt{1-\frac{1}{\beta}-\alpha''r''(\alpha'', \beta)}.
\end{equation}
We did not derive the expression of $r''$ as a function of $\alpha''$ and $\beta$, as it involved next-to-leading-order corrections to the expression in \eqref{eq:Kd_asymp_larged}, \eqref{eq:gd_asymp_larged}, resulting in computationally quite demanding. However, numerically, by extrapolating the expression in \eqref{eq:sp_eq_r_infty_d_alpha2} to $d\rightarrow\infty$ we found that $r''$ at $T=0$ is real in the range $0<\alpha''<\alpha_c''(0)=4/27\simeq 0.148181$.


\section{Further results for the hessian spectrum (I)}

This appendix contains several derivations for the Hessian spectrum that were not included in the main body of the text.

\subsection{The distribution of local fields}
\label{sec:local_fields_pdf_study}

The local fields
\begin{equation}
    \eta_i=|\sum_{j:j\neq i}\mm{J}_{ij}\bm{S}_j^*|
\end{equation}
are distributed according to
\begin{equation}
\label{eq:pEta}
    P_\eta(\eta)=\vartheta\left(\eta-p\right)P_{h}\left(\eta-p\right),\qquad p=\frac{\alpha\sigma}{d}\frac{\chi}{\frac{d}{\sigma^2}-\chi} 
\end{equation}
where $p$ is the Onsager reaction term, with $\chi$ solving the $T=0$ saddle points equations in \eqref{eq:sp_eqs_T0}, and $P_h(h)$ is the pdf of cavity fields defined by eq. \eqref{eq:cavity_fields_pdf}.

We measured the empirical pdfs of local fields over numerical samples
\begin{equation}
\label{eq:pEta_emp}
    P_{\eta}^{(emp)}(\eta)=\frac{1}{N}\sum_{i=1}^N\overline{\delta\left(\eta_i-\left|\sum_{j:j\neq i}\mm{J}_{ij}\bm{S}_j^*\right|\right)}
\end{equation}
and compared it with the prediction yielded by \eqref{eq:pEta}, for both Matthis states and spurious spin glass states.
In figure we show our results, for the $d=3$ VHM at capacity $\alpha=0.04$. The left panel shows the pdf for Matthis states, the right one that for no-retrieval states. In the former case, we observe a perfect agreement between the theoretical prediction \eqref{eq:pEta} and the empirical one \eqref{eq:pEta_emp}; in the latter case, it can be seen that our prediction is not exact. This is due to the RS ansatz used for our solution in \eqref{eq:energy_density_RS}, \eqref{eq:sp_eqs_T0},\eqref{eq:cavity_fields_pdf}, 
that in the case of spurious spin glass states is not correct because of the RSB transition.

