\subsection{Derivation of the Hessian}
\label{sec:derivation_Hessian}
The Hessian in \eqref{eq:Hessian} can be derived straightforwardly from the Hamiltonian \eqref{eq:ModelHam}.
Consider a configuration of spins $\conf{S}_*$ that is a stationary point of $\mathcal{H}$: any configuration sufficiently close to it can be parametrized as follows
\begin{equation}
\label{eq:parametrize_with_pions}
    \bm{S}_i=\sigma\bm{\pi}_i+\sqrt{1-\pi_i^2}\bm{S}_i^*    
\end{equation}
where $|\bm{S}_i^*|=\sigma$ and $\bm{\pi}_i\cdot \bm{S}_i=0$. For any spin, we introduced an orthogonal "pion" vector: it is clear that \eqref{eq:parametrize_with_pions} describes for any site $i$ a random rotation of the original spin $\bm{S}_i^*$ within its half of hypersphere: indeed, $0\leq\frac{1}{\sigma^2}\bm{S}_i\cdot\bm{S}_i^*=\sqrt{1-\pi_i^2}\leq 1$. 
By plugging \eqref{eq:parametrize_with_pions}
 into \eqref{eq:ModelHam} we get
 \begin{equation*}
 \begin{gathered}
     \mathcal{H}(\conf{S})=-\frac{1}{2}\sum_{i\neq j}\sqrt{(1-\pi_i^2)(1-\pi_j^2)}\;\bm{S}_i^*\cdot\mm{J}_{ij}\bm{S}_j^*-\frac{\sigma^2}{2}\sum_{i\neq j}\bm{\pi}_i^\intercal \mm{J}_{ij}\bm{\pi}_j-\sigma\sum_{i\neq j}\sqrt{1-\pi_j^2}\;\bm{\pi}_i^\intercal \mm{J}_{ij}\bm{S}_j^* \\
     \; \\
     = \mathcal{H}(\conf{S}_*)-\sigma \sum_{i=1}^N \bm{\pi}_i\cdot \sum_{j:j\neq i} \mm{J}_{ij}\bm{S}_j^*+\frac{\sigma^2}{2}\sum_{i j}\bm{\pi}_i^\intercal \left[- \mm{J}_{ij}+\delta_{ij}\mm{I}_d\frac{\bm{S}_i^*}{\sigma^2}\cdot \sum_{j:j\neq i} \mm{J}_{ij}\bm{S}_j^* \right] \bm{\pi}_j+\Oo(\conf{\pi}^3) \\
     \; \\
     \simeq \mathcal{H}(\conf{S}_*)+\frac{\sigma^2}{2}\sum_{ij}\bm{\pi}_i^\intercal \left(-\mm{J}_{ij}+\delta_{ij}\frac{\eta_i}{\sigma}\mm{I}_d\right)\bm{\pi}_j
 \end{gathered}
 \end{equation*}
 where $\mm{I}_d$ is the $d$-dimensional identity matrix  and between the third and the fourth side of this last equation we applied the condition of stationarity \eqref{eq:stationarity_modelHam}: local field vectors $\bm{\eta}_i=\sum_{j:j\neq i}\mm{J}_{ij}\bm{S}_j^*$ are parallel to spins on a stationary point. The Hessian obtained translates into \eqref{eq:Hessian} when extended to the whole space of configurations:
 \begin{equation*}
     \mm{M}_{ij}(\conf{S}_*)=\mm{P}_{\perp}(\bm{S}_i^*)\left(-\mm{J}_{ij}+\frac{\eta_i}{\sigma}\delta_{ij}\mm{I}_d\right)\mm{P}_{\perp}(\bm{S}_j^*)
 \end{equation*}
where $\mm{P}_{\perp}(\bm{x})=\mm{I}_d-\frac{\bm{x}}{x}\frac{\bm{x}^\intercal}{x}$ is an orthogonal projector.

\subsection{The spectrum of the interaction matrix}
\label{sec:spectrum_interaction_matrix}
We consider the off-diagonal part of the Hessian, having elements
\begin{equation}
    W_{ij}^{\gamma\delta}\,=\,-(\mm{P}_{i}^{\perp}\mm{J}_{ij}\mm{P}_{j}^{\perp})_{\gamma\delta}(1-\delta_{ij})
\end{equation}
We compute its resolvent function
\begin{equation}
    g(z)\,=\,%\frac{1}{N\;d}\operatorname{Tr}(z\underline{\mm{I}}_{N\;d}-\underline{\mm{W}})^{-1}
    \frac{1}{N\;d}\operatorname{Tr}(\underline{\mm{W}}-z\underline{\mm{I}}_{N\;d})^{-1}
\end{equation}
through simplification of the exact Schur formula
\begin{equation}
\label{eq:Schur}
    (\mm{G}_{11}^{-1})_{\beta\gamma}\,=\,-z\delta_{\beta\gamma}-\sum_{j,k>1}\sum_{\delta\epsilon}^{1,d}W_{1j}^{\beta\delta}\widetilde{G}_{jk}^{\delta\epsilon}W_{k1}^{\epsilon\gamma}
\end{equation}
We define $\widetilde{\underline{\mm{G}}}$ as the cavity resolvent (the resolvent in the system with a cavity on site $1$).
We found that the spectrum of the interaction matrix does not depend on the type of minimum (pattern-correlated or spin glass). In the following, the calculation: introducing $v_{i,\gamma}^{\mu}=(\mm{P}_{i}^{\perp}\bm{\xi}_i^{\mu})_{\gamma}$, we expand eq.\eqref{eq:Schur}
\begin{equation}
\label{eq:Schur_1}
(\mm{G}_{11}^{-1})_{\beta\gamma}\,=\,-z\delta_{\beta\gamma}-\sum_{j,k>1}\sum_{\delta\epsilon}^{1,d}\frac{1}{N^2}\sum_{\mu,\nu}^{1, M}v_{1,\beta}^{\mu}v_{j,\delta}^{\mu}\widetilde{G}_{jk}^{\delta\epsilon}v_{k,\epsilon}^{\nu}v_{1,\gamma}^{\nu}
\end{equation}
The second term in the r.h.s. can be easily manipulated (note that in the following $A_{\mu\nu}$ is uncorrelated to $v_{1,\beta}^{\mu}, v_{1,\gamma}^{\nu}$ by construction)
\begin{eqnarray}
\label{eq:passaggi}
    &\frac{1}{N}\sum_{\mu,\nu}^{1, M}v_{1,\beta}^{\mu}\underbrace{\left(\frac{1}{N}\sum_{j,k>1}\sum_{\delta\epsilon}^{1,d}v_{j,\delta}^{\mu}\tilde{G}_{jk}^{\delta\epsilon}v_{k,\epsilon}^{\nu}\right)}_{A_{\mu\nu}}v_{1,\gamma}^{\nu}
    \,=\,
    \frac{1}{N}\sum_{\mu,\nu}v_{1,\beta}^{\mu}\;A_{\mu\nu}\;v_{1,\gamma}^{\nu}=
    \frac{1}{N}\sum_{\mu}
    v_{1,\beta}^{\mu}v_{1,\gamma}^{\mu}A_{\mu\mu}+O(1/\sqrt{N}) \\
    & \nonumber \\
    & \simeq \frac{(\mm{P}_{1}^\perp)_{\beta\gamma}}{N\;d}\sum_{j,k>1}\sum_{\delta\epsilon}\left(\frac{1}{N}\sum_{\mu}v_{j,\delta}^{\mu}v_{k,\epsilon}^{\mu}\right)\widetilde{G}_{jk}^{\delta\epsilon}\,=\,
    \frac{(\mm{P}_{1}^\perp)_{\beta\gamma}}{N\;d}\sum_{j,k>1}\sum_{\delta\epsilon}(-W_{jk}^{\delta\epsilon}+K_{j}^{\delta\epsilon}\delta_{jk})\widetilde{G}_{jk}^{\delta\epsilon} \nonumber \\
    & \nonumber \\
    & = \frac{(\mm{P}_{1}^\perp)_{\beta\gamma}}{N\;d}(-\operatorname{Tr}\underline{\widetilde{\mm{W}}}\;\underline{\widetilde{\mm{G}}}+\sum_{j>1}\operatorname{Tr} \mm{K}_j\widetilde{\mm{G}_j})\simeq 
    -(\mm{P}_{1}^\perp)_{\beta\gamma}-(\mm{P}_{1}^\perp)_{\beta\gamma}zg(z)+\frac{(\mm{P}_{1}^\perp)_{\beta\gamma}}{N d}\sum_{j>1}\operatorname{Tr}\mm{K}_j\widetilde{\mm{G}}_{jj}\nonumber
\end{eqnarray}
The tensor $K_j^{\gamma\delta}$ is
\begin{equation}
    K_{j}^{\gamma\delta}=\frac{1}{N}\sum_{\mu=1}^M v_{j,\gamma}^{\mu}v_{j,\delta}^{\mu}\simeq ... \simeq \frac{\alpha}{d}(\mm{P}_{j}^\perp)_{\gamma\delta}
\end{equation}
The last term in the last r.h.s. of \eqref{eq:passaggi} is
\begin{equation}
    \frac{1}{N d}\sum_{j>1}\operatorname{Tr} \mm{K}_j\widetilde{\mm{G}}_{jj}\,=\frac{\alpha}{N d^2}\sum_{j>1}\operatorname{Tr} \mm{P}_{j}^\perp\widetilde{\mm{G}}_{jj}\simeq\,\alpha\frac{(d-1)}{d^2}g_{\perp}(z)
\end{equation}
where we used the idem-potency of the Projector and the properties of trace to write $(1/Nd)\sum\operatorname{Tr}\mm{P}_{j}^\perp\widetilde{\mm{G}}_{jj}=(1/Nd)\sum\operatorname{Tr}(\mm{P}_{j}^\perp\widetilde{\mm{G}}_{jj}\mm{P}_{j}^\perp)=(1/Nd)\sum\operatorname{Tr}\widetilde{\mm{G}}_{jj}^{\perp})\simeq (1-1/d)g_{\perp}(z)$.
Collecting everything and using $g(z)=(1-1/d)g_{\perp}(z)+(1/d)g_{\parallel}(z)$, we end up with the expression
\begin{equation}
    (\mm{G}_{11}^{-1})_{\beta\gamma}\,=\,-z\delta_{\beta\gamma}
    -\left[-1-\frac{z}{d}g_{\parallel}(z)-z\left(1-\frac{1}{d}\right)g_{\perp}(z)+\frac{\alpha}{d}\left(1-\frac{1}{d}\right)g_{\perp}(z)\right](\mm{P}_{j}^\perp)_{\beta\gamma}+O(N^{-1/2})\end{equation}
Or equivalently, introducing $C(z)=1+\frac{z}{d}g_{\parallel}(z)+\left(z-\frac{\alpha}{d}\right)\left(1-\frac{1}{d}\right)g_{\perp}(z)$
\begin{equation}
    \mm{G}_{11}\,=\,-\left(z\mm{I}_d-C(z)\mm{P}_{1}^\perp\right)^{-1}
\end{equation}
The resolvent function is thus
\begin{equation}
    g(z)\,=\,-\frac{1}{N d}\sum_{i=1}^N\sum_{\beta=1}^d\;\left(z\mm{I}_d-C(z)\mm{P}_{i}^\perp\right)_{\beta\beta}^{-1}
\end{equation}
We can easily compute the r.h.s. of this last expression, knowing that the orthogonal projector has $1$ null eigenvalue and $d-1$ unit eigenvalues:
\begin{equation}
\label{eq:res_perp_parall}
    g(z)\,=\,-\frac{d-1}{d}\frac{1}{z-C(z)}-\frac{1}{d\;z}=(1-1/d)g_{\perp}(z)+(1/d)g_{\parallel}(z)
\end{equation}
The last equation shows that there are $N$ null eigenvalues out of $N\times d$ (there is a first order pole in $z=0$ with weight $1/d$). Let us consider from now on only $g_{\perp}(z)$, the resolvent function in the sector orthogonal to $\conf{S}$. From eq. \eqref{eq:res_perp_parall}, we obtain
\begin{equation}
\label{eq:equation_resolvent_interaction_matrix}
    g_{\perp}(z)\,=\,-\frac{1}{z-\left(1-\frac{1}{d}\right)-\left(z-\frac{\alpha}{d}\right)(1-1/d)g_{\perp}(z)}
\end{equation}
which yields a second order algebraic equation in $g(z)$ whose correct\footnote{It is the solution having the expected analytical properties for the resolvent function defined. In particular, it should behave as $g(z)\sim -1/z$ for large $|z|$.} solution is the one with the '+'
\begin{equation}
\label{eq:resolvent_interaction_matrix}
    g_{\perp}(z)\,=\,\frac{z-\left(1-\frac{1}{d}\right)}{2(z-\alpha/d)\left(1-\frac{1}{d}\right)}
    -\frac{\sqrt{\left[z-\left(1-\frac{1}{d}\right)\right]^2+4(z-\alpha/d)(1-1/d)}}{2|z-\alpha/d|\left(1-\frac{1}{d}\right)}
\end{equation}
The spectrum is given from the first order poles of the resolvent function and from its cuts on the real line. It is not hard to show that the resolvent has a pole on the point $\lambda_p=+\alpha/d$ when $\alpha<d-1$, with weight $1-\alpha/(d-1)$. For the continuous part of the spectrum, we shall compute the imaginary part of $g_{\perp}(z)$. Let $z=\lambda+i0_+$: one has that the argument of the square root in \eqref{eq:resolvent_interaction_matrix} becomes negative when $\lambda_{-}<\lambda<\lambda_{+}$, with
\begin{equation}
    \lambda_{\pm}\,=\,-[1-1/d\mp2\sqrt{(1-1/d)(\alpha/d)}]
\end{equation}
The final expression for the spectral density is a shifted Marchenko-Pastur law
\begin{equation}
\label{eq:shifted_nodiag_Wishart}
    \rho_{\perp}(\lambda)\,=\,(1-\alpha/(d-1))\vartheta(d-1-\alpha)\delta(\lambda-\lambda_p)+\frac{\sqrt{(\lambda_+-\lambda)(\lambda-\lambda_{-})}}{2\pi|\lambda-\lambda_p|(1-1/d)}\vartheta(\lambda-\lambda_{-})\vartheta(\lambda_+-\lambda)
\end{equation}
Interestingly, we recover the spectrum of a shifted (with no diagonal) Wishart matrix in the large $d$ limit if and only if one fixes $\alpha'=\alpha/d$.

\subsection{Derivation of the spectral equation}
\label{sec:derivation_spectral_equation}

We derive the spectral equation \eqref{eq:self_consistent_equation_resolvent}
using random matrix techniques. In the large $N$ limit, we treat the Hessian \eqref{eq:Hessian} as an instance of a random matrix ensemble, in this case the deformed Wishart ensemble, where a sort of Wishart matrix (the off-diagonal part or interaction matrix in \eqref{eq:Hessian}
) is summed to a disordered diagonal matrix (the local fields in \eqref{eq:Hessian}
).

We assume that the two random matrices that compose Hessian \eqref{eq:Hessian} are free: two random matrices are free when their respective eigenbasis are uncorrelated \cite{potters2020first}. Free random matrices have the so-called R-transform of the resolvent function $\mathcal{R}(\mathcal{G})=z(\mathcal{G})+\frac{1}{\mathcal{G}}$ additive, where $z(\mathcal{G})$ is the inverse of the resolvent function. 
Given a matrix $\mm{A}$ and a perturbation $\mm{B}=\operatorname{diag}\conf{v}$, one can show that the resolvent of the sum $\mm{A}+\mm{B}$, thanks to $\mathcal{R}_{A+B}=\mathcal{R}_A+\mathcal{R}_B$, satisfies a self-consistent equation \cite{potters2020first}
\begin{equation}
\label{eq:Zee}
    \mathcal{G}(z)=\int \frac{dv\;P_v(v)}{v-z+R_A(\mathcal{G}(z))}
\end{equation}
Therefore, if one knows the distribution of the diagonal elements (for our Hessian, $P_\eta$), it suffices to know the expression of the R-transform of matrix $\mm{A}$ (the off-diagonal part of \eqref{eq:Hessian} in our case).

The self-consistent equation for the Green function $\Green(z)$ of the off-diagonal part of the Hessian is eq. \eqref{eq:equation_resolvent_interaction_matrix}: from it, we see that the inverse of $\Green(z)$ is
\begin{equation}
    z(\Green)\,=\,-\frac{1}{[1-(1-1/d)\Green]\Green}+\frac{(1-1/d)(1-\alpha \Green/d)}{1-(1-1/d)\Green}    
\end{equation}
and consequently for the R-transform
\begin{equation}
    R(\Green)\,=\,z(\Green)+\frac{1}{\Green}\,=\,-\frac{(\alpha/d)(1-1/d)\Green}{1-(1-1/d)\Green}
\end{equation}
It then follows, plugging this last equation into \eqref{eq:Zee}, that the resolvent function is given by
\begin{equation}
    \mathcal{G}(z)=\int \frac{d\eta P_{\eta}(\eta)}{\frac{\eta}{\sigma}-\lambda-\frac{(\alpha/d)(1-1/d)\mathcal{G}(z)}{1-(1-1/d)\mathcal{G}(z)}}
\end{equation}
The resolvent in this is last equation is defined as $\Green(z)=\frac{\sigma^2}{N d}\operatorname{Tr}(\underline{\mm{M}}-z\;\mm{I}_{N d})^{-1}$:  by changing definition into $\mathcal{G}(z)=\frac{d-1}{N d}\operatorname{Tr}(\underline{\mm{M}}-z\;\mm{I}_{N d})^{-1}$, one gets
\begin{equation*}
\mathcal{G}(z)=\frac{d-1}{\sigma^2}\int \frac{d\eta P_{\eta}(\eta)}{\frac{\eta}{\sigma}-\lambda-\frac{(\alpha/d)\mathcal{G}(z)}{\frac{d}{\sigma^2}-\mathcal{G}(z)}}
\end{equation*}
which is eq. \eqref{eq:self_consistent_equation_resolvent}.

\subsection{Numerical solution of spectral equation}
\label{sec:spectral_equation_numerical}

In this Appendix we explain how to solve numerically the spectral equation \eqref{eq:self_consistent_equation_resolvent}. Written in its real and imaginary part, eq. \eqref{eq:self_consistent_equation_resolvent} translates into
\begin{equation}
\label{eq:self_consistent_equation_resolvent_RE}
    \Re \Green(\lambda)\,=\,\frac{(d-1)}{\sigma}\int\frac{d\eta\;P_{\eta}(\eta)\left[\eta-\lambda\sigma-\frac{\alpha\sigma}{d}\frac{(\Re \Green(\lambda)\;\frac{d}{\sigma^2}-|\Green(\lambda|^2)}{|\frac{d}{\sigma^2}-\Green(\lambda)|^2}\right]}{\left|\eta-\lambda \sigma-\frac{\alpha\sigma}{d}\frac{\Green(\lambda)}{\frac{d}{\sigma^2}-\Green(\lambda)}\right|_{\mathbb{C}}^2}.%-\frac{\lambda}{\alpha|\varphi(\lambda)|^2}+\frac{|g(\lambda)|^2}{d}
\end{equation}
\begin{equation}
\label{eq:self_consistent_equation_resolvent_IM}
    1\,=\,\frac{\alpha (d-1)}{\sigma^2|\frac{d}{\sigma^2}-\Green(\lambda)|^2}\int\frac{d\eta\;P_{\eta}(\eta)}{\left|\eta-\lambda \sigma-\frac{\alpha\sigma}{d}\frac{\Green(\lambda)}{\frac{d}{\sigma^2}-\Green(\lambda)}\right|_{\mathbb{C}}^2}
\end{equation}
On principle, one has two solve eqs \eqref{eq:self_consistent_equation_resolvent_RE} and \eqref{eq:self_consistent_equation_resolvent_IM} simultaneously in order to determine $\Green(\lambda)$. We used a simplification that reduces the number of equations to be solved to one: we introduce the auxiliary resolvent $\widetilde{\Green}(\lambda)=\frac{\Green(\lambda)}{\frac{d}{\sigma^2}-\Green(\lambda)}$, which satisfy the self consistent equation
\begin{equation}
\label{eq:self_consistent_auxiliary_resolvent}
    \widetilde{\Green}(\lambda)\,=\,\frac{\frac{(d-1)}{\sigma}\int \frac{dh\;P_h(h)}{h+x(\lambda)}}{\frac{d}{\sigma^2}-\frac{(d-1)}{\sigma}\int \frac{dh\;P_h(h)}{h+x(\lambda)}}
    %=\frac{\mathcal{I}(x(\lambda))}{\frac{d}{\sigma^2}-\mathcal{I}(x(\lambda))}
\end{equation}
where we used \eqref{eq:local_fields_norms_pdf} to express integrals in terms of cavity fields pdf $P_h(h)$ and set $x(\lambda)=\frac{\alpha\sigma}{d}\widetilde{\Green}(0)-\lambda\sigma-\frac{\alpha\sigma}{d}\widetilde{\Green}(\lambda)$.
The equations for the real and imaginary parts of \eqref{eq:self_consistent_auxiliary_resolvent} are
\begin{equation}
\label{eq:self_consistent_auxiliary_resolvent_RE}
    \Re \widetilde{\Green}(\lambda)\,=\,\widetilde{\Green}(0)-\frac{d}{\alpha\sigma}\left(\lambda\sigma+\Re x\right)\,=\,\frac{\Re\mathcal{I}(x)\frac{d}{\sigma^2}-|\mathcal{I}(x)|_{\mathbb{C}}^2}{|\frac{d}{\sigma^2}-\mathcal{I}(x)|_{\mathbb{C}}^2}
\end{equation}
\begin{equation}
\label{eq:self_consistent_auxiliary_resolvent_IM}
    1\,=\,\frac{\alpha (d-1) \mathcal{J}(x)}{\sigma^2|\frac{d}{\sigma^2}-\mathcal{I}(x)|_{\mathbb{C}}^2}
\end{equation}
\begin{equation}
\label{eq:I_def}
    \mathcal{I}(x)=\int \frac{dh P_h(h)}{h+x}
\end{equation}
\begin{equation}
\label{eq:J_def}
    \mathcal{J}(x)=\int \frac{dh P_h(h)}{|h+x|_{\mathbb{C}}^2}
\end{equation}
For any value of $\Re x$ (respectively $\Im x$), one can solve \eqref{eq:self_consistent_auxiliary_resolvent_IM} to determine the correspondent $\Im x$ (respectively $\Re x$) and then compute $\lambda$ through \eqref{eq:self_consistent_auxiliary_resolvent_RE}: in this way one is able to obtain the auxiliary resolvent $\widetilde{\Green}(\lambda)$ for any given $\lambda>0$. Finally, the original resolvent can be obtained through
\begin{equation}
    \Re \Green(\lambda)\,=\,\frac{(\Re\widetilde{\Green}(\lambda)+|\widetilde{\Green}(\lambda)|_{\mathbb{C}}^2)d}{(1+\Re\widetilde{\Green}(\lambda))^2+(\Im\widetilde{\Green}(\lambda))^2}
\end{equation}
\begin{equation}
    \Im \Green(\lambda)\,=\,\frac{d}{\sigma^2}\frac{\Im\widetilde{\Green}(\lambda)}{(1+\Re\widetilde{\Green}(\lambda))^2+(\Im\widetilde{\Green}(\lambda))^2}
\end{equation}
We solved numerically eq \eqref{eq:self_consistent_auxiliary_resolvent_IM} using Mathematica\texttrademark, using as input values of $\Re x$ ranging in $-5<\Re x<0$. The theoretical curves shown in figures \ref{fig:fig_spec_dens_matthis_d=3_theor_vs_emp} were obtained using the method described in this Appendix to solve \eqref{eq:self_consistent_equation_resolvent}.

\section{Further results for the hessian spectrum (II)}

\subsection{Crossover from non-trivial to trivial bulk}
\label{sec:crossover_nontrivial_trivial_bulk}

The spectrum of the Hessian is composed of a trivial and nontrivial bulk (see eq. \eqref{eq:spectral_density_effective}). The nontrivial bulk spectral density $\rho_{nt}$ is generated by the convolution of the Marchenko-Pastur term in \eqref{eq:shifted_nodiag_Wishart} with $P_\eta(\eta)$ in \eqref{eq:local_fields_norms_pdf}, while the trivial contribution is given by the free convolution of the Dirac delta term in \eqref{eq:shifted_nodiag_Wishart} with \eqref{eq:local_fields_norms_pdf}.

Let us show how to obtain the trivial bulk from the spectral equation \eqref{eq:self_consistent_equation_resolvent}.
In order to consider the effect of the pole $\lambda_p=\alpha/d$ in \eqref{eq:shifted_nodiag_Wishart} to the solution of \eqref{eq:self_consistent_equation_resolvent}, let us consider the behavior of the equation for $\Re g\rightarrow\infty$: by expanding, one finds
\begin{equation}
    \label{eq:self_consistent_resolvent_approx}
    g(\lambda)\,\simeq\,(d-1)\int\frac{d\eta\;P_{\eta}(\eta)}{\eta-(\lambda-\alpha/d)-i\epsilon}
\end{equation}
where we individuated the small parameter $\epsilon=\alpha\frac{\Im g}{(\Re g)^2}\ll 1$. In this limit, then one finds ($\frac{\epsilon}{x^2+\epsilon^2}\simeq \pi\delta(x)$ and $\rho = \frac{1}{(d-1)\pi}\Im g$)
\begin{equation}
\label{eq:approx_img_smaller_reg}
    \rho(\lambda) \approx P_{\eta}(\lambda-\alpha/d)
\end{equation}
This regime is expected to hold with very good approximation for sufficiently large $\lambda$, being more accurate the larger the $\lambda$. 

There are two ways to define the crossover value: the first is based on the weight born by the singular term in \eqref{eq:shifted_nodiag_Wishart}: by comparison, it is easy to see that the equation for $\widehat{\lambda}$ reads
\begin{equation}
\label{eq:lambda_st_1}
    1-\frac{\alpha}{d-1}=\int_{\lambda_*}^{\infty}\;d\lambda\;P_\eta(\lambda-\alpha/d)
\end{equation}
Eq. \eqref{eq:lambda_st_1} assigns a weight equal to that of the pole to the total probability of being in the region where the approximation \eqref{eq:self_consistent_resolvent_approx} holds. Alternatively, one can estimate the crossover value from the breaking of the regime where \eqref{eq:lambda_st_1} holds, i.e. $\epsilon=1$ or 
\begin{equation}
    1\,=\,\alpha\frac{\Im g(\hat{\lambda}_*)}{(\Re g(\hat{\lambda}_*))^2}.
\end{equation}

\subsection{Asymptotic expansions of the spectrum close to the lower edge}
\label{sec:asymptotic_expansions_spectrum_lower_edge}

\subsubsection{Expansion of $\rho(\lambda)$ for $\lambda\rightarrow 0_+$ and $d>2$}

Let us derive the behavior of the spectral density and the eigenvector moments in the vicinity of the lower edge $\lambda=0$. We consider the spectrum in the case of both Matthis states and spin-glass states. In the following paragraphs, we will use the notation $\langle\cdot\rangle\equiv \int dh P_h(h)(\cdot)$ for averages over cavity fields. Before doing the expansion, we show that the lower spectral edge must be $\lambda=0$. We consider only the case of Matthis states, as for spin-glass states of vector spin glass systems it is well known that the spectrum is gapless.

We can easily show for Matthis states that $\lambda_{min}=0$ in the thermodynamic limit, using a \emph{ab absurdum} short proof: suppose that $\rho(\lambda)=\pi\Im\Green(\lambda)=0$ for small enough $\lambda>0$,
which is equivalent to asking that the spectrum be gapped. By expanding eq. \eqref{eq:self_consistent_equation_resolvent} for $\lambda\rightarrow 0$, we get
\begin{equation}
    \label{eq:self_consistent_resolvent_small_lambda}
    \Re\Green(\lambda)\simeq \frac{(d-1)}{\sigma}\int_{0}^{\infty}\frac{d h \;P_h(h)}{h-\frac{\lambda\sigma}{\Lambda_0}}
\end{equation}
where $\Lambda_0$ is the $T=0$ Replicon defined in eq. \eqref{eq:Replicon_T0}.
Since $\Lambda_0>0$ for a Matthis state, the integral in \eqref{eq:self_consistent_resolvent_small_lambda} exists if and only if $\lambda=0$, contradicting the initial condition $\Im\Green(\lambda)=0$ for $\lambda>0$. It follows that one must necessarily have $\rho(\lambda)=\pi\Im\Green(\lambda)>0$ for any $\lambda>0$.

We proceed with the expansion.
\begin{itemize}
    \item Matthis states: here the Replicon, as defined by eq. \eqref{eq:Replicon_T0}, is strictly positive. Let us begin: by plugging eq. \eqref{eq:self_consistent_equation_resolvent_IM} into \eqref{eq:self_consistent_equation_resolvent_RE}, we get

    \begin{equation}
    \label{eq:self_consistent_equation_resolvent_RE_bis}
        \Re \Green(\lambda) \,=\, \frac{(d-1)}{\sigma}\left\langle \frac{h}{|h+x|_{\mathbb{C}}^2}\right\rangle+\frac{\sigma|\frac{d}{\sigma^2}-\Green(\lambda)|_{\mathbb{C}}^2\;\Re x(\lambda)}{\alpha}
    \end{equation}

    where

    \begin{equation}
    \label{eq:x_def}
        x(\lambda)\,=\,\frac{\alpha\sigma}{d}\frac{\chi}{\frac{d}{\sigma^2}-\chi}-\lambda\sigma-\frac{\alpha\sigma}{d}\frac{\Green(\lambda)}{\frac{d}{\sigma^2}-\Green(\lambda)}.
    \end{equation}

    Now, knowing that $\Re \Green(\lambda)\,=\,\chi+\chi_{SG}\lambda+O(\lambda^2)$, and $\chi\,=\,\frac{(d-1)}{\sigma}\langle 1/h \rangle$, after a few straightforward simplifications eq. \eqref{eq:self_consistent_equation_resolvent_RE_bis} rewrites
    \begin{equation}
    \label{eq:self_consistent_resolvent_small_lambda_0}
        -\left(\chi_{SG}\lambda+\frac{\sigma(\frac{d}{\sigma^2}-\chi)^2}{\alpha}\Re x(\lambda)\right)\,=\,\frac{(d-1)}{\sigma}|x(\lambda)|_{\mathbb{C}}^2\left\langle\frac{1}{h|h+x|_{\mathbb{C}}^2}\right\rangle
    \end{equation}
    Since the r.h.s. of this last equation is positive, the l.h.s. is positive if and only if $\Re x<0$: this is indeed the case. Indeed, $x(0)=0$ and one can show that
    \begin{equation}
        \chi_{SG}=\frac{d\Green}{d\lambda}(0)\,=\,-\frac{(d-1)}{\sigma}\left\langle \frac{1}{h^2}\right\rangle \frac{d\Re x}{d\lambda}(0)
    \end{equation}
    so that
    \begin{equation}
      \frac{d\Re x}{d\lambda}(0)\,=\,-\frac{\sigma \chi_{SG}}{(d-1)\left\langle \frac{1}{h^2}\right\rangle}\,=\,-\frac{\sigma}{\Lambda}.  
    \end{equation}
    We have then that the l.h.s. of eq. \eqref{eq:self_consistent_resolvent_small_lambda_0} is
    \begin{equation}
        -\chi_{SG}\lambda-\frac{\sigma(\frac{d}{\sigma^2}-\chi)^2}{\alpha}\Re x\simeq -\frac{\sigma^2(\frac{d}{\sigma^2}-\chi)^2}{\alpha\Lambda}(1-\Lambda)\lambda+\frac{\sigma^2(\frac{d}{\sigma^2}-\chi)^2}{\alpha\Lambda}\lambda\,=\,\frac{\sigma^2(\frac{d}{\sigma^2}-\chi)^2}{\alpha}\lambda.
    \end{equation}
    With this, eq. \eqref{eq:self_consistent_resolvent_small_lambda_0} rewrites
    \begin{equation}
        1\,=\,\frac{\alpha (d-1) |x|_{\mathbb{C}}^2}{\sigma^3(\frac{d}{\sigma^2}-\chi)^2\lambda}\left\langle\frac{1}{h|h+x|_{\mathbb{C}}^2}\right\rangle
    \end{equation}
    To evaluate the integral in the r.h.s. of this last expression, we assume that $|\Im x|\ll |\Re x|$: by doing this, we can evaluate the integral easily using $\frac{\epsilon}{x^2+\epsilon^2}\simeq \pi \delta(x)$
    \begin{equation}
    \label{eq:simplification}
        \int\frac{dh P_h(h)}{h|h+x|^2}\,=\,\frac{\pi}{|\Im x|}\int\frac{|\Im x| P_h(h) dh}{\pi h[(h+\Re x)^2+(\Im x)^2]}\simeq \frac{\pi}{|\Im x|}\frac{P_h(|\Re x|)}{|\Re x|}
    \end{equation}
    By combining the last two equations and expanding until leading order, we finally get ($|\Im x|\simeq \frac{\alpha}{\sigma^2(\frac{d}{\sigma^2}-\chi)^2}\Im \Green$ and $\rho=\frac{\Im \Green}{\pi (d-1)}$)
    \begin{equation}
    \label{eq:rho_close_to_lower_edge}
    \begin{gathered}
        \rho(\lambda)\simeq \frac{\sigma}{\Lambda}P_h\left(\frac{\lambda \sigma}{\Lambda}\right)=a_d\lambda^{d-1} \\
        \; \\
        a_d = \frac{\mathcal{S}_{d-1}(\sigma)\sigma\;e^{-\frac{m^2(d-1)\langle 1/h^2\rangle \sigma^2}{2(1-\Lambda)}}(1-\Lambda)^{d/2}}{[2 \pi (d-1)\langle 1/h^2\rangle]^{d/2}\Lambda^d}
    \end{gathered}
    \end{equation}
where we used the identity $\alpha r_0 = \frac{1-\Lambda}{(d-1)\langle 1/h^2\rangle}$ coming from eq. \eqref{eq:Replicon_T0}.
The prefactor $a_d$ is exponentially suppressed as $\Lambda\rightarrow 1$, which corresponds to the sub-linear capacity limit $\alpha\rightarrow 0$: this corresponds to the trivialization of the spectrum in that limit, $\rho(\lambda)\rightarrow \delta(\lambda-1)$.

Let us check a posteriori the validity of the assumption $|\Im x|\ll |\Re x|$: combining eq. \eqref{eq:simplification} and $\Re x\simeq -\lambda/\Lambda$, we get
\begin{equation}
\label{eq:Img_less_Reg}
\begin{gathered}
    \frac{|\Im x|}{|\Re x|}\simeq b_d\lambda^{d-2}\ll 1\Longrightarrow \lambda_{cr}=\frac{1}{b_d^{\frac{1}{d-2}}} \\
    \; \\
    b_d = \frac{\pi\alpha (d-1) a_d \Lambda}{\sigma^4 \left(\frac{d}{\sigma^2}-\chi\right)^2}
\end{gathered}
\end{equation}
The prefactor $b_d$ is proportional to $a_d$, therefore the crossover eigenvalue $\lambda_{cr}$ grows exponentially fast as $\alpha\rightarrow 0$, consistently with the trivialization of the spectrum in this limit $\rho(\lambda)\rightarrow \delta(\lambda-1)$ (with a delta peak spectrum, the imaginary part of $x$ is identically null for any $\lambda$).

We finally complete this section with the estimation of the pseudogap eigenvalue. To do that, we rearrange the terms in eq. \eqref{eq:x_def}, obtaining for small $|x|_{\mathbb{C}}$
\begin{equation}
\label{eq:x_def_rewritten}
    -\lambda-\Lambda_0 x=\left(\frac{d-1}{\sigma}\right)\alpha r_0 \left[\left\langle\frac{1}{h^3}\right\rangle+\left(\frac{d-1}{\sigma}\right)\sigma\sqrt{r_0}\,\left\langle \frac{1}{h^2}\right\rangle^2\right]x^2
\end{equation}
By neglecting the imaginary part of $x$, we can solve eq. \eqref{eq:x_def_rewritten} as a second order algebraic equation for its real part: to estimate the pseudogap, we compute the value of $\lambda$ that cancels the discriminant of said equation, obtaining
\begin{equation}
    \label{eq:pseudogap_width}
    \lambda_{pg}=\frac{\Lambda_0^2}{4 W}
\end{equation}
where $W$ is the coefficient of the $x^2$ term in eq. \eqref{eq:x_def_rewritten}. In the $d=3$ case, the term $\langle 1/h^3\rangle$ is divergent and the coefficient is replaced by a singular term $W\propto |\log \Lambda_0|$.

\item Spin glass states: although we do not know the Full Replica Symmetry Breaking phase (fRSB) expression of the pdf of local fields on a local minimum of the energy, we can altogether characterize the scaling of $\rho(\lambda)$ at small eigenvalues. In order to obtain a physical solution for the spectrum, we need to impose $\Lambda_0=0$ for any $\alpha>0$: in fact, the unphysical solution with a spectral gap in the right panel of figure \ref{fig:fig_spec_dens_matthis_d=3_theor_vs_emp} is a consequence of having $\Lambda_0<0$ from eq. \eqref{eq:Replicon_T0} when using the RS $P_h(h)$. In the following lines, the average over the cavity fields is assumed to be over the fRSB pdf. 

Let us consider eq. \eqref{eq:self_consistent_equation_resolvent_RE_bis}: by assuming $|\Re x|\ll |\Im x|$ and $|\Re x|=\Oo(\Im x)^2$, the integral can be expanded and we get at leading order
\begin{equation}
    \Re\Green(\lambda)=\chi-\frac{2\Re x}{\alpha r_0 \sigma}-\frac{d-1}{\sigma}\left\langle \frac{1}{h^3}\right\rangle\,(\Im x)^2+\frac{\sigma}{\alpha}\left|\frac{d}{\sigma^2}-\Green(\lambda)\right|^2\Re x
\end{equation}
In deriving this last expression we imposed the nullity of the Replicon in \eqref{eq:Replicon_T0} and thus set $1=\alpha r (d-1)\langle 1/h^2\rangle$. Here, $\langle \cdot \rangle $ denotes an average over the unknown $P_h^{RSB}(h)$.
Note that the relation between the distribution of local fields and that of cavity fields in \eqref{eq:local_fields_norms_pdf} still holds, though with a value of the Onsager reaction dictated by the unknown fRSB solution and a different expression of the fRSB distribution of cavity fields.

If we further assume that $\Re \Green(\lambda)=\chi+o(\Im x)^2$ and thus $\Re x=-\lambda+o(\lambda)$, we get at leading order
\begin{equation}
    \frac{d-1}{\sigma}\left\langle \frac{1}{h^3}\right\rangle (\Im x)^2 = \frac{\lambda}{\alpha r_0\sigma}\Longrightarrow \rho(\lambda)=\frac{1}{\pi}\sqrt{\frac{\lambda}{(\alpha r_0)^3 (d-1)\langle 1/h^3\rangle}}\equiv \widehat{a}_d \,\sqrt{\lambda}
\end{equation}
where we used $|\Im x|=\alpha r_0 |\Im \Green|$ and $\rho=\frac{1}{\pi}|\Im \Green|$. The prefactor $\widehat{a}_d$ is well defined if $P_h^{RSB}(h)=o(h^2)$ for small $h$. On contrary, it should be replaced by a $\lambda$-dependent singular term. Assuming that $P_h^{RSB}(h)$ retains the low cavity field of the RS solution, $P_h^{RSB}(h)\approx h^{d-1}$, we get the following scaling for the spectral density at low eigenvalues
\begin{equation}
    \rho(\lambda)\approx \begin{cases}
        \sqrt{\lambda}\qquad d>3 \\
        \, \\
        \sqrt{\frac{\lambda}{|\log \lambda|}}\qquad d=3
    \end{cases}
\end{equation}

\end{itemize}

\subsubsection{Expansion of $\rho(\lambda)$ for $\lambda\rightarrow 0_+$ for $d=2$}

In the $d=2$ case the integral defining the Replicon in eq. \eqref{eq:Replicon_T0} is logarithmically divergent to $-\infty$, if close to $h=0$ the scaling $P_h(h)\propto h$ is assumed. Given that the retrieval phase has fRSB as well, we expect both for Matthis and spin glass states to have $\Lambda=0$ and thus $P_h^{(RSB)}(h)\ll h$ close to $h=0$.

Here we cannot find the scaling of the spectrum without knowing the fRSB distribution of fields. We conjecture that in the case of Matthis states the behavior of the exponent is continuous, so that one has by comparing with eq. \eqref{eq:rho_close_to_lower_edge} 
\begin{equation}
    \rho(\lambda) \approx \lambda\qquad d=2
\end{equation}
For spin glass minima, instead we conjecture a behavior akin to that of the $d=3$ case, with a square root behavior with logarithmic corrections.

\subsubsection{Expansion of $\kappa(\lambda)$ for $\lambda\rightarrow 0_+$}
\label{sec:expansion_rescaled_IPR_close_to_lower_edge} In this section, we expand eq. \eqref{eq:rescaled_IPR_theory} for the rescaled IPR $\kappa(\lambda)=NI(\lambda)$ close to the lower edge.

Preliminary to that, we derive eq. \eqref{eq:rescaled_IPR_theory} starting from eq. \eqref{eq:eigenvector_weights_local_fields}, which we report here for the convenience of the readers
\begin{equation}
\begin{split}
    \label{eq:eigenvector_weights_local_fields}
    N\langle|\bm{\psi}_i^{(k)}|^2\rangle=\frac{\alpha/\sigma^2}{\left|\frac{d}{\sigma^2}-\Green(\lambda_k)\right|_{\mm{C}}^2}\frac{d-1}{\left|\eta_i-\lambda_k\sigma-\frac{\alpha\sigma}{d}\frac{\Green(\lambda_k)}{\frac{d}{\sigma^2}-\Green(\lambda_k)}\right|_{\mm{C}}^2}    
\end{split}
\end{equation}
where $|\cdot|_{\mathbb{C}}$ it the complex norm.
Eq. \eqref{eq:eigenvector_weights_local_fields} should be understood as an eq. for the average value of eigenvector weights at fixed local fields $\eta_k$. Indeed, eigenvector components in deformed ensembles $\psi_{i,a}^j$ for a fixed configuration of $\eta_k$ are gaussian variables with variance given by \eqref{eq:eigenvector_weights_local_fields} with a factor $1/d$ (see \cite{truong2016eigenvectors} for the case of deformed Wigner ensembles).
The rescaled IPR 
$\kappa(\lambda)=NI(\lambda)$ can be computed combining eqs \eqref{eq:IPR} and \eqref{eq:eigenvector_weights_local_fields} and exploiting the gaussian nature of the $\psi_{i,a}^j$
\begin{equation}
\label{eq:rescaled_IPR_theory_bis}
\begin{gathered}
    \kappa(\lambda)=N\sum_{i=1}^N\langle |\bm{\psi}_i(\lambda)|^4 \rangle=3N\sum_{i=1}^N \langle |\bm{\psi}_i(\lambda)|^2 \rangle^2 \\
    \, \\
    \overset{N\rightarrow\infty}{=} 3\left(1-\frac{1}{d}\right)\left[\frac{(d-1)\alpha}{\sigma^2|\frac{d}{\sigma^2}-\Green(\lambda)|_{\mathbb{C}}^2}\right]^2
    \int\frac{d\eta P_\eta(\eta)}{\left|\eta-\lambda\sigma-\frac{\alpha\sigma}{d}\frac{\Green(\lambda)}{\frac{d}{\sigma^2}-\Green(\lambda)}\right|_{\mm{C}}^{4}}
\end{gathered}
\end{equation}

We now proceed to expand \eqref{eq:rescaled_IPR_theory_bis} in the limit $\lambda\rightarrow 0_+$. We consider the case of Matthis states of $d>2$ VHM. By proceeding similarly to the previous section, we find
\begin{equation}
\label{eq:rescaled_IPR_loweredge_scaling_patological}
    \kappa(\lambda)\approx \frac{3\left(d-1\right)^3}{d}(\alpha r_0)^2\frac{\pi P_h(-\Re x)}{2(\Im x)^3}\propto \lambda^{-2(d-1)}
\end{equation}
where we defined $x$ in \eqref{eq:x_def}. The scaling in \eqref{eq:rescaled_IPR_loweredge_scaling_patological} leads to $I(\lambda)\propto N\lambda^{2(d-1)}\propto N^{1-\frac{2}{d}}$ for the IPR, where we used the scaling $\lambda\sim N^{-1/d}$, valid for lower edge eigenvalues. Since by definition the IPR is bounded by unit (compare with the definition in \eqref{eq:IPR}), formula \eqref{eq:rescaled_IPR_theory_bis} cannot be true for the softest modes.
To highlight the origin of this paradox, consider equation \eqref{eq:eigenvector_weights_local_fields}. Applying it to the normalization of eigenvectors $\sum_k |\bm{\psi}_k^j|^2=1$, it returns
\begin{equation}
\label{eq:normalization_condition_in_terms_of_spec}
    1 = \frac{\alpha (d-1)}{\sigma^2\left|\frac{d}{\sigma^2}-\Green(\lambda)\right|_{\mm{C}}^2}\int \frac{d\eta P_\eta(\eta)}{\left|\eta-\lambda\sigma-\frac{\alpha\sigma}{d}\frac{\Green(\lambda)}{\frac{d}{\sigma^2}-\Green(\lambda)}\right|_{\mm{C}}^2}
\end{equation}
For any $\lambda>0$, this identity is valid: it is just the imaginary part of the spectral equation \eqref{eq:self_consistent_equation_resolvent}. However, at $\lambda=0$ the r.h.s. of \eqref{eq:normalization_condition_in_terms_of_spec} is equal to $1-\Lambda_0$, where $\Lambda_0<1$ is the $T=0$ Replicon introduced by eq. \eqref{eq:Replicon_T0}. Since for $d>2$ one has $\Lambda_0>0$ for Matthis states, it follows that \eqref{eq:normalization_condition_in_terms_of_spec} is wrong in the limit $\lambda\rightarrow 0_+$. The solution of such an impasse 
is that soft modes of Matthis states undergo condensation: by assuming the existence of a condensate weight $|\bm{\psi}_{i_*}(0)|^2=\Oo(1)$ for some node $i_*$, we get by using eq. \eqref{eq:eigenvector_weights_local_fields} with the condensate weight
\begin{equation}
    \label{eq:normalisation_at_lambda0}
    1=|\bm{\psi}_{i_*}(0)|^2+\frac{\alpha (d-1)}{\sigma^4\left[\frac{d}{\sigma^2}-\Green(0)\right]^2}\int \frac{d\eta P_\eta(\eta)}{\left[\eta-\frac{\alpha}{d}\frac{\Green(0)}{\frac{d}{\sigma^2}-\Green(0)}\right]^2}.
\end{equation}
The second addendum in the rhs of this last equation is just $1-\Lambda_0$ (see eqs \eqref{eq:local_fields_norms_pdf} and \eqref{eq:Replicon_T0}); therefore, we find that the condensate is equal to the Replicon $|\bm{\psi}_{i_*}(0)|^2=\Lambda_0$.

The presence of condensation in soft modes of continuous disordered systems is mathematically akin to a Bose-Einstein condensation, and is sometimes referred in literature as Random Matrix Bose-Einstein Condensation (RMBEC) \cite{Ikeda2023Bose}.
The RMBEC condition of our model can be obtained from eq.\eqref{eq:eigenvector_weights_local_fields} by imposing $|\bm{\psi}_{i_*}^{(k)}|^2=\Oo(1)$:
\begin{equation}
\label{eq:condensation_condition}
    \frac{\alpha}{\sigma^2\left|\frac{d}{\sigma^2}-\Green(\lambda_k)\right|_{\mm{C}}^2}\frac{d-1}{\left|\eta_{i_*}-\lambda_k\sigma-\frac{\alpha\sigma}{d}\frac{\Green(\lambda_k)}{\frac{d}{\sigma^2}-\Green(\lambda_k)}\right|_{\mm{C}}^2}=\Oo(N)
\end{equation}
that is valid in the regime $\lambda_k\sim N^{-1/d}$. It can be shown that eq. \eqref{eq:condensation_condition} implies an order statistics between low-rank eigenvalues and low-rank cavity fields of the kind $\lambda\sim \Lambda_0h$ \cite{lee2016extremal, franz2022delocalization}.

We can estimate the scale of eigenvalues in $N$ at which formula \eqref{eq:rescaled_IPR_theory_bis} does not need to be rectified with RMBEC. Let us consider lower edge modes with subextensive rank $k=\widetilde{k}N^{a}$ for $0<a<1$: then $\lambda_k=\widetilde{\lambda}N^{-\frac{1-a}{d}}$ and from eq. \eqref{eq:rescaled_IPR_loweredge_scaling_patological} it follows that RMBEC disappears at ranks with an exponent
\begin{equation}
    \lambda^{-2(d-1)}\leq N\Rightarrow a_*= \frac{d-2}{2(d-1)}
\end{equation}
For $a> a_*$, one has $I(\lambda)=\kappa(\lambda)/N\leq1$ and therefore for modes with rank $k\gg N^{a_*}$ eq. \eqref{eq:rescaled_IPR_theory_bis} is correct. 

\subsection{Limit $d\rightarrow\infty$ for the spectrum}
\label{sec:spectrum_infinite_d_limit}
Let us consider the large $d$ limit of the spectral equation \eqref{eq:self_consistent_equation_resolvent} in the two regimes SupLin and SubLin described in Appendix \ref{sec:scaling_limits_computations}.
In the SupLin case, $\alpha'=\alpha/d$, one has $P_h(h)\rightarrow \delta(h-\sqrt{m^2+\alpha' r'})$: then the spectral equation becomes (again, we use $\sigma=\sqrt{d}$ in the derivation)
\begin{equation}
    \label{eq:spectral_eq_SupLin}
    \Green(\lambda)=\frac{1}{\sqrt{m^2+\alpha' r_0'}+\frac{\alpha' \chi}{1-\chi}-\lambda-\frac{\alpha' \Green(\lambda)}{1-\Green(\lambda)}}
\end{equation}
Considering the physical solution $m=0$, $\chi=\frac{1}{1+\sqrt{\alpha'}}$, knowing that $r_0=\frac{1}{(1-\chi)^2}$, the solution of \eqref{eq:spectral_eq_SupLin} reads
\begin{equation}
\label{eq:spectral_eq_SupLin_sol}
    \Green(\lambda)=\frac{2(1+\sqrt{\alpha'})-\lambda}{2(1+2\sqrt{\alpha'}+\alpha'-\lambda)}+\frac{\sqrt{\lambda\,(\lambda-4\sqrt{\alpha'})}}{2(1+2\sqrt{\alpha'}+\alpha'-\lambda)}
\end{equation}
The spectrum is given by the continuous bulk (the imaginary part of \eqref{eq:spectral_eq_SupLin_sol}) and the pole in $\lambda=1+2\sqrt{\alpha'}+\alpha'$, which has weight $1-\alpha'$ and exists for $0\leq\alpha'\leq 1$. The final expression of the spectral density is thus
\begin{equation}
\label{eq:spectrum_SupLin}
    \rho(\lambda)=\frac{\sqrt{\lambda\,(4\sqrt{\alpha'}-\lambda)}}{2(1+2\sqrt{\alpha'}+\alpha'-\lambda)}+(1-\alpha')\vartheta(1-\alpha')\delta(\lambda-1-2\sqrt{\alpha'}-\alpha')
\end{equation}
This is the spectrum that one obtains for a $p=2$ spherical Hopfield model: this system is marginally stable having $\Lambda_0=0$, as it should be since the lower tail in eq. \eqref{eq:spectrum_SupLin} is $\propto \sqrt{\lambda}$. As a consequence, the corresponding eigenvectors are fully localized with $\kappa(\lambda)=\Oo(1)$ for all $0\leq \lambda\leq4\sqrt{\alpha'}$ or $\lambda=1+2\sqrt{\alpha'}+\alpha'$.

In the SubLin case, $\alpha''=\alpha d$, the spectrum becomes trivial for $d\rightarrow\infty$: again, $P_h(h)\rightarrow\delta(h-\sqrt{m^2+\alpha''r''})$, but the spectral equation is simply
\begin{equation}
    \Green(\lambda)=\frac{1}{\sqrt{m''^2+\alpha'' r_0''}-\lambda}
\end{equation}
In the SubLin regime, one has at equilibrium $\sqrt{m^2+\alpha''r_0''}=1$ and therefore $\rho(\lambda)=\delta(\lambda-1)$, as in the $\alpha=0$ case for finite $d$.

