\paragraph{Patterns}

Let us consider a fixed point $\conf{S}$ of eq. \eqref{eq:retrieval_versor_rule} with magnetization $m$ with the pattern $\conf{\xi}^1$: the local field vector on this point reads
\begin{equation}
\label{eq:signal_to_noise_stationary}
\begin{gathered}
    \frac{1}{\sigma}\sum_{j:j\neq i}\mm{J}_{ij}\bm{S}_j=\frac{1}{N\sigma}(\conf{\xi}^1\cdot\conf{S})\;\bm{\xi}_i^1+\frac{1}{N\sigma}\sum_{\mu=2}^P(\conf{\xi}^\mu\cdot\conf{S})\bm{\xi}_i^{\mu}+\Oo\left(\frac{1}{\sqrt{N}}\right) \simeq m\bm{\xi}_i^1+\bm{n}_i
\end{gathered}
\end{equation}
The vector $\bm{n}_i$ is an isotropic gaussian vector with zero mean and variance $\frac{\alpha r_0}{\sigma^2}$ (compare with def. \eqref{eq:noise_order_parameter}), where $r_0$ is the order parameter defined in eqs. \eqref{eq:sp_eqs_T0}.
Thanks to the stationarity condition \eqref{eq:stationarity_modelHam}, the spins are $\bm{S}_i=\frac{(m\bm{\xi}_i^1+\bm{r}_i)\sigma}{|m\bm{\xi}_i^1+\bm{r}_i|}$, hence the Matthis magnetization $m=\frac{1}{N\sigma}\conf{S}\cdot\conf{\xi}^1$ for large $N$ satisfies
\begin{equation}
\label{eq:sp_from_noise_to_signal_analysis}
\begin{gathered}
     m\,=\,\frac{1}{N\sigma}\sum_{i=1}^N\bm{\xi}_i^1\cdot\bm{S}_i=\int \frac{d\bm{n}\; e^{-\frac{n^2 \sigma^2}{2\alpha r_0}}}{(2\pi \alpha r/\sigma^2)^{d/2}}\int\frac{d\bm{\xi}\delta(|\bm{\xi}|-1)}{\mathcal{S}_{d-1}(1)}\frac{m\bm{\xi}+\bm{n}}{|m\bm{\xi}+\bm{n}|}\cdot\bm{\xi} \\
     \;\\
    =\int_0^{\infty}dn\; P_h\left(n\right)\g{d}\left(\frac{m \sigma n}{\alpha r_0}\right)=\Phi_d\left(\frac{m}{\sqrt{\alpha r_0}}\right)
\end{gathered}
\end{equation}
and we derived again the third of eqs. \eqref{eq:sp_eqs_T0}. We introduced a function $\Phi_d(\cdot)$ to represent in a compact fashion the integral in the last r.h.s. of \eqref{eq:sp_from_noise_to_signal_analysis}. For the standard Hopfield model, when $d=1$, one can show that $\Phi_1(\cdot)=\operatorname{Erf}\left(\frac{\cdot}{\sqrt{2}}\right)$.

We remark that the noise vectors $\bm{n}_i$ have the same statistics as the cavity fields of the RS solution, but they are not exactly cavity vectors since in cavity theory the cavity fields $\bm{h}_i$ vectors must be parallel to the spins $\bm{S}_i$. 

\vspace{10pt}
\paragraph{Mixture states} We proceed in a similar way as in the previous paragraph, but now consider as initial condition $  \frac{1}{\sigma}\bm{S}_i(0)=m_0\frac{\bm{z}_i}{z_i}+\sqrt{1-m_0^2}\;\bm{\pi}_i$, where $\bm{\pi}_i$ are unit vectors satisfying $\bm{\pi}_i\cdot \bm{z}_i=0$ and $\bm{z}_i=\sum_{\mu=1}^s c_\mu \bm{\xi}_i^{\mu}$ with $s=\Oo(1)$. We found

\begin{equation}
     \label{eq:m1_mixtures}
     \begin{split}
         \frac{1}{\sigma}&\sum_{j:j\neq i}\mm{J}_{ij}\bm{S}_j(0)=\widetilde{m}_0 \bm{z}_i+\bm{n}_i \\
         \; \\
         m_1&=\frac{1}{N}\sum_{i=1}^N \frac{\widetilde{m}_0\bm{z}_i+\bm{n}_i}{|\widetilde{m}_0\bm{z}_i+\bm{n}_i|}\cdot \frac{\bm{z}_i}{z_i}=\\
         &=\mathcal{S}_{d-1}(1)\int_0^s dz z^{d-1}\rho_s(z)\Phi_d\left(\frac{\widetilde{m}_0 z}{\sqrt{\alpha/d}}\right)
     \end{split}
 \end{equation}
 where the noise vector is again an isotropic gaussian vector with zero mean and variance $\alpha/d^2$, $\rho_s(z)$ is the pdf of the vector $\bm{z}=\sum_{\mu=1}^s c_{\mu}\bm{\xi}_{\mu}$ and $\widetilde{m}_0=\langle 1/z \rangle m_0$. We discuss how to compute the distributions $\rho_s(z)$ in Appendix \ref{sec:Instability_mixtures}. 



