\section{Model and Test Statistic \protect\label{sec:_Model_and_stat}}

We consider the linear IV regression with a scalar outcome $y_i$, a scalar endogenous variable $x_i$, and a $K \times 1$ vector of instruments $z_i$ such that 
\begin{align}\label{eq: model}
y_i = x_i \beta + \varepsilon_i, \quad  x_i = z_i'\pi + v_i, \quad \forall i \in [N].
%\label{eq:1}
\end{align}
%where $\Pi_i = \mathbb{E}X_i$ and $\{Z_i\}_{i\in [n]}$ is treated as fixed, following the many-instrument literature. 
%We let $K$ diverge with sample size $n$, allowing for the case that $K$ is of the same order of magnitude as $n$. We further have $\mathbb{E}V_i = 0$ by construction, and $\mathbb{E}e_i = 0$ by IV exogeneity.  We allow $(e_i, V_i)$ to be heteroskedastic across $i$.
Following the literature on many instruments, we assume that there are no (low-dimensional) controls included in our model as they can be partialled out from $(Y_i,X_i,Z_i)$. 
%We provide more discussions about the effect of partialling out the covariates after Assumption \ref{ass:weak_convergence} below. 
%We consider a single endogenous linear regression model with many weak instruments given by 
%\begin{equation}
%y_{i}=\Delta_{0}+x_{i}\Delta+\varepsilon_{i},\text{ }x_{i}=z_{i}^{'}\pi+v_{i},\text{ }\forall i\in\left[N\right],\label{eq:=000020IVs=000020model}
%\end{equation}
%where $y_{i}$ is response, $x_{i}$ is an endogenous variable such that there exist a high-dimensional column vector $z_{i}$ of dimension $p$ that can linearly explain its variation. 
The source of endogeneity is caused by a correlation between $\varepsilon_{i}$ and $v_{i}$, which represent the errors associated with the structural and the first-stage equation, respectively. The two sequences of regression errors, $\left\{ \varepsilon_{i}\right\} _{i=1}^{N}$ and $\left\{ v_{i}\right\} _{i=1}^{N}$, follow a mean-zero random process whose functional forms are unknown and potentially heteroskedastic. The unknown parameters are $\beta\in\mathbb{R}$ and $\pi\in\mathbb{R}^{K\times1}$, where $K$ is comparable or exceeds its sample size. 

We are interested in testing the null hypothesis 
\begin{equation}
H_{0}:\beta=\beta_{0}\text{ versus }H_{1}:\beta\neq\beta_{0}\label{eq:_null_hypothesis},
\end{equation}
even when the identification for the structural parameter of interest $\beta$ may be weak.
We focus on the model with a scalar endogenous variable for two reasons. First, in many empirical applications of IV regressions, there is only one endogenous variable (as can be seen from the surveys by \cite{Andrews-Stock-Sun(2019)} and \cite{lee2021}). Second, the asymptotic results derived in the paper extend directly to the general case of full-vector inference with multiple endogenous variables. 
Additionally, for the subvector inference, one may use a projection approach \citep{Dufour-Taamouti(2005)} after implementing our test on the whole vector of endogenous variables.\footnote{Alternative subvector inference methods for IV regressions (e.g., see \cite{GKMC(2012)}, \cite{Andrews(2017)}, and \cite{GKM(2019), GKM(2021)}) provide a power improvement over the projection approach under fixed $K$. However, whether they can be applied to the current setting is unclear.  
Also, \cite{Wang-Doko(2018)} and \cite{Wang(2020)} show that bootstrap tests based on the standard subvector AR statistic may not be robust to weak identification even under fixed $K$ and conditional homoskedasticity.}

%where $\beta_{1}$ is a real value and $\ensuremath{\beta_{0}}$ is a nuisance structural parameter. 
%Without loss of generality, we assume $\beta_{1}=0$ as one may parameterized the structural model in Equations \ref{eq:=000020IVs=000020model} to be 
%\[
%\widetilde{y}_{i}=\beta_{0}+x_{i}\widetilde{\beta}+\varepsilon_{i}=\beta_{0}+x_{i}\widetilde{\beta}+\varepsilon_{i},
%\]

To proceed, let us denote $y^*_{i}=y_{i}-x_{i}\beta_{0}.$ 
%As a result, the null hypothesis becomes $H_{0}:\widetilde{\beta}_{0}=0$. 
Let a singular value decomposition of the normalized instrument matrix be expressed as 
\begin{align}
\frac{Z}{\sqrt{N}}:=\sum_{\ell=1}^{\min\left\{ K,N\right\} }\sqrt{\lambda_{\ell}}q_{\ell}w_{\ell}^{'},
\end{align}
where $Z:=\left(z_{1},\ldots,z_{N}\right)^{'}\in\mathbb{R}^{N\times K},$ $\lambda_{\ell}$ denotes the $\ell$-th largest non-zero eigenvalue of the matrix $S_{N}:=\frac{1}{N}Z^{'}Z,$ $q_{\ell}$ and $w_{\ell}$ denotes the associated orthonormal eigenvector of the $\ell$-th largest eigenvalue of $\underline{S}_{N}:=\frac{1}{N}ZZ^{'}$ and $S_{N}$, respectively. 

To conduct the hypothesis testing in \eqref{eq:_null_hypothesis}, the associated test statistic proposed in this paper can be obtained by equating the sample analogue of
\begin{equation}
\mathbb{E}\left[\lambda_{\ell}\cdot\left(\frac{1}{\gamma_{j}^{2}}\left(q_{\ell}^{'}Y^{*}\right)^{2}-1\right)\right]=0,\label{eq:_a_moment_of_interest}
\end{equation}
where $Y^{*}=Y-X\beta_{0}$, $Y=\left(y_{1},\ldots,y_{N}\right)^{'}$, 
$X=\left(x_{1},\ldots,x_{N}\right)^{'}$, 
and $\gamma_{j}^{2}:=\mathbb{E}\varepsilon_{j}^{2}$. 
Similar (high-dimensional) moment condition was studied in \citet{Feng2024} to overcome the curse of dimensionality of coefficients in linear regression models with a presence of (unconditional) heteroskedasticity and autocorrelation of an unknown form. 
%Despite of beta being low dimensional in our model, the moment \eqref{eq:_a_moment_of_interest} remains useful for conducting the test with a presence of many weak instruments. 
After substituting $\gamma_{j}^{2}$ with its plug-in estimator under the null, namely $\frac{Y^{*'}Y^{*}}{N}$, the statistic of interest is obtained by evaluating its associated sample counterpart: 
\begin{align}
M_{N} & =\frac{1}{N}\sum_{\ell=1}^{\min\left\{K,N\right\} }\lambda_{\ell}\left(N\left(q_{\ell}^{'}\underline{Y}\right)^{2}-1\right)\notag \\
 & =\sum_{\ell=1}^{\min\left\{ K,N\right\} }\left(q_{\ell}^{'}\underline{Y}\right)^{2}\lambda_{\ell}-\frac{1}{N}\sum_{\ell=1}^{\min\left\{ K,N\right\} }\lambda_{\ell},
\end{align}
where $\underline{Y}:=Y^{*}/\left(Y^{*'}Y^{*}\right)^{1/2}\in\left(0,1\right)$. Then, with a proper convergence rate (shown in Theorem \ref{thm:_oracle_null}), our (oracle) statistic of interest is given by
\begin{align}
Q_{N} & :=\sqrt{\frac{N^{2}}{2\text{tr}\left(\Sigma^{2}\right)}}\left(\sum_{\ell=1}^{\min\left\{ K,N\right\} }\left(q_{\ell}^{'}\underline{Y}\right)^{2}\lambda_{\ell}-\frac{1}{N}\sum_{\ell=1}^{\min\left\{ K,N\right\} }\lambda_{\ell}\right) \notag \\
 & =\sqrt{\frac{N^{2}}{2\text{tr}\left(\Sigma^{2}\right)}}\left(\underline{Y}{}^{'}\underline{S}_{N}\underline{Y}-\frac{1}{N}\text{tr}\left(\underline{S}_{N}\right)\right).
\end{align}
Unless stated otherwise, we denote $\underline{a}:a/\left(a^{'}a\right)^{1/2}$ a self-normalized version of any column vector $a.$  

To build intuition, suppose for the moment that the errors are homoskedastic, i.e., $\mathbb{E}(\varepsilon \varepsilon' |Z) = \gamma^2I_N$, where $\varepsilon = (\varepsilon_1, ..., \varepsilon_N)'$. 
By the law of iterated expectation,  
\begin{align}
    \mathbb{E}\left[\lambda_{\ell}\cdot\left(\frac{1}{\gamma^{2}}\left(q_{\ell}^{'}Y^{*}\right)^{2}-1\right)\right] 
    & = \mathbb{E} \left[ \lambda_{\ell} \frac{1}{\gamma^2} \left(
    q'_{\ell} \mathbb{E}(\varepsilon \varepsilon'|Z) q_{\ell}\right) -\lambda_{\ell} \right] \notag \\
    &= \mathbb{E} \left[ \lambda_{\ell} \frac{1}{\gamma^2} \left(\gamma^2 \cdot q'_{\ell} I_N q_{\ell} \right) - \lambda_{\ell} \right] =0,
\end{align}
under the null hypothesis, where $\ell$ is randomly chosen from the set $\{1, ..., \min\{K,N\}\}$.
We note that $q'_{\ell}q_{s}$ and $w'_{\ell}w_s$ are equal to one when $\ell = s$ for all $\ell, s = 1, ..., \min\{K,N\}$ but zero otherwise. On the other hand, under the alternative $\beta \neq \beta_0$, 
\begin{align}
\mathbb{E}\left[\lambda_{\ell}\cdot\left(\frac{1}{\gamma^{2}}\left(q_{\ell}^{'}Y^{*}\right)^{2}-1\right)\right] 
= \frac{1}{\gamma^2} \mathbb{E} \left[ \lambda_{\ell} \cdot (q'_{\ell} X \Delta)^2 \right] > 0, 
\end{align}
where $\Delta = \beta - \beta_0$.

For general error dependence, i.e., $\mathbb{E}(\varepsilon \varepsilon' | Z) = \Psi$, it is expected that under the null hypothesis, 
\begin{align}
    \mathbb{E}\left[\lambda_{\ell}\cdot\left(\frac{1}{\Psi_{ii}}\left(q_{\ell}^{'}Y^{*}\right)^{2}-1\right)\right] 
    = 
    \mathbb{E} \left[ \lambda_{\ell} \left( \frac{q'_{\ell}\varepsilon}{\Psi_{ii}}\right)^2 - \lambda_{\ell} \right] \rightarrow 0, 
\end{align}
where $\Psi^2_{ii}$ denotes the $i$-th diagonal entry of $\Psi$. The proposed test becomes robust against general error dependence with high-dimensional IVs if there exists, for some $i \in \{1, ..., N\}$, the sequence $\{ (q_{\ell}' \varepsilon \cdot \Psi_{ii}^{-1})^2\}_{\ell=1}^{\min\{K, N\}}$
converges to one in probability as $K$ and $N$ grow, 
where the quantity $q_{\ell}'\varepsilon \cdot \Psi_{ii}^{-1}$ is the inner product of an eigen basis generated by the Gram matrix $\underline{S}_N$ and the normalized regression errors. 
We establish the asymptotic validity of our inference procedure under the following regularity conditions. 
%Given the sequences $\left(y_{i},x_{i},z_{i}^{'}\right)$ for $i=1,\ldots,N$ are observable, we propose a novel technique to conduct inference for the structural parameter $\beta$ of the IV model in \eqref{eq: model} under the following regularity conditions. 

\begin{assumption}[High-dimensional asymptotic regime]
 The dimension of instruments is considered high-dimension such that $K\rightarrow\infty,$ $N\rightarrow\infty$, and $K/N \rightarrow c\in\left(0,\infty\right)$. \label{ass:_std_highdim_regime} 
\end{assumption}
%
With rank deficiency generally observed in sample covariance matrices, this regime is widely regarded as a standard high-dimensional paradigm in the literature \citep[see e.g.,][]{Ledoit2002, Bai2007, Onatski2013}. This paper introduces a more adaptable framework at a general level of intensity beyond that of \citet{Khan2024}, where the number of covariates may exceed its sample size.

\begin{assumption}[Instruments]
 The data generating process of $Z=\left(z_{1},\ldots,z_{N}\right)^{'}\in\mathbb{R}^{N\times K}$ is given by $z_{i}=\Sigma^{1/2}f_{i},$ where $f_{i}=\left(f_{1i},\ldots,f_{Ki}\right)^{'}$ for all $i=1,\ldots,N$, $\Sigma^{1/2}$ is the square root of a deterministic non-negative definite Hermitian matrix $\Sigma,$ and $\lambda_{max}\left(\Sigma\right)=O\left(1\right)$. Moreover, $f_{i}$ consists of $K$ independent and identically distributed (i.i.d.) random variables with mean zero, unit variance, and finite fourth moment. \label{ass:_instruments} 
\end{assumption}
%Assumption \ref{ass:_instruments} is recognized as a typical design in RMT literature \citep[e.g.,][]{Karoui2008, Li2024, hastie2022surprises, Zhang2025},which we employ to characterize correlations within instruments. 

Assumption \ref{ass:_instruments} is recognized as a typical design in RMT literature \citep[e.g.,][]{Karoui2008, dobriban2018high, hastie2022surprises, Li2024, farbmacher2024revisiting, Zhang2025},which we employ to characterize correlations within instruments. The instruments, therefore, possess a weak form of cross-sectional dependence defined in \citet{Chudik2011}. Qualitative instruments can also be included, but require standardization or variable transformation to ensure zero mean, unit variance, and a finite fourth moment (see, Theorem \ref{thm:_oracle_null}). 
Assumption \ref{ass:_instruments} allows us to apply RMT, which helps to generalize the error dependence structure, in the current setting with high-dimensional instruments, as can be seen in Assumption \ref{ass:_errors_iid_X} below. 

\begin{assumption}
Denote $a_{-i}$ a whole sequence of the random variable $a$ with the $i$-th entry removed. The two unobserved errors in the IV model are given by
\[
\varepsilon_{i}=\Xi_{\varepsilon}\left(i,\varepsilon_{-i}^{'},v^{'},\mathcal{M}^{'}\right), \;\; \text{and} \;\;
v_{i}=\Xi_{v}\left(i,v_{-i}^{'},\varepsilon^{'},\mathcal{M}^{'}\right),
\]
where $\Xi_{\varepsilon}$ and $\Xi_{v}$ are unknown functions and $\mathcal{M}=\left(m_{1}^{'},\ldots,m_{N}^{'}\right)^{'}$ where $m_{i}$ denotes a vector of exogenous variables that jointly explains the variation of the error at individual $i$ for all $i=0, \ldots, N$. %Both errors have zero mean and unit variance. 
The data generating process of $z$ is independent of $\varepsilon$ and $v$. \label{ass:_errors_iid_X}
\end{assumption}
%
The permitted structure of errors are general and flexible, accommodating complicated network or spatial dependence structure into account. Assumption \ref{ass:_errors_iid_X} ensures the mean independence of $\varepsilon$ and $v$ against instruments $z$. Specifically, $\mathbb{E}\left(\left.f_{i}^{\delta}\right|\varepsilon_{i},v_{i}\right)=\mathbb{E}\left(f_{i}^{\delta}\right)$, for $0<\delta\leq4$. 
%The assumption on the independency is standard in the literature \citep[See, also][]{Andrews2023}.

Define the self-normalized vector $u:=\left(u_{1},\ldots,u_{N}\right)$ where $u_{i}=\varepsilon_{i}/\left(\varepsilon^{'}\varepsilon\right)^{1/2}.$ The following theorem provides the null limiting distribution of $Q_{N}$, the oracle statistic, under high-dimensional IVs with a presence of (unconditional) heteroskedasticity in error processes.
\begin{thm}[Oracle statistic]
 \label{thm:_oracle_null} Suppose that Assumptions \ref{ass:_std_highdim_regime}-\ref{ass:_errors_iid_X} are satisfied. Further suppose that (i) $\mathbb{E}\left(f_{11}^{4}\right)=\kappa<\infty$,and (ii) $\sum_{i=1}^{N}\left|u_{i}^{3}\right|=o_{\mathbb{P}}\left(1\right).$ 
 Then, under the null hypothesis in \eqref{eq:_null_hypothesis}, 
\[
Q_{N}=\sqrt{\frac{N^{2}}{2\text{tr}\left(\Sigma^{2}\right)}}\left(\underline{Y}{}^{'}\underline{S}_{N}\underline{Y}-\frac{1}{N}\text{tr}\left(\underline{S}_{N}\right)\right)\overset{d}{\rightarrow}\mathcal{N}\left(0,1\right).
\]
\end{thm}
%
Replacing $\text{tr}\left(\Sigma^{2}\right)$ with the consistent estimator proposed by \citet{Li2012}, 
%and the unknown intercept with the OLS estimator under the null, 
we have the following asymptotic result for the feasible statistic.
\begin{cor}[Feasible statistic]
Under Assumptions \ref{ass:_std_highdim_regime}-\ref{ass:_errors_iid_X}, and all conditions in Theorem \ref{thm:_oracle_null}, we further assume that $\sum_{i=1}^{N}u_{i} = O_{\mathbb{P}}\left(1\right).$ Then, \label{cor:_Feasible_stat}
\[
\widehat{Q}_{N} := \sqrt{\frac{N^{2}}{2\widehat{\text{tr}\left(\Sigma^{2}\right)}}}\left(\underline{Y}^{'}\underline{S}_{N}\underline{Y}-\frac{1}{N}\text{tr}\left(\underline{S}_{N}\right)\right)\overset{d}{\rightarrow}\mathcal{N}\left(0,1\right),
\]
where $\widehat{\text{tr}\left(\Sigma^{2}\right)}:=\frac{1}{N\left(N-1\right)}\sum_{i\neq j}^{N}\left(z_{i}^{'}z_{j}\right)^{2}$ is a ratio-consistent estimator of $\text{tr}\left(\Sigma^{2}\right)$. 
%and $\widehat{\underline{Y}}:=\left(\widehat{\underline{Y}}_{1},\ldots,\widehat{\underline{Y}}_{N}\right)^{'}$ denotes the estimated vector of the self-normalized regression error $u$ such that $\widehat{\underline{Y}}_{j}=\frac{Y_{j}-\bar{Y}}{\sqrt{\sum_{m=1}^{T}\left(Y_{j}-\bar{Y}\right)^{2}}},$ where $\bar{Y}=\frac{1}{T}\sum_{j=1}^{T}Y_{j},$ for all $j=1,\ldots,T.$ 
\end{cor}
%


Let $\Delta = \beta - \beta_0$. The alternative with local departure is defined as
\begin{equation}
H_{1}:h^{2}:=\frac{N}{\left(2\text{tr}\left(\Sigma^{2}\right)\right)^{2/5}}\Delta^{2}>0,\label{eq:=000020local=000020alternative}
\end{equation}
