\subsection{Proof of Theorem \ref{thm:_power_theory}}

Under the alternative \eqref{eq:=000020local=000020alternative}, we have $Y=X\Delta+\varepsilon$. The test statistic $Q_{N}$ can be decomposed to 
\begin{align*}
Q_{N} & =\sqrt{\frac{N^{2}}{2\text{tr}\left(\Sigma^{2}\right)}}\left(\frac{\left(X\Delta + \varepsilon\right)^{'}}{\left\Vert X\Delta + \varepsilon\right\Vert }\left(\underline{S}_{N}\right)\frac{\left(X\Delta + \varepsilon\right)}{\left\Vert X\Delta + \varepsilon\right\Vert }-\frac{1}{N}\text{tr}\left(\underline{S}_{N}\right)\frac{\left\Vert X\Delta + \varepsilon\right\Vert ^{2}}{\left\Vert X\Delta + \varepsilon\right\Vert ^{2}}\right)\frac{\frac{1}{\left\Vert \varepsilon\right\Vert ^{2}}}{\frac{1}{\left\Vert \varepsilon\right\Vert ^{2}}}\\
 & =\frac{\sqrt{\frac{N^{2}}{2\text{tr}\left(\Sigma^{2}\right)}}\left(u^{'}\underline{S}_{N}u-\frac{1}{N}\text{tr}\left(\underline{S}_{N}\right)\left(\frac{\left\Vert X\Delta + \varepsilon\right\Vert ^{2}}{\left\Vert \varepsilon\right\Vert ^{2}}\right)\right)+\frac{\Delta^{2}X^{'}ZZ^{'}X}{\sqrt{2\text{tr}\left(\Sigma^{2}\right)}\left\Vert \varepsilon\right\Vert ^{2}}+\frac{2\Delta X^{'}ZZ^{'}\varepsilon}{\sqrt{2\text{tr}\left(\Sigma^{2}\right)}\left\Vert \varepsilon\right\Vert ^{2}}}{\frac{\left\Vert X\Delta+\varepsilon\right\Vert ^{2}}{\left\Vert \varepsilon\right\Vert ^{2}}}\\
 & =:\frac{J_{1}}{J_{2}},
\end{align*}
where $\left\Vert X\Delta + \varepsilon\right\Vert ^{2} = \Delta^{2}X^{'}X + 2 \Delta X^{'}\varepsilon + \varepsilon^{'}\varepsilon$. We aim to show the following:

(i) $J_{1}\overset{d}{\rightarrow}\mathcal{N}\left(\varpi_{N},1\right),$ where $\varpi_{N}$ is defined in Theorem \ref{thm:_power_theory},
% \begin{align*}
% \varpi_{N} & =\frac{N}{\left\Vert \varepsilon\right\Vert ^{2}\left(2\text{tr}\left(\Sigma^{2}\right)\right)^{1/10}}h^{2}\left(\pi^{'}S_{N}^{2}\pi+\frac{1}{N}v^{'}\underline{S}_{N}v-\frac{1}{N}\text{tr}\left(S_{N}\right)\pi^{'}S_{N}\pi\right)\\
%  & -\frac{2 N^{1/2}}{\left\Vert \varepsilon\right\Vert ^{2}\left(2\text{tr}\left(\Sigma^{2}\right)\right)^{3/10}}hv^{'}\left(\frac{1}{N}\text{tr}\left(S_{N}\right)I_{N}-\underline{S}_{N}\right)\varepsilon.
% \end{align*}
and

(ii) $J_{2}=\frac{\Delta^{2}X^{'}X + 2\Delta X^{'}\varepsilon+\varepsilon^{'}\varepsilon}{\left\Vert \varepsilon\right\Vert ^{2}}\overset{p}{\rightarrow}1.$ 
\begin{proof}[Proof of the statement (ii)]
 First consider the denominator $J_{2}$, it suffices to show that $J_{21}:=\frac{\Delta^{2}X^{'}X}{\left\Vert \varepsilon\right\Vert ^{2}}$ and $J_{22}:=\frac{2\Delta^{}X^{'}\varepsilon}{\left\Vert \varepsilon\right\Vert ^{2}}$ converge in probability to zero. 
 Recall that the signal length of $\Delta$ is directly proportional to $\left(\frac{\text{tr}^{2/5}\left(\Sigma^{2}\right)}{N}\right)^{1/2}$. 
 In addition, the first-stage equation in matrix form is given by $X=Z\pi+v.$ Then, 
\begin{align*}
0\leq\frac{\Delta^{2}\left(Z\pi+v\right)^{'}\left(Z\pi+v\right)}{\left\Vert \varepsilon\right\Vert ^{2}} & =\frac{\Delta^{2}\pi^{'}Z^{'}Z\pi+2\Delta^{2}v^{'}Z\pi+\Delta^{2}v^{'}v}{\left\Vert \varepsilon\right\Vert ^{2}}\\
 & =:J_{211}+J_{212}+J_{213}.
\end{align*}

To show $J_{21}\overset{p}{\rightarrow}0$, it suffices to show that $J_{21i}\overset{p}{\rightarrow}0$ for $i=1,2,3$. By Condition (i), $J_{213}=\frac{\Delta^{2}\frac{1}{N}v^{'}v}{\frac{1}{N}\left\Vert \varepsilon\right\Vert ^{2}}\overset{p}{\rightarrow}0.$ By the trace inequality, 
\begin{align*}
J_{211} & =\frac{\Delta^{2}\pi^{'}S_{N}\pi}{\frac{1}{N}\left\Vert \varepsilon\right\Vert ^{2}}\leq\frac{h^{2}\text{tr}^{2/5}\left(\Sigma^{2}\right)}{N}\frac{\lambda_{\max}\left(S_{N}\right)\pi^{'}\pi}{\frac{1}{N}\left\Vert \varepsilon\right\Vert ^{2}}\\
 & = O_{\mathbb{P}}\left(\frac{h^{2}K^{2/5}\pi^{'}\pi}{N}\right)\overset{p}{\rightarrow}0.
\end{align*}
By Jensen's inequality, and the trace inequality, 
\begin{align}
\mathbb{E}\left|v^{'}Z\pi\right| & \leq\left(\mathbb{E}\left(v^{'}Z\pi\pi^{'}Zv\right)\right)^{1/2}\nonumber \\
 & =\left(v^{'}\mathbb{E}\left(\left.\sum_{i=1}^{N}\sum_{j=1}^{N}e_{i}f_{i}^{'}\Sigma^{1/2}\pi\pi^{'}\Sigma^{1/2}f_{j}e_{j}^{'}\right|v\right)v\right)^{1/2}\nonumber \\
 & =\left(\mathbb{E}\left(\pi^{'}\Sigma^{1/2}\mathbb{E}\left(\left.\sum_{i=1}^{N}\sum_{j=1}^{N}f_{j}f_{i}^{'}\right|v\right)\Sigma^{1/2}\pi v_{i}v_{j}\right)\right)^{1/2}\nonumber \\
 & =\left(\pi^{'}\Sigma\pi\cdot\mathbb{E}\left(\sum_{i=1}^{N}v_{i}^{2}\right)\right)^{1/2}=O\left(\left(\pi^{'}\pi\right)^{1/2}N^{1/2}\right).\label{eq:_vZPi}
\end{align}

By Markov's inequality,
\[
J_{212}=\frac{\Delta^{2}v^{'}Z\pi}{\frac{1}{N}\left\Vert \varepsilon\right\Vert ^{2}}=\frac{h^{2}\text{tr}^{2/5}\left(\Sigma^{2}\right)}{N^{2}}O_{\mathbb{P}}\left(\left(\pi^{'}\pi\right)^{1/2}N^{1/2}\right)\overset{p}{\rightarrow}0.
\]

Next, we aim to show the term $\frac{2\Delta^{}X^{'}\varepsilon}{\left\Vert \varepsilon\right\Vert ^{2}}$ converges in probability.
\begin{align*}
J_{22}^{2} & =\frac{4\Delta^{2}\left(Z\pi+v\right)^{'}\varepsilon\varepsilon^{'}\left(Z\pi+v\right)}{\left\Vert \varepsilon\right\Vert ^{4}}\\
 & =\frac{\frac{4}{N^{2}}\Delta^{2}\pi^{'}Z^{'}\varepsilon\varepsilon^{'}Z\pi+\frac{8}{N^{2}}\Delta^{2}\varepsilon^{'}Z\pi+\frac{4}{N^{2}}\Delta^{2}\left(v'\varepsilon\right)^{2}}{\frac{1}{N^{2}}\left\Vert \varepsilon\right\Vert ^{4}}\\
 & :=\frac{J_{221}+J_{222}+J_{223}}{J_{224}}.
\end{align*}
It suffices to show that $J_{221},J_{222},J_{223}\overset{p}{\rightarrow}0$ since $J_{224}=O_{\mathbb{P}}\left(1\right)$ due to Condition (i). Being analogous to Equation \eqref{eq:_vZPi}, we have $\mathbb{E}\left(\pi^{'}Z^{'}\varepsilon\varepsilon^{'}Z\pi\right)=O\left(\pi^{'}\pi\cdot N\right)$. With Markov's inequality,
\[
J_{211}=O_{\mathbb{P}}\left(\frac{h^{2}\text{tr}^{2/5}\left(\Sigma^{2}\right)}{N^{3}}\pi^{'}\pi\cdot N\right)\overset{p}{\rightarrow}0.
\]

Along with Jensen's inequality, we follow the same fashion as in Equation \eqref{eq:_vZPi} to show that $J_{222}\overset{p}{\rightarrow}0.$ By Cauchy-Schwartz's inequality and Condition (i), $J_{223}\leq M\Delta^{2}\left(\frac{1}{N}v^{'}v\right)\left(\frac{1}{N}\varepsilon^{'}\varepsilon\right)=O_{\mathbb{P}}\left(\Delta^{2}\right)\overset{p}{\rightarrow}0.$ We complete the proof of the statement (ii). 
\end{proof}
