\end{align*}

\textbf{Addressing $J_{1311}:$} Using the trace property yields,
\begin{align*}
\left(\frac{1}{N}\left\Vert \varepsilon\right\Vert ^{2}\right)^{1/2}J_{1311} & =\frac{1}{\sqrt{2N\text{tr}\left(\Sigma^{2}\right)}}\sum_{j=1}^{N}\left(f_{j}^{'}\Sigma F_{j}u\Delta\pi^{'}\Sigma^{1/2}f_{j}-\Delta\pi^{'}\Sigma^{3/2}F_{j}u\right)\\
