\end{align*}

By Condition (i) of Theorem \ref{thm:_power_theory}, we know that $\frac{1}{N}\left\Vert \varepsilon\right\Vert ^{2}\overset{p}{\rightarrow}\alpha_{1}<\infty.$ Along with Markov's inequality and Jensen's inequality, it suffices to prove that $\mathbb{E}\left(J_{13111}^{2}\right),\,\mathbb{E}\left(J_{13112}^{2}\right)\rightarrow0.$ By construction, $\sum_{j=1}^{N}F_{j}=\sum_{j=1}^{N}\left(F-f_{j}e_{j}^{'}\right)=\left(N-1\right)F.$ As a result,
\begin{align*}
\mathbb{E}\left(J_{13112}^{2}\right) & =\frac{\mathbb{E}\left(\Delta\pi^{'}\Sigma^{3/2}\sum_{j=1}^{N}F_{j}u\right)^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\\
 & =\frac{\left(N-1\right)^{2}\mathbb{E}\left(\sum_{j=1}^{N}\Delta\pi^{'}\Sigma^{3/2}f_{j}e_{j}^{'}u\right)^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\\
 & =\frac{\left(N-1\right)^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j=1}^{N}\left(u_{j}^{2}\Delta^{2}\pi^{'}\Sigma^{3/2}f_{j}f_{j}^{'}\Sigma^{3/2}\pi\right)+\sum_{j\neq i}^{N}\left(u_{j}u_{i}\Delta^{2}\pi^{'}\Sigma^{3/2}f_{j}f_{i}^{'}\Sigma^{3/2}\pi\right)\right]\\
 & =\frac{\left(N-1\right)^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\cdot\Delta^{2}\pi^{'}\Sigma^{3}\pi\cdot\mathbb{E}\left(\sum_{j=1}^{N}u_{j}^{2}\right)\rightarrow0.
\end{align*}

Moreover,
\begin{align*}
\mathbb{E}\left(J_{13111}^{2}\right) & =\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j=1}^{N}\left(f_{j}^{'}\Sigma F_{j}u\Delta\pi^{'}\Sigma^{1/2}f_{j}-\Delta\pi^{'}\Sigma^{3/2}F_{j}u\right)\right]^{2}\\
