With the same fashion proceeded in $L_{21}$, we address $L_{121}$ by 
\begin{align*}
L_{121} & =\mathbb{E}\left[\sum_{j\neq\ell}^{N}u_{\ell}\mathbb{E}\left(\left.\left(f_{j}^{'}\Sigma f_{\ell}\Delta\pi^{'}\Sigma^{1/2}f_{j}-\Delta\pi^{'}\Sigma^{3/2}f_{\ell}\right)\left(f_{\ell}^{'}\Sigma F_{j\ell}u\Delta\pi^{'}\Sigma^{1/2}f_{\ell}-\Delta\pi^{'}\Sigma^{3/2}F_{j\ell}u\right)\right|\mathcal{F}_{T,*}\right)\right]\\
 & =\mathbb{E}\left[\sum_{j\neq\ell}^{N}u_{\ell}\left(f_{\ell}^{'}\Sigma F_{j\ell}u\Delta\pi^{'}\Sigma^{1/2}f_{\ell}-\Delta\pi^{'}\Sigma^{3/2}F_{j\ell}u\right)\mathbb{E}\left(\left.\left(f_{j}^{'}\Sigma f_{\ell}\Delta\pi^{'}\Sigma^{1/2}f_{j}-\Delta\pi^{'}\Sigma^{3/2}f_{\ell}\right)\right|\mathcal{F}_{T,*}\right)\right]\\
 & =0.
\end{align*}

Let $\tilde{\Sigma}_{k}$ and $\tilde{\Sigma}_{k}^{1/2}$ denote the $k$-th column of matrix $\Sigma$ and $\Sigma^{1/2}$ respectively. Further denote $\left(A\right)_{ij}$ the $\left(i,j\right)$-th entry of a matrix $A$. For $L_{122}$, with Assumption \ref{ass:_errors_iid_X}, it follows that 
\begin{align*}
L_{122} & =\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j\neq\ell}^{N}u_{\ell}u_{j}\left(f_{j}^{'}\Sigma f_{\ell}\Delta\pi^{'}\Sigma^{1/2}f_{j}-\Delta\pi^{'}\Sigma^{3/2}f_{\ell}\right)\left(f_{\ell}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{\ell}-\Delta\pi^{'}\Sigma^{3/2}f_{j}\right)\right]\\
 & =\frac{\Delta^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j\neq\ell}^{N}u_{\ell}u_{j}\cdot\mathbb{E}\left(\left.f_{j}^{'}\Sigma f_{\ell}f_{\ell}^{'}\Sigma f_{j}\cdot f_{\ell}^{'}\Sigma^{1/2}\pi\pi^{'}\Sigma^{1/2}f_{j}\right|f_{\ell},u_{1},\ldots,u_{T}\right)\right]\\
 & =\frac{\Delta^{2}\mathbb{E}\left(f_{11}^{3}\right)}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j\neq\ell}^{N}u_{\ell}u_{j}\cdot\sum_{k=1}^{p}\left(f_{\ell}^{'}\tilde{\Sigma}_{k}\tilde{\Sigma}_{k}^{'}f_{\ell}\right)\left(\tilde{\Sigma}_{k}^{1/2}\pi\pi^{'}\Sigma^{1/2}f_{\ell}\right)\right]\\
 & =\frac{\Delta^{2}\mathbb{E}\left(f_{11}^{3}\right)}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j\neq\ell}^{N}u_{\ell}u_{j}\cdot\sum_{k=1}^{p}\sum_{s=1}^{p}\left(\tilde{\Sigma}_{k}\tilde{\Sigma}_{k}^{'}\right)_{ss}\left(\pi^{'}\tilde{\Sigma}_{s}^{1/2}\tilde{\Sigma}_{k}^{1/2}\pi\right)\right].
\end{align*}

Using the majorization property that $\underset{ss\in\left\{ 1,\ldots,p\right\} }{\text{max}}\left(\tilde{\Sigma}_{k}\tilde{\Sigma}_{k}^{'}\right)_{ss}\leq\lambda_{\max}\left(\Sigma\right),$ $\sum_{s=1}^{p}\pi^{'}\tilde{\Sigma}_{s}^{1/2}=\pi^{'}\Sigma^{1/2}\mathds{1}_{p}$ and Cauchy-Schwarz's inequality, it follows that 
\begin{align*}
0\leq\left|L_{122}\right| & \leq\frac{M\Delta^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\lambda_{\max}\left(\Sigma\right)\left(\pi^{'}\Sigma^{1/2}\mathds{1}_{p}\right)^{2}\left|\mathbb{E}\left(\sum_{j\neq\ell}^{N}u_{\ell}u_{j}\right)\right|\\
 & \leq\frac{M\Delta^{2}}{2N}\cdot\frac{\lambda_{\max}\left(\Sigma^{2}\right)}{\frac{1}{p}\text{tr}\left(\Sigma^{2}\right)}\cdot\pi^{'}\pi\cdot\mathbb{E}\left(\sum_{j=1}^{N}u_{j}\right)^{2}\\
 & \leq\frac{M\Delta^{2}}{2N}\cdot\frac{\lambda_{\max}\left(\Sigma^{2}\right)}{\frac{1}{p}\text{tr}\left(\Sigma^{2}\right)}\cdot\pi^{'}\pi\cdot N\mathbb{E}\left(\sum_{j=1}^{N}u_{j}^{2}\right)\rightarrow0.
\end{align*}

\textbf{Addressing $J_{1312}:$} We rewrite
\begin{align*}
\left(\frac{1}{T}\left\Vert \varepsilon\right\Vert ^{2}\right)^{1/2}J_{1312} & =\frac{\sum_{j=1}^{N}\left(\Delta\pi^{'}\Sigma^{1/2}f_{j}f_{j}^{'}\Sigma f_{j}e_{j}^{'}u\right)}{\sqrt{2N\text{tr}\left(\Sigma^{2}\right)}}\\
 & =\frac{1}{\sqrt{2N\text{tr}\left(\Sigma^{2}\right)}}\left[\sum_{j=1}^{N}\left(f_{j}^{'}\Sigma f_{j}e_{j}^{'}u\Delta\pi^{'}\Sigma^{1/2}f_{j}-\mathbb{E}\left(\left.f_{j}^{'}\Sigma f_{j}e_{j}^{'}u\Delta\pi^{'}\Sigma^{1/2}f_{j}\right|u\right)\right)\right]\\
 & +\sum_{j=1}^{N}\frac{u_{j}\mathbb{E}\left(\left.f_{j}^{'}\Sigma f_{j}\Delta^{'}\Sigma^{1/2}f_{j}\right|u\right)}{\sqrt{2N\text{tr}\left(\Sigma^{2}\right)}}=:J_{13121}+J_{13122}.
\end{align*}

It suffices to show that $J_{13121}$ and $J_{13122}$ converge in probability. To address $J_{13122},$ we apply Cauchy-Schwartz's inequality
\begin{align*}
0\leq J_{13122}^{2} & =\frac{\left(\sum_{j=1}^{N}u_{j}\mathbb{E}\left(\left.f_{j}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{j}\right|u\right)\right)^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\\
 & =\frac{N\left(\mathbb{E}\left(f_{1}^{'}\Sigma f_{1}\Delta\pi^{'}\Sigma^{1/2}f_{1}\right)\right)^{2}\sum_{j=1}^{N}u_{j}^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\\
 & =\frac{\left(\sum_{j=1}^{p}\Sigma_{jj}\Delta\pi^{'}\tilde{\Sigma_{j}}^{1/2}\mathbb{E}\left(f_{11}^{3}\right)\right)^{2}}{2\text{tr}\left(\Sigma^{2}\right)}\\
 & \leq\frac{M\lambda_{\max}\left(\Sigma\right)}{\text{tr}\left(\Sigma^{2}\right)}\left(\Delta\pi^{'}\Sigma^{1/2}\mathds{1}_{p}\right)^{2}\\
 & \leq\frac{M\lambda_{\max}\left(\Sigma^{2}\right)}{\frac{1}{K}\text{tr}\left(\Sigma^{2}\right)}\Delta^{2}\pi^{'}\pi\rightarrow0.
\end{align*}

The argument holds thanks to Markov's inequality. With the same fashion, we address $J_{13121}$ by showing that 
\begin{align*}
\mathbb{E}\left|J_{13121}\right|^{2} & =\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j=1}^{N}\left(f_{j}^{'}\Sigma f_{j}e_{j}^{'}u\Delta\pi^{'}\Sigma^{1/2}f_{j}-\mathbb{E}\left(\left.f_{j}^{'}\Sigma f_{j}e_{j}^{'}u\Delta\pi^{'}\Sigma^{1/2}f_{j}\right|u\right)\right)\right]^{2}\\
 & =\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left[\sum_{j=1}^{N}u_{j}^{2}\left(f_{j}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{j}-\mathbb{E}\left(f_{j}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{j}\right)\right)^{2}+\sum_{j\neq i}^{N}u_{i}u_{j}\cdot\right.\\
 & \left.\left(f_{j}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{j}-\mathbb{E}\left(f_{j}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{j}\right)\right)\left(f_{i}^{'}\Sigma f_{i}\Delta\pi^{'}\Sigma^{1/2}f_{i}-\mathbb{E}\left(f_{i}^{'}\Sigma f_{i}\Delta\pi^{'}\Sigma^{1/2}f_{i}\right)\right)\right]\\
 & =:L_{1}+L_{2}.
\end{align*}

It suffices to show that $L_{1},L_{2}\rightarrow0$. For $L_{1},$ we further decompose
\begin{align*}
L_{1} & =\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\mathbb{E}\left(\sum_{j=1}^{T}u_{j}^{2}\mathbb{E}\left[\left(f_{j}^{'}\Sigma f_{j}-\text{tr}\left(\Sigma\right)\right)\Delta\pi^{'}\Sigma^{1/2}f_{j}\right.\right.\\
 & \left.\left.-\mathbb{E}\left(f_{j}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{j}\right)+\text{tr}\left(\Sigma\right)\Delta\pi^{'}\Sigma^{1/2}f_{j}\right]^{2}\right)\\
 & \leq\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\cdot\mathbb{E}\left(1\right)\cdot\left(\mathbb{E}\left[\left(f_{j}^{'}\Sigma f_{j}-\text{tr}\left(\Sigma\right)\right)\Delta\pi^{'}\Sigma^{1/2}f_{j}\right]^{2}\right.\\
 & \left.+\mathbb{E}^{2}\left(f_{j}^{'}\Sigma f_{j}\Delta\pi^{'}\Sigma^{1/2}f_{j}\right)+\text{tr}^{2}\left(\Sigma\right)\mathbb{E}\left(\Delta\pi^{'}\Sigma^{1/2}f_{j}\right)^{2}\right)\\
 & \leq\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\left(\mathbb{E}\left[\left(f_{j}^{'}\Sigma f_{j}-\text{tr}\left(\Sigma\right)\right)^{2}\left(\Delta\pi^{'}\Sigma^{1/2}f_{j}\right)^{2}\right]\right)\\
 & +\frac{\lambda_{\max}\left(\Sigma^{2}\right)\left(\Delta\pi^{'}\Sigma\mathds{1}\right)^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}+\frac{\text{tr}^{2}\left(\Sigma\right)\Delta^{2}\pi^{'}\Sigma\pi}{2N\text{tr}\left(\Sigma^{2}\right)}\\
 & =:L_{11}+L_{12}+L_{13}.
\end{align*}
 Applying Holder's inequality to $L_{11}$ yields,
\begin{align*}
0\leq L_{11} & \leq\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\left(\left[\mathbb{E}\left(f_{j}^{'}\Sigma f_{j}-\text{tr}\left(\Sigma\right)\right)^{4}\mathbb{E}\left(\Delta\pi^{'}\Sigma^{1/2}f_{j}\right)^{4}\right]^{1/2}\right)\\
 & =\frac{1}{2N\text{tr}\left(\Sigma^{2}\right)}\cdot\mathbb{E}^{1/2}\left(f_{j}^{'}\Sigma f_{j}-\text{tr}\left(\Sigma\right)\right)^{4}\cdot\mathbb{E}^{1/2}\left(\Delta f_{j}^{'}\Sigma^{1/2}\pi\pi^{'}\Sigma^{1/2}f_{j}\right)^{2}\\
 & \leq\frac{K\Delta^{2}}{2N\text{tr}\left(\Sigma^{2}\right)}\cdot\text{tr}\left(\Sigma^{2}\right)\cdot\pi^{'}\Sigma\pi\rightarrow0.
\end{align*}

The last inequality holds due to Condition (ii), and Lemma \ref{lem:=000020Concentration=000020inequality}. With the same fashion, $L_{12}$ converges as $0\leq L_{12}\leq\frac{K\Delta^{2}\lambda_{\max}^{2}\left(\Sigma^{2}\right)}{\text{tr}\left(\Sigma^{2}\right)}\pi^{'}\pi\rightarrow0$. And, $0\leq L_{13}\leq\frac{\Delta^{2}\text{tr}^{2}\left(\Sigma\right)\lambda_{\max}\left(\Sigma^{2}\right)}{N\text{tr}\left(\Sigma^{2}\right)}\pi^{'}\pi\rightarrow0.$ 

For $J_{12},$ by definition, we directly have 
\begin{align*}
J_{12} & =\frac{\Delta^{2}\left(Z\pi+v\right)^{'}ZZ^{'}\left(Z\pi+v\right)}{\left\Vert \varepsilon\right\Vert ^{2}\sqrt{2\text{tr}\left(\Sigma^{2}\right)}}\\
 & =\frac{\Delta^{2}N^{2}\pi^{'}S_{N}^{2}\pi+2\Delta^{2}v^{'}ZZ^{'}Z\pi+\Delta^{2}Nv^{'}\underline{S}_{N}v}{\left\Vert \varepsilon\right\Vert ^{2}\sqrt{2\text{tr}\left(\Sigma^{2}\right)}}\\
 & :=J_{121}+J_{122}+J_{123},
\end{align*}
where $J_{121},J_{122}$ and $J_{123}$ are defined obviously. It suffices to show that $J_{122}\overset{p}{\rightarrow}0.$ By applying the same proof techniques used for $J_{131}$, we conclude that $J_{122}$ converges in probability. This completes the proof.

\end{proof}

