\caption{Staggered grid with variables \( w\) and \( v \), with \( \lambda \in \left\{ 0, \tfrac{1}{2} \right\} \)}
\label{fig_2}
\end{figure}
Assume that \( \{x_i\}_{i \in \mathbb{Z}} \) is a uniform grid with constant spacing \( h = x_{i+1} - x_i \), and define the midpoint by  $x_{i+\frac{1}{2}} = (x_i + x_{i+1})/{2}$ .
\par
In the staggered-grid configuration, \(v\) and \(w\) are located at different sets of grid points. Accordingly, two stencil point sets are introduced to support the discretization.
\[
\{ v_{i + p} \mid p\in \{-2, -1, 0, 1, 2\} \}, \quad
\{ w_{i + q} \mid q \in \{-\tfrac{3}{2}, -\tfrac{1}{2}, \tfrac{1}{2}, \tfrac{3}{2}\} \}.
\]
We follow the same construction strategy, with the only difference lying in the stencil point configuration. The approximations take the form:
\begin{equation}\label{eq-old}
\begin{aligned}
    &\sum_{k=0}^{3}\tilde{e}_kv_i^{(k)} = \sum_{p} a_{p} v_{i+p} + \mathcal{O}(h^4), \\
    &\sum_{k=0}^{3}\tilde{e}_kw_i^{(k+1)} = \sum_{q} \frac{b_{q+\f}}{h} w_{i+q} + \mathcal{O}(h^4),
\end{aligned}
\end{equation}
where the unknowns \( a_p \) and \( b_{q+\frac{1}{2}} \) are to be determined.
\par
To determine them, we apply Taylor expansions of \( v_{i+p} \) and \( w_{i+q} \) about the point \( x_i \) and substitute the results into \eqref{eq-old}. This yields linear combinations of derivatives, whose coefficients are then matched to the IMVL coefficients \( \tilde{e}_k \) for \( k = 0, 1, 2, 3 \), resulting in a linear system for \( a_p \) and \( b_{q+\frac{1}{2}} \).
\par
Solving the linear system yields the coefficients below. Since the coefficients \( a_p \) are identical to those in the node-centered formulation, they are omitted here.
\begin{gather*}
    b_1=-b_{0}= \frac{9-2m^2}{8}, \quad b_{2}=-b_{-1} =\frac{-1+2m^2}{24}.
\end{gather*}
The corresponding linear combinations are expressed as the following operators, where \( \lambda \in \left\{ 0, \tfrac{1}{2} \right\} \) indicates the staggered position of the variables.
\begin{align*}
    &\mathcal{A}(m,a_2)v_{i+\lambda }:= a_{2} v_{i-2+\lambda }+ a_{1} v_{i-1+\lambda}+a_0v_{i+\lambda}+a_1 v_{i+1+\lambda}+ a_2v_{i+2+\lambda},\\   
    & \delta(m)w_{i+\lambda}:=\frac{1}{h}(b_2w_{i+\frac{3}{2}+\lambda}+b_1w_{i+\f+\lambda}-b_1w_{i-\f+\lambda}-b_{2}w_{i-\frac{3}{2}+\lambda}).
\end{align*}
\begin{remark}
    The parameter \( \lambda \) reflects the staggered grid configuration of \( v \) and \( w \), acting as an index offset. This has no impact on the computation of \( a_{p} \) and \( b_{q+\f} \), as they are defined independently of \( \lambda \).
\end{remark}
To differentiate these parameters from those in \eqref{eq-opp}, \( m \) and \( a_2 \) are replaced by \( m^* \) and \( a_2^* \), respectively. This change is only for clarity and does not imply a fixed association with the numerical schemes introduced later. Applying equation \eqref{eq-eq} and Taylor expansion, we obtain
\begin{align}
  &\mathcal{A}(m^*,a^*_2)v_{i+\lambda} = \delta(m^*)w_{i+\lambda}+ h^4 w_{i+\lambda}^{(5)}( \frac{3}{640}  - \frac{{m^{*}}^2}{288} + a^*_2) \notag\\
   & + h^6 w_{i+\lambda}^{(7)}\left(\frac{135 + 80640 a^*_2 - 161 {m^{*}}^2 }{483840}\right) + h^8w_{i+\lambda}^{(9)}\left(\frac{3024a^*_2 + {m^{*}}^2}{241920}\right) +O(h^9).\label{eq-op} 
\end{align}
Appendix~A derives the truncation error for the above parameterized scheme. 
The truncation error shows that choosing
$a_2^* = \frac{{m^{*}}^2}{288} - \frac{3}{640}$
eliminates the leading fourth-order error, resulting in a sixth-order accurate scheme and forming a one-parameter family of sixth-order schemes.
\subsubsection{Examples of IMVL Schemes} 
Starting from the parameterized scheme, we select particular parameter values to derive specific numerical schemes, which will be employed in the numerical experiments presented later.
\par
For $ m=m^*=\frac{\sqrt 2}{2}, a_{2}=a_2^*=0$, the operators  $\mathcal{A}(m^*,{a_2}^*)$, $\delta({m}^*)$, $\mathcal{A}(m,a_2)$ and $\mathcal{H}(m) $ can be represented by the following schemes,where $\lambda \in \left\{ 0, \frac{1}{2} \right\}$
\begin{equation*}
 \textbf{HOS1:}\quad
\begin{aligned}
& \frac{1}{24}(v_{i+1+\lambda}+22v_{i+\lambda}+v_{i-1+\lambda}) = \frac{1}{h}(w_{i+\frac{1}{2}+\lambda} - w_{i-\frac{1}{2}+\lambda}) + O(h^4),\\
&\frac{1}{24}(v_{i+1}+22v_{i}+v_{i-1}) = \frac{1}{16h}(w_{i-2} -10 w_{i-1}+10 w_{i+1}-w_{i+2})+ O(h^4).
\end{aligned}
\end{equation*}
This numerical format adopted in \cite{shi2022fourth} was applied to solve nonlinear contaminant transport with adsorption.
\par
When $ m=m^*=\sqrt{2}, a_{2}=a_{2}^*=0$, we obtain new formats as follows:
\begin{equation*}
\textbf{HOS2:}\quad
\begin{aligned}
&\frac{1}{6}(v_{i-1+\lambda}+4v_{+\lambda}+v_{i+1+\lambda})=\frac{1}{8h}(-5w_{i-\frac{1}{2}+\lambda}+5w_{i+\frac{1}{2}+\lambda}+w_{i+\frac{3}{2}+\lambda}-w_{i-\frac{3}{2}+\lambda}) +O(h^4),\\
&\frac{1}{6}(v_{i-1}+4v_i+v_{i+1})=\frac{1}{2h}(w_{i+1}-w_{i-1}) +O(h^4).
\end{aligned}
\end{equation*}
\par
When $ m=m^*=\frac{\sqrt{11}}{2}, a_{2}=a_{2}^*=\frac{7}{1440}$, we obtain new sixth-order compact schemes as follows:
\begin{equation*}
\textbf{HOS3:}\quad
\begin{aligned}
&\frac{7}{1440}v_{i-2+\lambda}+\frac{151}{720}v_{i-1+\lambda}+\frac{137}{240}v_{i+\lambda}+\frac{151}{720}v_{i+1+\lambda}+\frac{7}{1440}v_{i+2+\lambda}\\
=&\frac{1}{16h}(-7w_{i-\frac{1}{2}+\lambda}+7w_{i+\frac{1}{2}+\lambda}+3w_{i+\frac{3}{2}+\lambda}-3w_{i-\frac{3}{2}+\lambda}) +O(h^6),\\
&\frac{7}{1440}v_{i-2}+\frac{151}{720}v_{i-1}+\frac{137}{240}v_i+\frac{151}{720}v_{i+1}+\frac{7}{1440}v_{i+2}
=\frac{1}{32h}(w_{i+2}-14w_{i-1}+14w_{i+1}-w_{i-2}) +O(h^6).
\end{aligned}
\end{equation*}
\par
Substituting the specific parameter values into the operators
$\mathcal{A}\left(9\sqrt{\frac{3}{119}}, \right.$ 
$\left.\frac{183}{76160}\right), \,
\delta\left(9\sqrt{\frac{3}{119}}\right), \,
\mathcal{A}\left(2\sqrt{\frac{6}{7}}, \frac{1}{70}\right)$ and
$\mathcal{H}\left(2\sqrt{\frac{6}{7}}\right)$,
we obtain the following eighth-order compact schemes
\begin{equation*}
\textbf{HOS4:}\quad
\begin{aligned}
&\frac{183}{76160}v_{i-2+\lambda}+\frac{3057}{19040}v_{i-1+\lambda}+\frac{3667}{5440}v_{i+\lambda}+\frac{3057}{19040}v_{i+1+\lambda}+\frac{183}{76160}v_{i+2+\lambda}\\
=&\frac{1}{2856h}(-1755w_{i-\frac{1}{2}+\lambda}+1755w_{i+\frac{1}{2}+\lambda}+367w_{i+\frac{3}{2}+\lambda}-367w_{i-\frac{3}{2}+\lambda}) +O(h^8),\\
&\frac{1}{70}v_{i-2}+\frac{8}{35}v_{i-1}+\frac{18}{35}v_i+\frac{8}{35}v_{i+1}+\frac{1}{70}v_{i+2}
=\frac{1}{84h}(5w_{i+2}+32w_{i+1}-32w_{i-1}-5w_{i-2}) +O(h^8).
\end{aligned}
\end{equation*}
\par
The above represents typical schemes, while various numerical formats can be derived by parameter variations, which will not be elaborated here.
\subsection{ High-Order Schemes for Contaminant Transport with Adsorption}
Building on the simplified setting, we now extend the IMVL framework to more complex models by developing high-order schemes for contaminant transport with adsorption.
\subsubsection{Periodic BC Numerical Schemes}
We first consider the construction of the scheme under periodic boundary conditions
\begin{equation}\label{eq-bc}
\begin{aligned}
& c_t+\phi(c)_t-(Dc_x)_x+(u c)_x =f(x, t), \quad(x, t) \in(0,x_R) \times(0, T], \\
&c(0,t)=c(x_R,t),\quad t\in (0, T],\\
&c(x,0)=c_0(x),\quad x\in (0,x_R).
\end{aligned}
\end{equation}
For the purpose of numerical scheme construction, we introduce the auxiliary variables \( z = -D c_x \), \( q = z_x \), and \( p = (u c)_x \), representing the diffusive flux, the divergence of the flux, and the convection term, respectively.
Accordingly, equation \eqref{eq-bc} can be equivalently written as:
\begin{equation}\label{rewrite}
\begin{cases}
    & c_t+\phi(c)_t+ q+p=f(x, t), \quad(x, t) \in(0,x_R) \times(0, T], \\
    & -\frac{z}{D}=c_x, \quad(x, t) \in(0,x_R) \times(0, T],\\
    & q=z_x,\quad(x, t) \in(0,x_R) \times(0, T],\\
    &p=(uc)_x,\quad(x, t) \in(0,x_R) \times(0, T].
\end{cases}
\end{equation}
%\begin{equation}\label{rewrite}
%\begin{cases}
%    & \left(uc+z \right)_x=c_t+\phi(c)_t+f(x, t), \quad(x, t) \in(0,x_R) \times(0, T], \\
%& c_x=-\frac{z}{D}, \quad(x, t) \in(0,x_R) \times(0, T]\\
%&c(0,t)=c(x_L,t),\quad t\in (0, T],\\
%&c(x,0)=c_0(x),\quad x\in (x_L,x_R).
%\end{cases}
%\end{equation}
\par
We adopt a block-centered grid as illustrated in Figure 3, where fluxes are defined at cell centers and variables at cell boundaries. The mesh is constructed by dividing the interval \( [0, x_R] \) into points \( \Pi:x_0 = 0 < x_1 < \cdots < x_{J-1} < x_J = x_R \).
