\section{Theory of Transfer Learning in Infinite Width Two Layer Networks}\label{sec:theory}
\vspace{-5pt}
\subsection{Problem Setup}
\vspace{-3pt}
We start by describing our problem setup. We will consider two layer non-linear networks that learn a dataset, respectively $\mathcal{T}_1 = \{\bar{\bm x}_{\mu}, \bar{y}_{\mu} \}_{\mu=1}^{P_1}$ for the pre-trained model and $\mathcal{T}_2 = \{\bm x_{\mu}, y_{\mu}\}_{\mu=1}^{P_2}$ for the downstream task, composed of $P_1$ and $P_2$ input-output pairs respectively. We are interested in the regime where $P_1 \geq P_2$. We define the output of our MLP as
\begin{align}\label{eq::NN}
    &f_{\mu} = \frac{1}{\gamma_0 N} \bm w \cdot \phi\left(\frac{1}{\sqrt{D}}\bm W \bm x_{\mu} \right),
\end{align}
where $\bm x_{\mu} \in \mathbb{R}^D$ is a $D-$dimensional input vector,  $\bm W \in \mathbb{R}^{N\times D}$ is the first layer of weights to be learned, $\phi(\cdot)$ is a generic non-linear activation function, and $\bm w \in \mathbb{R}^N$ is the last layer weight vector. The same network parameterization is applied for the source model, whose collection of weights $\bar{\bm \theta} = \text{Vec}\{\bar{\bm W}, \bar{\bm w}\}$. We will indicate variables from the source model with $\bar{\cdot}$ notation.

In both settings we will consider, either the adaptive Neural Bayesian kernel (aNBK \cite{lauditi2025adaptive}) framework (different from the NNGP lazy kernel of~\cite{lee2018deepneuralnetworksgaussian}) or gradient descent dynamics of randomly initialized networks, both the source and target weights are Gaussian $W_{ij} \sim \mathcal{N}(0,1)$ under the prior, such that in the infinite width limit $N\to \infty$ the preactivation entries $\{\bar{h}_i, h_i \}_{i=1}^N$ evolve by $\Theta_N (1)$. This corresponds to the Bayesian version of $\mu$P/mean-field scaling for neural networks \cite{Mei2018, yang2021tensor, bordelon2022selfconsistentdynamicalfieldtheory}. We rescale the network output by $\gamma_0 N$ and use a learning rate $\eta = \eta_0 \gamma_0^2 N$ for the discretized dynamics accordingly to the mean-field ($\mu P$) parameterization~\cite{yang2021tensor,yang2022featurelearninginfinitewidthneural,Mei2018, rotskoff2018trainability}. Here, $\gamma_0 = \Theta_N(1)$ tunes the feature learning strength on a given task $\mathcal{T}_{1/2}$, allowing the preactivations to evolve during training in a task-dependent manner. In principle, we will allow the pre-trained and target models to learn with different richness parameters $\{\bar{\gamma}_0, \gamma_0\}$. 

\subsection{A Bayesian Framework for Transfer Learning in Two Layer Networks}\label{sec::bayesian_theory}


\begin{theorem}\label{result:bayes}
Consider a two layer MLP sampled from the aNBK Bayes posterior \cite{lauditi2025adaptive} for the source task $\mathcal T_1$, generating sampled weights $\bar{\bm\theta} = \{ \bm\bar{\W}, \bar\w \}$ from density
\begin{align}
    p(\bar{\bm\theta}) \propto \exp\left( - \frac{\beta N \gamma_0^2}{2} \mathcal L(\bar{\bm\theta},\mathcal T_1) - \frac{\lambda}{2} |\bm{\bar\theta}|^2 \right).
\end{align}
Subsequently, sample new weights $\bm\theta = \{\W, \w\}$ from the aNBK Bayes posterior for the target task $\mathcal T_2$ with an elastic penalty $\frac{\delta}{2}|\W - \bar{\W}|^2$ between source and target hidden weights in the log-prior
\begin{align}
    p(\bm\theta|\bar{\bm\theta}) \propto \exp \left(-\frac{\beta N \gamma_0^2}{2}\sum_{\mu = 1}^{P_2}\mathcal{L}(\bm \theta, \mathcal{T}_2)-\frac{\lambda}{2}||\bm \theta ||^2 -\frac{\delta}{2}||\bm W - \bar{\bm W}||^2 \right).
\end{align}
In the infinite width $N \to \infty$ limit with square loss, the predictor $f(\x_0)$ on test point $\bm x_0$ is a kernel predictor
\begin{align}\label{eq:aNBK}
    f(\bm x_0) = \sum_{\mu,\nu \in \mathcal T_2} \Phi(\bm x_0, \bm x_\mu) \left(\bm \Phi + \beta^{-1} \bm I \right)^{-1}_{\mu\nu} y_\nu
\end{align}
where $\bm \Phi \in \mathbb{R}^{P_2 \times P_2}$ is the \textbf{adapted feature kernel}, which depends on both tasks $\mathcal T_1$ and $\mathcal T_2$. The feature kernel can be obtained by solving a min-max problem $\min_{\bm\Phi} \max_{\hat{\bm\Phi}} \mathcal F[\bm\Phi,\hat{\bm\Phi}]$ where the function $\mathcal F$ is
\begin{align}\label{eq::datagram}
    &\mathcal F[\bm\Phi,\hat{\bm\Phi}] = -\frac{1}{2} \text{Tr}( \bm \Phi \hat{\bm \Phi}) + \frac{\gamma_0^2 }{2}\bm y^{\top} \Big(\bm \Phi + \frac{\bm I}{\beta} \Big)^{-1} \bm y - \mathbb{E}_{\bar{\h}} \ln \mathcal{Z}_2 [\bar{\bm h}] , \nonumber
    \\
    &\mathcal{Z}_{2}[\bar{\bm h}] = \int d \bm h\exp\left(-\frac{1}{2}\Big(\bm h-\frac{\delta}{1+\delta}\bar{\bm h}\Big)^{\top}\Big(\frac{\bm C^{(2,2)}}{1+\delta}\Big)^{-1}\Big(\bm h-\frac{\delta}{1+\delta}\bar{\bm h}\Big)-\frac{1}{2}\phi(\bm h)^{\top}\hat{\bm \Phi} \,\phi(\bm h)\right) ,\nonumber\\
    &C^{(2,2)}_{\mu\nu} \equiv \frac{1}{D} \bm x_\mu \cdot \x_\nu ,
\end{align}
where $C^{(2,2)}_{\mu\nu}$ is the data Gram matrix for all pairs of inputs $\x_\mu,\x_\nu \in \mathcal T_2$ and the average $\mathbb{E}_{\bar{\h}}$ represents an average over the hidden preactivation distribution $\bar{\h}$ induced by the source hidden weights on the target task data $\mathcal T_2$. The distribution of $\bar{\h}$ is itself obtained as a solution to a min-max problem involving only the source task $\mathcal T_1$ following \cite{lauditi2025adaptive}.
\end{theorem}

