The saddle point equations, which describe the $N \to \infty$ limit, are
\begin{align}
    \frac{\partial}{\partial \hat{\bm\Phi}}  \mathcal F[\bm\Phi,\hat{\bm\Phi}] = &\bm \Phi -\mathbb{E}_{\bar{\bm h}}\left[ \mathbb{E}_{\bm h |\bar{\bm h}}\, \phi (\bm h) \phi(\bm h)^{\top}\right] = 0, \\
    \frac{\partial}{\partial {\bm\Phi}} \mathcal F[\bm\Phi,\hat{\bm\Phi}] = &\hat{\bm \Phi} +\gamma_0^2 \Big(\frac{\bm{I}}{\beta}+\bm{\Phi}\Big)^{-1}\bm{y}\bm{y}^{\top}\Big(\frac{\bm{I}}{\beta}+\bm{\Phi}\Big)^{-1}= 0, \nonumber
\end{align}
where $\h|\bar{\h}$ is the distribution defined by the single-site moment generating function $\mathcal Z_2$ in Result \ref{result:bayes} while $\mathbb{E}_{\bar{\h}}$ refers to the average over the source field distribution on  the target task $\mathcal{T}_2$ (see Appendix~\ref{appendix::bayes} for details). In general, this single site density is non-Gaussian. As a result, the adaptive kernel $\bm \Phi$ collects all higher moments of the activation distribution, which are shifted by both the source fields $\bar{\bm h}$ and the term involving the dual kernel $\hat{\bm \Phi}$. However, in the lazy limit $\gamma_0 \to 0$, the dual kernel vanishes $\hat{\bm \Phi}\to 0$ and the preactivation distribution $p(\bm h |\bar{\bm h})$ simply recovers a Gaussian distribution $p(\bm h | \bar{\bm h})\sim \mathcal{N}(\frac{\delta}{1+\delta}\bar{\bm h}, \frac{\bm C^{(2,2)}}{1+\delta})$ with shifted mean and rescaled covariance, both dependent on the transfer from $\mathcal{T}_1$. Moreover, when both $\gamma_0 =\delta = 0$ we recover an unstructured Gaussian process $p(\h|\bar{\h}) \sim \mathcal{N}(0, \bm C^{(2,2)})$ ~\cite{lee2018deepneuralnetworksgaussian}. As clarified in Appendix~\ref{appendix::bayesian_generalization}, knowing the form of the free energy in Eq.~\eqref{eq::free_energy} makes it easy to compute the \textit{deterministic predictor} of the target model on a new unseen sample $\{\bm x_0, y_0\}$, which turns out to be a kernel regression predictor with the adapted target task kernel $\Phi(x,x')$ as in Eq.~\eqref{eq:aNBK}. Consistently with~\cite{lauditi2025adaptive}, $\bm \Phi(\bm x_0) = \mathbb{E}_{\bar{h}_0, \bar{\bm h}}\left[\mathbb{E}_{h_0, \bm h|\bar{h}_0, \bar{\bm h}} \,\phi(h_0)\phi(\bm h)\right]$ is the kernel between the test point $\bm x_0$ and the training data $\{\bm x_{\mu}\}_{\mu = 1}^{P_2} \in \mathcal{T}_2$ (see  Appendix~\ref{appendix::bayesian_generalization}).  

\subsection{Two Stage Gradient Flow Dynamics for Transfer Learning}\label{sec::dmft}

%In addition to Bayesian learning, we can also track the dynamics of a target network under gradient flow dynamics. %from random initial conditions for the readout weights $w_i \sim \mathcal{N}(0,1)$ and source initial conditions for hidden weights $\bm W(0) = \bar{\bm W}$. 
\begin{theorem}
    Consider a two-layer MLP with parameters $\bar{\bm \theta} =\text{Vec}(\bar{\bm W}, \bar{\bm w})$, trained on a source task $\mathcal{T}_1$ from random initial conditions $\bar{W}_{ij}(0),\bar{w}_j(0) \sim \mathcal{N}(0,1)$ under gradient flow with weight decay $\frac{d\bar{\bm \theta}}{dt} = -\bar{\gamma}_0^2 N \nabla_{\bar{\bm \theta}} \mathcal{L}-\lambda \bar{\bm \theta}$ and up to a time $\bar{t}$. Subsequently, a target model with parameters $\bm \theta$ is trained on a downstream task $\mathcal{T}_2$ from random initial conditions for the readout weights $w_i \sim \mathcal{N}(0,1)$ and source initial conditions for hidden weights $\bm W(0) = \bar{\bm W}$. The infinite width $N \to \infty$ dynamics of this second model under gradient flow, with weight decay and an elastic penalty $\frac{\delta}{2} |\bm W(t)-\bar{\bm W}|^2$ only on the first layer weights, converges after a training time $t$ to a predictor $f(\bm x_0, t)$ on a test point $\bm x_0$
    \begin{align}
        %f(\bm x_0, t_2 ) = e^{-\lambda \kappa t_2} f(\bm x_0, 0)+ \int_{0}^{t_2} e^{-\lambda \kappa (t_2-s)\sum_{\nu \in \mathcal{T}_2}}
        %\\
        f(\bm x_0,t) = \gamma_0^{-1} \mathbb{E}_{\psi, \{\bar{h}_{\mu}\}_{\mu \in P_2} } \left[ z(t) \phi(h_0(t))  \right]
    \end{align}
    where the preactivations and the readout variables evolve as stochastic processes
    \begin{align}
        &h_{\mu}(t) = e^{-(\lambda+\delta)t} \bar{h}_\mu +\frac{\delta}{\lambda + \delta}\left( 1-e^{-(\lambda + \delta)t}\right)\bar{h}_{\mu}+\gamma_0 \int_0^t ds e^{-(\lambda + \delta)(t-s)}\sum_{\nu \in \mathcal T_2 }\Delta_{\nu}(s) g_{\nu}(s) C^{(2,2)}_{\mu\nu},
    \nonumber
    \\
    & z(t) = e^{-\lambda t}\psi+ \gamma_0 \int_0^t e^{-\lambda (t-s) }\sum_{\mu \in \mathcal T_2} \Delta_{\mu}(s) \phi(h_{\mu}(s)),\nonumber
    \\
    & g_{\mu}(t) = \dot{\phi}(h_{\mu}(t))z(t)\label{eq::fields_dyn_dmft}
    \end{align}
    being $C^{(2,2)}_{\mu\nu}$ the data Gram matrix as in Eq.~\eqref{eq::datagram}. The average $\mathbb{E}_{\psi, \{\bar{h}_{\mu}\}_{\mu \in P_2} }$ is over both $\psi = w_i(0) \sim \mathcal{N}(0,1)$ and $\{ \bar{h}_\mu \}$, defined with its own stochastic process by evolving the DMFT equations on the source task $\mathcal{T}_1$ up to a time $\bar{t}$ as in~\cite{bordelon2022selfconsistentdynamicalfieldtheory}. $\Delta_{\mu}(t) = y_\mu - f_\mu(t)$ represents the error signal for a pattern $\mu \in \mathcal{T}_2$, and $g_\mu$ are the entries of the gradient vector $\bm g_{\mu}(t) = N \gamma_0 \frac{\partial f}{\partial \h_\mu}$.
\end{theorem}
A detailed derivation of this result is given in Appendix~\ref{appendix::dmft} and as an extension of~\cite{bordelon2022selfconsistentdynamicalfieldtheory}. To get this result, the first layer weight dynamics we consider on $\mathcal{T}_2$ takes the form 
\begin{align}
    \frac{d\bm W(t)}{dt} = -\frac{\gamma^2}{N}\sum_{\mu \in \mathcal{T}_2} \Delta_{\mu}(t)\bm g_{\mu}(t) \x_\mu^\top -\lambda \bm W(t)-\delta \left(\bm W(t) - \bar{\bm W} \right).
\end{align}
The above weight dynamics induces dynamics for the $h_\mu(t)$ variables. In the infinite width limit $N\to \infty$, the $N$ neurons become statistically independent and the predictions $f(x,t)$ concentrate. The predictor value can be determined by keeping track of the preactivations and readout variables (see Appendix~\ref{appendix::dmft}).

