\subsection{Linear Networks}\label{appendix::bayesian_linearNN}
If we specialize to linear networks where $\phi (h) \equiv h$ and to regression tasks, the target action can be solved explicitly. Indeed, this is given by
\begin{equation}
    S_2 = -\frac{1}{2}\sum_{\mu\nu} \Phi_{\mu\nu} \hat{\Phi}_{\mu\nu} + \frac{\gamma_0^2 }{2}\bm y^{\top} \Big(\bm \Phi + \frac{\bm I}{\beta} \Big)^{-1} \bm y - \langle \ln \mathcal{Z}_2 [\bar{\bm h}]\rangle_1 
\end{equation}
where the single-site remains now Gaussian even after feature learning, being 
\begin{align}
    \mathcal Z_2 = \int dh_\mu d\hat h_\mu \exp\left( - \frac{1}{2(1+\delta)} \hat h_\mu \hat h_\nu C_{\mu\nu} - \frac{1}{2} \sum_{\mu\nu} \hat\Phi_{\mu\nu} h_\mu h_\nu + i \sum_\mu \hat h_\mu ( h_\mu - \delta (1+\delta)^{-1} \bar h_\mu )  \right).
\end{align}

Here, we can think $\hat{\bm h}, \bm h$ as jointly Gaussian with 
\begin{align}
    &\begin{bmatrix}
        \hat{\bm h} 
        \\
        \bm h
    \end{bmatrix} \sim \mathcal{N}\left( \bm \mu, \bm \Sigma \right) \nonumber
    \\
    &\bm\mu = \begin{bmatrix}
        (1+\delta)^{-1} \bm C & -i \bm I
        \\
        -i \bm I & \hat{\bm \Phi}
    \end{bmatrix}^{-1} \begin{bmatrix}
       - i\delta(1+\delta)^{-1} \bar{\h}
        \\
        \bm 0
    \end{bmatrix} \nonumber
    \ , \ 
    \bm\Sigma = \begin{bmatrix}
         (1+\delta)^{-1}  \bm C & -i \bm I
        \\
        -i \bm I & \hat{\bm \Phi}
    \end{bmatrix}^{-1}.
\end{align}
The mean and covariance are equal to 
\begin{align}
   \left< \bm h \right>_{\cdot | \bm h} = \delta \left[ (1+\delta) \bm C^{-1} + \hat{\bm \Phi} \right ]^{-1} \bm{C}^{-1}\bar{\h}  \ , \ \text{Cov}_{\cdot |\bar \h}( \h) = \left[ (1+\delta) \bm C^{-1} + \hat{\bm\Phi} \right]^{-1}.
\end{align}

We can thus compute the correlation of $\bm h | \bar{\bm h}$ as $\left<\h \h^\top \right> = \left< \h\right> \left< \h \right>^\top + \text{Cov}(\h)$
\begin{align}
    \left< \h \h^\top \right>_{\cdot | \bar{\h}} = \left[ (1+\delta) \bm C^{-1} + \hat{\bm\Phi} \right]^{-1} + \delta^2 \left[ (1+\delta) \bm C^{-1} + \hat{\bm\Phi} \right]^{-1} \bm{C}^{-1} \bar{\h}_{\mathcal T_2} \bar{\h}_{\mathcal T_2}^\top \bm{C}^{-1}  \left[ (1+\delta) \bm C^{-1} + \hat{\bm\Phi} \right]^{-1}. 
\end{align}

Now, we must perform the covariance of $\bar \h$ using $\mathcal{Z}_1$. Note that this is technically $\bar{\h}$ restricted to the second dataset $\mathcal T_2$. The full covariance of $\bar{\h}$ for both $\mathcal T_1 \cup \mathcal T_2$ has the structure
\begin{align}
    \left< \bar{\h} \bar{\h}^\top \right> = \left[ \bm C_{\mathcal T_1 \cup \mathcal T_2}^{-1} + \begin{bmatrix}
        \hat{\bar{\bm\Phi}} & \bm 0
        \\
        \bm 0 & \bm 0
    \end{bmatrix} \right]^{-1} = \bm C_{\mathcal T_1 \cup \mathcal T_2}  \left[ \bm I +  \begin{bmatrix}
        \hat{\bar{\bm\Phi}} & \bm 0
        \\
        \bm 0 & \bm 0
    \end{bmatrix} \bm C_{\mathcal T_1 \cup \mathcal T_2}  \right]^{-1}.
\end{align}
We are interested in the lower $(2,2)$ block of this matrix, which gives the Schur complement
\begin{align}
    \left< \bar{\h}_{\mathcal T_2} \bar{\h}_{\mathcal T_2}^\top  \right> = \left[ [\bm C^{-1}]_{22} - [\bm C^{-1}]_{21} \left( \left[ \bm C^{-1}\right]_{11}+\hat{\bar{\bm \Phi}} \right)^{-1} [\bm C^{-1}]_{12}\ \right]^{-1}.
\end{align}

Thus we are left with the final equations for the target kernels
\begin{align}
    &\bm\Phi = \left[ (1+\delta) \bm C_{\mathcal T_2}^{-1} + \hat{\bm\Phi} \right]^{-1} \nonumber
    \\
    &+ \delta^2 \left[ (1+\delta) \bm C_{\mathcal T_2}^{-1} + \hat{\bm\Phi} \right]^{-1} \bm C^{-1}_{\mathcal T_2} \left[ [\bm C^{-1}]_{22} - [\bm C^{-1}]_{21} \left( \left[ \bm C^{-1}\right]_{11}+\hat{\bar{\bm \Phi}} \right)^{-1} [\bm C^{-1}]_{12}\ \right]^{-1} \bm C^{-1}_{\mathcal T_2} \left[ (1+\delta) \bm C_{\mathcal T_2}^{-1} + \hat{\bm\Phi} \right]^{-1} 
\end{align}
\begin{align}
    \hat{\bm \Phi} = -\gamma_0^2 \left( \bm \Phi + \beta^{-1} \bm I\right)^{-1} \bm y \bm y^{\top} \left( \bm \Phi + \beta^{-1} \bm I\right)^{-1} 
\end{align}
being the action
\begin{equation}
\begin{split}
    S_2 =& -\frac{1}{2}\text{Tr}(\bm \Phi \hat{\bm \Phi} )+ \frac{\gamma_0^2 }{2}\bm y^{\top} \Big(\bm \Phi + \frac{\bm I}{\beta} \Big)^{-1} \bm y + \frac{1}{2}\ln\det\Big[\bm I+\Big(\frac{\bm C_{\mathcal{T}_{2}}}{1+\delta}\Big)\hat{\bm \Phi}\Big]  \nonumber
    \\
    &- \frac{\delta^2}{2}\text{Tr} \Big(\left[(\bm C_{\mathcal{T}_{2}})^{-1}\Big[(1+\delta)(\bm C_{\mathcal{T}_{2}})^{-1}+\hat{\bm \Phi}\Big]^{-1} (\bm C_{\mathcal{T}_{2}})^{-1}\right] \left[ \left< \bar{\h}_{\mathcal T_2} \bar{\h}_{\mathcal T_2}^\top  \right>\right]\Big).
\end{split}
\end{equation}
The saddle point equations for the source kernels were firstly derived in~\cite{lauditi2025adaptive} and are instead
\begin{align}\label{eq::sp_linear}
    &\bar{\bm \Phi} =\left[\bm C_{\mathcal T_1}^{-1} + \hat{\bar {\bm\Phi}} \right]^{-1}  \nonumber
    \\
    & \hat{\bar{\bm \Phi}} =  -\bar{\gamma}_0^2 \left( \bar{\bm \Phi} + \beta^{-1} \bm I\right)^{-1} \bar{\bm y} \bar{\bm y}^{\top} \left( \bar{\bm \Phi} + \beta^{-1} \bm I\right)^{-1}.
\end{align}
\subsubsection{Train-Test adaptive kernels}
In order to compute the test-train kernel to get the network predictor in the linear case, we need to compute $\bm \Phi_{0T} =  \langle\bm{h}_{0}\bm{h}^{\top}\rangle=\langle\bm{h}_{0}\rangle\langle\bm{h}^{\top}\rangle+ \text{Cov}(\bm{h}_{0},\bm{h}^{\top})$. The covariance is computed by resorting to the single site extended to the test point with index $0$
\begin{equation}
    \mathcal{Z}_{2}[\bar{h}]\propto\int\prod_{\mu=0}^{P_{2}}dh_{\mu}\exp\left(-\frac{1}{2}\sum_{\mu\nu=0}^{P_{2}}\Big(h_{\mu}-\frac{\eta}{1+\eta}\bar{h}_{\mu}\Big)\Big(\frac{C_{\mu\nu}}{1+\eta}\Big)^{-1}\Big(h_{\nu}-\frac{\eta}{1+\eta}\bar{h}_{\nu}\Big)-\frac{1}{2}\sum_{\mu\nu=1}^{P_{2}}h_{\mu}h_{\nu}\hat{\Phi}_{\mu\nu}\right)
\end{equation}
 from which
 \begin{equation}
     \begin{bmatrix}
    \bm{\Lambda=}\left((1+\eta)\bm{C}^{-1}+\left(\begin{array}{cc}
0 & 0\\
0 & \hat{\bm{\Phi}}
\end{array}\right)\right)^{-1}
\end{bmatrix}
 \end{equation}
and $ \text{Cov}(\bm{h}_{0},\bm{h}^{\top})=\bm{\Lambda}_{0T}$. It remains to compute 
\begin{equation}
    \left(\begin{array}{c}
\langle\bm{h}_{0}\rangle_{\cdot |\bar{\bm h}} 
\\
\langle\bm{h}\rangle_{\cdot |\bar{\bm h}}
\end{array}\right) = \eta\left(\begin{array}{c}
\bm{\Lambda}_{00}(\bm{C}_{00}^{-1}\bar{\bm{h}}_{0}+\bm{C}_{0T}^{-1}\bar{\bm{h}})+\bm{\Lambda}_{0T}(\bm{C}_{T0}^{-1}\bar{\bm{h}}_{0}+\bm{C}_{TT}^{-1}\bar{\bm{h}})
\\
\bm{\Lambda}_{T0}(\bm{C}_{00}^{-1}\bar{\bm{h}}_{0}+\bm{C}_{0T}^{-1}\bar{\bm{h}})+\bm{\Lambda}_{TT}(\bm{C}_{T0}^{-1}\bar{\bm{h}}_{0}+\bm{C}_{TT}^{-1}\bar{\bm{h}})
\end{array}\right)
\end{equation}
where the subscript $0$ refers to the test point while $T$ to the training points $P_2 \in \mathcal{T}_2$. From Eq. ? we get
\begin{equation}\label{eq::traintest_linear}
    \begin{split}
        \langle\bm{h}_{0}\rangle_{\cdot |\bar{\bm h}}\langle\bm{h}^{\top}\rangle_{\cdot |\bar{\bm h}} =& \eta^{2}\bm{\Lambda}_{00}\Big(\bm{C}_{00}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}_{0}^{\top}\bm{C}_{00}^{-1}+\bm{C}_{00}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}^{\top}\bm{C}_{T0}^{-1}+\bm{C}_{0T}^{-1}\bar{\bm{h}}\bar{\bm{h}}_{0}^{\top}\bm{C}_{00}^{-1}+\bm{C}_{0T}^{-1}\bar{\bm{h}}\bar{\bm{h}}^{\top}\bm{C}_{T0}^{-1}\Big)\bm{\Lambda}_{0T}\\
        &+ \eta^{2}\bm{\Lambda}_{00}\Big(\bm{C}_{00}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}_{0}^{\top}\bm{C}_{0T}^{-1}+\bm{C}_{00}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}^{\top}\bm{C}_{TT}^{-1}+\bm{C}_{0T}^{-1}\bar{\bm{h}}\bar{\bm{h}}_{0}^{\top}\bm{C}_{0T}^{-1}+\bm{C}_{0T}^{-1}\bar{\bm{h}}\bar{\bm{h}}^{\top}\bm{C}_{TT}^{-1}\Big)\bm{\Lambda}_{TT}\\
        &+\eta^{2}\bm{\Lambda}_{0T}\Big(\bm{C}_{T0}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}_{0}^{\top}\bm{C}_{00}^{-1}+\bm{C}_{T0}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}^{\top}\bm{C}_{T0}^{-1}+\bm{C}_{TT}^{-1}\bar{\bm{h}}\bar{\bm{h}}_{0}^{\top}\bm{C}_{00}^{-1}+\bm{C}_{TT}^{-1}\bar{\bm{h}}\bar{\bm{h}}^{\top}\bm{C}_{T0}^{-1}\Big)\bm{\Lambda}_{0T}\\
        & +\eta^{2}\bm{\Lambda}_{0T}\Big(\bm{C}_{T0}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}_{0}^{\top}\bm{C}_{0T}^{-1}+\bm{C}_{T0}^{-1}\bar{\bm{h}}_{0}\bar{\bm{h}}^{\top}\bm{C}_{TT}^{-1}+\bm{C}_{TT}^{-1}\bar{\bm{h}}\bar{\bm{h}}_{0}^{\top}\bm{C}_{0T}^{-1}+\bm{C}_{TT}^{-1}\bar{\bm{h}}\bar{\bm{h}}^{\top}\bm{C}_{TT}^{-1}\Big)\bm{\Lambda}_{TT}.
    \end{split}
\end{equation}
As we did for the train kernels in the previous section, we are now interested in the lower $(2,2)$ block of each kernel matrix $\langle \bm{\bar{\bm h}} \bm{\bar{\bm h}}^{\top}\rangle_{\mathcal{T}_2}$ in Eq.~\eqref{eq::traintest_linear}, which would give the source kernel predictions of train and test kernels on $\mathcal{T}_2$, having learned the source task $\mathcal{T}_1$.
