\section{DMFT theory of transfer learning}\label{appendix::dmft}
In this section, we extend the derivation of~\cite{bordelon2022selfconsistentdynamicalfieldtheory} to include the effect of transfer learning in a two-layer network under gradient descent dynamics. As clarified in the main text in Eq.~\eqref{eq::NN}, given the mean-field parameterization we consider here, the gradient updates of our target network, whose first layer $\bm W$ is constrained with an elastic force $\delta$ to the source weights $\bar{\bm W}$, are given by
\begin{align}
    &\frac{d\bm W(t)}{dt} =  -\frac{\gamma^2}{N}\sum_{\mu \in \mathcal{T}_2} \Delta_{\mu}(t)\bm g_{\mu}(t)\phi(\bm h_{\mu}(t))^{\top}-\lambda \bm W(t)-\delta \left(\bm W(t) - \bar{\bm W}\right)\\
    &\frac{d\bm z(t)}{dt} = -\frac{\gamma^2}{N}\sum_{\mu \in \mathcal{T}_2} \Delta_{\mu}(t)\phi(\bm h_{\mu}(t))^{\top}-\lambda \bm z(t)
\end{align}
by calling $\bm g_{\mu}=\frac{\partial f_{\mu}}{\partial \bm h_{\mu}}$ and $\Delta_{\mu}=-\frac{\partial \mathcal{L}}{\partial f_{\mu}} $. Now, by noticing that $\bm h_{\mu} (t) =\frac{1}{\sqrt{D}}\bm W (t)\bm x_{\mu} $ we get
\begin{equation}
    \frac{d\bm h_{\mu}(t)}{dt} = -(\lambda + \delta)\bm h_{\mu}(t)+\delta \bar{\bm h}_{\mu}(t)+\gamma_0 \sum_{\nu}\Delta_{\nu}(t) \bm g_{\nu}(t)C^{(2,2)}_{\mu\nu}\label{eq::h_field_dmft} 
\end{equation}
where $C^{(2,2)}_{\mu\nu} = \frac{1}{D}\bm x_{\mu} \cdot \bm x_{\nu}$ with $\mu,\nu \in \mathcal{T}_2$. We notice that, when $\delta =0$ and there is no transfer from $\mathcal{T}_1$ to $\mathcal{T}_2$, the field dynamics is the same as~\cite{lauditi2025adaptive}. Instead, as soon as $\delta >0$, we get both contributions from the pre-activation fields of $\mathcal{T}_1$ and feature learning from $\mathcal{T}_2$.
We can do the same for the $\bm z_{\mu}(t)$ pre-gradient fields by noticing that $\bm z =\bm w(t) $ and then
\begin{align}
    \frac{d\bm z(t)}{dt} = \gamma_0 \sum_{\mu} \Delta_{\mu}(t) \phi(\bm h_{\mu}(t)).
\end{align}
 As a consequence, the network predictor evolve as
\begin{equation}\label{eq::f_dyn}
    \frac{df_{\mu}(t)}{dt} =  \sum_{\nu \in \mathcal{T}_2} \left[ \Phi_{\mu\nu}(t,t)+G_{\mu\nu}(t,t)C^{(2,2)}_{\mu\nu}\right]\Delta_{\nu}(t) -\lambda \kappa f_{\mu}(t)
\end{equation}
having introduced the feature and gradient kernel definitions
\begin{align}\label{eq::kernels_def_dmft}
    &\Phi_{\mu\nu}(t,s) = \frac{1}{N}\phi(\bm h_{\mu}(t)) \cdot \phi (\bm h_{\nu}(s))\\
    &G_{\mu\nu}(t,s) = \frac{1}{N}\bm g_{\mu}(t) \cdot  \bm g_{\nu}(s).
\end{align}
\begin{figure*}[h!]
    \centering
        \includegraphics[width=0.5\linewidth]{figures/tl_dmft_preact_delta.png}
    \caption{Preactivation distribution for different $\delta$ values. As $\delta$ becomes bigger, the target task distribution $p(\bm h)$ recovers the source task distribution $p(\bar{\bm h})$. Full colored lines are from a $N = 5000$ ReLU NN under gradient descent. Corresponding dashed curves are from DMFT theory.} 
    \label{fig::tl_dmft_preact}
\end{figure*}
The second term in Eq.~\eqref{eq::f_dyn} depends on $\kappa$, which is the degree of homogeneity of the output function, which we suppose $f(a\bm \theta) = a^{\kappa}f(\bm \theta)$ as well as the activation $\phi (a\bm \theta) = a^{\kappa}\phi(\bm \theta)$ (consistently with~\cite{bordelon2022selfconsistentdynamicalfieldtheory}). Now, to construct our mean field theory we should in principle compute the moment generating function
\begin{equation}
    Z \left[ \{\bm j_{\mu}, \bm v \}\right] = \left<\exp \left( \sum_{\mu}\bm j_{\mu} \cdot \bm \xi_{\mu} + \bm v \cdot \bm \psi\right) \right>_{\bm \theta_0 =\text{Vec}\{\bm W(0),\bm w(0)\}}
\end{equation}
whose average is taken over the random initialization of the fields $\bm \xi_{\mu} = \frac{1}{\sqrt{D}}\bm W(0)\bm x_{\mu}$ and $\bm \psi = \bm w(0)$, given the initialization of the weights as $\{W_{ij}, w_{j}\}\sim \mathcal{N}(0,1)$. In this simple case of a two-layer NN this step is redundant, since by enforcing the fields $\bm \xi_{\mu}$ and $\bm \psi$ definitions through Dirac functions
\begin{align}\label{eq::dirac_deltas}
    &1 = \int d\bm \xi_{\mu}\,\delta\left(\bm \xi_{\mu} -\frac{1}{\sqrt{D}}\bm W(0)\bm x_{\mu} \right) = \int \frac{d\bm \xi_{\mu}\, d\hat{\bm \xi}_{\mu}}{2\pi}\exp \left( i\hat{\bm \xi}_{\mu} \cdot \left(  \bm \xi_{\mu} -\frac{1}{\sqrt{D}}\bm W(0)\bm x_{\mu}\right)\right)\\
    &1 = \int d\bm \psi \,\delta \left( \bm \psi -\bm w(0)\right)= \int \frac{d\bm\psi \,d\hat{\bm \psi}}{2\pi}\, \exp \left(i\hat{\bm \psi}\cdot \left( \bm \psi -\bm w(0)\right) \right)
\end{align}
we realize that, because the field have no time dependency, it is enough to just keep track of the feature and gradient kernels values at each time $t$, i.e. $\Phi_{\mu\nu}(t,t), \,G_{\mu\nu}(t,t)$ and not their correlation across times. In this case, by enforcing the kernel definitions of Eq.~\eqref{eq::kernels_def_dmft} in the same way as Eq.~\eqref{eq::dirac_deltas}, in the infinite width limit $N\to \infty$ we get a MGF of the form $Z = \int d\Phi d\hat{\Phi}dG d\hat{G}\, \exp \left(NS\left[\Phi, \hat{\Phi}, G, \hat{G} \right] \right)$, and because everything is factorized over the $N$ neurons and the kernels concentrate, we get 
\begin{align}
    &\Phi_{\mu\nu} (t,t)= \langle \phi(h_{\mu}(t))\phi(h_{\nu}(t))\rangle, \quad \hat{\Phi}_{\mu\nu}(t,t) = 0 \nonumber
    \\
    & G_{\mu\nu}(t,t) = \left< g_{\mu}(t) g_{\nu}(t) \right>, \quad \hat{G}_{\mu\nu}(t,t) =0
\end{align}
which are averages over the stochastic processes
\begin{align}
    &h_{\mu}(t) = e^{-(\lambda+\delta)t}\xi_{\mu}+\frac{\delta}{\lambda + \delta}\left( 1-e^{-(\lambda + \delta)t}\right)\bar{h}_{\mu} \nonumber
    \\
    &+\gamma_0 \int_0^t ds e^{-(\lambda + \delta)(t-s)}\sum_{\nu}\Delta_{\nu}(s) g_{\nu}(s) C^{(2,2)}_{\mu\nu} \nonumber
    \\
    & z(t) = e^{-\lambda t}\psi+ \gamma_0 \int_0^t e^{-\lambda (t-s) }\sum_{\mu} \Delta_{\mu}(s) \phi(h_{\mu}(s)) \nonumber
    \\
    & g_{\mu}(t) = \dot{\phi}(h_{\mu}(t))z(t).
    \end{align}
    \begin{figure*}[h!]
    \centering
        \includegraphics[width=0.5\linewidth]{figures/tl_vs_P_gammat_05_fashionMNIST.png}
    \caption{Test loss vs $P_2$ for different $\delta$. Transfer learning is much more effective when sample size $P_2$ is small. Source task: $P_1 = 1000$ for $\{0,5\}$ classes of Fashion-MNIST and $\bar{\gamma}_0 = 1.0$. Target: $P_2$ for $\{0,9\}$ classes of Fashion-MNIST.} 
    \label{fig::tl_dmft_fashion}
\end{figure*}
\subsection{CNN extension}
It is easy to extend the DMFT field equations for a two-layer CNN. In this case, the network definition involves convolution over a set of spatial indices $a, b \in \mathcal{S}^0$
\begin{align}
    &h_{\mu ia}=\frac{1}{\sqrt{D}}\sum_{j=1}^{D}\sum_{b\in\mathcal{S}^{0}}W_{ijb} x_{\mu,j,a+b}\\
    &f_{\mu}=\frac{1}{\gamma_{0}N}\sum_{i=1}^{N}\sum_{a}w_{ia}\phi(h_{\mu ia}).
\end{align}
In our notation $a$ is the spatial displacement from the center of the filter at each layer where $b \in \mathcal{S}^{\ell}$ is the spatial relative field at layer $\ell$. The gradient signal is now defined as 
\begin{equation}
    \bm g_{\mu,a}= \gamma_0 N \sum_b \frac{\partial f}{\partial \bm h_{\mu,b}^{\ell +1}}
\end{equation}  
while the weight dynamics per filter is 
\begin{equation}
    \frac{d}{dt}\bm W_b(t) = \frac{\gamma_0}{\sqrt{N}}\sum_{\mu,a} \Delta_{\mu} \bm g_{\mu,a}\phi (\bm h_{\mu,a+b})^{\top}-\lambda \bm W_b(t)-\delta \left(\bm       
   W_b (t)- \bar{\bm W}_b \right)
\end{equation}
Given that, the stochastic dynamics for the pre-activation and pre-gradient signals becomes
\begin{equation}
    \begin{split}
        &\bm h_{\mu,a}(t) = e^{-(\lambda+\delta) t}\bm \xi_{\mu,a}(t) +\frac{\delta}{\lambda + \delta} \left(1-e^{-(\lambda + \delta)t} \right)\bar{\bm h}_{\mu,a} \nonumber
        \\
        &+ \gamma_0 \int_0^t dt' e^{-(\lambda+\delta) (t-t')}\sum_{\nu,b,c}\Delta_{\nu}(t') C^{(2,2)}_{\mu \nu, a+b,a+c} (t,t')\bm g_{\nu,c}^{\ell+1}(t')
        \\
        &\bm z_{\mu,a}(t) = e^{-\lambda t}\bm \psi_{\mu a}(t) + \gamma_0 \int_0^t dt' e^{-\lambda(t-t')}\sum_{\nu,b,c}\Delta_{\nu}(t')G_{\mu\nu,a-b,c-b}(t,t')\phi(\bm h_{\nu,c})
    \end{split}
\end{equation}
where again $\bm \xi_{\mu,a}^{\ell+1}(t) = \frac{1}{\sqrt{N}}\bm W^{\ell}(0)\phi (\bm h^{\ell}_{\mu a}(t))$ and $\bm\psi_{\mu a}^{\ell}(t) = \frac{1}{\sqrt{N}}\bm W^{\ell}(0) g_{\mu,a}^{\ell +1}(t)$ from the initial conditions.

