Given \( \varphi, \psi, g \in C(X, \mathbb{R}) \) with \( \psi > 0 \). Since the map $t\mapsto P_{\psi}(\varphi + t g)$ is convex by Theorem \ref{induced pressure prop}, one can show that the map $t \mapsto t^{-1} \left( P_{\psi}(\varphi + t g) - P_{\psi}(\varphi) \right)$ is increasing. Thus, the following two limits exist:
\[
d^{+} P_{\psi}( \varphi)(g): = \lim_{t \rightarrow 0+} \frac{1}{t} \left( P_{\psi}( \varphi + t g) - P_{\psi}( \varphi) \right)
\]
and
\[
d^{-} P_{\psi}( \varphi)(g) := \lim_{t \rightarrow 0-} \frac{1}{t} \left( P_{\psi}( \varphi + t g) - P_{\psi}( \varphi) \right).
\]
Furthermore, one can show that the following properties hold:
\begin{enumerate}
\item[(1)] \( d^{-} P_{\psi}( \varphi)(g) = -d^{+} P_{\psi}( \varphi)(-g) \);
\item[(2)] \( d^{-} P_{\psi}(\varphi)(g) \leqslant d^{+} P_{\psi}(\varphi)(g) \);
\item[(3)] If \( \lambda \geqslant 0 \), then \( d^{+} P_{\psi}(\varphi)(\lambda g) = \lambda d^{+} P_{\psi}(\varphi)(g) \).
\end{enumerate}
The induced topological pressure of \( P_{\psi}( \varphi) \)  is said to be G\^{a}teaux differentiable, if for all \( g \in C(X, \mathbb{R}) \), the following limit exists:
\[
\lim_{t \rightarrow 0} \frac{P_{\psi}( \varphi + t g) - P_{\psi}( \varphi)}{t}.
\]
The previous limit exists if and only if \( d^{+} P_{\psi}( \varphi)(g) = -d^{+} P_{\psi}( \varphi)(-g) \) holds for all \( g \in C(X,\mathbb{R}) \). % which is equivalent to the fact that the map \( g \mapsto d^{+} P_{\psi}( \varphi)(g) \) is linear.

\begin{definition}
 A probability measure \( \mu: \mathcal{B}(X) \rightarrow \mathbb{R} \)  is called the tangent functional (also known as the subdifferential) of \( P_{\psi}(\cdot) \) at \( \varphi \), if
 \[
P_{\psi}( \varphi + g) - P_{\psi}( \varphi) \geqslant \frac{\int g \, d \mu}{\int \psi \, d \mu}
\]
for all $g \in C(X, \mathbb{R})$.
Let \( t_{\psi, \varphi}(X, f) \) denote the set of all tangent functionals of \( P_{\psi}(\cdot) \) at \( \varphi \).
\end{definition}

The following theorem gives some basic properties of the tangent functional.

\begin{proposition}
Let \( (X, f) \) be a TDS with \( h_{top}(f) < +\infty \), and let \( \varphi, \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \). The following properties hold:
\begin{enumerate}
\item[(i)] \( t_{\psi, \varphi}(X, f) \) is a compact convex set;
\item[(ii)] \( \mathcal{M}_{\psi, \varphi}(X, f) \subset t_{\psi, \varphi}(X, f) \subset \mathcal{M}(X, f) \);
\item[(iii)] If the entropy map \(\mu\mapsto  h_\mu(f) \) is upper semi-continuous on $\mathcal{M}(X, f)$, then \( \mathcal{M}_{\psi, \varphi}(X, f) \) is non-empty, and thus \( t_{\psi, \varphi}(X, f) \neq \emptyset \);
\item[(iv)] \( \mu \in t_{\psi, \varphi}(X, f) \) if and only if
\[
P_{\psi}(\varphi) - \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} = \inf \Big\{ P_{\psi}(h) - \frac{\int h \, d\mu}{\int \psi \, d\mu} : h \in C(X) \Big\}
\]
holds;
\item[(v)] \( d^{+} P_{\psi}(\varphi)(g) \ge \sup \left\{ \frac{\int g \, d\mu}{\int \psi \, d\mu} : \mu \in t_{\psi, \varphi}(X, f) \right\} \) for every $g\in C(X,\mathbb{R})$.
\end{enumerate}
\end{proposition}
\begin{proof}
(i)  By definition, the compactness clearly holds. For every $\mu_1, \mu_2 \in t_{\psi,\varphi}(X, f)$ and every $g \in C(X, \mathbb{R})$, we have that
\[
P_{\psi}( \varphi + g) - P_{\psi}( \varphi) \geqslant \frac{\int g \, d \mu_i}{\int \psi \, d \mu_i} \quad i=1,2.
\]
For each $p \in [0,1]$, consider the measure $p\mu_1 + (1-p)\mu_2$. One can show that
\[
P_{\psi}( \varphi + g) - P_{\psi}( \varphi) \geqslant \frac{p\int g \, d \mu_{1}+(1-p)\int g \, d \mu_{2}}{p\int \psi \, d \mu_{1}+(1-p)\int \psi \, d \mu_{2}} = \frac{\int g \, d (p\mu_{1}+(1-p)\mu_{2})}{\int \psi \, d (p\mu_{1}+(1-p)\mu_{2})}.
\]
Therefore, $p\mu_{1}+(1-p)\mu_{2} \in t_{\psi,\varphi}(X, f)$.

(ii) Let \( \mu \in \mathcal{M}_{\psi, \varphi}(X, f) \),  \( g \in C(X, \mathbb{R}) \). By Theorem \ref{induced Variational Principle}, we have that
\[
P_{\psi}(\varphi + g) - P_{\psi}(\varphi) \geqslant \frac{h_{\mu}(f) + \int \varphi \, d\mu + \int g \, d\mu}{\int \psi \, d\mu} - \frac{h_{\mu}(f) + \int \varphi \, d\mu}{\int \psi \, d\mu} = \frac{\int g \, d\mu}{\int \psi \, d\mu}.
\]
Thus, \( \mathcal{M}_{\psi, \varphi}(X, f) \subset t_{\psi, \varphi}(X, f) \).

Next, we prove that \( t_{\psi, \varphi}(X, f) \subset \mathcal{M}(X, f) \). Let \( \mu \in t_{\psi, \varphi}(X, f) \). For every \( n \in \mathbb{Z} \) and every \( g \in C(X, \mathbb{R}) \),  by Theorem \ref{induced pressure prop} (vii), we have that
\[
\begin{aligned}
\frac{n \int (g \circ f - g) \, d\mu}{\int \psi d\mu} &\leqslant P_{\psi}(\varphi + n(g \circ f - g)) - P_{\psi}(\varphi) = 0.
\end{aligned}
\]
The arbitrariness of $n\in \mathbb{Z}$ implies that \( \int g \circ f \, d\mu = \int g \, d\mu \). Hence, we have that \( \mu \in \mathcal{M}(X, f) \).

(iii) By (ii) and Theorem \ref{induced Variational Principle}, this is obviously true.

(iv) It follows from the definition of tangent functional that
\begin{align*}
& \mu \in t_{\psi,\varphi}(X, f) \\
& \iff P_{\psi}(\varphi)-\frac{\int \varphi d \mu}{\int \psi d \mu} \leqslant P_{\psi}(\varphi+g)-\frac{\int \varphi+g d \mu}{\int \psi d \mu} \quad \forall g \in C(X, \mathbb{R})\\
& \iff P_{\psi}(\varphi) - \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} = \inf \Big\{ P_{\psi}(h) - \frac{\int h \, d\mu}{\int \psi \, d\mu} \mid h \in C(X,\mathbb{R}) \Big\}.
\end{align*}

(v) Take \( \mu \in t_{\psi, \varphi}(X, f) \) and $g\in C(X,\mathbb{R})$, for every \( t > 0 \), we have that
\[
\frac{\int g \, d\mu}{\int \psi \, d\mu} \leqslant t^{-1} \left( P_{\psi}(\varphi + t g) - P_{\psi}(\varphi) \right).
\]
Letting $t \to 0^{+}$, one has that
\[
\frac{\int g \, d\mu}{\int \psi \, d\mu} \leqslant d^{+} P_{\psi}(\varphi)(g).
\]
Since \( \mu \in t_{\psi, \varphi}(X, f) \) is chosen arbitrarily, the desired result follows immediately.
\end{proof}


\begin{theorem}
Let \( (X, f) \) be a TDS with \( h_{top}(f) < +\infty \), and let \( \varphi_1, \varphi_2, \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \). If $t_{\psi,\varphi_1}(X, f) \cap t_{\psi,\varphi_2}(X, f)\neq \emptyset$, then
\[
P_{\psi}\left( p \varphi_1 + (1-p) \varphi_2 \right) = P_{\psi}(\varphi_1) + (1-p) \frac{\int (\varphi_2 - \varphi_1) \, dm}{\int \psi \, dm},\quad \forall\, 0\le p \le 1
\]
for every $m \in t_{\psi,\varphi_1}(X, f) \cap t_{\psi,\varphi_2}(X, f)$,
and
$
t_{\psi,p \varphi_1 + (1 - p) \varphi_2}(X, f) \subset t_{\psi,\varphi_1}(X, f) \cap t_{\psi,\varphi_2}(X, f)
$ for every $0<p<1$.
\end{theorem}
\begin{proof}
Let \( m \in t_{\psi,\varphi_1}(X, f) \cap t_{\psi,\varphi_2}(X, f) \)  and \( 0 \le p \le 1 \). By Theorem \ref{induced pressure prop} (iv), we have that
\begin{equation}\label{3*}
\begin{aligned}
p P_{\psi}(\varphi_1) + (1 - p) P_{\psi}(\varphi_2) &\geqslant P_{\psi}(p \varphi_1 + (1 - p) \varphi_2) \\
&= P_{\psi}\left( \varphi_1 + (1 - p)(\varphi_2 - \varphi_1) \right)\\
 &\geqslant P_{\psi}(\varphi_1) + (1 - p) \frac{\int (\varphi_2 - \varphi_1) \, dm}{\int \psi \, dm}.
\end{aligned}
\end{equation}
Consequently, we have that
\[
P_{\psi}(\varphi_2) - \frac{\int \varphi_2 \, dm}{\int \psi \, dm} \geqslant P_{\psi}(\varphi_1) - \frac{\int \varphi_1 \, dm}{\int \psi \, dm}.
\]
The reverse inequality can be shown in a similar fashion since \( m \in t_{\psi,\varphi_1}(X, f) \cap t_{\psi,\varphi_2}(X, f) \). Hence, we have that
\begin{align}\label{3***}
P_{\psi}(\varphi_2) - \frac{\int \varphi_2 \, dm}{\int \psi \, dm} = P_{\psi}(\varphi_1) - \frac{\int \varphi_1 \, dm}{\int \psi \, dm}.
\end{align}
This together with inequality \eqref{3*} yields that
\begin{align} \label{3**}
P_{\psi}(p \varphi_1 + (1 - p) \varphi_2) = P_{\psi}(\varphi_1) + (1 - p) \frac{\int \varphi_2 - \varphi_1 \, dm}{\int \psi \, dm}.
\end{align}

Given $0<p<1$, let $\varphi_p=p \varphi_1 + (1 - p) \varphi_2$.  %For every \( \mu \in t_{\psi,\varphi_p}(X, f) \) and every \( g \in C(X, \mathbb{R}) \),
Since $t_{\psi,\varphi_1}(X, f) \cap t_{\psi,\varphi_2}(X, f)\neq \emptyset$, by \eqref{3***} and \eqref{3**} we have that
\[
P_{\psi}(\varphi_p) = pP_{\psi}(\varphi_1)+(1-p)P_{\psi}(\varphi_2).
\]
Let \( \mu \in t_{\psi,\varphi_p}(X, f) \) and $g\in C(X, \mathbb{R})$, by Theorem \ref{induced pressure prop} (iv) we have that
\begin{align*}
\int g d\mu &\le P_{\psi}(\varphi_p+g)-P_{\psi}(\varphi_p)\\
&\le pP_{\psi}(\varphi_1+\frac{g}{p})+(1-p)P_{\psi}(\varphi_2)-( pP_{\psi}(\varphi_1)+(1-p)P_{\psi}(\varphi_2))\\
&=p(P_{\psi}(\varphi_1+\frac{g}{p})-P_{\psi}(\varphi_1)).
\end{align*}
Hence, we have that $\int \frac{g}{p} d\mu\le P_{\psi}(\varphi_1+\frac{g}{p})-P_{\psi}(\varphi_1)$, which implies that $\mu\in t_{\psi,\varphi_1}(X, f)$. Similarly, one can show that  $\mu\in t_{\psi,\varphi_2}(X, f)$. This completes the proof of the theorem.
