\end{proof}

\subsection{Freezing States}  We extend the results established in \cite{hedges2024equivalence} for induced topological pressure . Precisely,  we introduce the concept of freezing states and zero-temperature limits of induced topological pressure, and investigate the relationship between equilibrium states and freezing states.

Let \( (X, f) \) be a TDS, and let \( \varphi, \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \).  For every \( \beta > 0 \), assume that $P_\psi(\beta \varphi)$ has an equilibrium state  \( \mu_{\beta} \),  \( \mu_{\infty} \) is called the \emph{zero temperature limit} of \( \varphi \), if  \( \left\{\mu_{\beta}\right\} \) converges to \( \mu_{\infty} \) in the weak-* sense as \( \beta \to \infty \). The function \( \varphi \) is said to \emph{freeze} at \( \beta_0 \), if there exists an invariant measure \( \mu \) such that  \( \mu \) is the equilibrium state of the induced topological pressure $P_\psi(\beta \varphi)$  for all \( \beta \geqslant \beta_0 \), and the measure  \( \mu \) is called a \emph{freezing state} of  \( \varphi \). It is clear that \( \mu \) is the zero temperature limit of \( \varphi \), if \( \mu \) is a freezing state of \( \varphi \).

The following result characterizes the relationship between equilibrium states and freezing states.

\begin{theorem}\label{freezing equivalent conditions}
Let \( (X, f) \) be a TDS with \( h_{top}(f) < +\infty \), and let \( \varphi, \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \). Let \( \mathcal{F} \) be a non-empty subset of \( \mathcal{M}(X, f) \). Then for all \( \beta \geqslant 1 \), \( \mathcal{F} \) is the set of equilibrium states for \( P_\psi(\beta \varphi) \) if and only if the following properties hold:
\begin{enumerate}
\item[(1)] \( \mathcal{F} \) is the set of equilibrium states of \( P_\psi(\varphi) \);
\item[(2)] For all \( \mu \in \mathcal{F} \),
\[
\frac{\int \varphi \, d\mu}{\int \psi \, d\mu} = \sup_{\nu \in \mathcal{M}(X, f)} \frac{\int \varphi \, d\nu}{\int \psi \, d\nu}.
\]
\end{enumerate}
\end{theorem}
\begin{proof}
First, assume that properties (1) and (2) hold.

Let \( \beta \geqslant 1 \), for every \( \nu \in \mathcal{M}(X, f) \backslash \mathcal{F} \) and every \( \mu \in \mathcal{F} \). By Theorem \ref{induced Variational Principle} and  (2), we have that
\begin{align*}
\frac{h_{\mu}(f) + \int \beta \varphi \, d\mu}{\int \psi \, d\mu}  = & \frac{h_{\mu}(f) + \int \varphi \, d\mu}{\int \psi \, d\mu} + (\beta - 1) \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} \\
> &  \frac{h_{\nu}(f) + \int \varphi \, d\nu}{\int \psi \, d\nu} + (\beta - 1) \frac{\int \varphi \, d\nu}{\int \psi \, d\nu} \\
= & \frac{h_{\nu}(f) + \beta \int \varphi \, d\nu}{\int \psi \, d\nu}.
\end{align*}
This implies that  the set of equilibrium states for \( \beta \varphi \) and $\psi$ is contained in \( \mathcal{F} \).

For every \( \mu \in \mathcal{F} \) and \( \nu \in \mathcal{M}(X, f) \), one can prove in a similar fashion that
\[
\frac{h_{\mu}(f) + \int \beta \varphi \, d\mu}{\int \psi \, d\mu}
\geqslant \frac{h_{\nu}(f) + \beta \int \varphi \, d\nu}{\int \psi \, d\nu}.
\]
Therefore, \( \mathcal{F} \) is the set of equilibrium states for \( \beta \varphi \) and $\psi$.

Next, assume that for all \( \beta \geqslant 1 \), \( \mathcal{F} \) is the set of equilibrium states for \( \beta \varphi \) and $\psi$.  The first property  obviously holds by taking \( \beta = 1 \). Now, we prove the second property  holds. Take \( \nu \in \mathcal{M}(X, f) \) and \( \mu \in \mathcal{F} \). For every \( \beta \geqslant 1 \), we have that
\[
\begin{aligned}
\frac{h_{\mu}(f) + \int \beta \varphi \, d\mu}{\int \psi \, d\mu} \geqslant \frac{h_{\nu}(f) + \beta \int \varphi \, d\nu}{\int \psi \, d\nu}.
\end{aligned}
\]
Hence, we have
\[
\begin{aligned}
\frac{h_{\mu}(f)}{\beta \int \psi \, d\mu} + \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} &\geqslant \frac{h_{\nu}(f)}{\beta \int \psi \, d\nu} + \frac{\int \varphi \, d\nu}{\int \psi \, d\nu}.
\end{aligned}
\]
Letting  \( \beta \to \infty \), we have that
\[
\begin{aligned}
\frac{\int \varphi \, d\mu}{\int \psi \, d\mu} \geqslant \frac{\int \varphi \, d\nu}{\int \psi \, d\nu}.
\end{aligned}
\]
This implies the desired result.
\end{proof}

Given $\varphi, \psi\in C(X, \mathbb{R})$ with $\psi>0$, let
\[
\operatorname{Max}^{\psi}(\varphi) := \sup_{\mu \in \mathcal{M}(X, f)} \frac{\int \varphi \, d\mu}{\int \psi \, d\mu}
\]
the above supremum is always attained by an invariant measure, since the map $\displaystyle \mu\mapsto \frac{\int \varphi \, d\mu}{\int \psi \, d\mu}$ is continuous and $\mathcal{M}(X, f)$ is weak$^*$ compact.
Furthermore, let
\[
M_{\text{max}}^{\psi}(\varphi) := \Big\{ \mu \in \mathcal{M}(X, f) : \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} = \operatorname{Max}^{\psi}(\varphi) \Big\}
\]
and
\[
h_{\infty}^{\psi}(\varphi) := \sup \Big\{ \frac{h_{\mu}(f)}{\int \psi \, d\mu} : \mu \in M_{\text{max}}^{\psi}(\varphi) \Big\}.
\]

\begin{corollary}
Let \( (X, f) \) be a TDS with \( h_{top}(f) < +\infty \), and let \( \varphi, \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \). If \( \mu_{\infty} \) is the zero temperature limit of \( \varphi \), then \( \mu_{\infty} \in M_{\text{max}}^{\psi}(\varphi) \).
\end{corollary}

\begin{proof}
Since \( \mu_{\infty} \) is the zero temperature limit of \( \varphi \), there exists a sequence of invariant measures \( \left\{\mu_{\beta}\right\} \) that converges to \( \mu_{\infty} \) as \( \beta \to \infty \), where $\mu_\beta$ is the  equilibrium state for \( P_\psi(\beta \varphi) \).
Morevoer, for every \( \nu \in \mathcal{M}(X, f) \) and \( \beta>0 \), we have that
\[
\begin{aligned}
\frac{h_{\mu_{\beta}}(f) + \int \beta \varphi \, d\mu_{\beta}}{\int \psi \, d\mu_{\beta}} \geqslant \frac{h_{\nu}(f) + \beta \int \varphi \, d\nu}{\int \psi \, d\nu}.
\end{aligned}
\]
Hence, we have
\[
\begin{aligned}
\frac{h_{\mu_{\beta}}(f)}{\beta \int \psi \, d\mu_{\beta}} + \frac{\int \varphi \, d\mu_{\beta}}{\int \psi \, d\mu_{\beta}} \geqslant \frac{h_{\nu}(f)}{\beta \int \psi \, d\nu} + \frac{\int \varphi \, d\nu}{\int \psi \, d\nu}.
\end{aligned}
\]
Let \( \beta \to \infty \),  we have that
\[
\frac{\int \phi \, d\mu_{\infty}}{\int \psi \, d\mu_{\infty}} \geqslant \frac{\int \phi \, d\nu}{\int \psi \, d\nu}.
\]
The arbitrariness of $\nu\in \mathcal{M}(X, f)$ implies the desired result.
\end{proof}

\begin{corollary}
Let \( (X, f) \) be a TDS with \( h_{top}(f) < +\infty \), and let \(  \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \). Fix \( \mu \in \mathcal{M}(X, f) \), if there exists some \( \phi \in C(X, \mathbb{R}) \) such that \( \mu \) is the equilibrium state for \( P_\psi(\phi) \), and \( h_{\mu}(f) = 0 \), then \( \mu \) is the equilibrium state for \( P_\psi(\beta \phi) \)  for every \( \beta \geqslant 1 \).
\end{corollary}
\begin{proof}
By Theorem \ref{freezing equivalent conditions}, it suffices to prove that \( \mu \in M_{\text{max}}^{\psi}(\phi) \).
Since \( \mu \) is the equilibrium state for \( P_\psi(\phi) \), and \( h_{\mu}(f) = 0 \),   we have that
\[
\begin{aligned}
\frac{\int \phi \, d\mu}{\int \psi \, d\mu}=\frac{h_{\mu}(f) + \int \phi \, d\mu}{\int \psi \, d\mu}
\geqslant  \frac{h_{\nu}(f) + \int \phi \, d\nu}{\int \psi \, d\nu} \geqslant \frac{\int \phi \, d\nu}{\int \psi \, d\nu}\quad \forall \nu \in \mathcal{M}(X, f).
\end{aligned}
\]
 This implies that \( \mu \in M_{\text{max}}^{\psi}(\phi) \).
\end{proof}

\begin{proposition} \label{Necessary Conditions for Differentiability}
Let \( (X, f) \) be a TDS with \( h_{top}(f) < +\infty \), and let \( \varphi, \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \), \(\beta \in \mathbb{R} \). Put \( P_{\psi, \varphi}(\beta) = P_{\psi}(\beta \varphi) \), and assume that \( P_{\psi, \varphi} \) is differentiable at \( \beta_0 \) and that there exists at least one equilibrium state for \( P_\psi(\beta_0 \varphi) \). Then we have that
\[
\frac{\int \varphi \, d\mu}{\int \psi \, d\mu} = \frac{\partial P_{\psi, \varphi}}{\partial \beta} \left( \beta_0 \right),\quad \forall \mu\in \mathcal{M}_{\psi, \beta_0\varphi}(X, f).
\]
\end{proposition}
\begin{proof}
Given \( \beta > \beta_0 \) and $\mu\in \mathcal{M}_{\psi, \beta_0\varphi}(X, f)$, by Theorem  \ref{induced Variational Principle} we have that
\[
\frac{P_{\psi, \varphi}(\beta) - P_{\psi, \varphi}(\beta_0)}{\beta - \beta_0} \geqslant \frac{h_{\mu}(f) + \beta \int \varphi \, d\mu - h_{\mu}(f) - \beta_0 \int \varphi \, d\mu}{(\beta - \beta_0)\int \psi \, d\mu} =  \frac{\int \varphi \, d\mu}{\int \psi \, d\mu}.
\]
Taking \( \beta \to \beta_0^+ \), it follows that the right derivative is bounded from below by \( \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} \).

Similarly, consider \( \beta < \beta_0 \), one can show  that the  left derivative is bounded from above by \( \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} \). Since \( P_{\psi, \varphi} \) is differentiable at \( \beta_0 \), one can conclude that
\[
\frac{\int \phi \, d\mu}{\int \psi \, d\mu} = \frac{\partial P_{\psi, \varphi}}{\partial \beta} \left( \beta_0 \right).
\]
This completes the proof of the proposition.
\end{proof}

The following theorem gives the necessary and sufficient condition for the freezing state of a potential.
\begin{theorem}
Let \( (X, f) \) be a TDS with \( h_{top}(f) < +\infty \), and let \( \varphi, \psi \in C(X, \mathbb{R}) \) with \( \psi > 0 \). The potential function \( \varphi \) freezes at \( \beta_0 \) if and only if the following properties hold:
\begin{enumerate}
\item[(1)] \( P_{\psi, \varphi}(\beta)  = \beta \cdot \operatorname{Max}^{\psi}(\varphi) + h_{\infty}^{\psi}(\varphi) \) for every  \( \beta\ge \beta_0 \) ;
\item[(2)] there exists \( \beta_1 > \beta_0 \), such that \( \beta_1 \varphi \) has at least one equilibrium state.
\end{enumerate}
\end{theorem}
\begin{proof}
Assume that \( \varphi \) freezes at \( \beta_0 \), there exists $\mu\in \mathcal{M}(X,f)$ such that
\[
P_{\psi, \varphi}(\beta) = \frac{h_{\mu}(f) + \beta \int \varphi \, d\mu}{\int \psi \, d\mu},\quad \forall \beta \geqslant \beta_0.
\]
The second property clearly holds.

To show the first property,
we first prove that \( \frac{\int \varphi \, d\mu}{\int \psi \, d\mu} = \operatorname{Max}^{\psi}(\varphi) \). Indeed, for every \( \nu \in \mathcal{M}(X, f) \), by  Theorem \ref{induced Variational Principle} we have that
\[
\frac{h_{\mu}(f) + \int \beta \varphi \, d\mu}{\int \psi \, d\mu} \geqslant \frac{h_{\nu}(f) + \beta \int \varphi \, d\nu}{\int \psi \, d\nu},\quad \forall\beta \geqslant \beta_0.
\]
Dividing by \( \beta \) on both sides, and letting \( \beta \to \infty \), we have that
\[
\begin{aligned}
\frac{\int \varphi \, d\mu}{\int \psi \, d\mu} \geqslant \frac{\int \varphi \, d\nu}{\int \psi \, d\nu},
\end{aligned}
\]
since the topological entropy is finite. Furthermore, for each \( \nu \in M_{max}^{\psi}(\varphi) \), by Theorem \ref{induced Variational Principle} we have that
\[
\frac{h_{\mu}(f) + \int \beta \varphi \, d\mu}{\int \psi \, d\mu} \geqslant \frac{h_{\nu}(f) + \beta \int \varphi \, d\nu}{\int \psi \, d\nu}.
\]
Since \( \mu, \nu \in M_{max}^{\psi}(\varphi) \), we have that
\[
\frac{h_{\mu}(f)}{\int \psi \, d\mu} \geqslant \frac{h_{\nu}(f)}{\int \psi \, d\nu}.
\]
This yields that  \( \frac{h_{\mu}(f)}{\int \psi \, d\mu} = h_{\infty}^{\psi}(\varphi) \). Hence, we have that
\[
P_{\psi, \varphi}(\beta)  = \beta \cdot \operatorname{Max}^{\psi}(\varphi) + h_{\infty}^{\psi}(\varphi),\quad \forall\beta \geqslant \beta_0.
\]

Assume that  \( P_{\psi, \varphi}(\beta) = \beta \cdot \operatorname{Max}^{\psi}(\varphi) + h_{\infty}^{\psi}(\varphi) \) for every \( \beta \ge \beta_{0} \), and  \( \mu \) is an equilibrium state for \( P_\psi(\beta_1 \varphi) \). Note that  \( P_{\psi, \varphi}(\beta) \)  is differentiable at \( \beta_1 \), it follows from Proposition \ref{Necessary Conditions for Differentiability} that
\[
\frac{\int \varphi \, d\mu}{\int \psi \, d\mu} = \frac{\partial P_{\psi, \varphi}}{\partial \beta} \left( \beta_{1} \right) = \operatorname{Max}^{\psi}(\varphi).
\]
Hence, we have that
\[
\frac{h_{\mu}(f) + \beta_{1} \int \varphi \, d\mu}{\int \psi \, d\mu} = P_{\psi, \varphi}(\beta_{1}) =  \beta_{1} \cdot \operatorname{Max}^{\psi}(\varphi) + h_{\infty}^{\psi}(\varphi),
\]
which implies that $
\frac{h_{\mu}(f)}{\int \psi \, d\mu} = h_{\infty}^{\psi}(\varphi)$.
Thus, we have  that
\[
P_{\psi, \varphi}(\beta) = \frac{h_{\mu}(f) + \beta \int \varphi \, d\mu}{\int \psi \, d\mu},\quad \forall\beta \geqslant \beta_{0}.
\]
Therefore, \( \varphi \) freezes at \( \beta_{0} \).
\end{proof}

\section{High dimensional nonlinear topological pressure}\label{NTP}
This section first recalls the high dimensional nonlinear topological pressure defined in \cite{barreira2022higher}, and gives some basic properties of it. Moreover, following the approach as described in \cite{xing2015induced}, we define the high dimensional nonlinear induced topological pressure, and establish the variational principle for it.

\subsection{Properties of high dimensional nonlinear topological pressure} Let \((X, f)\) be a TDS,   $\Phi = (\varphi_{1},\varphi_2,\cdots,\varphi_{d})\in C(X, \mathbb{R})^d$ and   \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\)  a continuous function. For every \( \varepsilon > 0 \), let
\[
P_{n}^{F}(f, \Phi, \varepsilon) = \sup_{E} \sum_{x \in E} \exp \left[ n F \Big( \frac{S_{n} \varphi_{1}(x)}{n}, \ldots, \frac{S_{n} \varphi_{d}(x)}{n} \Big) \right],
\]
where the supremum is taken over all \( (n, \varepsilon) \)-separated sets.
The following quantity
\[
P^{F}(\Phi) = \lim_{\varepsilon \rightarrow 0} P^{F}(f, \Phi, \varepsilon)
\]
is called the \emph{nonlinear topological pressure} of \( \Phi \), where
\[
P^{F}(f, \Phi, \varepsilon) = \limsup_{n \rightarrow \infty} \frac{1}{n} \log P_{n}^{F}(f, \Phi, \varepsilon).
\]

In \cite{barreira2022higher}, the authors also give an equivalent definition of  nonlinear topological pressure  using  \( (n, \varepsilon) \)-spanning sets.
Let
\[
Q_{n}^{F}(f, \Phi, \varepsilon) = \inf_C \sum_{x \in C} \exp \left[ n F \Big( \frac{S_{n} \varphi_{1}(x)}{n}, \ldots, \frac{S_{n} \varphi_{d}(x)}{n} \Big) \right],
\]
where the infimum is  taken over all  \( (n, \varepsilon) \)-spanning sets of \( X \).
Let
\[
Q^{F}(f, \Phi, \varepsilon) = \limsup_{n \rightarrow \infty} \frac{1}{n} \log Q_{n}^{F}(f, \Phi, \varepsilon).
\]
Then one has that
\[
P^{F}(\Phi) = \lim_{\varepsilon \rightarrow 0} Q^{F}(f, \Phi, \varepsilon).
\]
Given  \( \Phi = \left\{ \varphi_{1}, \ldots, \varphi_{d} \right\} \in C(X,\mathbb{R})^d\), let
$\displaystyle \|\Phi\|_\infty = \max_{j \in \{1,2, \cdots, d\}} \left\|\varphi_{j}\right\|$, one can show that
 the map \( \Phi \mapsto P^{F}(\Phi) \) is continuous with respect to this norm.


\begin{definition}
Let \((X, f)\) be a TDS, and  $\Phi \in C(X, \mathbb{R})^d$. We say that \( (f, \Phi) \) has an abundance of ergodic measures, if for every \( \mu \in \mathcal{M}(X, f) \), \( h < h_{\mu}(f) \) and  \( \varepsilon > 0 \), there exists an ergodic measure \( \nu \in \mathcal{E}(X, f) \), such that \( h_{\nu}(f) > h \) and
\[
\left| \int{{{\varphi }_{i}}}d\nu-\int{{{\varphi }_{i}}}d\mu  \right| < \varepsilon, \quad  i = 1, \cdots , d.
\]
\end{definition}

In \cite{barreira2022higher}, Barreira and Holanda established the variational principle for the high dimensional nonlinear topological pressure as follows:

\begin{theorem} \label{high nonliner vp}
Let \((X, f)\) be a TDS and  $\Phi \in C(X, \mathbb{R})^d$, and let \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\) be continuous.
If either of the following conditions is satisfied:
\begin{enumerate}
\item[(1)] $(f, \Phi)$ has an abundance of ergodic measures;
\item[(2)] $F$ is a convex function,
\end{enumerate}
then
\[
P^{F}(\Phi) = \sup \Big\{ h_{\mu}(f) + F \Big( \int \Phi d \mu \Big): \mu \in \mathcal{M}(X,f)\Big\},
\]
where \( \displaystyle \int \Phi d \mu = \Big( \int \varphi_{1} d \mu, \cdots, \int \varphi_{d} d \mu \Big) \).
\end{theorem}

 By Theorem \ref{high nonliner vp}, it is easy to see that \(\displaystyle h_{\text {top }}(f) + \inf_{x \in \Phi(X)} F(x) \leqslant P^{F}(\Phi) \leqslant h_{\text {top }}(f) + \sup _{x \in \Phi(X)} F(x) \).
 The next result shows that  the high dimensional nonlinear topological pressure is a topologically conjugate invariant.


 \begin{theorem}
Let \((X, f)\) be a TDS and  $\Phi\in C(X, \mathbb{R})^d$, and let \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\) be continuous. The following properties hold:
\begin{enumerate}
\item[(i)] If \( f \) is a homeomorphism, then \( P^{F}(f^{-1}, \Phi) = P^{F}(f, \Phi) \); %If \( k > 0 \), then
%\[
%P^{F}\left(f^{k}, S_{k} \Phi\right) = k P^{F}(f, \Phi),
%\]
%where \( \left(S_{k} \Phi\right)(x) = \sum_{i=0}^{k-1} \Phi\left(f^{i} x\right) \);
%\item[(ii)]
\item[(ii)] Let \( ( Y, g ) \) be a TDS and  \( \phi: X \rightarrow Y \)  a surjective continuous map such that \( \phi \circ f = g \circ \phi \). For every $\Phi \in C(Y, \mathbb{R})^d$, let \( \Phi \circ \phi = (\varphi_{1} \circ \phi, \cdots, \varphi_{d} \circ \phi) \), we have that \( P^{F}(g, \Phi) \leqslant P^{F}(f, \Phi \circ \phi) \). If \( \phi\) is a homeomorphism, then \( P^{F}(g, \Phi) = P^{F}(f, \Phi \circ \phi) \).%If \( Y \) is a closed subset of \( X \), and \( f Y \subset Y \), then \( P^{F}\left(f|_Y, \Phi|_Y\right) \leqslant P^{F}\left(f, \Phi\right) \);
%\item[(iv)]
\end{enumerate}
\end{theorem}

\begin{proof}
(i) Given \( \varepsilon > 0 \) and \( n \in \mathbb{N} \), it is easy to see that  a subset $E\subset X$ is  $(n, \varepsilon)$-separated with respect to $f$ if and only if
 $f^{n-1} E$ is  $(n, \varepsilon)$-separated with respect to $f^{-1}$. Furthermore, one has that
\[
\sum_{x \in E} \exp \left[n F \left( \frac{S_{n} \Phi(x)}{n} \right) \right] = \sum_{y\in f^{n-1} E} \exp \left[n F \left( \frac{ \sum_{i=0}^{n-1}\Phi(f^{-i}y) }{n} \right) \right],
\]
where $S_n\Phi=(S_n\varphi_1,S_n\varphi_2,\cdots, S_n\varphi_d)$.
 This yields that \(P^{F}(f, \Phi, \varepsilon) = P^{F}(f^{-1}, \Phi, \varepsilon) \) and \( P^{F}(f^{-1}, \Phi) = P^{F}(f, \Phi) \).

(ii)  Given $\varepsilon>0$, there exists $0<\delta<\varepsilon$ such that $d_{X}(x_1, x_2)<\delta$ implies that  $d_{Y}(g(x_1), g(x_2))< \varepsilon$, here  $d_{X}$ and $d_{Y}$  denote the metrics on $X$ and $Y$ respectively.

Given \( \varepsilon > 0 \) and \( n \in \mathbb{N} \), if $C$ is an $(n, \delta)$-spanning set for $X$ with respect to $f$, then $\phi(C)$ is an $(n, \varepsilon)$-spanning set for $Y$ with respect to $g$. Therefore, for every $\Phi \in C(Y, \mathbb{R})^d$, we have that
\begin{align*}
&\sum_{x \in C} \exp \left[n F \left( \frac{\Phi(\phi x) + \Phi\left(\phi f x\right) + \cdots + \Phi\left(\phi f^{n-1} x\right)}{n} \right) \right] \\
&= \sum_{y \in \phi(C)} \exp \left[n F \left( \frac{\Phi(y) + \Phi\left(g y\right) + \cdots +\Phi\left(g^{n-1} y\right)}{n} \right) \right] \\
&\geq Q_{n}^{F}\left(g, \Phi, \varepsilon\right).
\end{align*}
Therefore, \( Q^{F}\left(f, \Phi \circ \phi, \delta\right) \geq Q^{F}\left(g, \Phi, \varepsilon\right) \) and \( P^{F}\left(f, \Phi \circ \phi \right) \geq P^{F}\left(g, \Phi\right) \).

If \( \phi \) is a homeomorphism, considering $g,f,\phi^{-1}, \Phi\circ\phi $ instead of $f, g, \phi, \Phi$, one has that $P^{F}\left(g, \Phi\right) \ge P^{F}\left(f, \Phi \circ \phi \right)$. This completes the proof of the theorem.
\end{proof}

\subsection{Definition of nonlinear induced topological pressure}
Following the approaches as described in \cite{xing2015induced} and \cite{barreira2022higher}, the high dimensional nonlinear induced topological pressure is defined as follows.

Let \((X, f)\) be a TDS, \(\psi \in C(X, \mathbb{R})\) with \(\psi > 0\),  and let \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\) be continuous.
For \(T > 0\), let
\[
S_{T} = \left\{n \in \mathbb{N} :    S_{n} \psi(x) \leqslant T < S_{n+1} \psi(x) \text{ for some } x \in X\right\}.
\]
For \( n \in S_{T} \), let
\[
X_{n} = \left\{x \in X : S_{n} \psi(x) \leqslant T < S_{n+1} \psi(x)\right\}.
\]
Given $\Phi\in C\left(X, \mathbb{R}\right)^d $ and \( \varepsilon > 0 \), define
\[
\begin{aligned}
Q_{\psi, T}^{F}(f, \Phi, \varepsilon) =
\inf \Big \{ &\sum_{n \in S_{T}} \sum_{x \in F_{n}}
\exp \left( n F \left( \frac{S_{n} \Phi(x)}{n} \right) \right):\\
&  F_{n} \text{ is an } (n, \varepsilon) \text{-spanning set of } X_{n}, \ n \in S_{T} \Big\}.
\end{aligned}
\]
The nonlinear induced topological pressure
of $\Phi$ is then defined by
\begin{align}\label{5*}
P_{\psi}^{F}(f,\Phi) = \lim _{\varepsilon \rightarrow 0} Q_{\psi}^{F}(f, \Phi, \varepsilon),
\end{align}
where
$\displaystyle
Q_{\psi}^{F}(f, \Phi, \varepsilon) = \limsup_{T \rightarrow \infty} \frac{1}{T} \log Q_{\psi, T}^{F}(f, \Phi, \varepsilon)
$. If there is no confusion caused, we simply write $P_{\psi}^{F}(f,\Phi)$  as $P_{\psi}^{F}(\Phi)$.

\begin{remark}(i) Let \( m = \inf \psi \), \( M = \sup \psi \). Fix \( T>0 \),  we have that \( n \leqslant \frac{T}{m} \) for each \( n \in S_{T}\) , i.e., \( S_{T} \) is a finite set; (ii) If \( 0 < \varepsilon_1 < \varepsilon_2 \), then \( Q_{\psi, T}\left(f, \Phi, \varepsilon_1\right) \geqslant Q_{\psi, T}\left(f, \Phi, \varepsilon_2\right) \), which implies the existence of  the limit in \eqref{5*}  and \( P_{\psi}^F(\Phi) > -\infty \).
\end{remark}

The following theorem gives an equivalent definition of the nonlinear induced topological pressure  using separated sets.
\begin{theorem}\label{equiv-sep}
Let \((X, f)\) be a TDS, \(\psi \in C(X, \mathbb{R})\) with \(\psi > 0\),  and let \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\) be continuous. Given $\Phi\in C\left(X, \mathbb{R}\right)^d $,
\( T > 0 \) and \( \varepsilon > 0 \), let
\[
\begin{aligned}
P_{\psi, T}^F(f, \Phi, \varepsilon) = \sup \Big\{ &\sum_{n \in S_T} \sum_{x \in F_n}
\exp \left( n F \left( \frac{S_n \Phi(x)}{n} \right) \right):\\
 &F_n \text{ is an } (n, \varepsilon)\text{-separated set of } X_n, \ n \in S_T \Big\}.
\end{aligned}
\]
Then
\[
P_{\psi}^{F}(\Phi) = \lim _{\varepsilon \rightarrow 0} P_\psi^F(f, \Phi, \varepsilon),
\]
where $\displaystyle
P_{\psi}^F(f, \Phi, \varepsilon) = \limsup_{T \rightarrow \infty} \frac{1}{T} \log P_{\psi, T}^{F}(f, \Phi, \varepsilon)$.
\end{theorem}
\begin{proof}
Given \( T > 0 \) and  \( n \in S_{T} \), let \( E_{n} \) be a maximal \((n, \varepsilon)\)-separated set of \( X_{n} \), then \( E_{n} \) is an \((n, \varepsilon)\)-spanning set of \( X_{n} \). This yields that
$
Q_{\psi, T}^{F}(f, \Phi, \varepsilon) \leqslant P_{\psi, T}^{F}(f, \Phi, \varepsilon).
$
Hence, we have
\[
P_{\psi}^{F}(\Phi) \leqslant \lim _{\varepsilon \rightarrow 0} \limsup_{T \rightarrow \infty} \frac{1}{T} \log P_{\psi, T}^{F}(f, \Phi, \varepsilon).
\]

  Next, we will show that
\[
P_{\psi}^{F}(\Phi) \geqslant \lim _{\varepsilon \rightarrow 0} \limsup_{T \rightarrow \infty} \frac{1}{T} \log P_{\psi, T}^{F}(f, \Phi, \varepsilon).
\]
Since \(\Phi\)  and  \(F\)  are continuous,  for every \(\varepsilon > 0\), there exists \(\bar{\delta},\delta  > 0\) such that
\[
 \varrho(\alpha, \beta) < \bar{\delta} \implies |F(\alpha) - F(\beta)| < \varepsilon, \quad \forall \alpha, \beta \in \Phi(X)
\]
and
\[
 d(x, y) \leqslant \frac{\delta}{2} \implies |\varphi_{i}(x) - \varphi_{i}(y)| < \bar{\delta}\,\, (i=1,2, \cdots, d),\quad\forall x, y\in X
\]
where $\varrho$ is the maximum norm on $\mathbb{R}^d$.


Given \( T > 0 \) and \(n \in S_T\), let \( E_n \) be an \((n, \delta)\)-separated set of \( X_n \), and \( F_n \) be an \((n, \frac{\delta}{2})\)-spanning set of \( X_n \). Define $\phi: E_{n} \rightarrow F_{n}$ by choosing,  for each $x \in E_{n}$, some point $\phi(x)\in F_{n}$ with $d_n(x, \phi(x)) \leqslant \frac{\delta}{2}$. It is easy to see that $\phi$ is injective.
Thus, we have that
$$
\begin{aligned}
&\sum_{y \in F_n} \exp \left( nF \left( \frac{S_n \Phi(y)}{n} \right) \right) \\
&\geqslant \sum_{x \in E_n} \exp \left( nF \left( \frac{S_n \Phi(\phi(x))}{n} \right) \right) \\
&= \sum_{x \in E_n} \exp \left( nF \left( \frac{S_n \Phi(x)}{n} \right) \right)
\exp \left( nF \left( \frac{S_n \Phi(\phi(x))}{n} \right) - nF \left( \frac{S_n \Phi(x)}{n} \right) \right) \\
&\geqslant \min_{x \in E_n} \exp \left( nF \left( \frac{S_n \Phi(\phi(x))}{n} \right)
- nF \left( \frac{S_n \Phi(x)}{n} \right) \right)
\sum_{x \in E_n} \exp \left( nF \left( \frac{S_n \Phi(x)}{n} \right) \right).
\end{aligned}
$$
Since $d_n(x, \phi(x)) \leqslant \frac{\delta}{2}$ for every \( x \in E_n \),
for each $i = 1, 2,\cdots,d$,  we have that
\[
\Big|\varphi_i(f^jx)-\varphi_i(f^j\phi(x))\Big|< \bar{\delta}, \quad \forall j= 1, 2,\cdots, n-1,
\]
which implies that
\[
\Big|\frac{S_n \varphi_i(\phi(x))}{n}-\frac{S_n \varphi_i(x)}{n}\Big| < \bar{\delta}, \quad \forall i = 1, \cdots, d.
\]
Hence, we have that
\[
\varrho\Big( \frac{S_n \Phi(\phi(x))}{n}, \frac{S_n \Phi(x)}{n}\Big) < \bar{\delta}.
\]
This yields that
\[
\Big| nF\Big(\frac{S_n \Phi(x)}{n}\Big)- nF\Big(\frac{S_n \Phi(\phi(x))}{n}\Big)\Big| < n\varepsilon< \frac{T\varepsilon}{m},\quad \forall x \in E_n
\]
since \( n \leqslant \frac{T}{m} \).
Hence, we have that
\begin{align*}
\sum_{y \in F_n} \exp\Big(nF\Big(\frac{S_n \Phi(y)}{n}\Big)\Big)
\geqslant e^{-\frac{T}{m}\varepsilon} \sum_{x \in E_n} \exp\Big(nF\Big(\frac{S_n \Phi(x)}{n}\Big)\Big).
\end{align*}
Consequently, one has that
\[
\begin{aligned}
P_F^{\psi}(\Phi) &= \lim_{\delta \to 0} \limsup_{T \to \infty} \frac{1}{T} \log Q_{\psi, T}^F(f,\Phi, \frac{\delta}{2}) \\
&\geqslant \lim_{\delta \to 0} \limsup_{T \to \infty} \frac{1}{T} \log P_{\psi, T}^F(f,\Phi, \delta) - \frac{\varepsilon}{m}.
\end{aligned}
\]
Since  \(\varepsilon \) is chosen arbitrarily, the desired result follows immediately.
\end{proof}

\begin{remark} As in Section \ref{equivalent Top-Pressure}, one can define the nonlinear induced topological pressure via open covers. Moreover, it can be shown in a similar fashion that Theorem \ref{open cover et}  is equivalent to the one defined by spanning sets.
\end{remark}

The following theorem shows that the nonlinear induced topological pressure is a topologically conjugate invariant.

\begin{theorem}
Let \( f: X \rightarrow X  \) be a continuous map of compact metric space \( \left(X, d_{1}\right) \), and let \( h: Y \rightarrow Y  \) be a continuous map of compact metric space \( \left(Y, d_{2}\right) \). Assume that \( F: \mathbb{R}^{d} \rightarrow \mathbb{R} \) is continuous, and  \( g: X \rightarrow Y \) is a  homeomorphism  such that \( g \circ f = h \circ g \). Let \(\psi \in C(Y, \mathbb{R})\) with \(\psi > 0\) and $
\Phi\in C\left(Y, \mathbb{R}\right)^d$,
 we have that
\[
P_{\psi}^{F}\left(h, \Phi\right) = P_{\psi \circ g}^{F}\left(f, \Phi \circ g\right),\]
  where  $\Phi \circ g = (\varphi_{1} \circ g, \cdots, \varphi_{d} \circ g)$.

\end{theorem}

\begin{proof}
For every $T>0$, let
$$
S^{X}_{T} := \left\{n \in \mathbb{N} : \exists x \in X \text{ such that } S_{n} \psi \circ g(x) \leqslant T < S_{n+1} \psi \circ g(x)\right\},
$$
and
$$
S^{Y}_{T} := \left\{n \in \mathbb{N} : \exists y \in X \text{ such that } S_{n} \psi(y) \leqslant T < S_{n+1} \psi(y)\right\}.
$$
If  \( \psi(y)+\psi(h(y))+\cdots+\psi(h^{n-1}(y)) \leqslant T < \psi(y)+\psi(h(y))+\cdots+\psi(h^{n}(y)) \) for some \( y \in Y \),  then  \( \psi(g(x))+\psi(g(f(x)))+...+\psi(g(f^{n-1}(x))) \leqslant T < \psi(g(x))+\psi(g(f(x)))+...+\psi(g(f^{n}(x))) \) by letting  \( x=g^{-1}(y) \in X \).  This implies that \( S^{Y}_{T} = S^{X}_{T} \). Let \( S_{T} \) denote the common set.

 Given $\varepsilon>0$, there exists $\delta\in (0,\varepsilon)$ such that  $d_{2}(g(x_1), g(x_2))< \varepsilon$  whenever $d_{1}(x_1, x_2)<\delta$. For every \( \varepsilon > 0 \), \( T >0 \) and \( n \in S_{T} \), if $F_n$ is an $(n, \delta)$-spanning set for $X_n$ with respect to $f$, then $g F_n$ is an $(n, \varepsilon)$-spanning set for $Y_n$ with respect to $h$. Therefore,  we have that
\begin{align*}
&\sum_{n \in S_{T}}\sum_{x \in F_n} \exp \Big[n F \Big( \frac{\Phi(g x) + \Phi(g f x) + \cdots + \Phi(g f^{n-1} x)}{n} \Big) \Big] \\
&= \sum_{n \in S_{T}}\sum_{y \in g F_n} \exp \Big[n F \Big( \frac{\Phi(y) + \Phi(h y) + \cdots +\Phi(h^{n-1} y)}{n} \Big) \Big] \\
&\geqslant Q_{\psi,T}^{F}(h, \Phi, \varepsilon).
\end{align*}
Hence, \(  Q_{\psi \circ g}^{F}(f, \Phi \circ g, \delta) \geqslant Q_{\psi}^{F}(h, \Phi, \varepsilon) \) and \( P_{\psi \circ g}^{F}(f, \Phi \circ g) \geqslant P_{\psi}^{F}(h, \Phi) \).

Since \( g \) is a homeomorphism, the reverse inequality \( P_{\psi \circ g }^{F}(f, \Phi \circ g) \leqslant P_{\psi}^{F}(h, \Phi) \) can be proven in a similar fashion.
\end{proof}

\subsection{Variational principle for nonlinear induced topological pressure}
This section gives the variational principle for high dimensional nonlinear induced topological pressure. The key ingredient of the proof is the study of the relation between the induced topological pressure and the nonlinear induced pressure.

Let $(X,f)$, $\psi$ be as before, for \( T > 0 \), let
$
G_T = \{n \in \mathbb{N} : \exists x \in X \text{ such that } S_n \psi(x) > T \},
$
and let
$
Y_n = \{x \in X : S_n \psi(x) > T\}
$
for \( n \in G_T \).
\begin{theorem} \label{induce nonliner p thm}
Let \((X, f)\) be a TDS, \(\psi \in C(X, \mathbb{R})\) with \(\psi > 0\),  and let \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\) be continuous.
Given $\Phi\in C(X,\mathbb{R})^d$, $\phi\in C(X,\mathbb{R})$ and \( \varepsilon > 0 \), let
\begin{align*}
R_{\psi, T}^F( \Phi, \phi, \varepsilon)
= \sup \Big\{&\sum_{n \in G_{T}} \sum_{x \in E_{n}^{\prime}}
\exp \Big[ n F\Big(\frac{S_n \Phi(x)}{n}\Big)
+ S_{n} \phi(x)\Big]:  \\
 & E_{n}^{\prime} \text{ is an } (n, \varepsilon)\text{-separated set of } Y_{n}, \ n \in G_{T} \Big\}.
\end{align*}
Then, we have that
\[
P_\psi^F(\Phi) = \inf\Big\{\beta \in \mathbb{R} : \lim_{\varepsilon \to 0} \limsup_{T \to \infty} R_{\psi, T}^F(  \Phi, -\beta \psi, \varepsilon) < \infty \Big\}.
\]
Here we take the convention that \(\inf \emptyset = \infty\).
\end{theorem}
\begin{proof}
For \( n \in \mathbb{N}, x \in X \), let \( m_n(x) \) denote the unique positive integer such that
\begin{equation}\label{***}
(m_n(x) - 1) \| \psi \|< S_n \psi(x) \leqslant m_n(x) \| \psi \|.
\end{equation}
Hence, one has that
\[
\begin{aligned}
\exp(-\beta m_n(x) \| \psi \|) \exp(-|\beta| \| \psi \|)
&\leqslant \exp(-\beta S_n \psi(x)) \\
&\leqslant \exp(-\beta m_n(x) \| \psi \|) \exp(|\beta| \| \psi \|)
\end{aligned}
\]
for every $x\in X$.
Given a family of functions \(\xi_T = \{\xi_n : X \to \mathbb{R} \mid n \in G_T\}\), for every \( \varepsilon > 0 \), define
\[
\begin{aligned}
R_{\psi, T}^F( \Phi, \xi_T, \varepsilon)
= \sup \Big\{ & \sum_{n \in G_T} \sum_{x \in E_n^{\prime}}
\exp\Big[ n F\Big(\frac{S_n \Phi(x)}{n}\Big) + \xi_n(x) \Big]:
 \\
& E_n^{\prime} \text{ is an  } (n, \varepsilon)\text{-separated set of } Y_n, \ n \in G_T \Big\}.
\end{aligned}
\]
This yields that
\begin{align*}
&\exp(-|\beta| \|\psi\|) R^{F}_{\psi, T}( \Phi, \left\{-\beta m_{n}\|\psi\|\right\}_{n \in G_{T}}, \varepsilon )\\
&\leqslant R^{F}_{\psi, T}( \Phi, -\beta \psi, \varepsilon) \\
&\leqslant \exp(|\beta| \|\psi\|) R^{F}_{\psi, T}( \Phi, \left\{-\beta m_{n}\|\psi\|\right\}_{n \in G_{T}}, \varepsilon).
\end{align*}
Consequently, one can conclude that
\[
\lim_{\varepsilon \to 0} \limsup_{T \to \infty} R^{F}_{\psi, T}( \Phi, -\beta \psi, \varepsilon) < \infty
\]
if and only if
 \[\lim_{\varepsilon \to 0} \limsup_{T \to \infty} R^{F}_{\psi, T}( \Phi, \left\{-\beta m_{n}\|\psi\|\right\}_{n \in G_{T}}, \varepsilon) < \infty.
\]
Thus, it suffices to show that
\[
P^{F}_{\psi}(\Phi) = \inf\Big\{\beta \in \mathbb{R} : \lim_{\varepsilon \to 0} \limsup_{T \to \infty} R^{F}_{\psi, T}(\Phi, \{-\beta m_{n}\|\psi\|\}_{n \in G_{T}}, \varepsilon) < \infty \Big\}.
\]


By Theorem \ref{equiv-sep}, for every \( \delta > 0 \),  \( \beta \in \mathbb{R} \) with \( \beta < P_{\psi}^{F}(\Phi) - \delta \), there exists \( \varepsilon_0 > 0 \), such that for every \( \varepsilon \in (0, \varepsilon_0) \), we have

\[
\beta + \delta < \limsup_{T \to \infty} \frac{1}{T} \log P^{F}_{\psi, T}(f, \Phi, \varepsilon) \leqslant P^{F}_{\psi}(\Phi).
\]
Therefore, for every \( T > 0 \) , there exists a sequence of numbers \( \{T_{j}\}_{j \in \mathbb{N}} \) such that for each $j \in \mathbb{N}$, the following properties hold:
\begin{enumerate}
\item[(i)]$T_{j+1} - T_j > 2\|\psi\|$ and $T_j - \|\psi\| > T$;
\item[(ii)]$\frac{1}{T_j} \log P^{F}_{\psi, T_j}(f,\Phi, \varepsilon) > \beta + \frac{\delta}{2}$.
\end{enumerate}
Fix $j \in \mathbb{N}$, for all $n \in S_{T_j}$, there exists an $(n, \varepsilon)$-separated set $E_n $ of $X_n$ such that
\begin{equation}\label{**}
\sum_{n \in S_{T_j}} \sum_{x \in E_n}
\exp\Big(nF\Big(\frac{S_n\Phi(x)}{n}\Big)\Big) \geqslant
\exp\Big(T_j(\beta + \frac{\delta}{2})\Big).
\end{equation}
Note that for every \( j \in \mathbb{N} \),  \( n \in S_{T_j} \) and  \( x \in E_n \),
$
T_j - \|\psi\| \leqslant S_n \psi(x) \leqslant T_j,
$
this implies that  \( S_{T_j} \cap S_{T_i} = \emptyset \)  for every \( i \neq j \). This together with \eqref{***} yield that
\[
-2\|\psi\| + T_j \leqslant S_n \psi(x) \leqslant  \|\psi\| m_n(x) \leqslant S_n \psi(x)+\|\psi\| \leqslant 2\|\psi\| + T_j.
\]
Hence,  we have that
\begin{equation}\label{*}
-\beta\|\psi\| m_n(x) \geqslant -2|\beta|\|\psi\| - \beta T_j, \quad \forall \beta \in \mathbb{R}.
\end{equation}
 By \eqref{**} and  \eqref{*}, we have that
\[
\begin{aligned}
R^{F}_{\psi, T}&\left(\Phi, \left\{-\beta m_n\|\psi\|\right\}_{n \in G_T}, \varepsilon\right) \\
&\geq \sum_{j \in \mathbb{N}, T_j - \|\psi\| > T} \sum_{n \in S_{T_j}} \sum_{x \in E_n}
\exp\Big(n F\Big(\frac{S_n \Phi(x)}{n}\Big) - \beta m_n(x)\|\psi\|\Big) \\
&\geqslant \exp\left(-2 |\beta| \|\psi\|\right)
\sum_{j \in \mathbb{N}, T_j - \|\psi\| > T}
\exp\Big(T_j (\beta + \frac{\delta}{2}) - \beta T_j\Big) \\
&= \infty.
\end{aligned}
\]
The above argument is not only valid for $P^{F}_{\psi}(\Phi)\in \mathbb{R}$, but also for $P^{F}_{\psi}(\Phi)=\infty$, in which case the previous inequality holds for
every $\beta\in\mathbb{R}$.
The arbitrariness of $\beta, \delta$ implies that
\[
P^{F}_{\psi}(\Phi) \leq \inf\Big\{\beta \in \mathbb{R} : \lim_{\varepsilon \to 0} \limsup_{T \to \infty} R^{F}_{\psi, T}(\Phi, \{-\beta m_{n}\|\psi\|\}_{n \in G_{T}}, \varepsilon) < \infty \Big\}.
\]

To prove the reverse inequality, given \( \delta > 0 \), we consider the case $P^{F}_{\psi}(\Phi)\in \mathbb{R}$ and show that
\[
\lim_{\varepsilon \to 0} \limsup_{T \to \infty} R_{\psi, T}^{F}( \Phi, \{-(P_{\psi}^{F}(\Phi)+\delta) m_{n}\|\psi\|\}_{n \in G_{T}} , \varepsilon ) < \infty.
\]
 By Theorem \ref{equiv-sep},  there exists \( \varepsilon_0 > 0 \) such that for every \( \varepsilon \in (0, \varepsilon_0) \), we have that
\[
\limsup_{T \to \infty} \frac{1}{T} \log P_{\psi, T}^F(f, \Phi, \varepsilon) < P_\psi^F(\Phi) + \frac{\delta}{2}.
\]
Fix such an $\varepsilon>0$, there exists \( \ell_0 \in \mathbb{N} \) such that for every positive
integer \( \ell > \ell_0 \), we have that
\begin{equation}\label{xx}
P_{\psi, \ell m}^{F}(f, \Phi, \varepsilon) < \exp\Big(\ell m \Big(P_\psi^F(\Phi) + \frac{2}{3} \delta\Big)\Big).
\end{equation}
For every \( n \in S_{\ell m}\) and \(x \in E_n \), by \eqref{***} and the fact that \( \ell m-\|\psi\| \leqslant S_n \psi(x) \leqslant \ell m \), we have that
\[
|\|\psi\| m_n(x) - \ell m| \leqslant |\|\psi\| m_n(x)-S_n \psi(x)|+|S_n \psi(x)-\ell m| \leqslant 2 \|\psi\|.
\]
Thus, one can conclude that
\begin{equation}\label{X}
 -(P_\psi^F(\Phi) + \delta) ||\psi|| m_n(x) \leqslant 2 |P_\psi^F(\Phi) + \delta| \cdot ||\psi|| - (P_\psi^F(\Phi) + \delta) \ell m.
\end{equation}
For sufficiently large $T > 0$, take $n \in G_T$ and let $E_n'$ be an $(n, \varepsilon)$-separated set for $Y_n$. For each $x \in E_n'$, there exists a unique $\ell \in \mathbb{N}$ with $\ell > \ell_0$ such that
\[
(\ell - 1)m < S_n \psi(x) \leqslant \ell m.
\]
Consequently, one has that
\[
\ell m > T \quad \text{and} \quad S_{n+1} \psi(x) > (\ell-1)m + m = \ell m.
\]
This implies that $(\ell - 1)m < S_r \psi(x) \leqslant \ell m$ if and only if  $r = n$.
Therefore, by \eqref{X} and \eqref{xx}, we have
\begin{align*}
& R_{\psi, T}^{F}( \Phi, \{ -(P_\psi^F(\Phi) + \delta) ||\psi|| m_n \}_{n \in G_T}, \varepsilon) \\
& \leqslant \sum_{\ell \geqslant \ell_0} \sup \Big\{
\sum_{n \in S_{\ell m}} \sum_{x \in E_n}
\exp\Big[ nF\Big( \frac{S_n \Phi(x)}{n}  \Big)
- ( P_\psi^F(\Phi) + \delta ) \|\psi\| m_n(x) \Big]: \\
& \qquad \qquad \qquad \qquad\qquad\qquad \qquad E_n \text{ is an } (n, \varepsilon)\text{-separated set of } X_n, n \in S_{\ell m}
\Big\} \\
& \leqslant \sum_{\ell \geqslant \ell_0} \sup \Big\{
\sum_{n \in S_{\ell m}} \sum_{x \in E_n}
\exp\Big( nF\Big( \frac{S_n \Phi(x)}{n} \Big) \Big) \cdot
\exp\Big( 2 |P_\psi^F(\phi) + \delta| \cdot ||\psi|| \Big) \\
& \qquad \qquad \cdot
\exp( -(P_\psi^F(\phi) + \delta) \ell m ): E_n \text{ is an } (n, \varepsilon)\text{-separated set of } X_n, n \in S_{\ell m} \Big\}\\
& \leqslant \exp\Big(2 |P_\psi^F(\Phi) + \delta| \cdot ||\psi||\Big)
\sum_{\ell \geqslant \ell_0} \exp\Big(-\ell m (P_\psi^F(\Phi) + \delta)\Big) P_{\psi, \ell m}^{F}( f,\Phi, \varepsilon) \\
& \leqslant \exp\Big(2 |P_\psi^F(\Phi) + \delta|\cdot||\psi||\Big) \sum_{\ell \geqslant \ell_0} \exp\Big(-\ell m (P_\psi^F(\Phi) + \delta)\Big) \exp\Big(\ell m (P_\psi^F(\Phi) + \frac{2}{3} \delta)\Big) \\
&  < \infty.
\end{align*}
Hence,
\[
\lim_{\varepsilon \to 0} \limsup_{T \to \infty} R_{\psi, T}^{F}(\Phi,  \left\{ -\left( P_\psi^F(\Phi) + \delta\right) ||\psi|| m_n(x) \right\}_{n \in G_T}, \varepsilon) < \infty.
\]
The arbitrariness of $\delta$ implies the desired result. The case of $P_\psi^F(\Phi)=\infty$ can be proven in a similar fashion.
\end{proof}

\begin{corollary} \label{induce nonliner p cor1}
Let \((X, f)\) be a TDS, \(\psi \in C(X, \mathbb{R})\) with \(\psi > 0\),  and let \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\) be continuous.  Given
$
\Phi \in C (X, \mathbb{R})^d$, let
$
\Psi(x) = (\Phi(x), \psi(x)) \in C (X, \mathbb{R})^{d+1}.
$
For each \( \beta \in \mathbb{R} \), define $G_{\beta}: \mathbb{R}^{d+1} \to \mathbb{R}$ as  $(a, b) \mapsto F(a) - \beta b$, where  $a \in \mathbb{R}^d$.
Then, we have that
\[
P_\psi^F(\Phi) \geqslant \inf\Big\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \Big\}
\]
where $P^{G_{\beta}}(\Psi)$ is the nonlinear topological pressure of $\Psi$.
\end{corollary}
\begin{proof}
 Take \( \displaystyle \beta \in \Big\{\beta \in \mathbb{R} \mid \lim _{\varepsilon \rightarrow 0} \lim _{T \rightarrow \infty} R_{\psi, T}^{F}( \Phi, -\beta \psi, \varepsilon)<\infty\Big\} \),
and let
\[
\lim_{\varepsilon \to 0} \lim_{T \to \infty} R_{\psi, T}^{F}( \Phi, -\beta \psi, \varepsilon) = a.
\]
Fix a small \( \varepsilon > 0 \), there exists \( T_0 \) such that for every \( T > T_0 \),
\[
R_{\psi,T}^{F}(\Phi, -\beta \psi, \varepsilon) < a + 2.
\]
For sufficiently large \( n \in \mathbb{N} \),  we have \( S_n \psi(x) > T \) for every \( x \in X \). Given such \( n \in G_T \), let \( E_n^{'} \) be an \( (n, \varepsilon) \)-separated set of \( Y_n = X \),
hence
\begin{align*}
&\sum_{x \in E_n^{'}}  \exp\Big(nF\Big(\frac{S_n \Phi(x)}{n}\Big) - \beta S_n \psi(x)\Big) \\
& < \sum_{n \in G_T} \sum_{x \in E_n^{'}} \exp\Big(nF\Big(\frac{S_n \Phi(x)}{n}\Big) - \beta S_n \psi(x)\Big) \\
& < a + 2.
\end{align*}
This yields that
\begin{align*}
P^{G_{\beta}}(\Psi) &= \lim _{\varepsilon \rightarrow 0} \limsup _{n \rightarrow \infty}
\frac{1}{n} \log \sup \Big\{
\sum_{x \in E_n}  \exp\Big(nF\Big(\frac{S_n \Phi(x)}{n}\Big) - \beta S_n \psi(x)\Big) : \\
& \quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad  E_n \text{ is an } (n, \varepsilon)\text{-separated set of } X
\Big\} \leqslant 0.
\end{align*}
Therefore, by Theorem \ref{induce nonliner p thm}, we have
\[
\Big\{\beta \in \mathbb{R} : \lim _{\varepsilon \rightarrow 0} \lim _{T \rightarrow \infty} R_{\psi, T}^{F}( \Phi, -\beta \psi, \varepsilon)<\infty\Big\} \subset \Big\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \Big\}.
\]
Consequently, one has that
\[
\begin{aligned}
P^{F}_{\psi}(\Phi) &=\inf \Big\{\beta \in \mathbb{R} : \lim _{\varepsilon \rightarrow 0} \lim _{T \rightarrow \infty} R_{\psi, T}^{F}( \Phi, -\beta \psi, \varepsilon)<\infty\Big\}\\
&\geqslant \inf\Big\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \Big\}.
\end{aligned}
\]
This completes the proof of the corollary.
\end{proof}

Let \((X, f)\), $F$, $\psi$, $\Phi$, $\Psi$ and $G_{\beta}$ be the same as in Corollary \ref{induce nonliner p cor1}, the following result hold.

\begin{corollary} \label{induce nonliner p cor2}
If either of the following two conditions is satisfied:
\begin{enumerate}
\item[(1)] $(f, \Psi)$ has an abundance of ergodic measures;
\item[(2)] $F$ is a convex function,
\end{enumerate}
then we have that
\[
P^{F}_{\psi}(\Phi) = \inf\Big\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \Big\}
= \sup\Big\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \geqslant 0 \Big\}.
\]
\end{corollary}
\begin{proof}
It is easy to see that $G_\beta$ is a convex function for each $\beta\in \mathbb{R}$, since $F$ is a convex function.

If \( h_{\text {top }}(f) = +\infty \), by Theorem \ref{high nonliner vp}, one can see that $P^{G_{\beta}}(\Psi)=+\infty$ for each $\beta\in \mathbb{R}$. Hence, we have that
\[
P^{F}_{\psi}(\Phi) = \inf\left\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \right\}
= \sup\left\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \geqslant 0 \right\}=+\infty.
\]
Here we make the convention that $\inf \emptyset =+\infty$.

In the following, we assume that \( h_{\text {top }}(f) < +\infty \).
By Theorem \ref{high nonliner vp}, for every \( \beta \in \mathbb{R} \), we have
\begin{align*}
P^{G_{\beta}}(\Psi) & = \sup \Big\{h_{\nu}(f) + G_{\beta}\Big(\int \Psi d \nu\Big) : \nu \in \mathcal{M}(X, f)\Big\} \\
& = \sup \Big\{h_{\nu}(f) + F\Big(\int \Phi d\nu \Big) - \beta \int \psi d \nu : \nu \in \mathcal{M}(X, f)\Big\}\\
&<+\infty.
\end{align*}
Given \( \beta_1, \beta_2 \in \mathbb{R} \) with \( \beta_1 < \beta_2 \). For each \( 0 < \varepsilon \leqslant \frac{m(\beta_2 - \beta_1)}{2} \) (recall that $m=\inf \psi$), there exists \( \mu \in \mathcal{M}(X, f) \) such that
\[
\begin{aligned}
& \sup \Big\{  h_{\nu}(f) + F\Big(\int \Phi d\nu\Big) - \beta_2 \int \psi d \nu : \nu \in \mathcal{M}(X, f) \Big\} \\
& < h_{\mu}(f) + F\Big(\int \Phi d \mu\Big) - \beta_2 \int \psi d \mu + \varepsilon \\
& \le h_{\mu}(f) + F\Big(\int \Phi d \mu\Big) - (\beta_2 - \beta_1)\Big(\int \psi d \mu - \frac{m}{2}\Big) - \beta_1 \int \psi d \mu \\
& \leqslant \sup \Big\{ h_{\mu}(f) + F\Big(\int \Phi d \mu\Big) - \beta_1 \int \psi d \mu : \mu \in \mathcal{M}(X, f)\Big\}.
\end{aligned}
\]
Hence, the map \( \beta \mapsto P^{G_\beta}(\Psi) \) is strictly decreasing.  Since \( P^{G_\beta}(\Psi) \) is continuous in \( \beta \), we have that
\[
\inf\left\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \right\}
= \sup\left\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \geqslant 0 \right\}.
\]
 By Corollary \ref{induce nonliner p cor1}, one has that \( P^{F}_{\psi}(\Phi) \geqslant \inf\left\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \right\} \).

 To complete the proof of the corollary, it suffices to show that
\[
P^{F}_{\psi}(\Phi) \leqslant \inf\left\{\beta \in \mathbb{R} : P^{G_{\beta}}(\Psi) \leqslant 0 \right\}.
\]
By Theorem \ref{induce nonliner p thm} , this is equivalent to show that $R_{\psi, T}^F(\Phi, -\beta \psi, \varepsilon) < \infty$ for sufficiently large $T$ and small $\varepsilon$, provided that $P^{G_{\beta}}(\Psi) < 0 $.


Let \( P^{G_\beta}(\Psi) = 2a < 0 \). For every small \( \varepsilon > 0 \), there exists \( N \in \mathbb{N} \) such that for every positive integer \( n > N \),
\[
 \sup_{E_n} \sum_{x \in E_n} \exp \Big(n F\Big(\frac{ S_n\Phi(x)}{n}\Big)-\beta S_n \psi(x)\Big) \leqslant e^{na},
\]
where the supremum is taken over all $(n, \varepsilon)$-separated sets of $X$.
Consequently,  for sufficiently large \( T>0 \), we have
\begin{align*}
R_{\psi, T}^{F}( \Phi, -\beta \psi, \varepsilon )
& \leqslant \sum_{n \geqslant N} \sup_{E_n} \sum_{x \in E_n} \exp \Big(n F\Big(\frac{ S_n\Phi(x)}{n}\Big)-\beta S_n \psi(x)\Big) \\
& \leqslant \sum_{n \geqslant N} e^{n a}\\
& <\infty.
\end{align*}
This completes the proof of the corollary.
\end{proof}

\begin{remark} Under the condition of Corollary \ref{induce nonliner p cor2},   assume that \( h_{top}(f) < +\infty \), then one has that  \( P^{G_{\beta}}(\Psi) = 0 \) for $\beta= P^{F}_{\psi}(\Phi)$. In fact, $P^{G_{\beta}}(\Psi)\in \mathbb{R}$ for every $\beta\in \mathbb{R}$, and the map \( \beta \mapsto P^{G_\beta}(\Psi) \) is continuous and strictly decreasing. This implies the desired result.
\end{remark}

The following theorem establishes the variational principle for nonlinear induced topological pressure.

\begin{theorem}
Let \((X, f)\) be a TDS, $\Phi \in C(X, \mathbb{R})^d$ and \(\psi \in C(X, \mathbb{R})\) with \(\psi > 0\), and let \(F: \mathbb{R}^{d} \rightarrow \mathbb{R}\) be continuous.
If either of the following two conditions is satisfied:
\begin{enumerate}
\item[(1)] $(f, \Psi)$ has an abundance of ergodic measures, where $\Psi(x) = (\Phi(x), \psi(x))$;
\item[(2)] $F$ is a convex function,
\end{enumerate}
then
\[
P_{\psi}^{F}(\Phi) = \sup \Big\{ \frac{h_{\nu}(f) + F\left(\int \Phi d \nu\right)}{\int \psi d \nu} : \nu \in \mathcal{M}(X, f) \Big\}.
\]
\end{theorem}
\begin{proof}
For every \( \beta\in \mathbb{R}\), let $G_\beta$ be the same as in Corollary \ref{induce nonliner p cor1}. Without loss of generality, one may assume that $P_{\psi}^{F}(\Phi)$ is finite. Otherwise, one can show that $P^{G_{\beta}}(\Psi)=+\infty$ for each $\beta\in \mathbb{R}$, which implies that $h_{\text {top }}(f) = +\infty$. This implies the desired result immediately.


 For every \( \beta > P^{F}_{\psi}(\Phi) \),  by Corollary \ref{induce nonliner p cor2} and Theorem \ref{high nonliner vp},  one has that
\[
0 \ge P^{G_{\beta}}(\Psi) = \sup \Big\{  h_{\nu}(f) + F\Big(\int \Phi d \nu \Big) - \beta \int \psi d \nu : \nu \in \mathcal{M}\left(X, f\right) \Big\}.
\]
Hence,   we have that
$$
0 > \frac{h_{\nu}(f) + F\Big(\int \Phi d\nu\Big)}{\int \psi d\nu} - \beta,\quad \forall \nu \in \mathcal{M}(X, f).
$$
The arbitrariness of \( \beta >P^F_\psi(\Phi) \) and \( \nu \in \mathcal{M}(X, f) \)  implies that
$$
P^F_\psi(\Phi) \geq \sup \Big\{ \frac{h_{\nu}(f) + F\left(\int \Phi d \nu\right)}{\int \psi d \nu} : \nu \in \mathcal{M}(X, f) \Big\}.
$$


For every \( \beta < P^F_\psi(\Phi) \), by Corollary \ref{induce nonliner p cor2} and Theorem \ref{high nonliner vp},  we have that
$$
0 \le P^{G_\beta}(\Psi) = \sup \Big\{ h_\nu(f) + F\Big(\int \Phi d\nu \Big) - \beta \int \psi d\nu : \nu \in \mathcal{M}(X, f) \Big\},
$$
which implies that
$$
\beta \le \sup \Big\{ \frac{h_\nu(f) + F(\int \Phi d\nu)}{\int \psi d\nu} : \nu \in \mathcal{M}(X, f) \Big\}.
$$
Since \( \beta\) is chosen arbitrarily,  one can conclude that
$$
P_\psi^F(\Phi) \leqslant \sup \Big\{ \frac{h_\nu(f) + F(\int \Phi d\nu)}{\int \psi d\nu} : \nu \in \mathcal{M}(X, f) \Big\}.
$$
This completes the proof of the variational principle for nonlinear induced topological pressure.
\end{proof}






