\title{Weak Hopf tube algebra for domain walls between 2d gapped phases of Turaev-Viro TQFTs}


\author[a,b,*]{Zhian Jia\orcidlink{0000-0001-8588-173X},}


\author[c,d,e,\dagger]{Sheng Tan\orcidlink{0009-0008-3318-9942}}






