\begin{align}
   R_n = \frac{\mathcal{S}_{\mathcal{H},n}-\mathcal{S}_{c,n-1}}{\mathcal{S}_{c,n}-\mathcal{S}_{c,n-1}}. \label{eq:Rndef}
\end{align}

\no The ratio $R_n$ measures how far between two extremizers of the speed the $n$th extremizer of the energy is located. To approximate this limit we note that Longuett-Higgins and Fox's perturbation parameter $\epsilon$ tends to zero as the steepest wave is approached. Thus, for large $n$, we approximate $R_n$ by
\begin{align}
    R_n\sim \frac{\mathcal{S}_{\lim}+d_1\epsilon_{H,n}^2-(\mathcal{S}_{\lim}+d_1\epsilon_{c,n-1}^2)}{\mathcal{S}_{\lim}+d_1\epsilon_{c,n}^2-(\mathcal{S}_{\lim}+d_1\epsilon_{c,n-1}^2)}=\frac{\epsilon_{H,n}^2-\epsilon_{c,n-1}^2}{\epsilon_{c,n}^2-\epsilon_{c,n-1}^2}.\label{eq:R_nApprox1}
\end{align}
Using (\ref{eq:epsSpeed}) and (\ref{eq:epsEnergy}), 
\begin{align}
    \epsilon_{c,n} = \epsilon_{c,n-1}e^{-\frac{\pi}{3\mu}},\quad\text{and}\quad \epsilon_{\mathcal{H},n} = \epsilon_{\mathcal{H},n-1}e^{-\frac{\pi}{3\mu}}. \label{eq:epsilonRecursion}
\end{align}
To justify (\ref{eq:epsilonRecursion}), note that as $n\to \infty,$ $k \to -\infty$ in (\ref{eq:epsSpeed}) and (\ref{eq:epsEnergy}) and $\epsilon \to 0$ so the steepest wave is approached. We see that 
\begin{align}
    \lim_{n\to\infty} R_n &\sim \lim_{n\to\infty} \frac{\epsilon_{\mathcal{H},n}^2-\epsilon_{c,n-1}^2}{\epsilon_{c,n}^2-\epsilon_{c,n-1}^2}\nonumber \\
    &=\frac{e^{-\frac{2\pi}{3\mu}(n-2)}\left(\epsilon_{\mathcal{H},2}^2-\epsilon_{c,1}^2\right)}{e^{-\frac{2\pi}{3\mu}(n-2)}\left(\epsilon_{c,2}^2-\epsilon_{c,1}^2\right)}\nonumber\\
    &=\frac{e^{-\frac{2\pi}{3\mu}}\epsilon_{\mathcal{H},1}^2-\epsilon_{c,1}^2}{\epsilon_{c,1}^2\left(e^{-\frac{2\pi}{3\mu}(n-2)}-1\right)}\nonumber\\
    &=\frac{e^{-\frac{2\pi}{3\mu}}\frac{\epsilon_{\mathcal{H},1}^2}{\epsilon_{c,1}^2}-1}{e^{-\frac{2\pi}{3\mu}}-1}.\label{eq:RnApprox}
\end{align}

Thus, we compute the limiting ratio using just the ratio of the perturbation parameters corresponding to the first extremizers of the energy and speed. We could have used steeper extremizers as well, but the first one is most accessible. %\textcolor{red}{In future work, we refine} this by using steeper extremizers. 
We compute this limiting ratio in different depths and {present results} in Figure~\ref{fig:LimitingRatioFit}. Despite the noise introduced by the Longuett-Higgins and Fox asymptotics in a regime far beyond their validity, we can fit a rescaled, shifted power of the dispersion relation $\omega^2 = gk\tanh(kd)$ to this data, with an exponent whose confidence interval includes 1.

