\section{One-body LC momentum number  densisty }
\label{app:1bd}


Here we introduce the  baryon number and momentum sum rules for the {nuclear} one-body LC momentum number density. 
Let us remind that, from Eq. (\ref{Eq:density1})
\be
\bar \rho_\tau(\xi_1)= A \rho_\tau(\xi_1)=
A \sum_{\tau_2} \int_0^{1-\xi_1} d\xi_2~\int  d^2 k_{1,\perp} \int  d^2k_{2,\perp} |\psi(\xi_1,\xi_2, \mathbf k_{1,\perp},\mathbf k_{2,\perp},\tau,\tau_2)|^2
\ee

From the normalization of the LCMD Eq. \eqref{eq:normrho}, the baryon number sum rule reads as follows
\begin{align}
\label{Eq:numden}
    \sum_\tau \int d\xi ~\bar \rho_\tau (\xi) = A 
\end{align}
 therefore
\begin{align}
    \int d\xi ~\bar \rho_\tau (\xi) = N_\tau~, 
\end{align}
being $N_\tau$ the number of nucleons with isospin $\tau$, {i.e.} 
\be
\int_0^1 d\xi_1~\bar \rho_{p}(\xi_1)=Z~, \quad {\rm and} \quad 
\int_0^1 d\xi_1~\bar \rho_{n}(\xi_1)=(A-Z)~.\ee
In addition, the momentum sum rule {reads}
\begin{align}
\label{Eq:momcons}
    \langle \xi \rangle_p+\langle \xi \rangle_n = \sum_{\tau} \int d\xi~ \xi\bar \rho^A_{\tau}(\xi) =1~,
\end{align}
where
\begin{align}
\label{Eq:momcons2}
    \langle \xi \rangle_\tau = \int d\xi~\xi \bar \rho^A_\tau(\xi)~.
\end{align}

 \section{Two-body LC momentum number  density}
\label{app:2bd}
In this Appendix,  the number and momentum sum rules for the two-body LC momentum number density are introduced.

Let us recall the definition of  $\bar \rho_{\tau_1 \tau_2}^A (\xi_1,\xi_2)$ given in Eq. \eqref{Eq:density_bar_2}
\begin{align}
\label{eq:density_bar_2_app}
