\section{Evaluating the traces in ${\cal S}^{\mu\mu'}_{ij}$}
\label{app_traces}
In this Appendix, the evaluation of the four traces present in Eq. \eqref{eq:traceb} is discussed in detail. Notice that in what follows the LF momentum is indicated by ${\blf p}$ and amounts to ${\blf p}\equiv \{p^+, p_x,p_y\} $ with, importantly, $p^+=E(|{\bf p}|)+p_z$.

In the LF deuteron wave function,  one has to deal with the following  combination that can be recast in a new expression by using the relation $C^{1 \mu}_{\frac{1}{2} h_1, \frac{1}{2} h_2}= \langle 1/2 ~h_1|\sigma_\mu~i\sigma_y|1/2 ~h_2\rangle /\sqrt{2} $, with i) $\sigma_\mu=\hat{\bf e}_\mu \cdot {\bfm \sigma}$,  ii) $\hat{\bf e}_0=\hat{\bf e}_z$ and iii) $\hat{\bf e}_\pm =\mp (\hat{\bf e}_x \pm  i\hat{\bf e}_y)/\sqrt{2}$.  One gets
\be
\sum_{h_1, h_2} D^{{1 \over 2}} [{\cal R}^\dagger_M ({\blf k}_1)]_{\lambda_1 h_1}  D^{{1 \over 2}} [{\cal R}^\dagger_M ({\blf k}_2)]_{\lambda_2 h_2}~ C^{1 \mu}_{\frac{1}{2} h_1, \frac{1}{2} h_2}
\nonu
= \frac{1}{\sqrt{2}}\sum_{h_1, h_2} \langle \lambda_2| {\cal R}^\dagger_M({\blf k}_2)|h_2\rangle \langle h_2| 
 \sigma_{\mu} (i\sigma_y )|h_1\rangle\langle h_1|{\cal R}^*_M({\blf k}_1)|\lambda_1\rangle
\nonu
= \frac{1}{\sqrt{2}} \langle \lambda_2| {\cal R}^\dagger_M({\blf k}_2)~
 \sigma_{\mu} (i\sigma_y )~{\cal R}^*_M({\blf k}_1)|\lambda_1\rangle
\nonu
= \frac{1}{\sqrt{2}}\langle \lambda_2| \frac{m + k^+_2 +i {\bfm \sigma} \cdot (\hat e_z \times
{\bf k}_{2\perp}) }{\sqrt{(m + k^+_2)^2 + k_{2\perp}^2}}   ~  \sigma_{\mu}  (i\sigma_y) ~\frac{m + k^+_1 +i {\bfm \sigma}^* \cdot (\hat e_z \times
{\bf k}_{1\perp})}{\sqrt{(m + k^+_1)^2 + k_{1\perp}^2}} |\lambda_1\rangle
\nonu
=\frac{1}{\sqrt{2}}\langle \lambda_2| \frac{m + k^+_2 +i {\bfm \sigma} \cdot (\hat e_z \times
{\bf k}_{2\perp}) }{\sqrt{(m + k^+_2)^2 + k_{2\perp}^2}}   ~  \sigma_{\mu}   ~\frac{m + k^+_1 - i {\bfm \sigma} \cdot (\hat e_z \times
{\bf k}_{1\perp})}{\sqrt{(m + k^+_1)^2 + k_{1\perp}^2}} ~(i\sigma_y)|\lambda_1\rangle
\nonu
=\frac{1}{\sqrt{2}}\langle \lambda_2| {\cal R}^\dagger_M ({\blf k}_2)~  \sigma_{\mu}   ~{\cal R}_M ({\blf k}_1)~(i\sigma_y)|\lambda_1\rangle
\label{eq:deu_wf_spin}~,
\ee
where $(i\sigma_y)\sigma^{T}_k(i\sigma_y)=\sigma_k$ has been  also used.
For the conjugated wf one has
\be
\sum_{h'_1, h'_2} D^{{1 \over 2}} [{\cal R}_M ({\blf k}'_1)]_{h'_1\lambda'_1 }  D^{{1 \over 2}} [{\cal R}_M ({\blf k}'_2)]_{h'_2\lambda'_2 }~ C^{1 \mu'}_{\frac{1}{2} h'_1, \frac{1}{2} h'_2}
\nonu
=\sum_{h'_1, h'_2} D^{{1 \over 2}} [{\cal R}^T_M ({\blf k}'_1)]_{\lambda'_1h'_1 }  C^{1 \mu'}_{\frac{1}{2} h'_1, \frac{1}{2} h'_2}  D^{{1 \over 2}} [{\cal R}_M ({\blf k}'_2)]_{h'_2\lambda'_2} 
\nonu
= \frac{1}{\sqrt{2}}\sum_{h'_1, h'_2} \langle \lambda'_1| {\cal R}^TM({\blf k}'_1)| h'_1\rangle \langle h'_1| 
 \sigma_{\mu'} (i\sigma_y )|h'_2\rangle\langle h'_2|{\cal R}_M({\blf k}'_2)|\lambda'_2\rangle
\nonu
=-(-1)^{\mu'} \frac{1}{\sqrt{2}}~\langle \lambda'_1|  {\cal R}^T_M({\blf k}'_1)~(i\sigma_y )~
 \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)|\lambda'_2\rangle=-(-1)^{\mu'}\frac{1}{\sqrt{2}}~\langle \lambda'_1| (i\sigma_y )~ {\cal R}^\dagger_M({\blf k}'_1)~
 \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)|\lambda'_2\rangle~,
\label{eq:deu_wf_con_spin2}\ee
where in the last line one has $\sigma_{\mu'}\sigma_y=-(-1)^{\mu'}\sigma_y \sigma_{-\mu'}$.
Recall that ${\cal R}_M^T\ne {\cal R}_M^*$, since the Melosh rotations are unitary but not Hermitian.

The relevant quantity to be evaluated is 
\be
{\cal S}_{ij}^{\mu\mu'}=\sum_{\lambda_1\lambda_2}\sum_{\lambda'_1\lambda'_2}\frac{1}{\sqrt{2}} \langle \lambda_2| {\cal R}^\dagger_M({\blf k}_2)~
 \sigma_{\mu} ~{\cal R}_M({\blf k}_1)~(i\sigma_y )|\lambda_1\rangle~\langle \lambda_1|\hat \Phi ^i(x_1,0,{\bf k}_{\perp})|\lambda'_1\rangle 
 \nonu \times
 \frac{(-1)^{1+\mu'}}{\sqrt{2}}~\langle \lambda'_1| (i\sigma_y ){\cal R}^\dagger_M({\blf k}'_1)~
 \sigma_{-\mu'} ~{\cal R}_M({\blf k}'_2)|\lambda'_2\rangle~\langle \lambda'_2|\Bigl[\hat \Phi^{j }(x_2,0,-{\bf k}_\perp)\Bigr]^T|\lambda_2\rangle
 \nonu
 =~-(-1)^{\mu'}~{1\over 2} Tr\Biggl\{ {\cal R}^\dagger_M({\blf k}_2)~\sigma_{\mu}~{\cal R}_M({\blf k}_1)~ (i\sigma_y )~\hat \Phi^i(x_1,0,{\bf k}_\perp)~ (i\sigma_y )
 ~
 {\cal R}^\dagger_M({\blf k}'_1)~ \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)~\Bigl[\hat \Phi^j(x_2,0,-{\bf k}_\perp)\Bigr]^T\Biggr\}~.
\nonu
\label{eq:app_trace}\ee
The  LC correlator is defined as follows (recall that $\sigma^{+j} = i \gamma^+ \gamma^j$ and only the large component of the nucleon spinor is acting)
\be 
 \hat \Phi^{i}\left(x,0,{\bf k}_{\perp}\right)=H_i(x,0,-{\bf k}^2_{\perp}) -
\dfrac{i}{4 M}( \hat e_z\cdot {\bfm \sigma}\times {\bf k}_\perp  )  E_i(x,0,-{\bf k}^2_\perp)~,
\ee
with ${\bf k}_\perp={\bf k}'_{1\perp}-{\bf k}_{1\perp}= -({\bf k}'_{2\perp}-{\bf k}_{2\perp} )$. Moreover, 
by  taking ${\bf k}_\perp\equiv \{0,k_y\}$, without loss of generality, one has
\be
\hat \Phi^i (x,0,\pm{\bf k}_\perp)= H_i(x,0,- {\bf k}^2_\perp) \mp{i \over 4M} \sigma_x  k_y~E_i(x,0,-{\bf k}^2_\perp)
=\Bigl[\hat \Phi^i(x,0,\pm{\bf k}_\perp)\Bigr]^T
\nonu
(i\sigma_y )~\hat \Phi^i(x,0,{\pm\bf k}_\perp)~ (i\sigma_y )=~-\Bigl[H_i(x,0,- {\bf k}^2_\perp)\pm {i \over 4M} \sigma_x  k_y~E_i(x,0,-{\bf k}^2_\perp)\Bigr]= - \Bigl[\hat \Phi^i(x,0,\pm{\bf k}_\perp)\Bigr]^*~.
\ee
Therefore
\be
{\cal S}_{ij}^{\mu\mu'}=~(-1)^{\mu'}{1\over 2} Tr\Biggl\{ \sigma_{\mu}~{\cal R}_M({\blf k}_1)~\Bigl[\hat \Phi^i(x_1,0,{\bf k}_\perp)\Bigr]^* ~
 {\cal R}^\dagger_M({\blf k}'_1)~ \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)~\hat \Phi^j(x_2,0,-{\bf k}_\perp)~{\cal R}^\dagger_M({\blf k}_2)\Biggr\}=
 \nonu
 =(-1)^{\mu'}{1\over 2} Tr\Biggl\{ \sigma_{\mu}~{\cal R}_M({\blf k}_1)~\Bigl[ H_i( x_1,0,-{\bf k}^2_\perp)+ {i \over 4M} \sigma_x  k_y~E_i(x_1,0,-{\bf k}^2_\perp)  \Bigr] ~
 {\cal R}^\dagger_M({\blf k}'_1)~ \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)
 \nonu \times~\Bigl[H_j(x_2,0,- {\bf k}_\perp) +{i \over 4M} \sigma_x  k_y~E_j(x_2,0,-{\bf k}_\perp)\Bigr]~{\cal R}^\dagger_M({\blf k}_2)\Biggr\}
 \nonu
 =~ H_i(x_1,0, -{\bf k}^2_\perp)H_j(x_2,0,- {\bf k}^2_\perp)  ~{(-1)^{\mu'}\over 2} Tr\Biggl\{ \sigma_{\mu}~{\cal R}_M({\blf k}_1) ~
 {\cal R}^\dagger_M({\blf k}'_1)~ \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)~{\cal R}^\dagger_M({\blf k}_2)\Biggr\}
 \nonu
 +i { k_y\over 4M}H_i(x_1,0, -{\bf k}^2_\perp) ~ E_j(x_2,0,-{\bf k}^2_\perp)~{(-1)^{\mu'}\over 2} Tr\Biggl\{ \sigma_{\mu}~{\cal R}_M({\blf k}_1)~
 {\cal R}^\dagger_M({\blf k}'_1)~ \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)~\sigma_x  ~{\cal R}^\dagger_M({\blf k}_2)\Biggr\}
 \nonu
 +i {k_y\over 4M} ~E_i(x_1,0,-{\bf k}^2_\perp) H_j(x_2,0,- {\bf k}^2_\perp) ~{(-1)^{\mu'}\over 2} Tr\Biggl\{ \sigma_{\mu}~{\cal R}_M({\blf k}_1)~ \sigma_x   ~
 {\cal R}^\dagger_M({\blf k}'_1)~ \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)~{\cal R}^\dagger_M({\blf k}_2)\Biggr\}
 \nonu
 -{k^2_y\over 16M^2}~E_i(x_1,0,-{\bf k}^2_\perp)  ~E_j(x_2,0,-{\bf k}^2_\perp) ~{(-1)^{\mu'}\over 2} Tr\Biggl\{ \sigma_{\mu}~{\cal R}_M({\blf k}_1)~ \sigma_x   ~
 {\cal R}^\dagger_M({\blf k}'_1)~ \sigma_{-\mu'}~{\cal R}_M({\blf k}'_2)~ \sigma_x  ~{\cal R}^\dagger_M({\blf k}_2)\Biggr\}~.
\nonu
\ee
When $\hat \Phi$ reduces to a multiple of the  identity, e.g. for ${\bf k}_\perp={\bf k}'_{1\perp}-{ \bf k}_{1\perp}=0$,  one gets
\be
\label{Eq:iden}
{\cal R}_M({\blf k}_n)~\hat \Phi^{i}
 ~ {\cal R}^\dagger_M({\blf k}'_n)\to {\rm I}~,
\ee
and the trace becomes $\delta_{\mu,\mu'}$. In fact, one should recall that  (cf Varshalovich et al p. 48) $$\sigma_\mu=\hat {\bf e}_\mu \cdot {\bfm \sigma}~~,$$ leading to 
\be
 (-1)^{\mu'}{1\over 2} Tr \{\sigma_{\mu} ~ \sigma_{-\mu'}\}= (-1)^{\mu'}\Bigl[\hat {\bf e}_\mu \Bigr]_i  \Bigl[\hat {\bf e}_{-\mu '}\Bigr]_j ~{1\over 2} Tr \{\sigma_{i} ~ \sigma_{j}\}=\hat {\bf e}_\mu \cdot \hat {\bf e}^{\mu'}= \delta_{\mu,\mu'}~.
\ee

\subsection{Simplifying $S^{\mu\mu'}_{ij}$}
First, let us considering the following products involving  Melosh rotations,  recalling $k^+_n= E(|{\bf k}_n|) +k_{nz}$,
\be
{\cal R}_M({\blf k}'_n)  ~{\cal R}^\dagger_M({\blf k}_n)=
{\Bigl[ k^{\prime +}_n +m-i {\bfm \sigma}\cdot (\hat e_z \times {\bf k}'_{n\perp})\Bigr]~\Bigl[ k^{ +}_n+m +i {\bfm \sigma}\cdot (\hat e_z \times {\bf k}_{n\perp})\Bigr] \over  \sqrt{ | {\bf k}_{n\perp} |^ 2 +(k^+_n +m)^2 } ~ 
  \sqrt{ | {\bf k}^\prime_{n \perp}|^ 2 +(k^{\prime +}_n +m)^2 }}
 \nonu ={{\cal A}_1({\blf k}'_n,{\blf k}_n)
  +i {\bfm \sigma}\cdot  {\bfm {\cal B}}_1({\blf k}'_n,{\blf k}_n)\over  \sqrt{ | {\bf k}_{n\perp} |^ 2 +(k^+_n +m)^2 } ~ 
  \sqrt{ | {\bf k}^\prime_{n \perp}|^ 2 +(k^{\prime +}_n +m)^2  }} 
 ~, \ee
  and \be
  {\cal R}_M({\blf k}'_n)~ \sigma_x  ~{\cal R}^\dagger_M({\blf k}_n)=
{\Bigl[ k^{\prime +}_n+m -i {\bfm \sigma}\cdot (\hat e_z \times {\bf k}'_{n\perp})\Bigr]~\sigma_x~\Bigl[ k^{ +}_n +m+i {\bfm \sigma}\cdot (\hat e_z \times {\bf k}_{n\perp})\Bigr] \over  \sqrt{ | {\bf k}_{n\perp} |^ 2 +(k^+_n +m)^2 } ~ 
  \sqrt{ | {\bf k}^\prime_{n \perp}|^ 2 +(k^{\prime +}_n +m)^2 }}
  \nonu=i{{\cal A}_2({\blf k}'_n,{\blf k}_n)+i{\bfm \sigma}\cdot {\bfm {\cal B}}_2({\blf k}'_n,{\blf k}_n)
   \over  \sqrt{ | {\bf k}_{n\perp} |^ 2 +(k^+_n +m)^2 } ~ 
  \sqrt{ | {\bf k}^\prime_{n \perp}|^ 2 +(k^{\prime +}_n +m)^2 } }~.\ee
  In the above equations, one has
  \be
  {\cal A}_1({\blf k}'_n,{\blf k}_n)=(k^{\prime +}_n+m)~(k^{ +}_n+m) +  {\bf k}'_{n\perp}\cdot   {\bf k}_{n\perp}
  \nonu
  {\bfm {\cal B}}_1({\blf k}'_n,{\blf k}_n)=
  -\hat e_x [(k^{\prime +}_n+m) k_{ny}-(k^+_n+m) k'_{ny}]+\hat e_y [(k^{\prime +}_n+m) k_{nx}-(k^+_n+m) k'_{nx}]
  + \hat  e_z (k^{\prime}_{nx} k_{ny}-k_{nx} k'_{ny})~,
  \nonu\ee
and 
\be
{\cal A}_2({\blf k}'_n,{\blf k}_n)=(k^{ +}_n+m) k'_{ny}-(k^{\prime  +}_n+m) k_{ny}
\nonu
{\bfm {\cal B}}_2({\blf k}'_n,{\blf k}_n)=-\hat e_x [(k^{\prime +}_n+m) (k^{ +}_n+m) +{ k}^\prime_{ny} { k}_{ny}-{ k}'_{nx} { k}_{nx}] 
  +\hat e_y ({ k}'_{ny} { k}_{nx}+{ k}'_{nx} { k}_{ny} )+\hat e_z [(k^{\prime +}_n+m) k_{nx}+ (k^{ +}_n+m) k'_{nx}]~.
  \nonu
\ee
For the two-nucleon case, notice that for ${\bf k}_\perp =0$, i.e. ${\bf k}'_{1\perp}={\bf k}_{1\perp}$, one has $ k_{1z}=M_0 (\xi_1 -1/2)= k'_{1z}$ and gets 
\be 
{\cal A}_1({\blf k}_1,{\blf k}_1)=(k^{ +}_1+m)^2~ +  |{\bf k}_{1\perp}|^2 , \quad {\bfm {\cal B}}_1({\blf k}_1,{\blf k}_1)=0
\nonu
{\cal A}_2({\blf k}_1,{\blf k}_1)=0 , \hspace{3.3cm}{\bfm {\cal B}}_2({\blf k}_1,{\blf k}_1)=
\hat -e_x \Bigl[(k^{ +}_1+m)^2+k_{1y}^2 -k_{1x}^2\Bigr]
  +2\hat e_y { k}_{1y} { k}_{1x}+2\hat e_z (k^{ +}_1+m) k_{1x}~,
\nonu
\label{eq:calAB_kperp0}\ee
and analogously for ${\blf k}_2$.

Then
\be
{\cal S}_{ij}^{\mu\mu'}= {H_i( x_1,0,-{\bf k}^2_\perp)H_j(x_2,0,- {\bf k}^2_\perp)~T^{\mu\mu'}_{11}\over \Bigl[  | {\bf k}_{n\perp} |^ 2 +(k^+_n +m)^2 \Bigr] ~ 
  \Bigl[ | {\bf k}^\prime_{n \perp}|^ 2 +(k^{\prime +}_n +m)^2 \Bigr] }  
 \nonu
 -{ k_y\over 4M}{H_i(x_1,0, -{\bf k}^2_\perp) ~ E_j(x_2,0,-{\bf k}^2_\perp)~T^{\mu\mu'}_{12}\over  \Bigl[  | {\bf k}_{n\perp} |^ 2 +(k^+_n +m)^2 \Bigr] ~ 
