\be \hat \rho_1= {1 \over A}\SumInt_{l}~|n'_l \rangle  \langle n'_l| 
\ee~.

and
\be \hat \rho_2= {2 \over A(A-1)}\SumInt_{l>r}~|n'_r \rangle |n'_l \rangle  ~\langle n'_l| \langle n'_r|
\ee~.
Therefore, one can rewrite the above operators in terms of these two quantities, in particular:

\begin{align}
    \SumInt_{lr} \hat I_{lr} &= \SumInt_l |n'_l\rangle \langle n'_l|+ \SumInt_{l \neq r} |n'_r \rangle |n'_l\rangle \langle n'_l| \langle n'_r|
= A \hat \rho_1+  2 \SumInt_{l>r} |n'_r \rangle |n'_l \rangle  ~\langle n'_l| \langle n'_r|
    \\
    \nonumber
    &= A \hat \rho_1+ A(A-1) \hat \rho_2
\end{align}





















