\section{Introduction}

Let $M$ be a closed, connected, smooth manifold of positive dimension.
Here and throughout, we will take ``smooth" to mean $C^\infty$. 


For an extended real number $r\in[1,\infty)\cup\{0,\infty\}$, we write $\Diff^r(M)$ for the group of $C^r$ diffeomorphisms of $M$, and $\Diff^r_0(M)$ for the identity component. 
We also often write $\Homeo$ for $\Diff^0$.
If $\omega$ is a $C^r$ volume form on a smooth manifold, we write $\Diff^r_{\omega}$ and $\Diff^r_{0,\omega}$ for the group of volume-preserving $C^r$ diffeomorphisms and the identity component of that group, respectively. 
For statements that apply equally to  a full group of diffeomorphisms or to a group of volume-preserving diffeomorphisms, we will write $\Diff^r_{(\omega)}$ and $\Diff^r_{0(,\omega)}$ when either group can be substituted.
\textit{We will adopt the convention that the manifold in consideration has dimension at least two whenever $\Diff^r_{\omega}$ and $\Diff^r_{0,\omega}$ are discussed.}


In this paper, we prove the following
result about the first order theory of diffeomorphism groups of manifolds. 
Here, we consider diffeomorphism groups as structures in the \emph{language of group theory} and write
$\Th(G)$ for the \emph{theory} of a group $G$. 
For us, the language of group theory will have the binary group operation, the inverse operation and the identity element as the non-logical symbols
in its signature.
If $G$ and $H$ are groups then we write
$G\equiv H$ whenever $G$ and $H$ are \emph{elementarily equivalent}, i.e.~$\Th(G)=\Th(H)$.


\begin{mainthm}\label{thm:main}
Let $M$ and $N$ be
smooth manifolds, with $M$ being closed and connected.
We also let $r,s\in[1,\infty)\cup\{0,\infty\}$. 
%We assume further that $\dim M, \dim N\geq 2$ whenever diffeomorphisms below are required to be volume preserving.
If we have elementarily equivalent groups $G$ and $H$ satisfying
that \[\Diff^r_{0(,\omega)}(M)\leq G\leq \Diff^r_{(\omega)}(M)\] and 
that \[\Diff^s_{0(,\omega)}(N)\leq H\leq \Diff^s_{(\omega)}(N),\] then we have that  $r=s$ and that $M$ is $C^r$--diffeomorphic to $N$.
%Moreover, if $r$ is rational then there is a sentence \[\phi_{r,M}\in\Th(G)\] such that whenever $K\models \phi_{r,M}$for some group  \[\Diff_{0(,\omega)}^{t}(N)\leq K\leq\Diff_{0(,\omega)}^{t}(N)\] and then $r=t$ and $M$ is diffeomorphic to $N$.
\end{mainthm}


\begin{rem}\label{rem:topology}
\begin{enumerate}
    \item 
    It is a standard fact that a $C^1$ manifold admits a unique smooth structure; see~\cite[Theorem 2.10]{hirsch2012differential}. Hence, in the case when $r\ge1$, it follows that $M$ and $N$ are smoothly diffeomorphic.
    \item 
    We do not consider the case that $0<r<1$, since $\Diff^r(M)$ is not closed under group composotion in general; see~\cite[Chapter A.2]{KK2021book}.
    \item
    The first order theory of diffeomorphism group can express  topological properties of ambient manifolds such as being connected, compact, or having nonempty boundary. See Theorem~\ref{thm:homeomorphism type}. Hence, we may only consider the case that $N$ is also closed and connected.
    \item In the case when $r=s=0$, we can even drop the hypothesis that $M$ and $N$ admit smooth structures; this is the content of~\cite{kkdln2025}.
    \item 
    We recall our standing convention that the ambient manifolds have dimensions at least two whenever diffeomorphisms discussed are assumed to be volume preserving.
\end{enumerate}
\end{rem}


It is known from the work of Takens, Bochner--Montgomery, and
Filipkiewicz~\cite{BM1945,Takens1979,filipkiewicz} that for integer regularities, two diffeomorphism groups of closed manifolds are isomorphic as abstract groups if and only if the regularities agree and the isomorphism is induced by a diffeomorphism between underlying manifolds of that regularity.
In fact, it is a consequence of the Generalized Takens--Filipkiewicz Theorem~\cite[Theorem 3.1.2]{KK2021book} that Main Theorem holds with a stronger assumption that $G$ and $H$ are isomorphic as groups and that $r,s$ belongs to the set $\mathbb{Z}_{+}\cup\{\infty\}$.
%In particular, for a fixed smooth manifold, diffeomorphism groups of different integer regularities are pairwise non-isomorphic. 
Because of the difficulty of extending Bochner--Montgomery's results to non-integer regularities, a corresponding result for non-integer regularities was not known.

\begin{cor}\label{cor:isomorphic}
For closed, connected smooth manifolds $M$ and $N$,
and for $r,s\in[1,\infty)\cup\{0,\infty\}$,
the groups $\Diff^r_{0(,\omega)}(M)$ and $\Diff^s_{0(,\omega)}(N)$ are isomorphic if and only if   $r=s$ and $M$ and $N$ are $C^r$--diffeomorphic.
\end{cor}
%\comment{changed}
In particular, the groups $\{\Diff_{0}^r(M)\}_{r\in[1,\infty)\cup\{0,\infty\}}$ are pairwise non-isomorphic.
%and the groups $\{\Diff_{0(,\omega)}^r(M)\}_{r\in[1,\infty)\cup\{\infty\}}$ are all pairwise non-isomorphic.
It is worth noting that Corollary~\ref{cor:isomorphic} is an instance of a purely geometric topology result first proved via applied logic. The reader may find a further treatment of the algebraic structure of diffeomorphism groups in dimension one in~\cite{Navas2011,CKK2019,KKM2019} and the references therein, for example.

We prove the Main Theorem largely in two steps, as described by the following two theorems. 
%: \emph{manifold recognition} and \emph{regularity detection}. 
In the first step, we construct a group theoretic sentence expressing that ``My underlying manifold is diffeomorphic to $M$'':
\begin{thmA}[Manifold recognition]\label{thm:mfd}
For all closed smooth manifolds $M$, there exists a sentence $\phi_M$ such that the following hold:
\begin{enumerate}[(i)]
\item\label{p:mfd1} if a group $G$ satisfies $\Diff^\infty_{0(,\omega)}(M)\le G\le \Diff^1_{(\omega)}(M)$, then $G\models\phi_M$;
\item\label{p:mfd2} if a group $H$ satisfies $\Diff^\infty_{0(,\omega)}(N)\le H\le \Diff^1_{(\omega)}(N)$
for some closed smooth manifold $N$
and if $H\models\phi_M$, then $M$ and $N$ are diffeomorphic.
\end{enumerate}
\end{thmA}
%\comment{changed}
Note that the sentence $\phi_M$ may differ in the  volume-preserving case. In the second step, we find a formula $\rho_q(g)$ implying (but not necessarily equivalent to) that ``the diffeomorphsim $g$ is not $C^s$ for $s>q$''.

\begin{thmA}[Regularity detection]\label{thm:reg}
For a closed smooth manifold $M$ and for a rational  $q\ge1$, there exists a formula $\rho_{M,q}(x)$ such that whenever a group $G$ satisfies
\[
\Diff^\infty_{0(,\omega)}(M)\le G\le\Diff^1_{(\omega)}(M),\]
the following hold:
\begin{enumerate}[(i)]
\item\label{p:reg1} If $\Diff^q_{0(,\omega)}(M)\le G$, then $G\models \rho_q(g)$ for some $g\in G$;
\item\label{p:reg2} If $G\models \rho_q(g)$ for some $g\in G$, then $g$ does not belong to $\bigcup_{s>q}\Diff^s(M)$.
\end{enumerate}
\end{thmA}


%\begin{thmA}[regularity detection]\label{thm:reg} Let $M$ be a closed smooth manifold, and let $q\in \mathbb{Q}_{\ge1}$.  Then there exists a sentence $\phi_q$ such that the following hold: \begin{enumerate}[(i)] \item\label{p:reg1} if a group $G$ satisfies $\Diff_{0(,\omega)}^q(M)\le G\le \Diff^1_{(\omega)}(M)$, then we have $G\models\phi_q$; \item\label{p:reg2} if a group $H$ satisfies $\Diff^\infty_{0(,\omega)}(M)\le H\le \bigcup_{s>q}\Diff^s_{(\omega)}(M)$, then $H\not\models\phi_q$. \end{enumerate} \end{thmA}

%\comment{changed}
The Main Theorem will then be a straightforward consequence. Indeed, under the hypothesis of the theorem, we see that $M$ and $N$ are $C^p$--diffeomorphic
by Theorem~\ref{thm:mfd} for $p:=\min(r,s)$.
If $1\le r<s\le\infty $, then we can pick $q\in[r,s)\cap\mathbb{Q}$. 
Theorem~\ref{thm:reg} implies that $\rho_{M,q}(g)$ holds in $G$ for some $g\in G$, while it holds for no $g\in H$. This contradicts the elementary equivalence.
The case when $r=0$ is similar (and easier).

We also observe that the first order theory of diffeomorphism groups can express the existence of exotic smooth structures, or that the particular underlying manifold is itself equipped with a nonstandard smooth structure.

%\comment{dependency of $\phi$ on $r$?}
\begin{prop}\label{prop:homeomorphic} (Theorem~\ref{thm:homeomorphism type})
For a given closed smooth manifold $M$,
there exists a sentence $\phi_{M,0}$ 
in the set
\[\bigcap\left\{\Th(G)\mid
\Diff^\infty_{0(,\omega)}(M)\le G\le \Diff^1_{(\omega)}(M)\right\}\]
%\[\bigcap\left\{\Th(G)\mid \Diff^r_{0(,\omega)}(M)\le G\le \Diff^r_{(\omega)}(M)\text{ for some }r\in[1,\infty]\right\}\]
such that for an arbitrary closed smooth manifold $N$ we have
\[
\phi_{M,0}\in
\bigcup\left\{\Th(H)\mid \Diff^\infty_{0(,\omega)}(N)\le H\le \Diff^1_{(\omega)}(N)\right\}\]
if and only if $M$ is homeomorphic to $N$.
\end{prop}

