\subsubsection{Action structures}

Diffeomorphism groups of smooth manifolds of arbitrary regularity (both general and
volume preserving) are \emph{locally dense} groups of homeomorphisms, whence Rubin's
theory of action structures applies~\cite{Rubin1989,Rubin1996}. For $g\in G$ as above,
we write $\suppe g$ for the extended support of $g$, namely the interior of the closure
of $M\setminus\fix{g}$. The Boolean algebra $\ro(M)$ denotes the \emph{regular open sets}
of
$M$, i.e.~open sets that are equal to the interior of their closure. For $U\in\ro(M)$
we write $G[U]$ for the \emph{rigid stabilizer} of $U$, which is to say all elements
of $G$ which contain $M\setminus U$ in their fixed point set.

As we summarize here,
nearly all of the content of~\cite{kkdln2025} carries over to the case of diffeomorphisms
without major change; one need only check that certain existential statements
(i.e.~ones which require producing a homeomorphism) can be witnessed by sufficiently
smooth diffeomorphisms. We will not give all the full statements from~\cite{kkdln2025}
here -- it suffices to note that most of sections 2 and 3 of that paper carry over
without change.
\begin{prop}\label{prop:full support}
If $M$ is a smooth manifold, 
then 
%Let $M$ be a smooth manifold and $G$ as above, and if $\dim M=1$, assume that $G$ does not consist of volume preserving diffeomorphisms.
for each regular open $U\in\ro(M)$, we have some $g\in \Diff^\infty_0(M)$ such that $U=\suppe g$.
\end{prop}
\begin{proof}
The proof is nearly identical to Proposition 2.7 in~\cite{kkdln2025}; writing a dense
open subset of $U$ as the
union of a countable union of disjoint balls, one produces elements of $G$ supported
on each of these balls separately. To guarantee that their composition is an element of
$G$, one need only arrange that the derivatives on each component decay to the identity
sufficiently quickly, which can be achieved through standard techniques.
\end{proof}

Hence, we have a surjection
\[
\rho_0\co G\longrightarrow \ro(M)\]
defined by $\rho_0(g):=\suppe g$. Since $G$ as above is locally moving, one can apply Rubin's Expressibility Theorem (\cite{Rubin1996}; see also~\cite[Theorem 3.4]{kkdln2025}) and obtain the following.
\begin{cor}
    There is a uniform (independent of $M$ and $G$) interpretation of the action structure $\on{ACT}(M,G)$, i.e.~the sort consisting of the full Boolean algebra $\ro(M)$ of regular open sets of $M$ together with the action of $G$ on $\ro(M)$.
\end{cor}

\subsubsection{Reduction to connected manifolds}
Let us first establish that the theory of $G$ detects the connectivity of the ambient manifold $M$, with a rather mild condition on $M$ and $G$.
\begin{lem}\label{lem:cnt}
There exists a sentence $\phi=\phi^{(\vol)}_{\mathrm{cnt}}$ such that the following hold:
\\
Assume either
\begin{enumerate}[(i)]
\item $N$ is a topological manifold 
(possibly noncompact or with boundary) and  
\[\Homeo_{0(,\omega)}(N)\le G\le \Homeo_\omega(N).\]
\item $N$ is a smooth manifold 
(possibly noncompact or with boundary) and  
\[\Diff^\infty_{0(,\omega)}(N)\le G\le \Homeo_\omega(N).\]
\end{enumerate}
Under these hypotheses, we have $G\models\phi$
iff $N$ is conncted.
\end{lem}
\begin{proof}
By interpreting $\on{ACT}(N,G)$ to $G$, 
we can require $\phi$ to express the following: for all nonempty disjoint $U,V\in\mathrm{RO}(N)$, there exist nonempty disjoint regular open sets $U',U''$ in $U$ such that $g(U')\subseteq V$ and $g(U'')=U''$. It is clear from~Lemma~\ref{lem:cr-trans-balls-gen} that this satisfies the conclusion.
\end{proof}

    Because there is a first order formula which uniformly detects connectedness of
    regular open sets,
    \emph{we will henceforth assume that all ambient manifolds
    connected}; the components of a test manifold $N$ can be marked by an arbitrary finite
    collection of connected regular open sets in $N$, and then the differential topology
    of $N$ can be investigated component-wise. In particular, in the statement of
    the Main Theorem, if the groups $G$ and $H$ are elementarily equivalent and $M$ is connected, then $N$ is automatically connected; more generally, the number of components of $M$ and $N$ must coincide.

\subsubsection{Topological properties of regular open sets}
Various topological properties of regular open sets can be interpreted in the action
structure, via suitable first order predicates.
Details can be found in Section 3.3 of~\cite{kkdln2025}, specifically
Lemma 3.6 and Corollary 3.7. We summarize
some relevant conclusions; proofs are identical to those in~\cite{kkdln2025}.
Recall that for an open set $U\subseteq M$, we write
$G[U]$ for the set of $g\in G$ which are the identity outside of $U$.

\begin{lemma}\label{lem:top-prop}
The following hold for $M$ and $G$ as above.
\be
    \item\label{p:full1}
For $U,V\in\ro(M)$, we have that $ G[U]= G[V]$ if and only if $U=V$.
\item\label{p:rigid-stab}
For each $U\in\ro(M)$, we have that
\[
G[U]=\{g\in G\mid g(V)=V\text{ for all regular open set }V\sse U^\perp\}.
\]
%\item\label{p:pcnt}
%An open subset of $M$ is path-connected if and only if it is connected. 
%\item\label{p:cnt1}
%An arbitrary union of connected components of a regular open set is necessarily regular open.
%More specifically, if a regular open set $W$ can be written as $W=U\sqcup V$ for some disjoint pair of open sets $U$ and $V$, then $U$ and $V$ are regular open and $W=U\oplus V$.
%Moreover, we have $V=W\cap U^{\perp}$.
\item\label{p:group}
For disjoint pair $U,V$ of regular open sets, we have (i)$\Rightarrow$(ii)$\Rightarrow$(iii).
\be[(i)]
\item $U$ is connected, and $U\oplus V=U\sqcup V$;
\item Every $g\in  G[U\oplus V]$ satisfies either $g(U)=U$ or $g(U)\cap U=\varnothing$;
\item $U\oplus V=U\sqcup V$
\ee
\item\label{p:cnt2}
    	Let $W$ and $U$ are regular open sets such that $U$ is connected and such that $U\sse W$.
    	Then $U$ is a connected component of $W$
    	if and only if $W=U\oplus V$ for some regular open $V$ that is disjoint from $U$
    	and every $g\in  G[W]$ satisfies either $g(U)=U$ or $g(U)\cap U=\varnothing$.
    	\item\label{p:cnt1-2} The following are all equivalent for a regular open set $W$.
    	\be[(i)]
    	\item  $W$ is disconnected;
    	\item $W=U\sqcup V$ for some disjoint pair of nonempty regular open sets $U$ and $V$ such that $U$ is connected;
    	\item $W=U\oplus V$ for some disjoint pair of nonempty regular open sets $U$ and $V$, and every $g\in  G[W]$ satisfies either $g(U)=U$ or $g(U)\cap U=\varnothing$;
    	\item $W=U\oplus V=U\sqcup V$ for some disjoint pair of nonempty regular open sets $U$ and $V$.\ee
    %\end{enumerate}
    \item\label{p:full2}
    For two regular open subsets $U$ and $V$
    satisfying $U\cap V=\varnothing$,
    we have that
    $U\sqcup V= U\oplus V$
    if and only if
    each connected component of $U\oplus V$ is contained either in $U$ or in $V$.
    \ee

    Moreover, there exist first order formulae in the language of groups,
    uniform in both $M$ and $G$,
    which express the following.

    \begin{enumerate}
\item\label{p:contained} The inclusion $\suppe g\sse U$ for $g\in G$ and $U\in\ro(M)$.
\item\label{p:conn}
Connectedness of a regular open set $U$.
\item\label{p:cc}
    	That a regular open set $U$ is a connected component of a regular open set
     $V$, i.e.~$U\in\pi_0(V)$.
\item\label{p:ucc}
    	That a regular open set $U$ is a union of connected components of a
     regular open set $V$.
\item\label{p:cck}
For all natural numbers $k$, that a regular open set $U$ has exactly $k$ components.
\item\label{p:disj} That regular open sets $U$ and $V$ satisfy $U\oplus V=U\sqcup V$;
here $\oplus$ denotes the Boolean join and $\sqcup$ denotes disjoint union.
\item\label{p:ccpartition}
That a regular open set $W$ is a disjoint union of regular open set $U$ and $V$, each
of which consists of connected components of $W$.
\item\label{p:cnteq}
That whenever regular open sets $U$ and $V$ have finitely many components, $U$ and $V$
have the same number of components.
\end{enumerate}
\end{lemma}




Continuing to follow Section 3.4 of~\cite{kkdln2025}, we are able to find formulae
expressing relative compactness. Proofs are identical.

\begin{lemma}[cf.~\cite{kkdln-pre}, Lemma 3.9]\label{lem:vol-tech}
Let $M$ be a closed manifold with a volume form $\omega$, and let $G$ be a group
of volume-preserving diffeomorphisms as above.
    There exists a formula $\vol_{\leq}(u_1,u_2,v)$ such that for all triples
    $(U_1,U_2,V)$ of regular open sets with $U_1$ and $U_2$ connected 
    and $U_1,U_2\subseteq V$, we have the following.
    \begin{enumerate}
    	\item
    	If $\omega(U_1)\leq \omega(U_2)$ then $\vol_{\leq}(U_1,U_2,V)$ holds.
    	\item
    	If $\vol_{\leq}(U_1,U_2,V)$ holds then
     $\omega(U_1)\leq\omega((\cl U_2)\cap V)$.
    \end{enumerate}
\end{lemma}

The proof of Lemma~\ref{lem:vol-tech} in~\cite{kkdln-pre} uses the continuous analogue
of Lemma~\ref{lem:trans-measure} and Lemma~\ref{lem:cr-trans-balls-gen}, which
are justified above. Lemma~\ref{lem:vol-tech}, together with the fact that
homeomorphisms can be arbitrarily well-approximated in the $C^0$ topology
by $C^{\infty}$ diffeomorphisms,
then yields:


\begin{lemma}[cf.~\cite{kkdln-pre}, Lemma 3.10]\label{lem:compact-contained}
    For $M$ and $G$ as above and $U,V\in\ro(M)$, there exists a formula expressing
    that $U$ is compactly contained in an open ball that is contained in $V$;
    that is, there exists an open ball $B\subseteq V$ such that the closure of $U$
    is contained in $B$.
\end{lemma}


\subsubsection{Reduction to closed manifolds}
Note that Lemma~\ref{lem:compact-contained} implies that in the Main Theorem, the groups $G$ and $H$ can only be elementarily equivalent if $N$ is necessarily closed. Indeed, for a fixed closed manifold $M$, one can assert the existence of a finite list $\{U_1,\ldots,U_n\}$ of regular open sets such that each $U_i$ is compactly contained in $M$ and such that \[M=\bigoplus_{i=1}^n U_i.\]  Such a finite list $\{U_1,\ldots,U_n\}$ will exist
    in $N$ if and only if $N$ is also closed.
Hence from now on, we may only consider the case that $N$ is closed. Note that, \emph{a priori}, such
 a formula will depend on $n$, and hence on $M$ since we have not yet interpreted arithmetic.  
\subsubsection{Infinitude of components}
Crucial to interpretations of arithmetic and of the boundary of $M$ is the detection
of infinitude of components of a regular open set. The proof follows
Section 3.4.2 of~\cite{kkdln2025}.

First, there is a formula which expresses that a regular open set $U$
is \emph{dispersed},
i.e.~every connected component $\hat U$ of $U$ is compactly contained in an open
ball inside of $U^{\perp}\oplus \hat U$.

In~\cite{kkdln2025}, we found a formula which essentially
asserted that a regular set $W$ has
infinitely many components if there is a subset $U$ of $W$ with a component-wise
injection between components of $W$ and $U$, and a homeomorphism which
permutes components of $W$ in a translation-like fashion.
Such a formula is not available in the smooth case, since one may not be able to
find a diffeomorphism with the desired properties. Some modifications are thus
necessary.

\begin{lem}\label{lem:infcomp}
There exists a formula $\on{infcomp}(w)$ which holds for a regular open set $W$
precisely when $W$ has infinitely many connected components.
\end{lem}

To explain the intuition behind Lemma~\ref{lem:infcomp}, we will first pass to a subset
$U\subseteq W$ which meets every component of $W$ in at most one component; moreover,
there will be another regular open $V$ ``interlaced" with $U$. One can imagine that
$U$ and $V$ are linearly arranged, with alternating components
\[\{U_0,V_0,U_1,V_1,U_2,V_2,\ldots\}.\]
We then insist that there be an element of the ambient
group $G$ which sends some point of $U_i$ into a unique component $V_i$ of $V$, and sends
a point of $V_i$ into a unique component $U_{i+1}$ of $U$. This argument is a slightly
modified version of an argument given in~\cite{kkdln2025}, with extra care given to
the existence of a diffeomorphism with the desired properties (and not just a
homeomorphism).

\begin{proof}[Proof of Lemma~\ref{lem:infcomp}]
    The formula $\on{infcomp}(w)$ will express the conjunction of the following
    clearly expressible statements:

    There exist regular open sets $U,V\in\ro(M)$, a unique component
    $U'\in\pi_0(U)$, and an element $g\in G$ such
    that:
%\comment{sam: shall we need $V\cup g(V)\sse U$ ? thomas: no, otherwise the argument would
%not produce a diffeomorphism}
    \begin{enumerate}
        \item $\varnothing\neq U\subseteq W$.
        \item Every component of $W$ contains at most one component of $U$.
        \item $U$ and $V$ are dispersed and disjoint.
        \item For all components $\hat U$ of $U$, there is a unique component
        $\hat V$ of $V$ such that $g(\hat U)\cap \hat V\neq \varnothing$,
        and for all components $\hat U\in\pi_0(U)\setminus U'$, there is a
        unique component $\hat V$ of $V$ such that $g^{-1}(\hat U)\cap\hat V\neq
        \varnothing$.
        \item For all components $\hat V$ of $V$, there is a unique component
        $\hat U\in\pi_0(U)\setminus U'$ such that
        $g(\hat V)\cap\hat U\neq\varnothing$, and for all components $\hat V$ of
        $V$ there is a unique component $\hat U$ of $U$ such that
        $g^{-1}(\hat V)\cap\hat U\neq\varnothing$.
        \item $g^{-1}(U')\cap V=\varnothing$.
    \end{enumerate}

    For the forward direction, suppose that $W$ satisfies $\on{infcomp}(W)$.
    It clearly suffices to prove that $U$ has infinitely many components.
    We let $U'=U_0$. We set $V_0$ to be the unique component of $V$ such that
    $g(U')\cap V_0\neq\varnothing$.

    Having defined $U_i$ and $V_i$, assume by induction that \[\{U_0,\ldots,U_i\}
    \quad
    \textrm{and}\quad \{V_0,\ldots,V_i\}\] are all distinct.
    We set $U_{i+1}$ to be the unique component of
    $U$ which satisfies \[g(V_i)\cap U_{i+1}\neq\varnothing.\] Note that
    \[U_{i+1}\notin\{U_0,\ldots,U_i\}.\] Indeed, suppose $U_{i+1}=U_j$ for some
    $j\leq i$. It is immediate that $j\neq 0$ since $g^{-1}(U_0)\cap V=\varnothing$.
    So, we may conclude that $g^{-1}(U_j)$ meets two distinct components of $V$,
    a contradiction. Similarly, we set $V_{i+1}$ to be the unique component of
    $V$ such that $g(U_{i+1})\cap V_{i+1}\neq\varnothing$. It is immediate that
    $V_{i+1}\notin \{V_0,\ldots,V_i\}$ since otherwise $g^{-1}(V_{i+1})$ would
    meet two distinct components of $U$, a contradiction. It follows that $U$,
    and hence $W$, both have infinitely many components.

    Conversely, suppose that $W$ has infinitely many components. By compactness,
    we may choose
    a convergent sequence of points $\{x_i\}_{i\in\N}\subseteq W$,
    each term lying in a different component of $W$. Passing to a further
    subsequence if necessary, we may assume that this sequence lies in a single
    Euclidean chart diffeomorphic to $\R^n$ (or to the upper half-space, in the case
    of a manifold with boundary), and that the sequence converges to
    the origin $0$. Passing to an even further subsequence if necessary,
    we may assume
    $d(x_{i+1},0)\leq \frac{1}{2}d(x_{i},0)$ for all $i$. We set $U$ to be a union
    of neighborhoods $\{U_i\}_{i\in\N}$ of the points
    $\{x_i\}_{i\in\N}$, where we take the radius
    of the neighborhood $U_i$ about $x_i$ to be $\frac{1}{4}d(x_i,0)$. Choose
    smooth paths $\{\gamma_i\}_{i\in\N}$ connecting $U_i$ to $U_{i+1}$ such that
    for all $y\in\gamma_i$, we have \[\frac{5}{4}d(x_{i+1},0)\leq d(y,0)\leq
    \frac{3}{4}d(x_i,0),\] and let $\tilde V$ be a small tubular neighborhood of
    the union of these paths. We shrink $\tilde V$ slightly to obtain the set $V$.
    Since we have freedom in shrinking $V$, it is clear that we may arrange
    the existence of a diffeomorphism $g$ with the desired properties; moreover,
    we may arrange for $g$ to preserve the standard volume form on $\R^n$ in the
    volume preserving case.
\end{proof}



Evidently, there is formula $\on{fincomp}(w)$ which is simply the negation of
$\on{infcomp}(w)$, and expresses that a regular open set has only finitely many
components.


\subsubsection{Another way of ruling out non-closed manifolds}
Suppose $N$ is a compact smooth manifold, possibly with boundary. We wish to show
that no diffeomorphism group of $N$ can be elementarily equivalent to a diffeomorphism
group of $M$, thus showing again why we may assume that the manifold $N$ in
the Main Theorem is closed. This can be achieved by finding a formula
$\on{touch}(u)$ which holds for a regular open set $U$ if and only if $U$ accumulates
on the boundary of the corresponding manifold. Such a formula is found in~\cite{kkdln2025}
and applies to the present situation verbatim; we do not reproduce the argument here.


\subsubsection{Interpreting second order arithmetic}

Since every regular open set in $M$ occurs as the extended support of a diffeomorphism
of $M$, the interpretation of second order arithmetic can be carried out identically
to the interpretation in~\cite{kkdln2025}.

\begin{prop}\label{prop:arith}
    There is a uniform (both in the underlying manifold and the underlying
    group), parameter-free interpretation of second order arithmetic in $G$.
\end{prop}

We thus obtain a uniform interpretation of first order analysis within the first order
theory of $G$. Note that since we can identify regular open sets which are compactly
contained in ball of $M$, we may carry out the interpretation of arithmetic in the
diffeomorphism (or homeomorphism) group of any manifold $M$ of positive dimension, regardless
of whether $M$ is compact.

%\comment{Sam: check if Remark 2.10 is comptatible/nonredundant to the following paragraph}
The preceding discussion has the following consequence: we can find a sentence
which holds in the homeomorphism (and diffeomorphism) groups of
manifolds of positive dimension precisely when the underlying manifold is compact; similar
arguments hold for manifolds of dimension at least two when volume (measure) preserving 
diffeomorphisms (homeomorphisms) are considered.

\begin{prop}\label{prop:compact-noncompact}
    There exists a sentence $\psi$ which is true in the homeomorphism group of an arbitrary connected manifold $N$ if and only if $N$ is compact.
\end{prop}
\begin{proof}
    We have that $N$ is compact if and only if it is sequentially compact. We treat the
    case where $\partial N=\varnothing$ first.
    Thus, a boundaryless manifold $N$ is noncompact if and only if
there is a regular open set $U\in\ro(N)$ such that:
\begin{enumerate}
    \item $U$ has at least $n$ components for every $n\in\N$; here we are using the
    interpretation of arithmetic in order to quantify over natural numbers, together
    with (an obviously definable) predicate which allows us to count components of regular
    open sets.
    \item For all $W\subseteq U$ with the property
that each component of $U$ 
contains exactly one component of $W$, and
for all $V\in\ro(N)$ with $V$ compactly
contained in a collared open ball in $N$, there exists a subset $W_0\subseteq W$ such that:
\begin{enumerate}
    \item Each component of $W$ contains exactly one component of $W_0$.
    \item $W_0\cap V$ has finitely many components.
\end{enumerate}
\end{enumerate}
It is
that the foregoing conditions are expressible by a single sentence.

To see that these conditions give the desired sentence $\psi$,
suppose that $N$ is compact, and let
$U$ be a regular open set with infinitely many components.

Fix a compatible metric on
$N$ and choose a dispersed sequence
collared balls, one in each of the components of $U$, with
shrinking radii; call their union, which is equal to their join, $W$. Note that these balls accumulate on some point $p\in N$, since $N$ is
compact. Choose an arbitrary $V$ containing $p$ which is compactly contained in a ball in
$M$, we observe that for any suitable $W_0$ as given by the conditions above,
the set $V$ must contain infinitely many
components of $W_0$.

Conversely, suppose at $N$ is not compact, and choose an exhaustion
\[N=\bigcup_{i\in\omega} K_i\] by increasing compact sets; for the sake of concreteness,
we may choose a compatible metric on $N$ and let $K_i$ consists of the closure of a ball
of radius $i$ centered at fixed but arbitrary point.
Choose $U$ such that for all $i$, at least
one component of $U$ lies in $N\setminus K_i$ and $U\cap K_i$ is a regular open set
with finitely many components. Choosing $W\subseteq U$ arbitrary, we see that
components of $W$ exit every compact subset of $M$. If $V$ is compactly contained in a ball
in $N$ then $V$ is contained in some $K_i$. Choosing sufficiently small balls in each
component of $W\cap K_i$, we arrange for $W_0$ to meet $V$ in finitely many components.

To address the case $\partial N\neq 0$, we may express that a tubular neighborhood
$U$ of $\partial N$ has finitely many or infinitely many components. Here, we need not
even directly quantify over tubular neighborhoods; one may consider regular open sets $V$
which:
\begin{enumerate}
    \item Contain a tubular neighborhood of $\partial N$.
    \item For every regular open set $W$ containing a tubular neighborhood of the boundary
    of $N$, there is an element $g\in G$ such that $g(V)\subseteq W$.
\end{enumerate}
See Section 3.4.3 of~\cite{kkdln2025}.

If every such $V$ necessarily has infinitely many components, then $U$ necessarily has
infinitely many components.
If there are
infinitely many components in $U$ then clearly $N$ is not compact. If $U$ has finitely
many components then one may fix such a neighborhood and consider regular open sets
$V$ with infinitely components which are disjoint from $U$. Then, if $N$ is compact
then any such $V$ will necessarily accumulate at a point in the interior of $N$, in which
one may run the same argument as in the case $\partial N=\varnothing$.
\end{proof}

With some small modifications, one may deal with the case of disconnected manifolds;
we omit the details.
An analogous result holds for measure preserving homeomorphisms in dimension at least two,
and for diffeomorphisms.

\subsubsection{Points, exponentiation, and covering}
One can interpret finite tuples of points similarly to~\cite{kkdln2025}, though there
the argument was complicated by the need to discuss points on the boundary of $M$. Since
here we are generally only interested in closed manifolds,
we can use an intuitively simpler
interpretation. Specifically, a point $p\in M$ is coded by a regular open set $U$ as follows:
\begin{enumerate}
    \item $U$ has infinitely many components.
    \item For all components $\hat U$ of $U$, the complement $\hat U^{\perp}$ consists of
    exactly two components, say $V_1^{\hat U}$ and $V_2^{\hat U}$;
    exactly one of these components, say $V_1^{\hat U}$, contains finitely many components
    of $U$, and $V_2^{\hat U}$ contains infinitely many components of $U$. Moreover, 
    $V_2^{\hat U}$ is compactly
    contained in $V_2^{\hat U}\oplus \hat U$.
    \item For all pairs $W_1,W_2\in\ro(M)$ of regular open sets such that $W_i$ is compactly
    contained in $W_j^{\perp}$ for $i\neq j$, we have all but finitely many components of $U$
    are contained in $W_i^{\perp}$ for at least one $i\in\{1,2\}$.
\end{enumerate}

The preceding conditions are clearly first order expressible. Notice furthermore that
an easy compactness argument shows that
\[\bigcap_{\hat U\in\pi_0(U)}V_2^{\hat U}\neq\varnothing.\] The separating condition
involving
the sets $W_1$ and $W_2$ shows that this intersection actually consists of exactly one point
$p$, the point coded by $U$.

We declare two sets $U_1$ and $U_2$ to be equivalent if for all $\hat U_1\in\pi_0(U_1)$,
infinitely many components of $U_2$ are contained in $V_2^{\hat U_1}$. Clearly this condition
will hold if and only if the points coded by $U_1$ and $U_2$ are equal, and it is
straightforward to see that this condition is actually symmetric and defines a (first order
definable) equivalence relation. It is straightforward also to generalize this condition to
code finite tuples of points in $M$ by regular open sets. Therefore:
\begin{prop}\label{prop:points}
    There is a uniform interpretation of finite tuples of points in $M$, uniformly in $G$
    and in $M$.
\end{prop}

From the interpretation of points, it is straightforward to define a predicate expressing that
a point lies in the closure of a regular open set $U$, and that some finite collection
$\{U_1,\ldots,U_n\}$ of regular open sets cover the closure of a regular open set
$V\subseteq M$.

From the interpretation of the action structure of $G$ on $\ro(M)$, the interpretation of
points, and the interpretation of arithmetic, it is also straightforward to show:

\begin{prop}\label{prop:exponentiation}
    The exponentiation function \[\exp\colon G\times N\times \Z\longrightarrow M\] given
    by $\exp(f,n,p)=f^n(p)$ is uniformly definable.
\end{prop}

\subsubsection{Dimension and balls}

Since we can directly discuss the closure of a regular open set in $M$ and covering,
we may interpret enough about Lebesgue covering dimension to prove the following:

\begin{prop}\label{prop:dimension}
    For all $n\in\N$ there is a sentence $\dim_n$ such that $G\models\dim_n$ if and only
    if the underlying manifold $M$ has dimension equal to $n$.
\end{prop}
The proof of Proposition~\ref{prop:dimension} is carried out identically to~\cite{kkdln2025}.
Similarly, Section 6.2 of~\cite{kkdln2025} carries through without change for diffeomorphisms,
and so we obtain:

\begin{prop}\label{prop:balls}
There exist formulae 
\[\on{flows}_n(u,\gamma,\pi),\, \on{Param}_n(u,\gamma,\pi,\rho,\pi')\]
such that the following hold for all $G$, provided the dimension $n=\dim M$ is at least two.
\begin{enumerate}
\item\label{p:flows1}
Let $U\in\ro(M)$, $\underbar g\in \cH^n$ and $p\in M$.
If \[\models\on{flows}_n(U,\underbar g,p),\] then there exists a unique homeomorphism 
\[\Psi=\Psi[U,\underline{g},p]\co I^n\longrightarrow \cl U\]
the graph $\Gamma$ of which satisfies
\[\Gamma=\{(r,q)\in I^n\times M\co G \models	 \param_n(U,\underbar g,p,r,q)\},\]
and also  $(0,p)\in\Gamma$.
\item\label{p:flows2} Let $U$ and $V$ be collared
open balls inside $M$ such that $\cl U\sse V$; if $G$ consists of volume-preserving diffeomorphisms, we further assume that \[\vol(U)/\vol(V)\] is sufficiently small compared to some positive number determined by $n$. Then we have \[ \models(\exists \underline{\gamma}\exists \pi)\,\on{flows}_{n}(U,\underline{\gamma},\pi).\] 
\end{enumerate}
  \end{prop}
Recall our convention that ``collared open balls'' are defined by a $C^\infty$ embedding. Since $\Diff^\infty_{0(,\omega)}(M)\le G$, we are able to parametrize $U$ with elements of $G$ as above.
  Note also that balls in one-dimensional manifolds are simply connected regular open sets; we
  will not need parameterizations of balls in one-dimensional manifolds in the sequel.

\subsection{Detecting the homeomorphism type from the diffeomorphism group}

We can now prove the following:

\begin{thm}\label{thm:homeomorphism type}
    Let $M$ be a connected, closed, smooth manifold,
    and let \[\Diff^\infty_{0(,\omega)}(M)\leq G\leq\Diff^1_{(\omega)}(M),\] There is a
    sentence $\phi_{M,0}\in \Th{G}$ such that for all smooth (not necessarily closed
    or even compact) manifolds $N$ and
    \[\Diff^\infty_{0(,\omega)}(N)\leq H\leq\Diff^1_{(\omega)}(N),\]
    we have $\phi_{M,0}\in\Th(H)$ if and only if $M$ and $N$ are
    homeomorphic.
\end{thm}
\begin{proof}
    If $M$ has dimension one, then $M$ is homeomorphic to the circle. When $G$ consists of
    volume-preserving diffeomorphisms, we may simply assert that $G$ is abelian and contains
    an element which is not of order two. If $G$ does not consist of volume-preserving
    diffeomorphisms then $\phi_{M,0}$ can be taken to assert that:
    \begin{enumerate}
        \item $M$ has dimension one;
        \item There is a connected regular open set $U$ of $M$ such that no nonempty, 
        connected, regular open $V\subseteq U$ separates $M$;
        \item Every regular open subset of $M$ with exactly two components separates $M$.
    \end{enumerate}

    For $M$ of dimension two or more, then we simply run the arguments of Section 8
    in~\cite{kkdln2025}, which require only parametrized balls, covering of $M$ be finitely
    many (topological) collared balls, and
    access to second order arithmetic.
\end{proof}



\section{Manifold Recognition}\label{s:mfd}
We now gather some generalities from differential topology which will allow us to
distinguish between different smooth structures from the first order theory of
diffeomorphism groups.

\subsection{Defining smooth atlases}
In this subsection, assume that $\dim M\geq 2$.
From Proposition~\ref{prop:balls}, we are able to define a topological atlas on $M$,
which is to say a covering of $M$ by topological collared balls; specifically, we can
express the fact that $\mathcal U=\{U_1,\ldots,U_n\}$ covers $M$ and that each $U_i$ is a
topological collared ball. In order to prove first order rigidity of diffeomorphism groups
of $M$, we will need to be able to discuss a smooth atlas, i.e.~when the elements of 
$\mathcal U$ are smooth collared balls in $M$. Recall here that a \emph{smooth collared
ball} in $M$ (which has dimension $n$) is a map \[\phi\colon B^n(1)\longrightarrow M\] which
is a diffeomorphism onto its image, which extends to a map $\Phi$ defined on $B^n(2)$,
which is also a diffeomorphism onto its image.

The main technical fact which allows us to achieve this goal is the Bochner--Montgomery
theorem (see~\cite{KK21-book}, Theorem 3.4.2 for instance):

\begin{thm}\label{thm:bochner-montgomery}
    Let $X$ be a smooth, connected manifold with $\partial X=\varnothing$, and let
    $k,d\in\N$.
    Suppose that \[H\colon \R^d\times X\longrightarrow X\] be a continuous map inducing an
    action of $\R^d$ on $X$ by $C^k$ diffeomorphisms. Then $H$ is a $C^k$ map.
\end{thm}




\begin{prop}\label{prop:smooth-ball}
There exists a uniformly definable sort $\mathcal D$, which consists of a $C^1$--smooth,
parametrized, collared balls. Moreover, $\mathcal D$ is a basis for the topology on $M$,
amd contains all $C^{\infty}$ collared balls.
\end{prop}



The proof consists of applying Theorem~\ref{thm:bochner-montgomery} in order to put
definable conditions on parametrized topological collared balls in $M$ which force them
to be smooth. We remark that we cannot arrange for $\mathcal D$ to consist of all
$C^1$--smooth balls because the elements of $\mathcal D$ ultimately arise
from the action of $G$, and $G$ may not contain all $C^1$ diffeomorphisms of $M$.
\begin{proof}[Proof of Proposition~\ref{prop:smooth-ball}]
    Let $p\in M$ be arbitrary, and let \[\phi\colon B^n(3)\longrightarrow M\] be a
    parametrized topological ball in $M$ with $\phi(0)=p$. We fix a $C^1$ action
    \[H\colon \R^n\times B^n(3)\longrightarrow B^n(3)\] of $\R^n$
    on $B^n(3)$ which coincides with the translation action of $\R^n$ on itself within 
    $B^n(1)$ and which is the identity outside of $B^n(2.5)$; see Lemma 3.2.3
    in~\cite{KK21-book}. Observe that by having $R^n$ act by rotations in each
    coordinate, we may arrange for $H$ to be volume preserving; see
    Lemma 6.6 in~\cite{kkdln-pre}.

    Now, we require $\phi$ to conjugate $H$ to an action of $\R^n$ by diffeomorphisms
    on $M$. This can be done by requiring that each conjugated homeomorphism acts by
    an element of $G$, i.e.~for all $v\in\R^n$, there exists an element $g\in G$ such
    that $g$ is the identity outside of $\phi(B^n(2.5))$ and such that for
    $q\in B^n(3)\subseteq M$, we have
    \[g(q)=\phi H(v,\phi^{-1}(q))\phi^{-1}.\] By Theorem~\ref{thm:bochner-montgomery},
    the corresponding conjugate map $\phi H\phi^{-1}$ is $C^1$--smooth, and by restricting the
    action of $\R^n$ to $B^n(2)$
    we thus immediately obtain a $C^1$--smooth collared ball in $M$ centered at $p$, with
    a parametrization inherited from the original parametrization given by $\phi$.

    We define $\mathcal D$ to consist of all collared balls defined in this way.
    Clearly, $\mathcal D$ consists of $C^1$--smooth balls. Since $G$ contains
    the identity component of the relevant group of $C^{\infty}$ diffeomorphisms, we
    see that $\mathcal D$ contains all $C^{\infty}$ collared balls. It is immediate
    that $\mathcal D$ contains a basis for the topology of $M$.
\end{proof}

\subsection{The Cheeger--Kister Lemma in the $C^\infty$ category}
