\title{Loose rectangular diagram, multi-crossing number, and arc index}
\author[T.Ito]{Tetsuya Ito}
\address{Department of Mathematics, Kyoto University, Kyoto 606-8502, JAPAN}
\email{tetitoh@math.kyoto-u.ac.jp}
\subjclass{57K10, 57M15}
\keywords{Arc index, $n$-crossing number, triple crossing number, loose rectangular diagram.}
\begin{document}

\begin{abstract}
For a non-split multi-crossing diagram $D$ of a link $L$ we show that $\alpha(L)-2 \leq c_2(D) + \sum_{n> 2}(2n-4)c_n(D)$ holds. Here $\alpha(L)$ is the arc index and $c_n(D)$ is the number of $n$-crossings of $D$. This generalizes and subsumes many known inequalities related to multi-crossing numbers. In the course of proof, we introduce a notion of loose rectangular diagram and show that a loose rectangular diagram can be converted to usual rectangular diagram preserving its arc index.
\end{abstract}


\maketitle

\section{Introduction}

A \emph{multi-crossing diagram} $D \subset \R^{2}$ of a (unoriented) link $L$ is an image $p(L)$ of the projection $p:\R^{3} \rightarrow \R^{2}$ such that each of its singular point is an $n$-crossing point for some $n$, where $n$ depends on a singular point. Here an \emph{$n$-crossing point} is a multiplicity $n$ transverse singularities, which is formed by $n$ arc segment intersecting at one point so that any two of them form a transverse double point singularity.

For a multi-crossing diagram $D$ and $n\geq 2$, we denote by $c_n(D)$ the number of its $n$-crossing points. The \emph{total crossing number} $c_{tot}(D)=\sum_{n\geq 2}c_n(D)$ is the number of singular points (crossing points) of $D$.

We say that a multi-crossing diagram is an \emph{$n$-crossing diagram} if all the singular points are $n$-crossing points. The \emph{$n$-crossing number} $c_n(L)$ of a link $L$ is the minimum number of $n$-crossing points among all $n$-crossing diagrams of $L$. The $n$-crossing number was introduced in \cite{ad1}, where it was shown that every link admits an $n$-crossing diagram. The $2$-crossing number $c_2(L)$ is usually called the (minimum) \emph{crossing number} and denoted by $c(L)$. This is one of the most elementary, but theoretically hard to treat invariant having many open problems. 



The aim of this paper is to prove the following inequality. Here we say that a multi-crossing diagram is \emph{non-split} if it is connected as a subset of $\R^{2}$.


\begin{theorem}
\label{theorem:main}
For a link $L$ and its non-split multi-crossing diagram $D$, 
\[\alpha(L)-2 \leq c_2(D) + \sum_{n>2}(2n-4) c_n(D)\]
holds. In particular, for a non-split link $L$ and $n>2$,
\[ \alpha(L) -2 \leq (2n-4)c_n(L)\]
holds.
\end{theorem}

This theorem subsumes or generalizes many known inequalities.
By the Morton-Beltrami inequality \cite{mb} $\mathrm{Breadth}_a F_L(a,z) \leq \alpha(L)-2$ of arc index and the Kauffman polynomial $F_L(a,z)$, we get the following.
\begin{corollary}
\label{cor:main}
For a non-split link $L$ and $n>2$
\[\mathrm{Breadth}_a F_L(a,z) \leq (2n-4)c_n(L) \]
holds. 
\end{corollary}


Since $\mathrm{Breadth}_a F_L(a,z) = c(L)$ for non-split alternating links \cite{th} , we get the following fundamental result of arc index.

\begin{corollary}\cite{bp,noy}
\label{cor:arc-index-alternating}
For a non-split alternating link $L$, $c(L)=\alpha(L)-2$.
\end{corollary}

Note that $c(L) \leq \frac{n(n-1)}{2}c_n(L)$ holds, since an $n$-crossing point can be decomposed with a $2$-crossing diagram with $\frac{n(n-1)}{2}$ $2$-crossings. By Corollary \ref{cor:main} and Corollary \ref{cor:arc-index-alternating}, we get the following better bound of $n$-crossing numbers for alternating links.

\begin{corollary}
\label{cor:alternating2}
For a non-split alternating link $L$ and $n>2$, $c(L) \leq (2n-4)c_n(L)$.
\end{corollary}



This subsumes the inequality $\frac{1}{2}c(K) \leq c_3(K)$ for the case $n=3$  \cite{ad1} and $\frac{1}{4}c(K) \leq c_4(K)$ for the case $n=4$ \cite{ad2}.
The proof of these inequalities in \cite{ad1,ad2} are based on a computation of Kauffman bracket. In \cite{ad4}, the Kauffman bracket bound is proven for general $n$, where it is shown that 
\begin{equation}
\label{eqn:Adams-bound} \mathrm{Breadth}\, \langle L \rangle \leq \left(\left\lfloor \frac{n^2}{2} \right\rfloor +4n-8\right)c_n(L)
\end{equation}
holds for $n \geq 3$, where $\langle L \rangle$ denotes the Kauffman bracket of a (framed) link $L$. Since $\mathrm{Breadth}\,\langle L \rangle = 4c(L)$ for a non-split alternating link, this implies 
\begin{equation}
\label{eqn:Adams-bound2} c(L) \leq \frac{1}{4}\left(\left\lfloor \frac{n^2}{2} \right\rfloor +4n-8\right)c_n(L) 
\end{equation}
for alternating non-split link and $n>2$. 
Although Corollary \ref{cor:main} and the inequality \eqref{eqn:Adams-bound}
are independent, our Corollary \ref{cor:alternating2} gives an improvement of \eqref{eqn:Adams-bound2}. 




For the braid index $b(L)$ of $L$, since $2b(L) \leq \alpha(L)$ holds \cite{cr}, we get the following.

\begin{corollary}
For a non-split link $L$, $b(L) \leq \frac{c_2(L)}{2}+1$ and $b(L) \leq (n-2)c_n(L)+1$ hold. 
\end{corollary}

This generalizes the inequalities for the case $n=2$ \cite{oh} and the case $n=3$ \cite{ni}.

Finally, the \emph{\"{u}ber crossing number} $\textit{\"u}\,(L)$ of a link $L$ is the minimum $n$ such that $L$ admits an $n$-crossing diagram with $c_n(D)=1$ \cite{ad3}. Theorem \ref{theorem:main} leads to the following.
\begin{corollary}\cite[Corollary 3.5]{ad3}
$\frac{1}{2}(\alpha(L)+2) \leq \text{\"u}\,(L)$ 
\end{corollary}



Our proof is based on a notion of a \emph{loose rectangular diagram}, a slight generalization of a rectangular diagram which is interesting in its own right (see Definition \ref{definition:loose}). In Theorem \ref{theorem:loose} we show that a loose rectangular diagram can be converted to an honest rectangular diagram without changing its arc index, the number of vertical segments. Since loose rectangular diagrams are more flexible, it helps us to estimate the arc index. In particular, loose rectangular diagram are useful for investigating the relations between the arc index and other link invariants, as our Theorem \ref{theorem:main} demonstrates.

\section{Loose rectangular diagram and arc index}

\subsection{Three views of arc index}
We quickly review three mutually related but slightly different expressions of knots and links that appear in the definition of the arc index.
The relations are summarized in Figure \ref{fig:arc-presentation}.

