\put(-55,0){$D_5$}
\put(-25,0){$D_6$}
\end{picture}
\end{center}
\caption{(i) Elementary $4$-crossing $(3,1)$-tangle and its elementary diagram (ii) Multi-crossing diagram in a sliced position (the height information of multi crossings are omitted). The slice $D_1,D_3,D_6$ are of type $0$.} 
\label{fig:slice-position}
\end{figure} 


Clearly, $D_1$ and $D_{c}$ must be of type $0$. We show that one can adjust the sliced position so that the other slices are not of type $0$.

\begin{proposition}(c.f. \cite[Theorem 1]{noy})
\label{prop:slice-reduced}
If a multi-crossing diagram $D$ is non-split, then it admits a sliced position such that its $i$-th slice $D_i$ is not of type $0$ for $i \neq 1,c_{tot}(D)$. 
\end{proposition}
\begin{proof}
Assume that the $i$-th slice $D_i$ is of type $0$, and that the elementary tangle $T$ in $D_i$ is a $(0,q)$-tangle for $i \neq 1, c_{tot}(D)$. The case where the elementary tangle is $(p,0)$-tangle case is similar.


We show that by suitably permuting the order of slices (i.e., swapping the $x$-coordinates of crossings), we are able to convert $D_i$ to a slice which is no longer of type $0$, without introducing any slices of type $0$. 

Since $i \neq 1$ and $D$ is non-split, the slice $D_i$ also contains at least one trivial $(1,1)$-tangle/ The non-split-ness of $D$ also implies that there is $i\leq j \leq c$ such that in the tangle diagram $D_{[i,j]}:=D_i \cup D_{i+1} \cup \cdots \cup D_{j}$, the connected component that contains $T$ also contains a trivial $(1,1)$-tangle $e$ in $D_{i}$. Among such $j$, we take the smallest one. 

By changing the order of slices (i.e. by pushing the crossing to the left-hand side if necessary), we may assume that in the tangle diagram $D_{[i,j]}$, the strand of the $(1,1)$-tangle $e$ does not encounter crossings until $D_{j}$ (see Figure \ref{fig:slice-position-reduced}).

Let $\overline{R}$ be a connected component of $([i,j] \times \R) \setminus D_{[i,j]}$ that contains both the $n$-crossing point of $D_i$ and the (1,1)-tangle $e$. We put $R = \overline{R} \cap [i+1,j] \times \R$.

Let $c_{1},\ldots, c_{m}$ be the crossing points that lies on $R$. 
We assume that $c_i$ lies in the slice $D_{k_i}$. We put $\{i,i+1,\ldots,j \} = \{k_1,k_2,\ldots,k_m,\ell_1,\ell_2,\ldots,\ell_{j-i-m}\}$, where
\[ k_1 < k_2 < \cdots< k_m=j, i= \ell_1<\ell_2 < \cdots < \ell_{j-i-m}. \]
Then we reorder the slices $D_{i},D_{i+1},\ldots,D_{j}$ as
\[ D_{k_{m}} < D_{k_{m-1}} < \cdots < D_{k_1} < D_{\ell_1} < \cdots  < D_{\ell_{j-i-m}}.\]
This operation removes type $0$ slice $D_i$ without introducing new type $0$ slices (see Figure \ref{fig:slice-position-reduced}). 


\begin{figure}[htbp]
\begin{center}
\includegraphics*[width=80mm]{slice-position-reduced.eps}
\begin{picture}(0,0)
\put(-210,242){$e$}
\put(-215,342){$T$}
\put(-150,250){\Large $R$}
\put(-20,285){contains}
\put(-22,275){ no crossings}
