\end{picture}
\end{center}
\caption{Removing type $0$ slices. We illustrate the effect of changing the $x$-coordinates by drawing how the line $x=a$ changes.} 
\label{fig:slice-position-reduced}
\end{figure} 
\end{proof}

%Thus we may assume that $T'$ is connected to the elementary in $D_i$. Since diagram is connected, by interchanging the $x$-coordinates of $D_i$ and $D_{i+1}$, the elementary tangles $T$ and $T'$ are changed to elementary tangles with type $(p,q)$ with $p,q \neq 0$. 
%Similarly, by pushing an elementary tangles of type $(0, 2n)$ so that its $x$-coordinates is as small as possible we remove all the elementary tangle of type $(0,2n)$ or $(2n,0)$ in the slices $D_{i}$ ($i=2,\ldots,c-1$)

% We call a sliced position in Proposition \ref{prop:slice-reduced} \emph{a reduced sliced position}.

Motivated by Proposition \ref{prop:slice-reduced}, we look at the complexity of basic buliding block of a sliced position, a slice which is not of type $0$.

\begin{definition}
\label{definition:constant}
For an elementary tangle $T$, we denote by $\alpha(T)$ the minimum number of vertical segment of its loose rectangular diagrams. We define
\[ u_n=\max \{\alpha(T)\: |\: T \mbox{ is an elementary }n\mbox{-crossing tangle which is not of type } 0\}\]
\end{definition}



\begin{example}[$u_2$ and $u_3$]
Since an elementary $2$-crossing $(1,1)$-tangle is trivial, to compute $u_2$, we need to consider $T_1,\ldots,T_6$ of elementary $2$-crossing tangles. By writing these tangles as a loose rectangular diagram, we confirm that $u_2=1$ (see Figure \ref{fig:u2}).

We remark that when we use usual rectangular diagram to represent the tangle $T_5,T_6$ then they require at least two vertical arcs. Thus it is crucial to use loose rectangular diagram to get a better (tight) bound. Also, it is clear that type $0$ elementary $2$-tangle $T$ requires at least two vertical arcs so it is again crucial to exclude type $0$ cases.

Similarly, although it is a bit cumbersome, one can check $u_3=2$ by checking all the possibilities. 
\end{example}

\begin{figure}[htbp]
\begin{center}
\includegraphics*[width=90mm]{u2.eps}
\begin{picture}(0,0)
\put(-275,135){$T_1$}
\put(-128,135){$T_2$}
\put(-275,75){$T_3$}
\put(-128,75){$T_4$}
\put(-275,15){$T_5$}
\put(-128,15){$T_6$}
\end{picture}
\end{center}
\caption{$u_2=1$. } 
\label{fig:u2}
\end{figure} 



\begin{proposition}
For $n>2$, $u_n \leq 2n-4$.
\end{proposition}
\begin{proof}
We prove the proposition by induction on $n$. We already mentioned that $u_3=2$.
To see general cases, we view general elementary $n$-crossing tangle $T$ is obtained by adding an elementary $(n-1)$-crossing tangle $T'$ by adding the topmost strand, and concatenating its endpoint if necessary.

When $T'$ is of type $0$, We get a loose rectangular of $T$ by adding a horizontal line to \a loose rectangular diagram of $T'$. An elementary $(n-1)$-crossing tangle $T'$ of type $0$ can be seen as a concatenation of the cap $\subset$ or $\supset$ (or, both) and an elementary $(n-1)$-crossing tangle $T''$ which is not type $0$.
Since caps $\subset$ and $\supset$ are written as a rectangular diagram having one vertical segment, it follows that $T'$, hence $T$, is represented by a loose rectangular diagram with at most $u_{n-1}+2 \leq 2n-4$ vertical arc segments.

Thus we assume that $T'$ is not of type $0$. Let $R'$ be a loose rectangular diagram of $T'$. Then we get a loose rectangular diagram $R$ of $T$ by putting the topmost arc so that it is away from the loose rectangular diagram $R'$ so that the added arc has at most two vertical segments. Thus $T$ is represented by a loose rectangular diagram having at most $u_{n-1}+2 \leq 2n-4$ vertical arc segments (see Figure \ref{fig:un})

\end{proof}
\begin{figure}[htbp]
\begin{center}
\includegraphics*[width=120mm]{un.eps}
\begin{picture}(0,0)
\put(-232,100){\large $R'$}
\put(-232,30){\large $R'$}
\put(-52,100){\large $R'$}
\put(-52,30){\large $R'$}
\end{picture}
\end{center}
\caption{The topmost strand (gray arc) can be added so that it is disjoint from a loose rentangular diagram $R'$ and that it has at most two vertical segments.} 
\label{fig:un}
\end{figure} 


%
%\begin{theorem}
%Let $L$ be a link represented by a connected multi-crossing diagram $D$.
%Then \[\alpha(L)-2 \leq c_2(D)+\sum_{n>2}(2n-4)c_n(D)\]
%\end{theorem}

\begin{proof}[Proof of Theorem \ref{theorem:main}]
By Proposition \ref{prop:slice-reduced} we put $D$ so that each slice $D_i$ is not of type $0$, except $D_1$ and $D_{c_{tot}(D)}$.
We view $D_1$ and $D_{c_{tot}(D)}$ as a concatenation of the caps $\subset$, $\supset$ and elementary tangles which are not of type $0$.

Since caps $\subset$ and $\supset$ are written as a rectangular diagram having one vertical segment, we conclude that $L$ is written as a loose rectangular diagram having at most $2+\sum_{n\geq 2}c_n(D)u_n$ vertical arcs. Therefore by Theorem \ref{theorem:loose}, $\alpha(L)-2 \leq c_2(D)+ \sum_{n>2}(2n-4)c_n(D)$.
\end{proof}


\begin{remark}
We noted that our argument can be seen as a generalization of arguments in \cite{noy} where they introduced a notion of bisected vertex labeling of plane graphs and gave a proof of the inequality $\alpha(L) \leq c(L)+2$. Our method to changing a loose rectangular diagram into an arc presentation appeared in \cite[Section 4]{noy} as a special case. Also, the notion of bisected labeling in \cite{noy} is essentially the same as a special position which we showed in Proposition \ref{prop:slice-reduced}.
\end{remark}





