\subsubsection{Pseudo-Dimension and the Proof of Theorem \ref{thm:util-learn-upper-bound}}
\label{sec:pseudodim}

To prove Theorem \ref{thm:util-learn-upper-bound}, we use a tool called \emph{pseudo-dimension} from stasitical learning theory (see, e.g., \citep{anthony2009neural}), which captures the complexity of a class of functions.  
% is a well known tool for upper bounding sample complexity , and has been applied to learning in mechanism design \citep{MR15, MR16, BSV18, BSV19}.

\begin{definition}
    \label{def:pseudo-dimension}
    Let $\funcClass$ be a class of real-valued functions on input space $\PinputSpace$. A set of inputs $\Pinputi[1], \ldots, \Pinputi[m]$ is said to be \emph{pseudo-shattered} if there exist \emph{witnesses} $\Pwitnessi[1], \ldots, \Pwitnessi[m] \in \mathbb R$ such that for any label vector $\Plabels\in\{1, -1\}^m$, there exists $\func_{\Plabels}\in \funcClass$ such that $\sgn(\func_{\Plabels}(\Pinputi) - \Pwitnessi)  = \Plabeli$ for each $i=1, \ldots, m$, where $\sgn(y)=1$ if $y>0$ and $-1$ if $y<0$. The \emph{pseudo-dimension} of $\funcClass$, $\Pdim(\funcClass)$, is the size of the largest set of inputs that can be pseudo-shattered by $\funcClass$. 
\end{definition}

\begin{definition}
	\label{def:uniform-convergence}
	For $\eps>0, \delta \in (0, 1)$, a class of functions $\funcClass: \PinputSpace \to \mathbb R$ is \emph{$(\eps, \delta)$-uniformly convergent with sample complexity $M$} if for any $\nsample \geq M$, for any distribution $\dist$ on~$\PinputSpace$, if $x^{(1)}, \ldots, x^{(\nsample)}$ are i.i.d.\@ samples from~$\dist$, with probability at least $1 - \delta$, for every $\func \in \funcClass$,
	$ \big| \Ex[\Pinput \sim \dist]{\func(\Pinput)} - \frac 1 {\nsample} \sum_{j = 1}^{\nsample} \func(x^{(j)}) \big| < \eps$. 
\end{definition}


\begin{theorem}[See, e.g., \citep{anthony2009neural}]
	\label{thm:pseudo-dimension}
	Let $\funcClass$ be a class of functions with range $[0, H]$ and pseudo-dimension $d = \Pdim(\funcClass)$, 
	for any $\eps>0$, $\delta\in(0, 1)$, 
	$\funcClass$ is $(\eps, \delta)$-uniformly convergent with sample complexity $O\left( \frac{H^2}{\eps^2} \big[d\log(\frac{H}{\eps}) + \log(\frac{1}{\delta})\big] \right)$.
	% That is, there is some $\nsample$ of this size, 
	% such that for any distribution $\dist$ on~$\PinputSpace$, 
	% if $\sample^1, \ldots, \sample^{\nsample}$ are i.i.d.\@ samples from~$\dist$, 
	% with probability at least $1 - \delta$, for every $\func \in \funcClass$,
	% \begin{align*}
	% 	\left| \Ex[\Pinput \sim \dist]{\func(\Pinput)} - \frac 1 {\nsample} \sum_{j = 1}^{\nsample} \func(\sample^j) \right| < \eps.
	% \end{align*}
% $\funcClass$ is $(\eps, \delta)$-uniformly convergent with sample complexity 
\end{theorem}

We prove Theorem~\ref{thm:util-learn-upper-bound} by treating the utilities on monotone bidding strategies as a class of functions, whose uniform convergence implies that $\emp$ learns the interim utilities.

% We relate our learning algorithm $\empp$ with uniform convergence on product distribution defined above, and use Corollary~\ref{cor:pseudo-dimension-product} to upper bound the sample complexity with which $\empp$ $(\eps, \delta)$-learns the utilities over all monotone strategies. 

For each bidder $i$, let $\func^{\vali, \strats}$ be the function that maps the opponents' values to bidder~$i$'s ex post utility: 
\begin{equation*}
    \func^{\vali, \strats}(\valsmi) = \expostUi(\vali, \strati(\vali), \stratsmi(\valsmi)).
\end{equation*}
Let $\funcClass_i$ be the set of all such functions corresponding to the set of monotone strategies, 
\begin{equation*}
    \funcClass_i = \big\{\func^{\vali, \strats }(\cdot) \given \vali \in \typespacei,~~ \strats \text{ is monotone} \big\}.
\end{equation*}
By Equation \eqref{eq:interim-util}, the expectation of $\func^{\vali, \strats}(\cdot)$ over~$\distsmi$ is the interim utility of bidder $i$: 
\begin{equation*}
    \Ex[\valsmi\sim \distsmi]{\func^{\vali, \strats}(\valsmi)} = \utili(\vali, \strati(\vali), \stratsmi).
\end{equation*}
% While according to \eqref{eq:def_empp}, 
By Definition~\ref{def:emp}, on samples $\mathcal S = \{ \vals^{(1)}, \ldots, \vals^{(\nsample)}\}$, $\emp(\mathcal S, i, \vali, \strats) = \frac 1 {\nsample} \sum_{j = 1}^{\nsample} \func^{\vali, \strats}(\vals^{(j)}_{-i})$. 
Thus, 
\begin{align}
  & \Big| \emp(\sampleSet, i, \vali, \strats) -  \utili(\vali, \strati(\vali), \stratsmi) \Big| \nonumber\\
 & = \left| \Ex[\valsmi\sim\distsmi]{\func^{\vali, \strats}(\valsmi)} - \frac 1 {\nsample} \sum_{j = 1}^{\nsample} \func^{\vali, \strats}(\vals^{(j)}_{-i})\right|.  \label{eq:emp-func}
\end{align}

The right hand side of~\eqref{eq:emp-func} is the difference between the expectation of $\func^{\vali, \strats}$ on the distribution $\distsmi$ and that on the empirical distribution with samples drawn from $\distsmi$.
% Comparing \eqref{eq:emp-func}, Definitions \ref{def:util-learn-ensemble} and 
Now by Theorem~\ref{thm:pseudo-dimension},
% \ref{def:uniform-convergence-product}, 
to bound the number of samples needed by $\emp$ to $(\eps, \delta)$-estimate the utilities over monotone strategies, 
it suffices to bound the pseudo-dimension of~$\funcClass_i$.
With the following key lemma, the proof of Theorem \ref{thm:util-learn-upper-bound} is completed by observing that the range of each $\func^{\vali, \strats}$ is within $[-H, H]$ and by taking a union bound over $i \in [n]$.

% if $\funcClass_i$ is $(\eps, \delta)$-uniformly convergent on product distribution $\distsmi$. 

% Then it suffices to upper bound the sample complexity with which $\funcClass_i$ uniformly converges. Consider the pseudo-dimension of $\funcClass_i$. 

\begin{lemma}
% \begin{lemma}
\label{lem:pseudo-dimension-utility-class}
$\Pdim(\funcClass_i) = O(n \log n)$.
% \end{lemma}
\end{lemma}
% The proof of Lemma~\ref{lem:pseudo-dimension-utility-class} makes crucial use of the monotonicity of bidding strategies,
% and follows a powerful framework for bounding pseudo-dimensions introduced by \citet{MR16} and \citet{BSV18}.  
% %It makes crucial use of the monotonicity of the bidding strategies.
% But existing techniques do not immediately apply here, due to the fact that bidding strategies, even when monotone, are infinite dimensional objects. Therefore we cannot easily make arguments on the geometry of the parameter space (cf.\@ the proof of Lemma~\ref{lem:pandora-pdim} which uses a more direct geometric argument \`a la \citealp{BSV18}).
% We give a proof here for the simplest case with two bidders and no-allocation tie-breaking rule, and relegate the full proof to Appendix~\ref{sec:proof-lem:pseudo-dimension-utility-class}. 

The proof of Lemma~\ref{lem:pseudo-dimension-utility-class} follows a powerful framework introduced by \citep{MR16} and \citep{BSV18} for bounding the pseudo-dimension of a class $\funcClass$ of functions: given inputs that are to be pseudo-shattered, fixing any witnesses, one classifies the functions in~$\funcClass$ into subclasses, such that the functions in the same subclass output the same label on all the inputs; by counting and bounding the number of subclasses, one can bound the number of shattered inputs.
Our proof follows this strategy.  To bound the number of subclasses, we make use of the monotonicity of bidding functions, which is specific to our problem.

\begin{proof}[Proof of Lemmea \ref{lem:pseudo-dimension-utility-class}]
By definition, given any $\vali$ and $\strats$ (with $\bidi = \strati(\vali)$), the output of $\func^{\vali, \strats}$ on input $\valsmi$ is
\begin{align*}
    \func^{\vali, \strats}(\valsmi) & = \vali \alloci(\bids) - \payi(\bids) \\
    & = \vali \alloci(\bids) - \alloci(\bids) f_i(b_i) - g_i(b_i) \\
    & = \big(\vali - f_i(b_i)\big) \alloci(\bids) - g_i(b_i). 
\end{align*}
Because the allocation $\alloci(\bids)$ is that the highest bidder wins with random tie breaking, $\func^{\vali, \strats}(\valsmi)$ must take one of the following $n+1$ values: 
\begin{align*}
    \vali - f_i(b_i) - g_i(b_i), ~ \tfrac{\vali - f_i(b_i)}{2} - g_i(b_i), ~ \ldots, ~ \tfrac{\vali - f_i(b_i)}{n}- g_i(b_i), ~ 0 - g_i(b_i).
\end{align*}
This value is fully determined by the $n-1$ comparisons $\bidi \lesseqqgtr \strati[j](\vali[j]^k)$, one for each $j\ne i$. 

Let $\valsmi^{(1)}, \ldots, \valsmi^{(m)}$ be any $m$ inputs. 
We argue that the function class $\funcClass_i$ can be divided into $O(\nsample^{2n})$ sub-classes $\{\funcClass_i^{\mathbf k }\}_{\mathbf k \in [m+1]^{2(n-1)}}$ 
%(where $\mathbf k \in \mathcal{K}$
such that each sub-class $\funcClass_i^{\mathbf k }$ generates at most $O(\nsample^n)$ different label vectors on the $m$ inputs. 
Thus $\funcClass_i$ generates at most $O(\nsample^{3n})$ label vectors in total. 
To pseudo-shatter $\nsample$~inputs, we need $O(\nsample^{3n})\ge 2^\nsample$, which implies $\nsample = O(n\log n)$. 

% We divide $\funcClass_i$ as follows. 
% Note that each $\Pinputs^k$ is a $(n-1)$ dimensional vector. 
We now define sub-classes $\{\funcClass_i^{\mathbf k}\}_{\mathbf k}$, each indexed by $\mathbf k \in [m + 1]^{2(n-1)}$.  
% Hypotheses in~$\funcClass_i$ are classified into the sub-classes as follows.
For each dimension $j \in [n]\setminus\{i\}$, we sort the $\nsample$ inputs by their $j^{\text{-th}}$ coordinates non-decreasingly, and use $\pi(j, \cdot)$ to denote the resulting permutation over $\{1, 2, \ldots, \nsample\}$: 
formally, $\vali[j]^{(\pi(j, 1))} \le \vali[j]^{(\pi(j, 2))}\le \cdots \le \vali[j]^{(\pi(j, \nsample))}$.
% where $\pi(j, \cdot)$ is a permutation over $\{1, 2, \ldots, \nsample\}$. 
For each function $\func^{\vali, \strats}(\cdot)$, for each $j$, 
we define two special positions: 
\begin{align*}
    & k_{j, 1} = \max \Big\{0, ~ \big \{k: \strati[j](\vali[j]^{(\pi(j, k))}) < \bidi \big\} \Big\}, \\
    & k_{j, 2}= \min \Big\{m + 1, ~ \big \{k: \strati[j](\vali[j]^{(\pi(j, k))}) > \bidi \big\} \Big\}.
\end{align*}
These two positions are well defined because $\strati[j](\cdot)$ is monotone. By definition, if $k_{j, 1} < k_{j, 2} - 1$, then for any $k$ such that $k_{j, 1} < k < k_{j, 2}$, we must have $\strati[j](\vali[j]^{(\pi(j, k))}) = \bidi$. 
We let a function $\func^{\vali, \strats}(\cdot)$ to belong to the sub-class $\funcClass_i^{\mathbf k }$ where the index $\mathbf k$ is $(k_{j, 1}, k_{j, 2})_{j\in[n]\backslash\{i\}}$.  
The number of sub-classes is the number of indices, which is bounded by $(m+1)^{2(n-1)}$.


We now show that the functions within a sub-class $\funcClass_i^{\mathbf k}$ give rise to at most $(m+1)^n$ label vectors on the $m$ inputs.
Let us focus on one such class with index~$\mathbf k$. 
%and therefore the index $\mathbf k$ is fixed.
% to $\sampleSetmi=(\Pinput^1\le \Pinput^2\le \cdots \le \Pinput^\nsample)$. 
On the $k^{\text{-th}}$ input~$\valsmi^{(k)}$, 
a function's membership in  
% $\func^{\vali, \bids(\cdot)}(\cdot)$ belongs to 
$\funcClass_i^{\mathbf k}$ suffices to specify whether bidder~$i$ is a winner on this input, and, if so, the number of other bidders winning at a tie.
Therefore, the class index~$\mathbf k$ determines a mapping $c: [m] \to \{0, 1, \ldots, n\}$, with $c(k) > 0$ meaning bidder~$i$ is a winner on input~$\valsmi^{(k)}$ at a tie with $c(k)-1$ other bidders, and $c(k) = 0$ meaning bidder~$i$ is a loser on input~$\valsmi^{(k)}$.  
Then, the output of a function $\func^{\vali, \strats}(\cdot) \in \funcClass_i^{\mathbf k}$ on input~$\valsmi^{(k)}$ is $\frac{\vali - f_i(b_i)}{c(k)} - g_i(b_i)$ if $c(k) > 0$ and $-g_i(b_i)$ otherwise.  
% A key observation is that 
The same utility is output on two inputs $\valsmi^{(k)}$ and~$\valsmi^{(k')}$ whenever $c(k) = c(k')$.
Consider the set~$S \subseteq [m]$ of inputs that are mapped to one integer by~$c$, and fix any $|S|$ witnesses. By varying the function in the subclass $\funcClass_i^{\mathbf k}$, we can generate at most $|S| + 1 \leq \nsample + 1$ patterns of labels on the input set $S$, because we are comparing the same utility with $|S|$ witnesses.
The label vector for the entire input set $[m]$ is the concatenation of these patterns of labels. Since the image of $c$ has $n+1$  integers, and there are at most $(\nsample+1)^n$ label vectors.

To conclude, the total number of label vectors generated by $\funcClass_i=\bigcup_{\mathbf k } \funcClass_i^{\mathbf k }$ is at most 
\[ (\nsample+1)^{2(n-1)} (\nsample+1)^{n+1} \le (\nsample+1)^{3n}. \]
To pseudo-shatter $\nsample$~inputs, we need $(\nsample+1)^{3n}\ge 2^\nsample$, which implies $\nsample=O(n\log n)$.
\end{proof}

\subsection{Lower Bound of Sample Complexity of Utility Estimation}
\label{FPA_sample:lower-bound}

We give an information-theoretic lower bound on the number of samples needed for any algorithm to estimate utilities over monotone strategies in a first-price auction. 
The lower bound matches our upper bound up to polylogarithmic factors.

\begin{theorem}
\label{thm:lower-bound-learning-util}
For any $\eps < \frac 1 {4000}, \delta < \frac 1 {20}$, 
there is a family of product value distributions for which no algorithm can $(\eps, \delta)$-estimate utilities over the set of all monotone bidding strategies with $m \leq \frac{1}{4\times10^8}\cdot \frac{n}{\eps^2}$ samples. 
\end{theorem}

The proof of Theorem~\ref{thm:lower-bound-learning-util} is in Appendix~\ref{sec:proof-thm:lower-bound-learning-utility}.  
As a sketch, the product value distributions we construct encode length $n-1$ binary strings by having a slightly unfair Bernoulli distribution for each bidder, the bias shrinking as $n$ grows large.
We then show that, if with a few samples a learning algorithm can estimate utilities for all monotone bidding strategies, then there must exist two product value distributions from the family that differ at only one coordinate, and yet they can be told apart by the learning algorithm. 
This must violate the well-known information-theoretic lower bound for distinguishing two distributions \citep{MansourNotes}.


\section{Sample Complexity of Learning BCE}
This section studies how to learn BCEs using samples from the value distribution $\dists$. 

\subsection{Estimating Utility by Empirical Product Distributions}
\label{sec:empp}
Section \ref{FPA_sample:fpa-upper-bound} shows that the empirical distribution estimator approximates interim utilities with high probability.  However, this does not immediately imply that the auction on the empirical distribution is a close approximation to the auction on the original distribution $\dists$. 
This is because the empirical distribution over samples is \emph{correlated} --- the values $\vals^{(j)} = (\vali[1]^{(j)}, \ldots, \vali[n]^{(j)})$ are drawn as a vector, instead of independently. 
% Standard notions defined on product distributions, such as Bayes Nash equilibria, become intricate on correlated distributions, and there is no reason to expect the latter to correspond to the equilibria in the original auction.
The equilibria (either BCE or BNE) with respect to this correlated empirical distribution do not correspond to the equilibria on the original product distribution $\dists$. 
Therefore, it is desirable that utilities can also be estimated on a \emph{product} distribution arising from the samples, where each bidder's value is independently drawn, uniformly from the $\nsample$ samples of her value.  
We show that this can indeed be done, without a substantial increase in the sample complexity.
The key technical step, Lemma~\ref{lem:relation-uniform-convergence},
is a reduction from learning on empirical distribution to learning on empirical product distribution.  We believe this lemma is of independent interest.
In fact, the preliminary version of our work \citep{fu_learning_2020} uses Lemma~\ref{lem:relation-uniform-convergence} to derive the sample complexity for another problem (Pandora's Box problem).
% {\color{blue} [Tao: I want to say a sentence like that.  But we cannot cite our work directly due to anonymous submission requirement.]}

% ; the reduction is crucial there for obtaining a polynomial-time learning algorithm.

% The key technical step, Lemma~\ref{lem:relation-uniform-convergence},
% is closely related to a concentration inequality by \citet{DHP16}.  
% We believe our lemma comes more handy for applications such as ours.
% The reduction from learning on such an empirical product distribution to learning on the empirical distribution may be of independent interest.
% In fact, in Section~\ref{sec:search} we invoke Lemma~\ref{lem:relation-uniform-convergence} in a different context, that of learning in Pandora's Box problem; the reduction is crucial there for obtaining a polynomial-time learning algorithm.

% We also show that the utilities can be estimated on a most natural \emph{product} distribution given by the samples.
\begin{definition}
\label{def:empp}
Given samples $\bm x^{(1)}, \ldots, \bm x^{(\nsample)}$ from a product distribution $\dists = \prod_{i=1}^n \disti$,  
let $\empDisti$ be the uniform distribution over $\{x_i^{(1)}, \ldots, x_i^{(\nsample)}\}$. The \emph{empirical product distribution} is the product distribution
%\begin{equation}\label{eq:empirical-product}
    $\empDists = \prod_{i=1}^n \empDisti$.
% \end{equation}
% and $\empDistsmi:=\prod_{k\ne i}\empDisti[k].$
% We call $\empDists$ the \emph{empirical product distribution} and define the \emph{empirical-product-distribution estimator}, denoted by $\empp$, as follows: 
\end{definition}

\begin{definition}
\label{def:uniform-convergence-product}
    For $\eps>0, \delta \in (0, 1)$, a class of functions $\funcClass: \prod_{i=1}^n \typespacei \to \mathbb R$ is \emph{$(\eps, \delta)$-uniformly convergent on product distribution with sample complexity $M$} if for any $\nsample \geq M$, for any product distribution $\dists$ on~$\prod_{i=1}^n \typespacei$, 
    if $\bm x^{(1)}, \ldots, \bm x^{(\nsample)}$ are i.i.d.\@ samples from~$\dists$, 
    with probability at least $1 - \delta$, for every $\func \in \funcClass$,
    \begin{equation*}
		\big| \Ex[\bm x \sim \dists]{\func(\bm x)} - \Ex[\bm x \sim \empDists]{\func(\bm x)} \big| ~ < ~ \eps,
    \end{equation*}
    where $\empDists = \prod_{i=1}^n \empDisti$ is the empirical product distribution. %(Definition~\ref{def:empp}).
\end{definition}

\begin{lemma}
\label{lem:relation-uniform-convergence}
Let $\funcClass$ be a class of functions from a product space $\typespaces = \prod_{i=1}^n T_i$ to $[0, H]$. 
If $\funcClass$ is $(\eps, \delta)$-uniformly convergent with sample complexity $\nsample(\eps, \delta)$, then $\funcClass$ is $\left(2\eps, \frac{H\delta}{\eps}\right)$-uniformly convergent on product distribution with sample complexity $\nsample(\eps, \delta)$. 
In other words, $\funcClass$ is $(\eps', \delta')$-uniformly convergent with sample complexity $\nsample(\frac{\eps'}{2}, \frac{\delta'\eps'}{2H})$.
\end{lemma}
\noindent Lemma~\ref{lem:relation-uniform-convergence} is closely related to a concentration inequality by \citep{DHP16}, who show that for any \emph{single} function $h:\typespaces\to[0, H]$, the expectation of $h$ on the empirical product distribution $\empDists$ is close to its expectation on the original distribution $\dists$ with high probability.
Our lemma generalizes \citep{DHP16} to the simultaneous concentration for a family of functions,   
and seems more handy for applications such as ours.

\begin{proof}[Proof of Lemma \ref{lem:relation-uniform-convergence}]
Write the $m$ samples $\sampleSet = \{\bm x^{1}, \ldots, \bm x^{m}\}$ from $\dists$ as an $\nsample \times n$ matrix $(x_i^{j})$, where each row $j\in[\nsample]$ represents a sample $\bm x^{j}$, and each column~$i\in[n]$ consists of the $m$ values sampled from~$\disti$. 
Then, we draw $n$ permutations $\pi_1, ..., \pi_n$ of $[\nsample]=\{1, \ldots, \nsample\}$ independently and uniformly at random, and permute the $\nsample$ elements in column~$i$ by~$\pi_i$. 
Regard each new row $j$ as a new sample, denoted by $\permSamples^{j} = (\samplei[1]^{\pi_1(j)}, \samplei[2]^{\pi_2(j)}, ..., \samplei[n]^{\pi_n(j)})$. 
% We argue that, 
Given $\pi_1, \ldots, \pi_n$, the ``permuted samples'' $\{\permSamples^{1}, \ldots, \permSamples^{m}\}$ have the same distributions as $\nsample$ i.i.d.\@ random draws from~$\dists$. 
% This is because any two $\permSamples^j$ and $\permSamples^{j'}$ do not overlap, i.e., do not contain a same value sample $\samplei^j$.

For $\func \in \funcClass$, let $p_\func = \Ex[\samples \sim\dists]{h(\samples )}$. 
By the definition of $(\eps, \delta)$-uniform convergence (not on product distribution),
\begin{equation}\label{eq:samples_pi}
\Prx[\sampleSet, \pi]{\exists \func \in \funcClass,\ \Big| p_\func - \frac{1}{\nsample }\sum_{j=1}^{\nsample} \func(\permSamples^j) \Big|\ge\eps} \le \delta.
\end{equation}

For a set of fixed samples $\sampleSet = (\samples^1, \ldots, \samples^\nsample)$, recall that $\empDisti[i]$ is the uniform distribution over $\{\samplei[i]^{1}, \ldots, \samplei[i]^{\nsample}\}$, and $\empDists = \prod_{i=1}^n \empDisti[i]$. 
We show that the expected 
value of $\func$ on $\empDists$ satisfies $\Ex[\samples\sim\empDists]{\func(\samples)} = \Ex[\pi]{\frac{1}{\nsample}\sum_{j=1}^\nsample \func(\permSamples^j)}$. This is because
\begin{align*}
    & \Ex[\pi]{\frac{1}{\nsample}\sum_{i=1}^\nsample \func(\permSamples^j)}
    = \frac{1}{\nsample} \sum_{j=1}^{\nsample} \Ex[\pi]{\func(\permSamples^j)} \\
    & = \frac{1}{\nsample}\sum_{j=1}^\nsample \sum_{(k_1, \ldots, k_n)\in[\nsample]^n} \func(\samplei[1]^{k_1}, \ldots, \samplei[n]^{k_n}) \\
    & \quad \cdot \Prx[\pi]{\pi_1(j)=k_1, \ldots, \pi_n(j)=k_n}  \\
    & =\frac{1}{\nsample}\sum_{j=1}^\nsample \sum_{(k_1, \ldots, k_n)\in[\nsample]^n} \func(\samplei[1]^{k_1}, \ldots, \samplei[n]^{k_n})\cdot \frac{1}{\nsample^n}\\
    & = \frac{1}{\nsample^n} \sum_{(k_1, \ldots, k_n)\in[\nsample]^n} \func(\samplei[1]^{k_1}, \ldots, \samplei[n]^{k_n}) \\
    & =\Ex[\samples \sim \empDists]{\func(\samples)}.
\end{align*}

Thus,   
\begin{align*}
     & \big| p_\func - \Ex[\samples\sim\empDists]{\func(\samples)}\big| \\
     & = \left| p_\func - \Ex[\pi]{\frac{1}{\nsample}\sum_{j=1}^\nsample \func(\permSamples^j)} \right| \\
    & \le \Ex[\pi]{ \Big| p_\func - \frac{1}{\nsample}\sum_{j=1}^\nsample \func(\permSamples^j) \Big|}\\
    & \le \Prx[\pi]{ \Big| p_\func - \frac{1}{\nsample}\sum_{j=1}^\nsample \func(\permSamples^j) \Big|\ge \eps}\cdot H \\
    & \hspace{1.5em} + \left(1-\Prx[\pi]{\Big| p_\func - \frac{1}{\nsample}\sum_{j=1}^\nsample \func(\permSamples^j) \Big|\ge \eps}\right)\cdot\eps \\
    & \le \Prx[\pi]{\mathrm{Bad}(\func, \pi, \sampleSet)}\cdot H + \eps, 
\end{align*}
where we define event
\[ \mathrm{Bad}(\func, \pi, \sampleSet) = \mathbb{I}\left[\Big| p_\func - \frac{1}{\nsample}\sum_{j=1}^\nsample \func(\permSamples^j) \Big|\ge \eps\right].\]
We note that, whenever $\big| p_\func - \Ex[\vals\sim\empDists]{\func(\vals)}\big| \ge 2\eps$, we have $\Prx[\pi]{\mathrm{Bad}(\func, \pi, \sampleSet)}\ge \frac{\eps}{H}$.

Finally, consider the random draw of samples $\sampleSet\sim\dists$, 
\begin{align*}
     & \Prx[\sampleSet]{\vphantom{\Big|} \exists \func\in \funcClass, \ \big| p_\func - \Ex[\vals \sim \empDists]{\func(\vals)} \big|\ge 2\eps} 
    \\
    & \le \Prx[\sampleSet]{\exists \func \in \funcClass, \ \Prx[\pi]{\mathrm{Bad}(\func, \pi, \sampleSet)}\ge \frac{\eps}{H} } 
    \\
    % \shortintertext{\hfill Choose $h$ to be an $\func^*$ s.t.~$\Prx[\pi]{\mathrm{Bad}(\func^*, \pi, \sampleSet)}\ge \frac{\eps}{H}$}
    & \le \Prx[\sampleSet]{\Prx[\pi]{\exists \func \in \funcClass, \ \mathrm{Bad}(\func, \pi, \sampleSet)\text{ holds} } \ge \frac{\eps}{H}} \\
    & \le  \frac{H}{\eps}\Ex[\sampleSet]{\vphantom{\Big|}\Prx[\pi]{\exists \func \in \funcClass, \ \mathrm{Bad}(\func, \pi, \sampleSet)\text{ holds} }  } && \text{by Markov inequality} \\
    &  = \frac{H}{\eps}\Prx[\sampleSet, \pi]{ \vphantom{\Big|} \exists \func \in \funcClass, \ \mathrm{Bad}(\func, \pi, \sampleSet)\text{ holds} } \\
     & \le \frac{H\delta}{\eps} && \text{by \eqref{eq:samples_pi}}. 
\end{align*}
\end{proof}


Combining Theorem~\ref{thm:util-learn-upper-bound} with Lemma~\ref{lem:relation-uniform-convergence}, we derive a result of utility estimation by empirical product distribution.

\begin{definition}
The \emph{empirical product distribution estimator} $\empp$ estimates interim utilities of a bidding strategy on the empirical product distribution~$\empDists = \prod_{i=1}^n \empDisti$.  Formally, 
for bidder~$i$ with value~$\vali$, for bidding strategy profile $\strats$, $\empp(\sampleSet, i, \vali, \strats) := 
\Ex[\valsmi\sim \empDistsmi] { \expostUi(\vali, \strati(\vali), \stratsmi(\valsmi)) }$. 
\end{definition}

\begin{theorem}
[Utility estimation by empirical product distribution]
\label{thm:util-learn-upper-bound-product}
Suppose $\typespacei\subseteq[0, H]$.
Let $\dists$ be a product distribution on $\prod_{i=1}^n \typespacei$. 
% The empirical-product-distribution estimator 
For any $\eps>0, \delta \in (0, 1)$, there is
\begin{equation}
M = O \left(\frac{H^2}{\eps^2} \left[n\log n\log \left(\frac{H}{\eps} \right) + \log\left(\frac{n}{\delta}\right)\right]\right),
\label{eq:util-learn-upper-bound-product}
\end{equation}
such that for any $\nsample \geq M$, 
% both $\emp$ and $\empp$ 
the empirical product distribution estimator $\empp$ $(\eps, \delta)$-estimates with $\nsample$ samples
% with $\nsample$ samples 
the utilities over the set of all monotone bidding strategies.
\end{theorem}

% Before proving Theorem~\ref{thm:util-learn-upper-bound-product}, we derive an important consequence. This theorem implies that the interim utilities of any monotone strategy can be preserved after each bidder's distribution is replaced by samples, and hence the set of monotone strategies that are $\eps$-BNE of the original first-price auction corresponds to the set of monotone strategies that are $\Theta(\eps)$-BNE on the empirical product distribution.

\subsection{Learning Equilibrium from Samples}
We are now ready to present our results for learning equilibria (BCE and BNE) using samples from the value distribution $\dists$. 
By Theorem~\ref{thm:util-learn-upper-bound-product}, utilities of the bidders on $\dists$ can be approximated by the utilities on the empirical product distribution $\empDists$, therefore the auctions on the two distributions share the same set of approximate equilibria:

\begin{theorem}\label{theorem:find-BCE}
Suppose $\typespacei\subseteq[0, H]$ and $\dists$ is a product distribution on $\prod_{i=1}^n \typespacei$. 
For any $\eps, \eps'>0, \delta \in (0, 1)$,
% For sufficiently large $\nsample$ (as in Theorem~\ref{thm:util-learn-upper-bound}), 
by drawing $m \ge \eqref{eq:util-learn-upper-bound-product}$ samples from $\dists$, with probability at least $1-\delta$, we have: 
Any monotone $\eps'$-BCE $Q$ on the empirical product distribution $\empDists = \prod_{i=1}^n \empDisti$ is a monotone $(\eps' + 2\eps)$-BCE on $\dists$.
Conversely, any monotone $\eps'$-BCE $Q$ on $\dists$  is a monotone $(\eps' + 2\eps)$-BCE on $\empDists$. 
Formally: $\mathrm{BCE}(\empDists, \eps') \subseteq \mathrm{BCE}(\dists, \eps'+2\eps)\,$ and $\,\mathrm{BCE}(\dists, \eps') \subseteq \mathrm{BCE}(\empDists, \eps'+2\eps)$. 
\end{theorem}

\begin{proof}
We will prove $\mathrm{BCE}(\empDists, \eps') \subseteq \mathrm{BCE}(\dists, \eps'+2\eps)$. The other direction is analogous. 
According to Theorem \ref{thm:util-learn-upper-bound-product}, for any bidder $i$ with value $\vali$ and bid $\bidi$, for any monotone strategies $\stratsmi$ of other bidders, bidder $i$'s interim utilities on distributions $\dists$ and $\empDists$ satisfy: 
\begin{equation}
    \label{eq:utility-preserve-product}
    \bigg| \E_{\valsmi \sim \distsmi}\Big[ \expostUi(\vali, \bidi, \stratsmi(\valsmi))\Big] - \E_{\valsmi \sim \empDistsmi} \Big[ \expostUi(\vali, \bidi, \stratsmi(\valsmi))\Big] \bigg| ~ \le ~ \eps. 
\end{equation}
Let $Q$ be any monotone $\eps'$-BNE $Q$ on $\empDists$. By Definition \ref{def:bce}, bidder $i$'s utility gain by deviating according to deviation function $\phi_i$ satisfies 
\begin{align*}
    \E_{\strats \sim Q} \bigg[ \E_{\valsmi \sim \empDistsmi} \Big[ \expostUi(\vali, \phi_i(\strati, \vali), \stratsmi(\valsmi)) - \expostUi(\vali, \strati(\vali), \stratsmi(\valsmi)) \Big] \bigg] ~ \le ~ \eps'. 
\end{align*}
Applying \eqref{eq:utility-preserve-product} to above, we obtain 
\begin{align*}
    \E_{\strats \sim Q} \bigg[ \E_{\valsmi \sim \distsmi} \Big[ \expostUi(\vali, \phi_i(\strati, \vali), \stratsmi(\valsmi)) - \expostUi(\vali, \strati(\vali), \stratsmi(\valsmi)) \Big] \bigg] ~ \le ~ \eps' + 2\eps, 
\end{align*}
which implies that $Q$ is an $(\eps' + 2\eps)$-BCE on $\dists$. 
\end{proof}

An implication of Theorem~\ref{theorem:find-BCE} is the following: if a mediator wants to coordinate the bidders in a non-truthful auction (such as first-price auction) but does not know the bidders' value distribution, the mediator can still achieve that by computing an approximate correlated equilibrium for the bidders using samples from the distribution.  Theorem~\ref{theorem:find-BCE} characterizes the number of samples needed. 

A similar conclusion also holds for BNEs: 
\begin{theorem}\label{theorem:find-BNE}
Under the same condition as Theorem~\ref{theorem:find-BCE}, 
$\mathrm{BNE}(\empDists, \eps') \subseteq \mathrm{BNE}(\dists, \eps'+2\eps)\,$ and $\,\mathrm{BNE}(\dists, \eps') \subseteq \mathrm{BNE}(\empDists, \eps'+2\eps)$.
\end{theorem}

% Corollary~\ref{cor:find-BNE} has an interesting consequence.  
% \citet{wang_bayesian_2020} gave a polynomial-time algorithm for computing Bayes Nash equilibrium in first-price auctions on discrete value distributions. 
% The empirical product distribution is discrete, so one can run \citeauthor{wang_bayesian_2020}'s algorithm on it.
% Corollary~\ref{cor:find-BNE} immediately implies:
% \begin{corollary}
% \label{cor:polytime-equilibria}
% There is a Monte Carlo randomized algorithm for computing an $\eps$-BNE in a first-price auction with $n$ bidders on arbitrary product value distributions.  
% The running time of the algorithm is polynomial in $n$ and~$\frac 1 {\eps}$.  
% \end{corollary}

% Note that the running time of the algorithm does not depend on the size of the distributions' support, and works for continuous distributions as well.

Given some recent progress on the computation of BNE in first-price auctions on \emph{discrete} distributions \citep{wang_bayesian_2020, chen_complexity_2023}, %\endnote{In particular, \citep{wang_bayesian_2020} give an ``algorithm'' that outputs a strategy profile that approaches a BNE in a first-price auction on discrete distribution if the algorithm runs for infinite time.  It is unclear whether their algorithm can output an $\eps$-BNE if run for finite time.},
we present an interesting corollary of Theorem~\ref{theorem:find-BNE}: if there exists an algorithm that can compute BNE for a first-price auction on discrete value distributions, then there also exists an algorithm that can compute approximate BNE on \emph{any} distributions, by simply sampling from the distribution and running the former algorithm on the empirical product distribution (which is discrete). 
\begin{corollary}
\label{cor:polytime-equilibria}
If there exists an algorithm that computes monotone $\eps'$-BNE for the first-price auction on any discrete product value distributions $\bm{D} = \prod_{i=1}^n D_i$, then there exists a sample-access algorithm that computes $(\eps'+\eps)$-BNE for the first-price auction on any product distributions $\bm F = \prod_{i=1}^n F_i$ with high probability.
If the running time of the former algorithm is polynomial in $\frac{1}{\eps'}$ and the support size of each discrete $D_i$, then the running time of the latter algorithm is $\mathrm{poly}(\frac{1}{\eps}, \frac{1}{\eps'})$, which does not depend on the support size of $F_i$ (and $F_i$ can be continuous). 
\end{corollary}



\section{Discussion}
In this work, we obtained the first sample complexity result for learning strategic form Bayesian correlated equilibria in non-truthful auctions such as first-price and all-pay auctions. En route, we showed that bidders' expected utilities can be estimated using a moderate amount of value samples for all monotone bidding strategies. 
Our work can be a starting point for several future research directions:
\begin{itemize}
\item{\it Other types of BCE.}
The learnability of strategic form BCE in non-truthful auctions relies on its simple form: recommending monotone joint bidding strategies to bidders without eliciting bidders' values.  Other types of BCEs, such as a communication equilibrium which includes an elicitation phase and a recommendation phase \citep{myerson_optimal_1982, forges_correlated_2006}, need not have a monotone structure, and we do not know whether they are efficiently learnable. 

\item{\it Correlated value distribution.}
Our results also depend on bidders' values being drawn independently.  
With correlated values, the conditional distribution of opponents' values changes with a bidder's own value, and any na\"ive utility estimation algorithm needs a number of samples that grows linearly with the size of a bidder's value space.
It is interesting whether there are meaningful tractable middle grounds between independent distributions and arbitrary correlated distributions.

\item{\it Multi-item auctions and general games.}
Monotonicity is a natural assumption on bidding strategies in a single-item auction, but it does not generalize to multi-parameter settings, where equilibria are difficult to characterize.
It is an interesting question whether our results can be generalized to multi-item auctions, such as simultaneous first-price auctions, via more general, lossless structural assumptions on the bidding strategies. 
One can ask an even more general question: when can BCE be learned from type samples in general incomplete-information games? 
\end{itemize}


