\section{Proof of Theorem \ref{thm:lower-bound-learning-util}}
\label{sec:proof-thm:lower-bound-learning-utility}
%\authcom{This proof may go to the supplementary file.}
Fixing $\eps > 0$, fixing $\distconst = 2000$, we first define two value distributions.
Let $\posdist$ be a distribution supported on $\{0, 1\}$, and for $\val \sim \posdist$, $\Prx{\val = 0} = 1 - \frac{1 + \distconst \eps}{n}$, and $\Prx{\val = 1} = \frac{1 + \distconst \eps}{n}$.  
Similarly define $\negdist$: for $\val \sim \negdist$, $\Prx{\val = 0} = 1 - \frac{1 - \distconst \eps}{n}$, and $\Prx{\val = 1} = \frac{1 - \distconst \eps}{n}$.   

Let $\kl(\posdist; \negdist)$ denote the KL-divergence between the two distributions.
\begin{claim}
\label{cl:lb-kl}
$\kl(\posdist; \negdist)= O(\frac {\eps^2}{n})$.
\end{claim}
\begin{proof}
% Let $\neutdist$ be the distribution such that $\Prx[\val \sim \neutdist]{\val = 0} = 1 - \frac 1 n$ annd $\Prx[\val \sim \neutdist]{\val = 1} = \frac 1 n$.  
By definition,
\begin{align*}
     \kl(\posdist; \negdist) 
    ={}& \frac{1 + \distconst\eps}{n} \ln \left( \frac{1 + \distconst\eps}{1 - \distconst\eps} \right) 
      + \frac{n - 1 - \distconst \eps}{n} \ln \left(\frac{n - 1 - \distconst \eps}{n - 1 +\distconst \eps}\right) \\
   ={}& \frac 1n  \ln \left( \frac {1 + \distconst\eps}{1 - \distconst \eps} \cdot \frac{(1 - \frac{\distconst \eps}{n - 1})^{n-1}}{(1 + \frac{\distconst \eps}{n-1})^{n-1}}
   \right)
   + \frac {\distconst \eps}{n} \ln \left(\frac{1 + \distconst \eps}{1 - \distconst \eps} \cdot 
   \frac{1 + \frac{\distconst \eps}{n-1}}{1 - \frac{\distconst \eps}{n-1}}\right) \\
   \leq{}& \frac 1n  \ln \left(  \frac {1 + \distconst\eps}{1 - \distconst \eps} \cdot \frac{\left(1 - \frac{\distconst \eps}{n - 1}\right)^{n-1}}{1 + \distconst \eps} \right)
    + \frac {2\distconst \eps}{n} \ln \left(1 + \frac{2\distconst \eps}{1 - \distconst \eps} \right)
\\
   \leq{}& \frac 1 n \ln \left( 
   \frac{1 - \distconst \eps + \frac 1 2 (\distconst \eps)^2}{1 - \distconst \eps}
   \right) + \frac{8\distconst^2 \eps^2}{n} \\
   \leq{}& \frac{10\distconst^2 \eps^2}{n}.
\end{align*}
In the last two inequalities we used $\distconst \eps < \frac 1 2$ and $\ln (1+x) \leq 1+x$ for all $x > 0$.
\end{proof}

It is well known that an upper bound on KL-divergence implies an information-theoretic lower bound on the number of samples to distinguish two distributions (e.g., \citep{MansourNotes}).
\begin{corollary}
\label{cor:lb-kl-single}
Given $t$ i.i.d.\@ samples from $\posdist$ or~$\negdist$, if $t \leq \frac{n}{80\distconst^2 \eps^2}$, no algorithm~$\diffalg$ that maps samples to $\{\posdist, \negdist\}$ can do the following: when the samples are from~$\posdist$, $\diffalg$ outputs~$\posdist$ with probability at least $\frac 2 3$, and if the samples are from~$\negdist$, $\diffalg$ outputs~$\negdist$ with probability at least~$\frac 2 3$.  
\end{corollary}

We now construct product distributions using $\posdist$ and~$\negdist$.  
For any $S \subseteq [n - 1]$, define product distribution $\dists_S$ to be $\prod_i \disti$ where $\disti = \posdist$ if $i \in S$, and $\disti = \negdist$ if $i \in [n-1] \setminus S$, and $F_n$ is a point mass on value~$1$.
For any $j \in [n - 1]$ and $S \subseteq [n - 1]$, distinguishing $\dists_{S \cup \{j\}}$ and $\dists_{S \setminus \{j\}}$ by samples from the product distribution is no easier than distinguishing $\posdist$ and $\negdist$, because the coordinates of the samples not from $\disti[j]$ contains no information about~$\disti[j]$.  

\begin{corollary}
\label{cor:lb-kl}
For any $j \in [n - 1]$ and $S \subseteq [n - 1]$, given $t$ i.i.d.\@ samples from $\dists_{S \cup \{j\}}$ or $\dists_{S \setminus \{j\}}$, if $t \leq \frac n {80 \distconst^2 \eps^2}$, no algorithm~$\diffalg$ can do the following: when the samples are from $\dists_{S \cup \{j\}}$, $\diffalg$ outputs~$\dists_{S \cup \{j\}}$ with probability at least $\frac 2 3$, and when the samples are from $\dists_{S \setminus \{j\}}$, $\diffalg$ outputs~$\dists_{S \setminus \{j\}}$ with probability at least~$\frac 2 3$.
% , correctly with probability at least $\frac 2 3$, the distribution from which the samples are drawn, 
\end{corollary}

We now use Corollary~\ref{cor:lb-kl} to derive an information-theoretic lower bound on estimating utilities for monotone bidding strategies, for distributions in $\{\dists_S\}_{S \subseteq [n]}$.

\begin{proof}[Proof of Theorem~\ref{thm:lower-bound-learning-util}]
Without loss of generality, assume $n$ is odd.  
Let $S$ be an arbitrary subset of~$[n - 1]$ of size either $\lfloor n/2 \rfloor$ or $\lceil n/ 2 \rceil$.
We focus on the interim utility of bidder~$n$ with value~$1$ and bidding $\frac 1 2$.  
Denote this bidding strategy by~$\strati[n]$.
The other bidders may adopt one of two bidding strategies.
One of them is $\posbid$: $\posbid(0) = 0$ and $\posbid(1) = \frac 1 2 + \eta$ for sufficiently small $\eta > 0$.  
The other bidding strategy $\negbid(\cdot)$ maps all values to~$0$.
For $T \subseteq [n-1]$, let $\strats_T$ be the profile of bidding strategies where $\strati = \posbid$ for bidder $i \in T$, and $\strati = \negbid$ for bidder $i \in [n-1] \setminus T$.  


For the distribution $\dists_S$, the interim utility of bidder $n$ is 
\begin{align*}
     & \utili[n]\left(1, \frac 1 2, \strats_T\right) 
    \frac 1 2  \Prx{\max_{i \in T} \vali = 0} \\
    & =  \frac 1 2 
    \left(1 - 
    \frac{1 + \distconst \eps}{n}
    \right)^{|S \cap T|}
    \left(1 - 
    \frac{1 - \distconst \eps}{n}
    \right)^{|T\setminus S|}
    \\
    & = \frac 1 2
    \left(
    1 - \frac{1 + \distconst \eps}{n}
    \right)^{|T|}
    \left(
    \frac{n - 1 + \distconst \eps}{n - 1 - \distconst \eps}
    \right)^{|T \setminus S|}.
\end{align*}
Therefore, for $T, T' \subseteq [n-1]$ with $|T| = |T'| $,
\begin{align*}
     \frac{\utili[n](1, \frac 1 2, \strats_T)}{\utili[n](1, \frac 1 2, \strats_{T'})} ={}& \left(
    1 + \frac{2\distconst \eps / (n-1)}{1 - \frac{\distconst \eps}{n-1}} 
    \right)^{|T\setminus S| - |T' \setminus S|} \\
     \geq{}& 1 + \frac{2\distconst \eps}{n-1} \cdot (|T \setminus S| - |T' \setminus S|);
\end{align*}
Suppose $|T \setminus S| \geq |T' \setminus S|$ and $|T| = |T'| \geq \lfloor \frac n 2 \rfloor$, then
\begin{align}
 & \utili[n]\left(1, \frac 1 2, \strats_T\right) - \utili[n]\left(1, \frac 1 2, \strats_{T'}\right) \\
 & \ge (|T \setminus S| - |T' \setminus S|) \cdot \frac {2\distconst \eps}{n-1} \cdot \utili[n]\left(1, \frac 1 2, \strats_{T'} \right) 
\notag \\
 & \geq (|T \setminus S| - |T' \setminus S|) \cdot \frac {2\distconst \eps}{n-1} \cdot \frac 1 {8 e^2}, 
 \label{eq:util-diff-eps}
\end{align}
where the last inequality is because $\utili[n](1, \frac 1 2, \strats_{T'}) \ge \frac{1}{2} (1 - \frac{2}{n})^n = \frac{1}{2} [(1 - \frac{2}{n})^\frac{n}{2}]^2\ge \frac{1}{2}  (\frac{1}{2e})^2 = \frac{1}{8e^2}$. 

Now suppose an algorithm~$\alg$ $(\eps, \delta)$-estimates the utilities of all monotone bidding strategies with $t \leq \frac{n}{80\distconst^2 \eps^2}$ samples~$\mathcal S$.
% = (\sampleSet^1, \ldots, \sampleSet^t)$, where $t \leq $, for all monotone bidding strategies.  
Define $\diffalg: \mathbb R_+^{n \times t} \times \mathbb N \to 2^{[n-1]}$ be a function that outputs, among all $T\subseteq [n-1]$ of size~$k$, the one that maximizes bidder~$n$'s utility when other bidders bid according to strategy $\strats_T$.  
Formally, 
\begin{align*}
    \diffalg(\sampleSet, k) = \argmax_{T \subseteq [n-1], |T| = k} \alg\left(\sampleSet, n, 1, (\strats_{T}, \strati[n]) \right),
\end{align*}
% where $(\bids_T(\cdot), \frac 12)$ denotes the bidding strategy profile in which the first $n-1$ bidders bid according to $\bids_T(\cdot)$ and bidder~$n$ maps her value (of~$1$) to bid~$\frac 1 2$.  

By Definition~\ref{def:util-learn-ensemble}, for any $S$ with $|S| = \lfloor n / 2 \rfloor$, for samples drawn from~$\dists_S$, with probability at least $1 - \delta$,
\begin{equation*}
    \alg(\sampleSet, n, 1, (\strats_{[n-1]\setminus S}, \strati[n]) ) \\
    \geq \utili[n]\left(1, \frac 1 2, \strats_{[n-1] \setminus S} \right) - \eps;
\end{equation*}
and for any $T \subseteq[n-1]$ with $|T| = \lceil n / 2 \rceil$,
\begin{equation*}
    \alg(\sampleSet, n, 1, (\strats_T, \strati[n]) )
    \leq \utili[n]\left(1, \frac 1 2, \strats_T \right) + \eps.
\end{equation*}
Therefore, for $W = \diffalg(\sampleSet, \lceil n / 2 \rceil)$, 
\begin{align*}
    \utili[n]\left(1, \frac 1 2, \strats_W \right) \geq 
    \utili[n] \left(1, \frac 1 2, \strats_{[n-1]\setminus S} \right) - 2\eps.
\end{align*}
Since $|W| = [n-1]\setminus S = \lceil n / 2 \rceil$, by \eqref{eq:util-diff-eps},
\begin{align*}
    \left(\lceil \frac n 2 \rceil - |W \setminus S| \right) \cdot \frac{\distconst \eps}{(n-1)4e^2} \leq 2\eps.
\end{align*}
So
\begin{align*}
    |W \cap S| \leq (n - 1) \cdot \frac{8e^2}{\distconst}.
\end{align*}
In other words, with probability at least $ 1- \delta$, $\diffalg(\sampleSet, \lceil n / 2 \rceil)$ is the complement of~$S$ except for at most $\frac{8e^2}{\distconst}$ fraction of the coordinates in $[n-1]$.

Similarly, for $S$ of cardinality $\lceil n / 2 \rceil$, 
\begin{align*}
    |\diffalg(\sampleSet, \lceil n / 2 \rceil) \cap S| \leq (n - 1) \cdot \frac{8e^2}{\distconst} + 1.
\end{align*}
Take $\diffconst$ to be $\frac{8e^2}{\distconst}$. We have $\diffconst<\frac 1 {20}$. For all large enough $n$ and all $S$ of size~$\lfloor n / 2 \rfloor$ or $\lceil n / 2 \rceil$, with probability at least $1 - \delta$, $\diffalg(\sampleSet, \lceil n / 2 \rceil)$ correctly outputs the elements not in~$S$ with an exception of at most $\diffconst$ fraction of coordinates.

Let $\coordsets$ be the set of all subsets of $[n-1]$ of size either $\lceil n / 2 \rceil$ or $\lfloor n / 2 \rfloor$.
Consider any~$S \in \coordsets$.  
Let $\diffset(S) \subseteq [n-1]$ denote the set of coordinates whose memberships in~$S$ are correctly predicted by $\diffalg(\sampleSet, \lceil n / 2 \rceil)$ with probability at least $2/3$; that is, $i \in \diffset(S)$ if{f} with probability at least $2/3$, $\diffalg(\sampleSet, \lceil n / 2 \rceil)$ is correct about whether $i \in S$.  
Let the cardinality of~$|\diffset(S)|$ be $z(n-1)$. Suppose we draw coordinate $i$ uniformly at random from $[n-1]$, and independently draw $t$ samples $\sampleSet$ from $\dists_S$, then the probability that $\diffalg(\sampleSet, \lceil n / 2 \rceil)$ is correct about whether $i\in S$ satisfies:
\begin{align*}
     & \Pr_{i, \sampleSet}\Big[ \diffalg(\sampleSet, \lceil n / 2 \rceil)\text{ is correct about whether }i\in S \Big] \\
     & \geq (1 - \diffconst) (1 - \delta)  \geq 0.9,
\end{align*}
and 
\begin{align*}
    & \Pr_{i, \sampleSet}\Big[ \diffalg(\sampleSet, \lceil n / 2 \rceil) \text{ is correct about whether }i\in S \Big] \\
    & \le \Prx[i]{i\in \diffset(S)}\cdot 1 + \Prx[i]{i\notin \diffset(S)}\cdot\frac{2}{3}  \\
    & = z\cdot 1 + (1-z)\cdot \frac 2 3,
\end{align*} 
which implies $z > 0.6$.  
% we know that for every $S \in \coordsets$, there is a set of coordinates $\diffset(S) \subseteq [n-1]$, with $|\diffset(S)| \geq (1 - \diffconst)(1 - \delta)(n-1) \geq \frac {9}{16} (n-1)$, such that for each $i \in \diffset(S)$,  with probability at least $2/3$, $\diffalg(\sampleSet, \lceil n / 2 \rceil)$ correctly predicts the membership of $i$ in~$S$.
% at least $1 - \delta$ fraction of the coordinates in $[n-1]$ whose membership in~$S$ is correctly predicted by~$\diffalg(\sampleSet, \lceil n / 2 \rceil)$ with probability at least $1 - \diffconst$.
If a pair of sets $S$ and~$S'$ differ in only one coordinate~$i$, and $i \in \diffset(S) \cap \diffset(S')$, then $\diffalg(\cdot)$ serves as an algorithm that tells apart $\dists_S$ and~$\dists_{S'}$, contradicting Corollary~\ref{cor:lb-kl}.  
We now show, with a counting argument, that such a pair of $S$ and~$S'$ must exist.

Since for each $S \in \coordsets$, $|\diffset(S)| \geq 0.6(n-1)$, there exists a coordinate $i \in [n-1]$ and $\mathcal T \subseteq \coordsets$, with $|\mathcal T| \geq 0.6 |\coordsets|$, such that for each $S \in \mathcal T$, $i \in \diffset(S)$. 
But $\coordsets$ can be decomposed into $|\coordsets| / 2$ pairs of sets, such that within each pair, the two sets differ by one in size, and precisely one of them contains coordinate~$i$.  
Therefore among these pairs there must exist one $(S, S')$ with $S, S' \in \mathcal T$, i.e., $i \in \diffset(S)$ and $i \in \diffset(S')$.
Using $\diffalg$, which is induced by~$\alg$, we can tell apart $\dists_S$ and~$\dists_{S'}$ with probability at least $2/3$, which is a contradiction to Corollary~\ref{cor:lb-kl}.
This completes the proof of Theorem~\ref{thm:lower-bound-learning-util}.
\end{proof}


