Let $\mathbb{T}\defeq \mathbb{T}^{-} \cup \mathbb{T}^{+} \cup \mathbb{T}^{modif}$ be the set of all event types for a stock where
\begin{align*}
    \mathbb{T}^{-} &\defeq \{-\} \times \mathbb{J} \times \mathbb{N}^*,\\
    \mathbb{T}^{+} &\defeq \{+\} \times \mathbb{J} \times \{b, a\} \times \mathbb{N}^*,\\
    \mathbb{T}^{modif} &\defeq \{\text{modif}\} \times \mathbb{J} \times  \mathbb{J}\times\mathbb{N}^*.
\end{align*}
An event $(-, j, n) \in \mathbb{T}^{-}$ corresponds to an order consuming $n$ units of the asset at pile $j$. An event $(-, j, b, n) \in \mathbb{T}^{+}$ corresponds to a buy limit order at pile $j$ with volume $n$, $(-, j, a, n) \in \mathbb{T}^{+}$ corresponds to a sell limit order at pile $j$ with volume $n$. An event $(\text{modif}, j_1, j_2, n)$ is a modification: a quantity $n$ that was pending at pile $j_1$ is now pending at pile $j_2$. A buy limit order is always modified to a buy limit order, and a sell limit order is always modified to a sell limit order.

\begin{remark}
    In practice, there are two types of orders that consume liquidity, represented by a \enquote{-} here: market orders and cancellations. Assuming market orders do not consume more than one pile, both have exactly the same role in LOB dynamics, so we do not separate them in the stability analysis. It is still possible to consider them separately for estimation purposes, see Section \ref{sec:estimation}.
\end{remark}

\begin{remark}
    It is necessary to specify if a limit order is buy or sell, mentioning the pile is not enough for orders in the spread. For example, if piles $(b, 2)$, $(b, 1)$ and $(a,2)$ are filled but $(a, 1)$ is empty, a limit order at pile $(a,1)$ could be either buy or sell.
\end{remark}

For each event type $e \in \mathbb{T}$, we define the set $\mathcal{Q}^{e, licit} \subset \mathcal{Q}$ of order book states for which such an event can occur. For $e=(-,j,n) \in \mathbb{T}^{-}$,
\begin{equation*}
    \mathcal{Q}^{e, licit} \defeq \{(q^{j'})_{j' \in \mathbb{J}} \in \mathcal{Q}: q^j \geqslant n\},
\end{equation*}
meaning that an order consuming a volume $n$ of the asset at pile $j$ is only possible when the said pile has at least $n$ units pending. For $e = (+,(s_1,l),s2,n) \in \mathbb{T}^{+}$,
\begin{equation*}
    \mathcal{Q}^{e,licit} \defeq
    \begin{cases}
        \mathcal{Q} & \text{if }s_1=s_2\\
        \{q \in \mathcal{Q}: l < j^{a,best}(q)\} &\text{if }s_1=a\text{ and }s_2=b\\
        \{q \in \mathcal{Q}: l < j^{b,best}(q)\} &\text{if }s_1=b\text{ and }s_2=a,
    \end{cases}
\end{equation*}
meaning a bid limit order cannot be placed at a price higher or equal than the best ask price, and an ask bid limit order cannot be placed at a price lower or equal than the best ask price. Finally, a modification $e=(\text{modif}, (s_1, l_1), j_2, n)\in \mathbb{T}^{modif}$ is licit if and only if n units of the asset can be taken from $(s_1, l_1)$ and can be added to $j_2$:
\begin{equation*}
    \mathcal{Q}^{e, licit} \defeq \begin{cases}Q^{(-, (s_1, l_1), n),licit} \cap Q^{(+, j_2, s_1, n),licit}& \text{if } j_2 \neq (s_1,l_1)\\
       \emptyset & \text{if } j_2 = (s_1,l_1)
    \end{cases},
\end{equation*}
excluding modifications in the same queue.

As in \parencite[Section 2.2.2]{huang2015simulating}, we consider a reference price that is either the mid-price if the spread is odd, or at half-tick from the mid-price if the spread is even. At a mid-price change, for example when the best queue is wiped or a limit order is placed in the spread, the new reference price is either:
\begin{itemize}
    \item the new mid-price if the new spread is even,
    \item the new mid-price plus or minus half a tick if the spread is odd, whatever is closer to the old reference price.
\end{itemize}
Precisely, we define the price variation function $\delta p^{e}$ for each event type $e \in \mathbb{T}$. For a liquidity consuming event $e=(-,j=(s,l), n) \in \mathbb{T}^{-}$,
\begin{equation*}
    \delta p^e(q) = \begin{cases}
        0 &\text{if } j \neq j^{s,best}(q)\text{ or }n \neq q^{j}\\
        \floor*{\frac{1}{2}(d(q)+j^{a,best,2}(q)-j^{a,best}(q))} &\text{if } s=a \text{ and } l = j^{a,best}(q)\text{ and }n = q^{j}\\
        \floor*{\frac{1}{2} + \frac{1}{2}(d(q)+j^{b,best,2}(q)-j^{b,best}(q))} &\text{if } s=b \text{ and } j = j^{b,best}(q)\text{ and }n = q^{j}
    \end{cases},\quad q \in \mathcal{Q}^{e,licit}.
\end{equation*}
For a limit order $e=(+,j,s,n) \in \mathbb{T}^{+}$,
\begin{equation*}
    \delta p^e(q) = \begin{cases}
        0 &\text{if } s=b\text{ and }j-j^{b,best}(q) \leqslant 0\\
        0& \text{if } s=a\text{ and }j-j^{a,best}(q) \geqslant 0\\
        \floor*{\frac{1}{2} + \frac{1}{2}(d(q)+j-j^{a,best}(q))} & \text{if }s=a \text{ and } j - j^{a,best}(q) < 0 \\
        \floor*{\frac{1}{2}(d(q)+j-j^{b,best}(q))} & \text{if }s=b \text{ and } j - j^{b,best}(q) > 0 
    \end{cases},\quad q \in \mathcal{Q}^{e,licit}.
\end{equation*}
For a modification $e=(\text{modif},j_1=(s,l),j_2,n) \in \mathbb{T}^{modif}$,
\begin{equation*}
    \delta p^e(q) = \begin{cases}
        \delta p^{(+,j_2,s, n)}(q) &\text{if } s=b\text{ and }j-j^{b,best}(q) > 0\\
        \delta p^{(+,j_2,s, n)}(q) &\text{if } s=a\text{ and }j-j^{a,best}(q) < 0\\
        \min\bigg(\begin{aligned}[t] &\floor*{\frac{1}{2}(d(q)+j^{a,best,2}(q)-j^{a,best}(q))},\\ &\floor*{\frac{1}{2}(d(q)+j_2-j^{a,best}(q))} \bigg)\end{aligned} & 
        \begin{aligned}[t]&\text{if }s=a \text{ and } j_1=j^{a,best}(q)\\ &\text{and }j_2 - j^{a,best}(q) > 0\\ & \text{and }n=q^j \end{aligned}\\
        \max\bigg(\begin{aligned}[t] &\floor*{\frac{1}{2} + \frac{1}{2}(d(q)+j^{b,best,2}(q)-j^{b,best}(q))},\\&\floor*{\frac{1}{2} + \frac{1}{2}(d(q)+j_2-j^{b,best}(q))} \bigg)\end{aligned} & 
        \begin{aligned}[t]&\text{if }s=b \text{ and } j_1=j^{b,best}(q)\\ &\text{and }j_2 - j^{b,best}(q) < 0\\ & \text{and }n=q^j \end{aligned} 
    \end{cases}, q \in \mathcal{Q}^{e,licit}.
\end{equation*}

\begin{remark}
    Since $j^{s,best,2}(q)$, $s \in \{a,b\}$ is fixed at $K+2$ if only one pile of side $s$ contains pending limit orders, a depletion of the full side $s$ will always trigger a reference price jump. Otherwise, the reference price would never jump in the case $K = 1$.
\end{remark}

We also define the variation in volume $\delta q$ in the LOB after every type of order. This quantity does not depend on the current state of the LOB. For $e \in \mathbb{T}$, we have
\begin{equation*}
    \delta q^e = \begin{cases}
        -ne_j & \text{if } e=(-,j,n) \in \mathbb{T}^{-}\\
        ne_j & \text{if } e=(+,j,s,n) \in \mathbb{T}^{+}\\
        -ne_{j_1} + ne_{j_2} & \text{if } e=(+,j_1,j_2,n) \in \mathbb{T}^{modif}.
    \end{cases}
\end{equation*}
We now introduce a notation to describe the state of the LOB after new piles are discovered due to a shift of the observation window. Let $q  = (q^j)_{j \in \mathbb{J}}\in \mathbb{N}^{\mathbb{J}}$ and $v=(v^m)_{1 \leqslant m \leqslant K'} \in \mathbb{N}^{K'}$ for some $1 \leqslant K' \leqslant K$. Then $[v, q] = (q^j_1)_{j \in \mathbb{J}}$ and $[q,v] = (q^j_2)_{j \in \mathbb{J}}$ where
\begin{align*}
    &(q_1^{b,K},\dots,q_1^{b,1},q_1^{a,1},\dots,q_1^{a,K})
    = (v^{K'},\dots,v^1,q^{b,K},\dots,q^{b,1}, q^{a,1},\dots,q^{a,K-K'})\\
    &(q_2^{b,K},\dots,q_2^{b,1},q_2^{a,1},\dots,q_2^{a,K})
    = (q^{b,K-K'},\dots,q^{b,1}, q^{a,1},\dots,q^{a,K-K'},v^1,\dots,v^K).
\end{align*}
For $q = (q_i^j)_{i \in \mathbb{I},j\in \mathbb{J}} \in (\mathbb{N}^{\mathbb{J}})^{\mathbb{I}}$ and $i \in \stocks$ we define the shifts on the component $i$ $[v,q]^{(i)}=(q^*_{i'})_{i' \in \stocks} \in (\mathbb{N}^{\mathbb{J}})^{\mathbb{I}}$ and $[q,v]^{(i)}=(q^{**}_{i'})_{i' \in \stocks} \in (\mathbb{N}^{\mathbb{J}})^{\mathbb{I}}$ by
$q^*_{i'} = q^{**}_{i'} = q_{i'}$ if $i' \neq  i$, $q^*_i = [v,q]_i$ and $q^{**}_i = [q,v]_i$. This bracket notation is illustrated in Figure \ref{fig:illustration_crochet}.

