    \input{BNPP_SOGN_stock_mean_plots.tex}
    \caption{Estimated coefficients for the dynamics of market orders for the stocks BNP Paribas and Société Générale. One estimation per trading day, over February 2022. We removed February 24 from the plots of $\sigma_{BNP}$ (value: 0.31085) and $\sigma_{SOGN}$ (value: 0.37024) for clarity.}
