\begin{corollary}
\label{cor: res over R}
    The minimal free resolution $F$ of $\kk$ over $R$ from \Cref{graded res} has following general description. For any $j \ges 0$, 
\[
        F_{2j} = \sC^{(0)}_{2j}\oplus \sC^{(1)}_{2j-1}\oplus\dots\oplus \sC^{(j)}_{j} \qquad \text{ and } \qquad 
        F_{2j+1}= \sC^{(0)}_{2j+1}\oplus \sC^{(1)}_{2j}\oplus\dots\oplus \sC^{(j)}_{j+1}. 
 \]
The differential maps $\partial^F_{2j}: F_{2j} \to F_{2j-1}$ are of size $j \times (j+1)$ as blocks of maps, 
    \begin{align*}
     \partial^F_{2j}&=
     \begin{pmatrix}
     \partial^{(0)}_{2j}&\varphi^{(1)}_{2j-1} &0&0&\dots&0&0\\[0.15in]
                   0&\partial^{(1)}_{2j-1}&\varphi^{(2)}_{2j-2}&0&\dots&0&0\\[0.15in]   
                   \vdots&\vdots&\vdots&\vdots&\vdots&\vdots&\vdots\\[0.15in]
                   0&0&0&0&\dots&\varphi^{(j-1)}_{j+1}&0\\[0.15in]
                   0&0&0&0&\dots&\partial^{(j-1)}_{j+1}&\varphi^{(j)}_{j}\\[0.15in]                   
     \end{pmatrix},
     \end{align*}
     and $\partial^F_{2j+1}: F_{2j+1} \to F_{2j}$ are of size $(j+1) \times (j+1)$ as blocks of maps,
     \begin{align*}
      \partial^F_{2j+1}&=
     \begin{pmatrix}
     \partial^{(0)}_{2j+1}& \varphi^{(1)}_{2j} &0&0&\dots&0&0\\[0.15in]
                   0&\partial^{(1)}_{2j}&\varphi^{(2)}_{2j-1}&0&\dots&0&0\\[0.15in]   
                   \vdots&\vdots&\vdots&\vdots&\vdots&\vdots&\vdots\\[0.15in]
                   0&0&0&0&\dots&\varphi^{(j-1)}_{j+2}&0\\[0.15in]
                   0&0&0&0&\dots&\partial^{(j-1)}_{j+2}&\varphi^{(j)}_{j+1}\\[0.15in]
                   0&0&0&0&\dots&0&\partial^{j}_{j+1}\\[0.15in]                   
     \end{pmatrix},
    \end{align*}
where the differential maps $\partial^{(k)}$ in the $\sC^{(k)}$ complex appear on the main diagonal, and the chain maps $\varphi^{(k)}$ appear on the superdiagonal (directly above the main diagonal).   
\end{corollary}   

If such $F$ exists, the above description holds for any local ring $R$ of any codepth $c \ges 1$. For a particular ring $R$, one needs to describe specific $u_{k,s}$ and $\varphi^{(k)}_i: \sC_i^{(k)} \to \sC_i^{(k-1)}$ such that the hypotheses of \Cref{graded res} are satisfied. In the next sections, we describe them for the complete intersection class of codepth $c \ges 1$ and for the class $\clT$ of codepth $3$.


\begin{definition} 
\label{gr Poi}
If a graded minimal free resolution of $\kk$ as an $A$-module has the form
\begin{equation*}
    \BF\colon \dots\to \bigoplus_{s\ges 0} A^{u_{k,s}}(-s)\xra{\partial_k^\BF} \bigoplus_{s\ges 0} A^{u_{k-1,s}}(-s)\xra{\partial_{k-1}^\BF}\dots \to \bigoplus_{s\ges 0} A^{u_{1,s}}(-s) \xra{\partial_{1}^\BF} A
\end{equation*}
then the \emph{graded Poincar\'e series of $A$} is defined as:
    \begin{equation*}
        \Poi{A}{\kk}(t,z)=\sum_{k,s\ges 0}u_{k,s}t^kz^s.
    \end{equation*}
\end{definition}


\begin{remark}   
If for each $k\ges 0$ we have $u_{k,s}=0$ for all $s \gg 0$,  then $u_k\coloneqq \sum_{s\ges 0}u_{k,s}$ is called  the {\it $k$-th Betti number} of $\kk$ as an $A$-module.
In this case, the \emph{Poincar\'e series of $A$} is:
\begin{equation*}
    %\label{Poi}
        \Poi{A}{\kk}(t) \coloneqq \sum_{k \ges 0}u_{k}t^k=\Poi{A}{\kk}(t,1).
    \end{equation*}
Note that in the literature, see e.g., \cite[1.7]{Av2}, $\Poi{A}{\kk}(t)$ is defined as $\Poi{A}{\kk}(t)\coloneqq \Poi{K}{\kk}(t)$.    
\end{remark}     


\begin{corollary} 
\label{Poi cor}
Under the hypotheses of \Cref{graded res} and let $n$ be
the embedding dimension of $R$, we have $\Poi{R}{\kk}(t)=(1+t)^n\Poi{A}{\kk}(t,t)$.
\end{corollary}

\begin{proof}
Using that $\sC^{(k)}_r=0$ for all $r<k$, we simplify the rank of each free $R$-module $F_i$ as follows:
\begin{align*}
\rank_R F_i&= \sum_{k \ges 0}\rank_R \sC^{(k)}_{i-k} =  \sum_{k,s\ges 0} \rank_RK^{u_{k,s}}_{i-k-s}=\sum_{k,s\ges 0} \binom{n}{i-k-s}u_{k,s}=  \sum_{j\ges 0} \binom{n}{i-j}\sum_{k+s=j}u_{k,s}.
                \end{align*}
Thus, we get
    \begin{align*}
    \Poi{R}{\kk}(t)&=\sum_{i\ges 0} (\rank_{R}F_i)t^i =\sum_{i\ges 0}\sum_{j\ges 0} \binom{n}{i-j}t^{i-j}\sum_{k+s=j}u_{k,s}t^kt^s=(1+t)^n\Poi{A}{\kk}(t,t).
    \end{align*}
\end{proof}



