\section{Application on class $\clC c$}
\label{ci}

The free resolution of the residue field $\kk$ over a complete intersection ring is well-known, see e.g., by Tate \cite[Theorem 4]{T}. In \cite{NV2}, the authors also obtained this resolution using iterated mapping cone construction and the short exact sequences of Koszul homologies \cite[Theorem 4.1]{NV2}. One advantage of this approach is the description of the differential maps of the resolution is given explicitly as blocks of maps that are easily obtained from a finite set of data. The second advantage is that this method extends to other classes of rings as we will see in the subsequent sections.
We reformulate here some results from \cite{NV2} to better fit the scope of the present paper and to illustrate \Cref{graded res}. 


For the rest of this section, let $(R,\fm,\kk)$ be a complete intersection local ring of codepth $c \ges 1$. Let $(K,\partial)$ be the Koszul complex of $R$ on a minimal set of generators of $\fm$ and $A=A_0\oplus A_1\oplus \cdots \oplus A_c$ its homology. We denote by $\{[z^1_1],\dots,[z^1_c]\}$ a basis for $A_1$, where each $z^1_u$ is a cycle representative in $K_1$. It is known that $A=\bigwedge A_1$, the exterior algebra on degree 1.


\begin{definition}
\label{def beta} 
For any integer $k\ges 0$, set $b_k=\textstyle\binom{k+c-1}{c-1}$. A set with $b_k$ elements is indexed by words $u_1\dots u_k$ of length $k$ with 
$1\les u_1\les \dots \les u_k\les c$ that are ordered lexicographically.

Let $\beta_k$ be the $b_{k-1}\times b_{k}$ matrix with entries in $K_1$, given as follows. For $1\les v_1\les\dots\les v_{k-1}\les c$ and $1\les u_1\les\dots\les u_{k}\les c$, its entry in the position $(v_1\dots v_{k-1},u_1\dots u_{k})$ is given by  
\begin{align*}
 \beta_k(v_1\dots v_{k-1},u_1\dots u_{k}) \coloneqq \begin{cases}
 z^1_{u},
 &\text{ if } u_1\dots u_{k}=[v_1\dots v_{k-1}u], \text{ for } 1 \les u \les c\\
 0,
 &\text{ otherwise.} 
 \end{cases}
\end{align*}
Here, we adopt the notation from \cite[Section 2]{NV2}. When the index is not in non-decreasing order, we use the square bracket notation $[u_1\dots u_k]$ to reorder it non-decreasingly; for example $[1312]=1123$. 

For $k\ges 0$, let $[\beta_k]$ denote the matrix with entries in $A_1$ where we replace entries $z^1_u$ in $\beta_k$ by $[z^1_u]$. 
\end{definition}

\begin{remark}
It is straightforward that $\beta_k$ is the matrix representation of the map $\zeta^{k-1}$ given in \cite[(2.1.1)]{NV2}. 
\end{remark}

\begin{proposition} 
\label{graded res CI}
Let $(R,\fm,\kk)$ be a complete intersection local ring of codepth $c \ges 1$. Let $K$ be the Koszul complex of $R$ on a minimal set of generators of $\fm$, and $A$ its homology which we consider as a graded-commutative ring. Then, a graded minimal resolution of $\kk$ over $A$ is given by:
\begin{equation}
\label{res k over A ci}
   \BF\colon     \cdots \to A^{b_{k}}(-k)\xra{[\beta_k]}A^{b_{k-1}}(-k+1)\to \cdots \to A^{b_2}(-2)\xra{[\beta_2]}A^{b_1}(-1)\xra{[\beta_1]} A^{b_0}\to 0,
\end{equation}
where $b_k=\textstyle\binom{k+c-1}{c-1}$ and matrices $\beta_k$ are defined in \Cref{def beta}, for each integer $k\ges 0$.
\end{proposition}

\begin{proof} 
Let $\CA_0$ be the complex $0 \to A_0^{b_0} = \kk \to 0$. For each $k \ges 1$, by \cite[Proposition 2.2]{NV2}, we consider the exact complex of $\kk$-modules of the form
\begin{equation}
\label{ses codepth c}
\CA_k \colon\qquad  0\to A_0^{b_{k}}\xrightarrow{[\beta_{k}]}A_1^{b_{k-1}} \xrightarrow{[\beta_{k-1}]}A_2^{b_{k-2}} \xrightarrow{[\beta_{k-2}]} \cdots A_{c-1}^{b_{k-c+1}} \xrightarrow{[\beta_{k-c+1}]}A_c^{b_{k-c}} \to 0,
\end{equation}
where the component $A_0^{b_k}$ is in the homological degree $k\ges 0$.
It follows that $\BF=\bigoplus_{k \ges 0} \CA_k$. 
Indeed, for each $i\ges 0$, we have
\[ \BF_i=\Big(\bigoplus_{k\ges 0} \CA_k \Big)_i= \bigoplus_{k\ges 0} A_{k-i}^{b_i}=A^{b_i}(-i).\]

The exactness of $\CA_k$ for each $k\ges 1$ implies the acyclicity of $\BF$. 
Moreover, from the above description, it is clear that each $\BF_i$ is free as an $A$-module. The minimality of $\BF$ follows since the differential maps all have entries in $A_1$. 
\end{proof}


We recover the well-known Poincar\'e series over complete intersection rings. 
\begin{corollary}
Let $(R,\fm,\kk)$ be a complete intersection local ring of embedding dimension $n$, codepth $c \ges 1$, and $A$ its Koszul homology. Then, we have
\begin{equation*}
    \Poi{A}{\kk}(t,z)=\frac{1}{(1-tz)^c} \qquad\text{ and } \qquad \Poi{R}{\kk}(t)=\frac{(1+t)^n}{(1-t^2)^c}.
\end{equation*}
\end{corollary}

\begin{proof}
By \Cref{gr Poi}, \Cref{graded res CI}, and definition of $b_k$, we have
    \begin{align*}
    \Poi{A}{\kk}(t,z)=\sum_{k\ges 0} b_kt^kz^k=\sum_{k\ges 0} \binom{k+c-1}{c-1}(tz)^k=\frac{1}{(1-tz)^c}.
\end{align*}
The expression for $\Poi{R}{\kk}(t)$ follows from \Cref{Poi cor}.
\end{proof}

Using this reformulation, we recover \cite[Theorem 4.1]{NV2} as a consequence of \Cref{graded res} and \Cref{graded res CI}.

\begin{corollary}
    Let $(R,\fm,\kk)$ be a complete intersection local ring of codepth $c \ges 1$ and $(K,\partial)$ the Koszul complex of $R$ on a minimal set of generators of $\fm$. Then, the minimal free resolution $(F,\partial^F)$ of the residue field $\kk$ over $R$ have the components and differential maps given by:
    \begin{equation*}
     F_i=K_i^{b_0} \oplus K^{b_1}_{i-2}\oplus K^{b_2}_{i-4}\oplus\cdots \oplus K^{b_j}_{i-2j}\oplus\cdots \qquad \text{ and } \qquad
 \partial_i^F=
 \begin{pmatrix}
 \partial^{b_0}_i & \beta_1& 0                &           0       &0&\cdots\\[0.2cm]
           0  & \partial_{i-2}^{b_1} &\beta_2&           0       &0&\cdots\\[0.2cm]
           0  &                 0 & \partial_{i-4}^{b_2} &\beta_3&0&\cdots\\[0.2cm]
      \vdots  &           \vdots  &          \vdots  &           \ddots  &\ddots  &
 \end{pmatrix},
 \end{equation*}
for all integer $i\ges 0$, where $b_k=\textstyle\binom{k+c-1}{c-1}$ and matrices $\beta_k$ are defined in \Cref{def beta}, for all integer $k\ges 0$.
\end{corollary} 


