%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Application on class $\clT$}
\label{class T}

In this section, let $(R,\fm,\kk)$ be a local ring of embedding dimension $n$ and codepth $c=3$ of class $\clT$. This is one of the five classes in the classification work of \cite{Av2, AKM, W}. We construct a sequence of complexes $\{\sC^{(k)}\}_{k \ges 0}$ (see \eqref{def Ck}) and a sequence of chain maps $\{\varphi^{(k)} \colon \sC^{(k)} \to \sC^{(k-1)}\}_{k \ges 1}$ (see \eqref{matrix phi}) that satisfy the hypotheses of \Cref{graded res}.  Consequently, they give rise to a graded minimal resolution of $\kk$ over $A$ (see \Cref{res k over A class T}), and a minimal free resolution of $\kk$ over $R$ (see \Cref{res k over R class T}). We explicitly describe the components and differential maps of these resolutions. 


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Exactness of sequences on Koszul homologies} 
\label{subsec:Koszul}

For class $\clT$, the Koszul homology components $A_i$, for $0\les i\les 3$, have the following $\kk$-bases:
\begin{align*}
A_0 \colon&\ [1], \\
A_1 \colon&\ [z^1_1],\, [z^1_2],\, [z^1_3], \dots, [z^1_{a_1}], \\
A_2 \colon&\ [z^1_1]\cdot[z^1_2],\, [z^1_2]\cdot[z^1_3],\, [z^1_1]\cdot[z^1_3],\quad\text{and}\quad [z^2_{1}],\dots,[z^2_{a_2-3}], \\
A_3 \colon&\ [z^3_1],\dots, [z^3_{a_3}],
\end{align*}
where each $z^j_u$ is a cycle representative in $K_j$. Here, $A_1\cdot A_1=\Span_\kk\{[z^1_1]\cdot[z^1_2],\, [z^1_2]\cdot[z^1_3],\, [z^1_1]\cdot[z^1_3]\}$ and all other products in $A$ are zero.


We have $A\cong B\ltimes C$, i.e., $A$ is a trivial extension of $B$ with $C$, where
$B=B_0\oplus B_1\oplus B_2$ is the $\kk$-subalgebra of $A$ and $C=C_1\oplus C_2\oplus C_3$ is the $B$-module, with $\kk$-bases for $B_i, C_i$ be given by:
\begin{align*}
B_0\colon&\ [1],&& \\
B_1\colon&\  [z^1_1],\, [z^1_2],\, [z^1_3], & C_1\colon&\ [z^1_4],\dots, [z^1_{a_1}], \\
B_2\colon&\ [z^1_1]\cdot[z^1_2],\, [z^1_2]\cdot[z^1_3],\, [z^1_1]\cdot[z^1_3], & C_2\colon&\ [z^2_1],\dots, [z^2_{a_2-3}],\\
&&C_3\colon&\ [z^3_1],\dots, [z^3_{a_3}].
\end{align*}


\begin{definition}
\label{def beta'}
Similar to \Cref{def beta}, for any integer $k\ges 0$, set $b_k=\textstyle\binom{k+2}{2}$ and let $\beta_k$ be the $b_{k-1}\times b_{k}$ matrix with entries in the subset $\{0, z^1_1,z^1_2,z^1_3\}$ of $K_1$ given as follows. For $1\les v_1\les\dots\les v_{k-1}\les 3$ and $1\les u_1\les\dots\les u_{k}\les 3$, its entry in the position $(v_1\dots v_{k-1},u_1\dots u_{k})$ is given by 
\begin{align*}
\beta_k(v_1\dots v_{k-1},u_1\dots u_{k}) \coloneqq \begin{cases}
 z^1_{u},
 &\text{ if } u_1\dots u_{k}=[v_1\dots v_{k-1}u], \text{ for } 1 \les u \les 3\\
 0,
 &\text{ otherwise.} 
 \end{cases}
      \end{align*}

For any integer $k\ges 0$, let $\beta_k'$ be the $b_{k-1}\times b_{k-2}$ matrix with entries in the subset $\{0, z^1_1\wedge z^1_2,z^1_2\wedge z^1_3,z^1_1\wedge z^1_3\}$ of $K_2$ given as follows. For $1\les u_1\les\dots\les u_{k-1}\les 3$ and $1\les v_1\les\dots\les v_{k-2}\les 3$, its entry in the position 
$(u_1\dots u_{k-1},v_1\dots v_{k-2})$ is given by
\begin{align*}
\beta_k'(u_1\dots u_{k-1},v_1\dots v_{k-2}) \coloneqq \begin{cases}
 z^1_{u'}\wedge z^1_{u''},
 &\text{ if } u_1\dots u_{k-1}=[v_1\dots v_{k-2}u]\\
 0,
 &\text{ otherwise.} 
 \end{cases}
      \end{align*}
Here, for $u\in\{1,2,3\}$ we denote $\{u',u''\}=\{1,2,3\}\setminus\{u\}$ with $u'< u''$. As before, replacing the entries by their corresponding homology, we denote $[\beta_k]$ and $[\beta_k']$ for matrices with entries in $A_1$ and $A_2$ respectively, and  $[\beta_k]$ and $[\beta_k']$ can be considered as maps of degree 1 and 2 respectively. 
\end{definition}

\begin{remark}
\label{rmk: ex beta}
We illustrate the above definitions for the first few values of $k$:
\begin{align*}
\beta_0&=0, & \beta_0'&=0, \\
\beta_1&=\begin{pmatrix}z^1_1 & z^1_2 & z^1_3\end{pmatrix},
& \beta_1'&=0, \\
\beta_2&=\begin{pmatrix} z^1_1 & z^1_2 & z^1_3 & 0 & 0 & 0 \\
    0 & z^1_1 & 0 & z^1_2 & z^1_3 & 0 \\
    0 & 0 & z^1_1 & 0 & z^1_2 & z^1_3 
\end{pmatrix}, 
& \beta_2'&= \begin{pmatrix}
    z^1_2 \wedge z^1_3 \\ z^1_1 \wedge z^1_3 \\ z^1_1 \wedge z^1_2
\end{pmatrix}, \\
\beta_3&=\begin{pmatrix} 
    z^1_1 & z^1_2 & z^1_3 & 0 & 0 & 0 & 0 & 0 & 0 & 0 \\
    0 & z^1_1 & 0 & z^1_2 & z^1_3 & 0 & 0 & 0 & 0 & 0 \\
    0 & 0 & z^1_1 & 0 & z^1_2 & z^1_3 & 0 & 0 & 0 & 0 \\
    0 & 0 & 0 & z^1_1 & 0 & 0 & z^1_2 & z^1_3 & 0 & 0 \\
    0 & 0 & 0 & 0 & z^1_1 & 0 & 0 & z^1_2 & z^1_3 & 0 \\
    0 & 0 & 0 & 0 & 0 & z^1_1 & 0 & 0 & z^1_2 & z^1_3 \\
\end{pmatrix},
& \beta_3'& = \begin{pmatrix}
    z^1_2 \wedge z^1_3 & 0 & 0 \\
    z^1_1 \wedge z^1_3 & z^1_2 \wedge z^1_3 & 0 \\
    z^1_1 \wedge z^1_2 & 0 & z^1_2 \wedge z^1_3 \\
    0 & z^1_1 \wedge z^1_3 & 0 \\
    0 & z^1_1 \wedge z^1_2 & z^1_1 \wedge z^1_3 \\
    0 & 0 & z^1_1 \wedge z^1_2
\end{pmatrix}.
\end{align*}
\end{remark}


\begin{proposition}
\label{exact B}
Retain the above notation. For any integer $k\ges 1$, there exists an exact complex of $\kk$-modules of the form:
\begin{equation*}
 \CB_k\colon \xymatrixrowsep{1.5pc}
 \xymatrixcolsep{2pc}
 \xymatrix{
 0\ar@{->}[r]^{} 
 &B_0^{b_{k}}\ar@{->}[r]^{[\beta_k]}
 &B_1^{b_{k-1}}\ar@{->}[r]^{[\beta_{k-1}]}\ar@{}[d]_{\bigoplus} 
 &B_2^{b_{k-2}}\ar@{->}[r]^{}
 &0,
 \\
 &           
 &B_0^{b_{k-3}}\ar@{^{(}->}[ru]_{[\beta_{k-1}']}           
 &
 &
 }
 \end{equation*}
with $B_0^{b_k}$ is placed in the homological position $k$ in the complex $\CB_k$.
\end{proposition}

\begin{proof}
By \cite[Proposition 2.2]{NV2} with $c=3$, for each integer $k\ges 1$ there exists a split exact sequence of $\kk$-modules:
\begin{equation*}
    \xymatrixrowsep{1.5pc}
 \xymatrixcolsep{2pc}
 \xymatrix{
 0\ar@{->}[r]^{} 
 &(\bigwedge^0 B_1)^{b_k}\ar@{->}[r]^{[\beta_k]}
 &(\bigwedge^1 B_1)^{b_{k-1}}\ar@{->}[r]^{[\beta_{k-1}]}
 &(\bigwedge^2 B_1)^{b_{k-2}}\ar@{->}[r]^{[\beta_{k-2}]}
 &(\bigwedge^3 B_1)^{b_{k-3}}\ar@{->}[r]^{}
 &0.
 }
\end{equation*}
To get the desired short exact sequence, using $B_0\cong\bigwedge^0 B_1\cong \bigwedge^3 B_1$ and  $B_2\cong\bigwedge^2 B_1$, it is enough to check that for $k\ges 3$, the map $[\beta_{k-1}']$ is a right inverse of the map $[\beta_{k-2}]$. That is, 
for all $k\ges 1$, we check  $\beta_{k}\beta_{k+1}'=z^1_1\wedge z^1_2\wedge z^1_3\, I_{b_{k-1}}$ in $K_3$, where $I$ denotes the identity matrix. 


Indeed, for $1\les v_1\les\dots \les v_{k-1}\les 3$ and $1\les v_1'\les\dots\les v_{k-1}'\les 3$, we calculate the entry $(v_1\dots v_{k-1},v_1'\dots v_{k-1}')$ of the product of matrices $\beta_{k}\beta_{k+1}'$. By definitions, the entries of $\beta_{k}$ and $\beta_{k+1}'$ are nonzero when $u_1\dots u_k = [v_1 \dots v_{k-1}u] = [v_1' \dots v_{k-1}'v]$, for some $u,v \in \{1,2,3\}$. 

If $v_1\dots v_{k-1} = v_1'\dots v_{k-1}'$, then the entry in $\beta_{k}\beta_{k+1}'$ is given by 
\[
    \sum_{u=1}^3 z^1_u\wedge z^1_{u'}\wedge z^1_{u''} =z^1_1\wedge z^1_2\wedge z^1_3 + z^1_2\wedge z^1_1\wedge z^1_3 + z^1_3\wedge z^1_1\wedge z^1_2 = z^1_1\wedge z^1_2\wedge z^1_3,
\]
where the last equality holds by the Koszul relations.     

If $v_1\dots v_{k-1}\not = v_1'\dots v_{k-1}'$, then the entry in $\beta_{k}\beta_{k+1}'$ is given by 
\[
    \sum_{[v_1\dots v_{k-1}u]=[v_1'\dots v_{k-1}'v]} z^1_u\wedge z^1_{v'}\wedge z^1_{v''}=0.
\]
To see this equality, if $u=v$, the condition $[v_1\dots v_{k-1}u]=[v_1'\dots v_{k-1}'v]$ implies $v_1\dots v_{k-1} = v_1'\dots v_{k-1}'$, which contradicts our assumption. Hence, $u\not=v$ which implies $u\in\{v',v''\}$, and we apply the Koszul relations again to get the desired result. Hence, $\CB_k$ is exact. 
\end{proof}


\begin{remark}
\label{exact C}
It is straightforward to see that the following complexes of $\kk$-modules are exact:
\begin{align*}
  \CC_1\colon & 0 \to A_0^{a_1-3}\xra{[\gamma_1]}C_1\to 0, \notag \\
  \CC_2\colon & 0 \to A_0^{a_2-3}\xra{[\gamma_2]}C_2\to 0, \label{exact C} \\
  \CC_3\colon & 0 \to A_0^{a_3}\xra{[\gamma_3]}C_3\to 0, \notag 
\end{align*}
where $C_j$ is in the homological position $0$ in the complex $\CC_j$, for all $1 \les j \les 3$, and $\gamma_1$ is the $1\times (a_1-3)$ matrix with entries in $K_1$, $\gamma_2$ is the $1\times (a_2-3)$ matrix with entries in $K_2$, and $\gamma_3$ is the $1\times a_3$ matrix with entries in $K_3$ respectively given by:
\begin{equation}
    \label{def gamma}
    \gamma_1=\begin{pmatrix} z^1_4 &\dots& z^1_{a_1} \end{pmatrix}, \qquad \gamma_2=\begin{pmatrix} z^2_1 &\dots& z^2_{a_2-3}\end{pmatrix}, \qquad 
\gamma_3=\begin{pmatrix} z^3_1 &\dots& z^3_{a_3}\end{pmatrix}.
\end{equation}
\end{remark}


\begin{definition}
\label{def seq T}
For any integer $k \ges 1$, let $\alpha_k$ be the $\ell_{k-1}\times \ell_{k}$ matrix with entries in $K_1$, $\alpha_k'$ be the $\ell_{k-1}\times \ell_k'$ matrix with entries in $K_2$, and $\alpha_k''$ be the $\ell_{k-1}\times \ell_k''$ matrix with entries in $K_3$ respectively given by:
\begin{equation}
\label{alpha and alpha'} 
  \alpha_k =\left(\bigoplus_{i=0}^{k-1}\beta_{k-i}^{d_{i}}\Big|\gamma_1^{\ell_{k-1}}\right), \qquad 
  \alpha_k'=\left( \begin{array}{c|c}\begin{array}{c} 0_{d_{k-1} \times \ell_{k-2}} \\ \hline \bigoplus_{i=0}^{k-2}\beta_{k-i}'^{d_{i}} \end{array} & \gamma_2^{\ell_{k-1}} \end{array} \right), \qquad \alpha_k''=\gamma_3^{\ell_{k-1}},
\end{equation}
where the matrices $\beta_i, \beta'_i$ are defined in \Cref{def beta'}, the matrices $\gamma_1,\gamma_2,\gamma_3$ are defined in \eqref{def gamma}, and 
$\{\ell_k\}_{k\ges 0}$, $\{\ell_k'\}_{k\ges 0}$, $\{\ell_k''\}_{k\ges 0}$, and $\{d_k\}_{k\ges 0}$ are sequences of integers satisfying the following recurrence relations:
\begin{align}
\label{ell}
    \ell_k&=\sum_{i=0}^{k}b_{k-i}d_{i},\quad  \text{ where } \\
    d_0&=1 \text{ and }  d_k=(a_1-3)\ell_{k-1},\notag \\
\label{ellprime}
    \ell_0'&=0 \text{ and } \ell_k'=\ell_{k-2}+(a_2-3)\ell_{k-1},\\
\label{elldprime}    
     \ell_0''&=0 \text{ and } \ell_k''=a_3\ell_{k-1}.
\end{align}
\end{definition}


\begin{remark}
\label{ellex}
We list the first few elements of these sequences in terms of $a_i= \rank_{\kk} (A_i)$:
\begin{align*} 
   \ell_0&=1, &\ell_1 &=a_1,         &\ell_2&=a_1^2-3,                   &\ell_3&=a_1^3-6a_1+1,\\
    d_0&=1, &d_1&=a_1-3, &d_2&=(a_1-3)a_1, &d_3&=(a_1-3)(a_1^2-3), \\
   \ell'_0&=0, &\ell_1'&=a_2-3,  &\ell_2'&=a_1a_2-3a_1+1,  &\ell_3'&=a_1^2a_2 - 3a_1^2-3a_2+a_1+9,\\
   \ell''_0&=0, &\ell_1''&=a_3, &\ell_2''&= a_1a_3, &\ell_3''&=a_1^2a_3-3a_3. 
\end{align*}
\end{remark}

\begin{remark}
\label{rmk T}
It is straightforward to check that the sequences of integers $\{b_k\}_{k\ges 0}$ and $\{\ell_k\}_{k\ges 0}$
have respectively the following generating functions:
\begin{equation*}
  \frac{1}{(1-t)^3}\quad\text{and}\quad  \frac{1}{(1-t)^3-t(a_1-3)}.
\end{equation*}
In particular, the sequences of integers
$\{\ell_k'\}_{k\ges 0}$, $\{\ell_k''\}_{k\ges 0}$, and $\{d_k\}_{k\ges 0}$ 
have respectively the following  generating functions:
\begin{equation*}
   \frac{t^2+t(a_2-3)}{(1-t)^3-t(a_1-3)}, \quad \frac{ta_3}{(1-t)^3-t(a_1-3)}, \text{ and } \quad \frac{t(a_1-3)}{(1-t)^3-t(a_1-3)}+1.
\end{equation*} 
\end{remark}


\begin{theorem}
\label{thm:exact A}
Let $(R,\fm, \kk)$ be a local ring of codepth 3 and of class $\clT$, and retain the above notation. Then for any integer $k\ges 1$, there exists an exact complex of $\kk$-modules:
\begin{equation*}
\CA_k\colon    
 \xymatrixrowsep{2pc}
 \xymatrixcolsep{3pc}
 \xymatrix{
 0\ar@{->}[r]^{} 
 &A_0^{\ell_k}\ar@{->}[r]^{[\alpha_k]}
 &A_1^{\ell_{k-1}} \ar@{->}[r]^{[\alpha_{k-1}]}\ar@{}[d]_{\bigoplus}
 &A_2^{\ell_{k-2}}\ar@{->}[r]^{[\alpha_{k-2}]}\ar@{}[d]_{\bigoplus}
 &A_3^{\ell_{k-3}}\ar@{->}[r]^{}
 &0.
 \\
 &           
 &A_0^{\ell'_{k-1}}\ar@{->}[ru]_{[\alpha'_{k-1}]}          
 &A_0^{\ell''_{k-2}}\ar@{->}[ru]_{[\alpha''_{k-2}]}
 &
 &
 } 
\end{equation*}
with $A_0^{\ell_k}$ is placed in the homological position $k$ in the complex $\CA_k$.
\end{theorem}


\begin{proof}
Observe that in class $\clT$, for any integer $k\ges 1$ the map $[\alpha_{k-2}]: A_2^{\ell_{k-2}} \to A_3^{\ell_{k-3}}$ is a zero map and the map $[\alpha_{k-2}'']: A_0^{\ell''_{k-2}} \to A_3^{\ell_{k-3}}$ defined in \eqref{alpha and alpha'} is an isomorphism. Hence, $\CA_k$ in the theorem is an extension of $\CA'_k$ by $\Sigma^{k-3}\CC_3^{\ell_{k-3}}$, where
\[
\CA_k'\colon    \xymatrixrowsep{1.5pc}
 \xymatrixcolsep{2pc}
 \xymatrix{
 0\ar@{->}[r]^{} 
 &A_0^{\ell_k}\ar@{->}[r]^{[\alpha_k]}
 &A_1^{\ell_{k-1}} \ar@{->}[r]^{[\alpha_{k-1}]}\ar@{}[d]_{\bigoplus}
 &A_2^{\ell_{k-2}}\ar@{->}[r]^{}
 &0,
 \\
 &           
 &A_0^{\ell'_{k-1}}\ar@{->}[ru]_{[\alpha'_{k-1}]}          
 &
 &
 }
\]
with $A_0^{\ell_k}$ in the homological degree $k$. Thus, it suffices to show that $\CA_k'$ is exact for each $k \ges 1$. By construction, we have the following isomorphism of complexes: 
\[ \CA_k' \cong \CB_k^{d_0}\oplus\dots \oplus \Sigma^{k-1}\CB_{1}^{d_{k-1}}\oplus \Sigma^{k-1}\CC_1^{\ell_{k-1}}  \oplus \Sigma^{k-2}\CC_2^{\ell_{k-2}}, \]
where the complexes $\CB_i$ and $\CC_j$ are exact by \Cref{exact B} and \Cref{exact C} respectively. Hence, $\CA_k'$ is exact, and we have an isomorphism of complexes of $\kk$-modules:
\[ \CA_k \cong \left(\bigoplus_{i=0}^{k-1} \Sigma^{i}\CB_{k-i}^{d_{i}}\right) \oplus
\left( \bigoplus_{j=1}^3\Sigma^{k-j}\CC_j^{\ell_{k-j}}\right). \]
\end{proof}

\begin{remark}
In what follows, we illustrate the structures of $\CA_k$ for small cases. Observe that the map $[\gamma_1]$ is a zero map, except when mapping from $A_0^{a_1-3}$, and we use the identification $A_0=B_0 \cong \kk$ throughout. 

\medskip

