\begin{corollary}
\label{cor:acyclic A}
Let $(R,\fm, \kk)$ be a local ring of codepth 3 and of class $\clT$, and retain the above notation. Consider the complex $\BA \coloneqq \bigoplus_{k \ges 0} \CA_k$ given as the sum of complexes of $\kk$-modules, where $\CA_0$ is the complex $0\to A_0^{\ell_0} \to 0$, and $\CA_k$ is as in \Cref{thm:exact A}. 

Then, $\BA$ is an acyclic complex of graded $A$-modules with $\HH{0}{\BA} \cong A_0 \cong \kk$, of the following form:
\begin{equation} 
\label{BA}
\BA \colon \hspace{-0.2in}
 \xymatrixrowsep{3pc}
 \xymatrixcolsep{2.2pc}
 \xymatrix{
 &\dots\ar@{->}[r]^{}
 &A^{\ell_{i}}(-i) \ar@{->}[r]^{[\alpha_{i}]}\ar@{}[d]_{\bigoplus}
 &A^{\ell_{i-1}}(-i+1)\ar@{->}[r]^{[\alpha_{i-1}]}\ar@{}[d]_{\bigoplus}
 &\qquad \dots \qquad \ar@{->}[r]^{[\alpha_{2}]}
 &A^{\ell_{1}}(-1)\ar@{->}[r]^{[\alpha_{1}]}\ar@{}[d]_{\bigoplus}
 &A^{\ell_0}
 \\  
 &\dots\ar@{->}[ru]^{}       
 &\kk^{\ell'_{i}}(-i-1)\ar@{->}[ru]|{[\alpha'_{i}]}\ar@{}[d]_{\bigoplus}
 &\kk^{\ell'_{i-1}}(-i)\ar@{->}[ru]|{[\alpha'_{i-1}]}\ar@{}[d]_{\bigoplus}
 &\dots\ar@{->}[ru]|{[\alpha'_2]}
 &\kk^{\ell'_{1}}(-2)\ar@{->}[ru]|{[\alpha'_{1}]}\ar@{}[d]_{\bigoplus}
 &
  \\   
 &\dots\ar@{->}[ruu]^{}        
 &\kk^{\ell''_{i}}(-i-2)\ar@{->}[ruu]|{[\alpha''_{i}]}
 &\kk^{\ell''_{i-1}}(-i-1)\ar@{->}[ruu]|{[\alpha''_{i-1}]} 
 &\dots\ar@{->}[ruu]|{[\alpha''_2]}
 &\kk^{\ell''_{1}}(-3)\ar@{->}[ruu]|{[\alpha''_{1}]}
 &
 } 
\end{equation}
\end{corollary}

\begin{proof}
By \Cref{thm:exact A}, for each $k \ges 1$, the complex of $\kk$-modules  $\CA_k$ is exact so $\BA = \bigoplus_{k \ges 0} \CA_k$ is an acyclic complex of $\kk$-modules with $\HH{0}{\BA}=A_0^{\ell_0}=A_0\cong \kk$. 

We now show that $\BA$ has the form as in \eqref{BA} as a complex of $A$-modules. Observe that for any $i \ges 0$, the $i$-th homological component of $\CA_k$ can be described as follows,
\begin{equation*}
    (\CA_k)_i=
    \begin{cases}
    A_0^{\ell_{k}},&\text{if } i=k\\[0.05in]
    A_1^{\ell_{k-1}}\oplus  A_0^{\ell'_{k-1}},&\text{if } i=k-1\\[0.05in]
    A_2^{\ell_{k-2}}\oplus  A_0^{\ell''_{k-2}} ,&\text{if } i=k-2\\[0.05in]
    A_3^{\ell_{k-3}},&\text{if } i=k-3\\[0.05in]
    0, &\text{otherwise}.
    \end{cases}
\end{equation*}
Thus, each $i$-th homological component of $\BA$ is given by:
\begin{align*}
    \BA_i&=(\CA_i)_i\oplus (\CA_{i+1})_i\oplus (\CA_{i+2})_i\oplus(\CA_{i+3})_i\\
        &=A_0^{\ell_{i}}\oplus \big( A_1^{\ell_{i}}\oplus  A_0^{\ell'_{i}}\big)\oplus \big( A_2^{\ell_{i}}\oplus  A_0^{\ell''_{i}}\big)\oplus A_3^{\ell_{i}}\\
        &=A^{\ell_{i}}\oplus \kk^{\ell'_{i}}\oplus \kk^{\ell''_{i}}.
\end{align*}
By \Cref{def seq T}, for each $i \ges 1$ the matrices $[\alpha_i], [\alpha_i'], [\alpha_i'']$ have entries in $A_1$, $A_2$, and $A_3$ respectively. This explains the internal shifts in each homological component of $\BA$ in \eqref{BA}. Therefore, $\BA$ becomes an acyclic complex of graded $A$-modules.
\end{proof}


