\subsection{Constructing the sequences of complexes $\sC^{(k)}$ and of chain maps $\varphi^{(k)}$}
\label{Candphi}

In this subsection, we describe the sequence of complexes $\{\sC^{(k)}\}_{k \ges 0}$ in terms of the Koszul complex $K$, and construct the sequence of chain maps $\{\varphi^{(k)} \colon \sC^{(k)} \to \sC^{(k-1)}\}_{k \ges 1}$ that satisfy the hypotheses of \Cref{graded res} for class $\clT$. To better describe the graded resolution of $\kk$ over $A$ coming from our construction, we need to relabel the sequences of integers and matrices defined in \Cref{def seq T}. 

For all integers $k,r \ges 0$, we set
\begin{align}
\label{ellks}
\ell_{k,r} &\coloneqq \begin{cases}
\ell_k,&\text{ if } r=k\\
\ell_k',&\text{ if } r=k+1\\
\ell_k'',&\text{ if } r=k+2\\
0, &\text{ otherwise}
\end{cases}
\end{align}
and for all integers $k,r \ges 1$, we set
\begin{align}
\label{alphaks}
\alpha_{k,r}&\coloneqq \begin{cases}
\alpha_k,&\text{ if } r=k\\
\alpha_k',&\text{ if } r=k+1\\
\alpha_k'',&\text{ if } r=k+2\\
0, &\text{ otherwise}
\end{cases}\\
\label{def delta}
\Delta_k &\coloneqq 
\begin{pmatrix} \alpha_{k,k} &  \alpha_{k,k+1} & \alpha_{k,k+2}\end{pmatrix}, 
\end{align}
where the sequences of integers $\ell_k, \ell_k', \ell_k''$ 
and the matrices $\alpha_k, \alpha_k', \alpha_k''$ with entries in respectively $K_1,K_2,K_3$ are given in \Cref{def seq T}.


\begin{lemma} 
\label{alpha chain}
Retain the above notation. Then, for all $k,r,m\ges 1$ we have 
\begin{itemize}
\item[(1)] The multiplication map $\Sigma^{1+r-k} K^{\ell_{k,r}} \xra{\alpha_{k,r}} K^{\ell_{k-1,k-1}}$ is a chain map of complexes. 
\item[(2)] The maps
\(
    (\Sigma K^{\ell_{k,k}} \oplus \Sigma^2 K^{\ell_{k,k+1}} \oplus \Sigma^3 K^{\ell_{k,k+2}})^m \xra{\Delta_k^m} (K^{\ell_{k-1,k-1}})^m,
\)
given by blocks of maps where each $\Delta_k$ appears in the main diagonal of $\Delta_k^m$ and $0$ everywhere else, are chain maps of complexes.
\end{itemize}
\end{lemma}


\begin{proof}
(1): It is enough to show that for all $i,k\ges 1$ and $r\in\{k,k+1,k+2\}$, the diagram below is commutative:
 \begin{equation*}
  \xymatrixrowsep{2pc}
  \xymatrixcolsep{2pc}
  \xymatrix
  {
  K_{i+k-r-1}^{\ell_{k,r}} \ar@{->}[d]_{  (-1)^{r-k+1}\partial_{i+k-r-1}^{\ell_{k,r}} }
                         \ar@{->}[r]^{\alpha_{k,r}}
  & K_{i}^{ \ell_{k-1,k-1} }
  \ar@{->}[d]^{ \partial_{i}^{\ell_{k-1,k-1}} }
  \\
  K_{i+k-r-2}^{\ell_{k,r}} \ar@{->}[r]_{\alpha_{k,r}}
  &  K_{i-1}^{\ell_{k-1,k-1}}.
 }
\end{equation*}
Since all the entries of $\alpha_{k,r}$ are cycles of degree $r-k+1$, the commutativity of the diagram  follows from a more general statement as follows.

Let $\theta$ be an $u\times v$ matrix with entries that are cycles of the Koszul complex $(K,\partial)$ of degree $j\ges 0$. Then, for all $i\ges 0$ the following diagram is commutative:
\begin{equation*}
  \xymatrixrowsep{1.5pc}
  \xymatrixcolsep{1.5pc}
  \xymatrix
  {
  K_{i-j}^{v}\ar@{->}[d]_{  (-1)^{j}\partial_{i-j}^{v}}
                         \ar@{->}[r]^{\theta}
  & K_{i}^{u}
  \ar@{->}[d]^{ \partial_{i}^{u} }
  \\
  K_{i-j-1}^{v} \ar@{->}[r]_{\theta}
  &  K_{i-1}^{u}.
 }
\end{equation*}
Indeed, for each  $(y_k)_{1\les k \les v}\in K_{i-j}^v$ we have: 
\begin{align*}
    (\partial_i^u\circ \theta) (y_k)_{1\les k \les v}
    &=\partial_i^u\left( \sum_{k=1}^v\theta(s,k)\wedge y_k\right)_{1\les s \les u}\\
    &=\left( \sum_{k=1}^v\partial_i(\theta(s,k)\wedge  y_k)\right)_{1\les s \les u}\\
    &=\left( \sum_{k=1}^v\partial_j(\theta(s,k))\wedge y_k+(-1)^j\theta(s,k)\wedge \partial_{i-j}(y_k)\right)_{1\les s \les u}\\
    &=(-1)^j\left(\sum_{k=1}^v\theta(s,k)\wedge \partial_{i-j}(y_k)\right)_{1\les s \les u}\\
    &=(-1)^j\theta\left(\partial_{i-j}(y_k)\right)_{1\les k \les v}\\
    &=\left(\theta\circ (-1)^j\partial_{i-j}^v\right)(y_k)_{1\les k \les v}.
\end{align*}
Finally, (2) is a direct consequence of (1). 
\end{proof}


Now, consider a non-commutative algebra $\TF$ generated over $\BZ$ by indeterminates $X_{i,i}, X_{i,i+1}, X_{i,i+2}$, all of degree $i \ges 1$ which is recorded by the first index, subject to the relations
\begin{equation}
\label{algebraF}
    \TF \coloneqq \frac{\BZ \langle X_{i,i}, X_{i,i+1}, X_{i,i+2} \colon \forall i \ges 1 \rangle}{\left(X_{i,i}X_{j,j}, \ X_{i,i+1}X_{j,j}, \  X_{i,i+2}X_{j,j}\colon \forall i,j \ges 1 \right)}. 
\end{equation}
Remark that for $k \ges 0$, each graded component $\TF_k$ is a free $\BZ$-module generated by monomials whose total degree is $k$. One can show that $\rank_{\BZ} \TF_k = 3^k$.

