Using this tree, we now construct the sequence of complexes $\{\sC^{(k)}\}_{k \ges 0}$ and the sequence of chain maps $\{\varphi^{(k)} \colon \sC^{(k)} \to \sC^{(k-1)}\}_{k \ges 1}$ that satisfy the hypotheses of the main \Cref{graded res} for class $\clT$.

First, for each $k \ges 0$, we associate each $k$-th vertical layer in the above tree to the complex $\sC^{(k)}$ that is a direct sum of copies of the Koszul complex $K$ with the corresponding shifts, as follows. Each monomial in $\TF$ has the form:
\begin{equation*}
\bm=\prod_{i=1}^j X_{k_i,s_i},\ \text{where } 1\les k_1\les s_1\les k_1+2\text{ and } 1 \les k_i< s_i\les k_i+2\ \text{for all } i\ges 2.
\end{equation*}
To each monomial $\bm$ above, we associate four degrees:
\begin{equation}
\label{deg}
\deg_1\bm\coloneqq\sum_{i=1}^jk_i,\qquad \deg_2\bm\coloneqq\sum_{i=1}^j s_i,\qquad \deg_3\bm\coloneqq\prod_{i=1}^j\ell_{k_i,s_i},\qquad\text{ and }\qquad \deg_4\bm\coloneqq j.
\end{equation} 
The component of $\sC^{(k)}$, where $k=\deg_1\bm$ that corresponds to the monomial $\bm$, is given by:
\begin{equation*}
%\label{identification}
\bm \mapsto \Sigma^s K^{u},\quad \text{where } s=\deg_2\bm\text{ and } u=\deg_3\bm.
\end{equation*} 
Here the first degree of $\bm$ is the total monomial degree in $\TF$, the second degree associates to the shifting or internal grading of $K$, the third degree associates to the number of direct sums of copies of $K$, and the fourth degree is the number of indeterminates appeared in $\bm$. 
In particular, we identify each indeterminate in $\TF$ with a shifting of copies of $K$ as $X_{k,s}\mapsto \Sigma^{s}K^{\ell_{k,s}}$, for all $k\ges 0$ and $s\in\{k,k+1,k+2\}$.

In conclusion, for all $k\ges 0$,  we set 
\begin{equation}
\label{def Ck}
    \sC^{(k)}\coloneqq \bigoplus_{\deg_1\bm=k}  \Sigma^{\deg_2\bm} K^{\deg_3\bm}   
\end{equation}
where $\bm$ is a monomial of $\TF$ (cf.~\eqref{algebraF}) and different degrees of $\bm$ are defined in \eqref{deg}. Observe that $\sC^{(0)}=K$ as $\bm=1$ of first degree $0$.

From the description of $\bm$ and its degrees, it is straightforward to obtain the following result.
\begin{lemma} 
\label{lem Ck}
For all $k\ges 0$, we have an isomorphism of complexes: \(\sC^{(k)}\cong \bigoplus_{s\ges 0} \Sigma^s K^{u_{k,s}}\),
where 
\begin{equation}
\label{uks}
u_{k,s} \coloneqq \sum_{\substack{k_1+\dots+k_j=k\\ s_1+\dots+s_j=s\\  s_i\neq k_i, \forall i\ges 2}} \ell_{k_1,s_1}\ell_{k_2,s_2}\dots\ell_{k_j,s_j}, \quad \text{ for each $k,s \ges 0$}.
\end{equation}
\end{lemma}



For example, the $0$-th vertical layer $\TF_0=1$ , the $1$-st vertical layer $\TF_1 = \Span_\kk \{X_{1,1},X_{1,2},X_{1,3}\}$, and the $2$-nd vertical layer $\TF_2 = \Span_\kk \{X_{2,2},X_{2,3},X_{2,4}, X_{1,1}X_{1,2}, X_{1,2}X_{1,2}, X_{1,3}X_{1,2}, X_{1,1}X_{1,3}, X_{1,2}X_{1,3}, X_{1,3}X_{1,3}\}$ correspond respectively to the following complexes: 
\begin{align*}
\sC^{(0)}&\coloneqq K^{\ell_{0,0}}, \\
\sC^{(1)}&\coloneqq \Sigma K^{\ell_{1,1}}\oplus\Sigma^2 K^{ \ell_{1,2}}\oplus \Sigma^3K^{\ell_{1,3}},\\
\sC^{(2)}&\coloneqq\Sigma^2 K^{\ell_{2,2}}\oplus\Sigma^3 K^{\ell_{2,3}}\oplus \Sigma^4K^{\ell_{2,4}}\\
    &\oplus\left(\Sigma^3 K^{\ell_{1,1}}\oplus\Sigma^4 K^{\ell_{1,2}}\oplus \Sigma^5K^{\ell_{1,3}}\right)^{\ell_{1,2}}
     \oplus\left(\Sigma^4 K^{\ell_{1,1}}\oplus\Sigma^5 K^{\ell_{1,2}}\oplus \Sigma^6K^{\ell_{1,3}}\right)^{\ell_{1,3}}.
\end{align*}
Similarly, we get the following:
\begin{align*}
\sC^{(3)}&\coloneqq\Sigma^3 K^{\ell_{3,3}}\oplus\Sigma^4 K^{\ell_{3,4}}\oplus \Sigma^5K^{\ell_{3,5}}\\
     &\oplus\left(\Sigma^4 K^{\ell_{1,1}}\oplus\Sigma^5 K^{\ell_{1,2}}\oplus \Sigma^6K^{\ell_{1,3}}\right)^{\ell_{2,3}}
    \oplus\left(\Sigma^5 K^{\ell_{1,1}}\oplus\Sigma^6 K^{\ell_{1,2}}\oplus \Sigma^7 K^{\ell_{1,3}}\right)^{\ell_{2,4}}\\
    &\oplus\left(\Sigma^4 K^{\ell_{2,2}}\oplus\Sigma^5 K^{\ell_{2,3}}\oplus \Sigma^6 K^{\ell_{2,4}}\right)^{\ell_{1,2}}\\
    &\oplus\left(\Sigma^5 K^{\ell_{1,1}}\oplus\Sigma^6 K^{\ell_{1,2}}\oplus \Sigma^7 K^{\ell_{1,3}}\right)^{(\ell_{1,2})^2}
      \oplus\left(\Sigma^6 K^{\ell_{1,1}}\oplus\Sigma^7 K^{\ell_{1,2}}\oplus \Sigma^8 K^{\ell_{1,3}}\right)^{\ell_{1,3}\ell_{1,2}}\\
       &\oplus\left(\Sigma^5 K^{\ell_{2,2}}\oplus\Sigma^6 K^{\ell_{2,3}}\oplus \Sigma^7 K^{\ell_{2,4}}\right)^{\ell_{1,3}}\\
       &\oplus\left(\Sigma^6 K^{\ell_{1,1}}\oplus\Sigma^7 K^{\ell_{1,2}}\oplus \Sigma^8 K^{\ell_{1,3}}\right)^{\ell_{1,2}\ell_{1,3}}
        \oplus\left(\Sigma^7 K^{\ell_{1,1}}\oplus\Sigma^8 K^{\ell_{1,2}}\oplus \Sigma^9 K^{\ell_{1,3}}\right)^{(\ell_{1,3})^2}.
\end{align*}
Observe that given this arrangement, each $\sC^{(k)}$ has $3^k$ terms, with each term corresponds to a monomial of first degree $k$ in $\TF$.

\medskip

Second, for each $k\ges 1$, using the above arrangements of $\sC^{(k)}$, we construct a map $\varphi^{(k)}\colon \sC^{(k)} \to \sC^{(k-1)}$. To each group of three arrows defined in \eqref{arrow}, we associate a map 
\[
    \begin{pmatrix} e_{i,i}(\bn) &  e_{i,i+1}(\bn) & e_{i,i+2}(\bn) \end{pmatrix} \mapsto (\Delta_i)^{\deg_3 \bn}, \text{ for all } i \ges 1,
\]
where $\bn$ is a monomial only given in terms of $X_{i,i+1}$ and $X_{j,j+2}$ for some $i,j \ges 0$ and $\Delta_i$ is defined in \eqref{def delta}. We define each chain map $\varphi^{(k)}$ recursively as blocks of maps: 
\begin{equation}
\label{matrix phi}
    \varphi^{(1)} \coloneqq \Delta_1 \qquad \text{ and } \qquad 
\varphi^{(k+1)} \coloneqq\begin{pmatrix}
\Delta_{k+1}&0&0&0&0\\
0&\Delta_1^{\ell_{k,k+1}}&0&0&0\\
0&0&\Delta_1^{\ell_{k,k+2}}&0&0\\
0&0&0&(\varphi^{(k)})^{\ell_{1,2}}&0\\
0&0&0&0&(\varphi^{(k)})^{\ell_{1,3}}\\
\end{pmatrix}.
\end{equation}

For example, we have the following 
\begin{align*}
\varphi^{(2)}&=\begin{pmatrix} 
\Delta_2&0&0\\
0&\Delta_1^{\ell_{1,2}}&0\\
0&0&\Delta_1^{\ell_{1,3}}
\end{pmatrix} 
\quad 
\text{and}\\[0.05in]
\varphi^{(3)}&=\begin{pmatrix} 
\Delta_3&0&0&0&0&0&0&0&0\\
0&\Delta_1^{\ell_{2,3}}&0&0&0&0&0&0&0\\
0&0&\Delta_1^{\ell_{2,4}}&0&0&0&0&0&0\\
0&0&0&\Delta_2^{\ell_{1,2}}&0&0&0&0&0\\
0&0&0&0&\Delta_1^{(\ell_{1,2})^2}&0&0&0&0\\
0&0&0&0&0&\Delta_1^{\ell_{1,3}\ell_{1,2}}&0&0&0\\
0&0&0&0&0&0&\Delta_2^{\ell_{1,3}}&0&0\\
0&0&0&0&0&0&0&\Delta_1^{\ell_{1,2}\ell_{1,3}}&0\\
0&0&0&0&0&0&0&0&\Delta_1^{(\ell_{1,3})^2}
\end{pmatrix}.
\end{align*}



