\subsection{A graded minimal resolution of $\kk$ over $A$}
\label{graded res over A}

In this subsection, we show that the sequences of complexes $\sC^{(k)}$ and of maps $\varphi^{(k)}$ constructed in \Cref{Candphi} indeed give us the setting for \Cref{graded res} and give rise to a graded minimal resolution of $\kk$ over $A$ for class $\clT$.


\begin{theorem}
\label{res k over A class T}
Let $(R,\fm, \kk)$ be a local ring of codepth 3 and of class $\clT$, $A$ its Koszul homology which we consider as a graded-commutative ring, and retain the notation in \Cref{Candphi}. For all $k \ges 1$, set $\partial^\BF_k = [\varphi^{(k)}]$. Then, a graded minimal resolution of $\kk$ over $A$  has the form:
\begin{equation*}
\label{curlyF}
    \BF\colon \dots\to \bigoplus_{s=k}^{3k} A^{u_{k,s}}(-s)\xra{\partial_k^\BF} \bigoplus_{s=k-1}^{3(k-1)} A^{u_{k-1,s}}(-s)\xra{\partial_{k-1}^\BF}\dots \to \bigoplus_{s=1}^{3} A^{u_{1,s}}(-s) \xra{\partial_{1}^\BF} A,
\end{equation*}
where $u_{k,s}$ is defined in \eqref{uks} for all $k,s$.
\end{theorem}


\begin{proof} 
It follows immediately from \Cref{alpha chain} that for each $k\ges 1$, the map $\varphi^{(k)}\colon \sC^{(k)} \to \sC^{(k-1)}$ is a chain map. Thus, $[\varphi^{(k)}]\colon \HH{}{\sC^{(k)}}\to \HH{}{\sC^{(k-1)}}$ is well-defined. By \Cref{lem Ck}, using that the homological shift of $K$ in $\sC^{(k)}$ becomes the internal grading shift of $A$ as a graded $\kk$-algebra, we get \(\BF_k\coloneqq \bigoplus_{s=k}^{3k} A^{u_{k,s}}(-s)\cong \HH{}{\sC^{(k)}}\), thus 
$\partial^\BF_k$ is well-defined.


To show that $\BF$ described in the statement is an acyclic complex, we give it a different description. Let $\varepsilon\colon \BA\to \kk$ be a quasi-isomorphism obtained from \Cref{cor:acyclic A} with $\varepsilon_i=0$ for all $i>0$ and $\varepsilon_0=\id{\kk}$. In \Cref{Candphi}, we associate the components of $\sC^{(k)}$ and $\varphi^{(k)}$ to the nodes (monomials in $\TF$) and arrows of the directed tree in \Cref{fig:tree} respectively. One can see that $\BF$ can be obtained from the complex $\BA$ given in \eqref{BA}, which corresponds to the seed \eqref{seed} of the tree, by iteratively replacing $\kk$ in \eqref{BA} by the complex $\BA$ via the quasi-isomorphism $\varepsilon$. More precisely, we obtain a sequence of quasi-isomorphisms
\[ \varepsilon^{(j+1)}\colon \BA^{(j+1)}\xra{\simeq} \BA^{(j)}, \qquad\text{for all }j\ges 0,  \]
where $\varepsilon^{(1)}\coloneqq\varepsilon$, $\BA^{(0)}\coloneqq \kk$, $\BA^{(1)} \coloneqq \BA$, and for example, $\BA^{(2)}$ is given by
\begin{equation*} 
 \xymatrixrowsep{3.3pc}
 \xymatrixcolsep{3.7pc}
 \xymatrix{
 \dots\ar@{->}[r]^{}
 &A^{\ell_{i}}(-i) \ar@{->}[r]^{[\alpha_{i}]}\ar@{}[d]_{\bigoplus}
 &A^{\ell_{i-1}}(-i+1)\ar@{->}[r]^{[\alpha_{i-1}]}\ar@{}[d]_{\bigoplus}
 &\dots
 &A^{\ell_{1}}(-1)\ar@{->}[r]^{[\alpha_{1}]}\ar@{}[d]_{\bigoplus}
 &A^{\ell_0}.
 \\  
 \dots\ar@{->}[ru]^{}       
 &\BA^{\ell'_{i}}(-i-1)\ar@{->}[ru]|{[\alpha'_{i}\circ \varepsilon^{\ell_i'}]}\ar@{}[d]_{\bigoplus}
 &\BA^{\ell'_{i-1}}(-i)\ar@{->}[ru]|{[\alpha'_{i-1}\circ \varepsilon^{\ell_{i-1}'}]}\ar@{}[d]_{\bigoplus}
 &\dots 
 &\BA^{\ell'_{1}}(-2)\ar@{->}[ru]|{[\alpha'_{1} \circ\varepsilon^{\ell_1'}]}\ar@{}[d]_{\bigoplus}
 &
  \\   
 \dots \ar@{->}[ruu]^{}        
 &\BA^{\ell''_{i}}(-i-2)\ar@{->}[ruu]|{[\alpha''_{i}\circ \varepsilon^{\ell_i''}]}
 &\BA^{\ell''_{i-1}}(-i-1)\ar@{->}[ruu]|{[\alpha''_{i-1}\circ \varepsilon^{\ell_{i-1}''}]} 
 &\dots
 &\BA^{\ell''_{1}}(-3)\ar@{->}[ruu]|{[\alpha''_{1}\circ\varepsilon^{\ell_1''}]}
 &
 } 
\end{equation*}
The $k$-th homological component of each $\BA^{(j)}$ is given by:
\begin{equation*}
    \BA^{(j)}_k \coloneqq  \left(\bigoplus_{\substack{\deg_1\bm = k\\ \deg_4\bm =j}} A^{\deg_3\bm}(-\deg_2\bm) \right) \oplus \left(\bigoplus_{\substack{\deg_1\bn = k\\ \deg_4\bn =j}} \kk^{\deg_3\bn}(-\deg_2\bn)\right),
\end{equation*}
where $\bm$ is a monomial in $\TF$ that contains $X_{i,i}$ and $\bn$ is a monomial in $\TF$ that does not contain $X_{i,i}$. 
In fact, for all $k \ges 1$ we have  $\BF_{\les k} = \BA_{\les k}^{(k+1)}$ by reading the vertical components. 
First of all, this shows that $\BF$ is a complex of graded $A$-modules. Second, for all $i\ges 1$, by construction via the quasi-isomorphisms, we have:
\[\HH{i}{\BF}= \HH{i}{\BA^{(k+1)}}\cong\HH{i}{\BA}\quad\text{for all}\ k \ges i+1.\]   
 By \Cref{cor:acyclic A}, $\BA$ is an acyclic complex of graded $A$-modules, so $\BF$ is also acyclic.
 The minimality of $\BF$ follows since the differential maps $\partial_k^\BF$ all have entries in $A_{\ges 1}$. Therefore, $\BF$ is a graded minimal resolution of $\kk$ over $A$ of the desired format.
\end{proof}


\begin{remark} 
The first few components of $\BF$ are: 
\begin{align*}
\BF_0&\cong A^{\ell_{0,0}} \\
\BF_1&\cong A^{\ell_{1,1}}(-1)\oplus A^{\ell_{1,2}}(-2)\oplus A^{\ell_{1,3}}(-3)\\
\BF_2&\cong A^{\ell_{2,2}}(-2)\oplus A^{\ell_{2,3}}(-3)\oplus A^{\ell_{2,4}}(-4)\\
 &\oplus \left(A^{\ell_{1,1}}(-3)\oplus A^{\ell_{1,2}}(-4)\oplus A^{\ell_{1,3}}(-5)\right)^{\ell_{1,2}} \oplus
\left(A^{\ell_{1,1}}(-4)\oplus A^{\ell_{1,2}}(-5)\oplus A^{\ell_{1,3}}(-6)\right)^{\ell_{1,3}}\\
\BF_3 &\cong A^{\ell_{3,3}}(-3)\oplus A^{\ell_{3,4}}(-4)\oplus A^{\ell_{3,5}}(-5)\\
      &\oplus\left(A^{\ell_{1,1}}(-4)\oplus A^{\ell_{1,2}}(-5)\oplus A^{\ell_{1,3}}(-6)\right)^{\ell_{2,3}}
        \oplus\left(A^{\ell_{1,1}}(-5)\oplus A^{\ell_{1,2}}(-6)\oplus A^{\ell_{1,3}}(-7)\right)^{\ell_{2,4}}\\
      &\oplus  \left(A^{\ell_{2,2}}(-4)\oplus A^{\ell_{2,3}}(-5)\oplus A^{\ell_{2,4}}(-6)\right)^{\ell_{1,2}}\\
      &\oplus \left(A^{\ell_{1,1}}(-5)\oplus A^{\ell_{1,2}}(-6)\oplus A^{\ell_{1,3}}(-7)\right)^{(\ell_{1,2})^2}
       \oplus\left(A^{\ell_{1,1}}(-6)\oplus A^{\ell_{1,2}}(-7)\oplus A^{\ell_{1,3}}(-8)\right)^{\ell_{1,3}\ell_{1,2}}\\
      &\oplus \left(A^{\ell_{2,2}}(-5)\oplus A^{\ell_{2,3}}(-6)\oplus A^{\ell_{2,4}}(-7)\right)^{\ell_{1,3}}\\
      &\oplus \left(A^{\ell_{1,1}}(-6)\oplus A^{\ell_{1,2}}(-7)\oplus A^{\ell_{1,3}}(-8)\right)^{\ell_{1,2}\ell_{1,3}}
      \oplus \left(A^{\ell_{1,1}}(-7)\oplus A^{\ell_{1,2}}(-8)\oplus A^{\ell_{1,3}}(-9)\right)^{(\ell_{1,3})^2}. 
\end{align*}
When we view $\BF_k=\bigoplus_{s=k}^{3k} A^{u_{k,s}}(-s)$ by grouping the internal grading shifts, we then obtain the following expressions for $u_{k,s}$ in terms of $\ell_{k,r}$, which for practicality we write in terms of $\ell_i, \ell_i', \ell_i''$ here; see \eqref{ellks}. Note that $u_{k,s}=0$ for all $s>3k$ and $s<k$.  
\begin{align*}
u_{1,1}&=\ell_1,   &u_{2,2}&=\ell_2 ,              &u_{3,3}&=\ell_3, \\   
u_{1,2}&=\ell_1',  &u_{2,3}&=\ell_2'+\ell_1\ell_1',& u_{3,4}&=\ell_3'+\ell_1\ell_2'+\ell_2\ell_1'\\        
u_{1,3}&=\ell_1'', &u_{2,4}&=\ell_2''+ (\ell_1')^2+\ell_1\ell_1'',&u_{3,5}&=\ell_3''+\ell_1(\ell_1')^2+\ell_1\ell_2''+2\ell_1'\ell_2'+\ell_2\ell_1'',\\
              &&u_{2,5}&=2\ell_1'\ell_1'',    &u_{3,6}&=2\ell_1\ell_1'\ell_1'' + 2\ell_1'\ell_2'' + 2\ell_1''\ell_2' + (\ell_1')^3,\\ 
              &&  u_{2,6}&=(\ell_1'')^2, & u_{3,7}&=3(\ell_1')^2\ell_1'' + 2\ell_1''\ell_2'' + \ell_1(\ell_1'')^2,\\
              &&                         && u_{3,8}&=3\ell_1'(\ell_1'')^2\\
              &&                         && u_{3,9}&=(\ell_1'')^3.
\end{align*}
One could further express these values in terms of the invariants $a_1,a_2,a_3$ by using \Cref{ellex}.
\end{remark}

We recover the Poincar\'e series of $\kk$ over $R$ for class $\clT$, which was given in \cite[Theorem 2.1]{Av2}.

\begin{corollary} 
\label{cor: Poi}
Let $(R,\fm, \kk)$ be a local ring of embedding dimension $n$, codepth codepth 3 and of class $\clT$, $A$ its Koszul homology, and retain the above notation. Then,
\begin{align*}
\Poi{A}{\kk}(t,z)&=\frac{1}{1-a_1tz-(a_2-3)tz^2+3t^2z^2-a_3tz^3-t^2z^3-t^3z^3}\quad\text{and}\\
\Poi{R}{\kk}(t)&=\frac{(1+t)^n}{1-a_1t^2-(a_2-3)t^3-(a_3-3)t^4-t^5-t^6}.
\end{align*}
\end{corollary}

\begin{proof}
Let $\CL(t,z) \coloneqq \sum_{k,s\ges 0} \ell_{k,s}t^kz^s$, where $\ell_{k,s}$ is defined in \eqref{ellks} for $k,s\ges 0$. By \Cref{rmk T} and \eqref{ellks}, the generating functions of the sequences
$\{\ell_{k,k}\}_{k\ges 0},\ \{\ell_{k,k+1}\}_{k\ges 0},\ \text{and}\ \{\ell_{k,k+2}\}_{k\ges 0}$ are respectively   
\[f(t)\coloneqq\frac{1}{(1-t)^3-t(a_1-3)},\quad g(t)\coloneqq\frac{t^2+t(a_2-3)}{(1-t)^3-t(a_1-3)},\text{ and} \quad h(t)\coloneqq\frac{ta_3}{(1-t)^3-t(a_1-3)}.\] 
Therefore, we obtain
\begin{equation}
\tag{$\star$}
\CL(t,z) = f(tz)+zg(tz)+z^2h(tz).
\end{equation}
By \Cref{gr Poi}, \Cref{res k over A class T}, and definition of $u_{k,s}$ in \eqref{uks}, we have
\begin{align*}
   P^A_\kk(t,z)&=\sum_{k,s\ges 0} \Bigg(\sum_{\substack{k_1+\dots+k_j=k\\ s_1+\dots+s_j=s\\  s_i\neq k_i, \forall i\ges 2}}\ell_{k_1,s_1}\dots \ell_{k_j,s_j} \Bigg) t^kz^s\\
    &= \sum_{k,s\ges 0} \ell_{k,s}t^kz^s + \sum_{k,s\ges 0}
    \sum_{\substack{ j\ges 2\\
                    k_1+\dots+k_j=k\\ 
                    s_1+\dots+s_j=s\\  
                    s_i\neq k_i, \forall i\ges 2}
                    }\left(\ell_{k_1,s_1}t^{k_1}z^{s_1}\right)\dots \left(\ell_{k_j,s_j}t^{k_j}z^{s_j}\right) \\
   &=\CL(t,z) + \sum_{j\ges 2} \big(\CL(t,z)-1\big) \big(\CL(t,z)-f(tz)\big)^{j-1}\\
   &=\CL(t,z) + \big(\CL(t,z)-1\big) \sum_{j\ges 1} \big(\CL(t,z)-f(tz)\big)^{j}\\
    &=\CL(t,z) + \big(\CL(t,z)-1\big) \left(\frac{1}{1-\CL(t,z)+f(tz)}-1\right)\\
    &=\frac{\CL(t,z)\big(1-\CL(t,z)+f(tz)\big) + \big(\CL(t,z)-1\big) \big(\CL(t,z)-f(tz)\big)}
          {1-\CL(t,z)+f(tz)}\\
    &=\frac{f(tz)}{1-\CL(t,z)+f(tz)}\\
    &\overset{\text{by } (\star)}{=}\frac{f(tz)}{1-zg(tz)-z^2h(tz)}\\
    &=\frac{1}{(1-tz)^3-tz(a_1-3)-z\big((tz)^2+tz(a_2-3)\big)-z^2(tz)a_3}\\
    &=\frac{1}{1-a_1tz-(a_2-3)tz^2+3t^2z^2-a_3tz^3-t^2z^3-t^3z^3}.
\end{align*}
In the second equality above, we separate the terms that have exactly one factor ($j=1$) and those that have more than one factor ($j \ges 2$). The third equality follows from the definition of $\CL(t,z)$, the first factor in the sum comes from $\displaystyle \CL(t,z)= 1+\sum_{k_1\ges 1}\ell_{k_1,s_1}t^{k_1}z^{s_1}$, as  $\ell_{0,0}t^0z^0 = 1$, and for $i\ges 2$ the remaining factors in the sum come from $\displaystyle \CL(t,z) = f(tz)+ \sum_{s_i\not=k_i\ges 1}\ell_{k_i,s_i}t^{k_i}z^{s_i}$, as $ f(tz)= \displaystyle \sum_{k_i\ges 1}\ell_{k_i,k_i}t^{k_i}z^{k_i}$. The remaining equalities are straightforward. 

The expression for $\Poi{R}{\kk}(t)$ follows from that of $\Poi{A}{\kk}(t,z)$ and \Cref{Poi cor}.
\end{proof}


