\subsection{A minimal free resolution of $\kk$ over $R$}
\label{res over R}

In \cite{NV}, for any local ring $R$ the authors describe a truncated resolution of $\kk$ as an $R$-module up to homological degree 5. Using the descriptions of $\sC^{(k)}$ and $\varphi^{(k)}$ from \Cref{Candphi} and \Cref{cor: res over R}, we now describe the entire minimal free resolution $(F,\partial^F)$ of $\kk$ over a local ring $R$ of codepth 3 and of class $\clT$. 

\begin{theorem}
\label{res k over R class T}
  Let $(R,\fm, \kk)$ be a local ring of codepth 3 and of class $\clT$, and retain the above notation. Let $(K,\partial^K)$ be the Koszul complex of $R$ on a minimal set of generators of $\fm$. Then, a minimal free resolution $F$ of $\kk$ over $R$ has the $k$-th homological component given by 
\begin{equation*}
      F_k \cong \bigoplus_{i=0}^k \Bigg(\bigoplus_{\substack{\deg_1\bm+\deg_2\bm}=k-i}K^{\deg_3\bm}_i\Bigg),
\end{equation*}
for all $k \ges 0$, where $\bm$ is a monomial of $\TF$ (cf.~\eqref{algebraF}) and different degrees of $\bm$ are defined in \eqref{deg}. 

The differential maps $\partial_k^F$ consists of maps described below. Set $\bm \coloneqq X_{j-1,j-1}\bn$ for some $j\ges 1$, where $\bn$ is a monomial of $\TF$ that does not contain $X_{u,u}$ for any $u \ges 1$; remark that $\deg_3\bm=\ell_{j-1,j-1}\deg_3\bn$. Let $K_i^{\deg_3\bm}$ be a component of $F_{k-1}$, then all the maps going into $K_i^{\deg_3\bm}$ have the following form:
\begin{equation*}  
 \xymatrixrowsep{3pc}
 \xymatrixcolsep{5pc}
 \xymatrix{
  K_{i+1}^{\deg_3\bm}\ar@{->}[r]^{(\partial_{i+1}^K)^{\deg_3\bm} }\ar@{}[d]_{\bigoplus}
 &K_i^{\deg_3\bm}. \\ 
(K_{i-1}^{\ell_{j,j}})   ^{\deg_3\bn}\ar@{->}[ru]  |{(\alpha_{j,j})   ^{\deg_3\bn}}\ar@{}[d]_{\bigoplus}&\\
(K_{i-2}^{\ell_{j,j+1}}) ^{\deg_3\bn}\ar@{->}[ruu] |{(\alpha_{j,j+1}) ^{\deg_3\bn}}\ar@{}[d]_{\bigoplus}&\\
(K_{i-3}^{\ell_{j,j+2}}) ^{\deg_3\bn}\ar@{->}[ruuu]|{(\alpha_{j,j+2}) ^{\deg_3\bn}}&
}
\end{equation*}
\end{theorem}


\begin{proof}
For all $k \ges 0$, we have
  \begin{align*}
      F_k = \bigoplus_{j=0}^{\lfloor\frac{k}{2}\rfloor}\sC^{(j)}_{k-j}&= \bigoplus_{j\ges 0}\sC^{(j)}_{k-j} = \bigoplus_{j\ges 0}\Big(\bigoplus_{\deg_1\bm=j}  \Sigma^{\deg_2\bm} K^{\deg_3\bm}\Big)_{k-j}= \bigoplus_{j\ges 0}\Big(\bigoplus_{\deg_1\bm=j}   K^{\deg_3\bm}_{k-j-\deg_2\bm}\Big),
  \end{align*} 
where $\bm$ is a monomial of $\TF$. The first equality follows from \Cref{cor: res over R}, the second equality follows from the fact that $\sC^{(j)}_{k-j}=0$ for all $k-j<j$, and the third equality follows from \eqref{def Ck}, and we apply the homological shift in the last equality.
Set $i=k-j-\deg_2\bm$, we obtain the desired expression for $F_k$.

The differential maps $\partial^F_k$ follows from \Cref{cor: res over R} and descriptions of $\sC^{(k)}$ and $\varphi^{(k)}$ in \Cref{Candphi}.
\end{proof}


